@MainActor
final class GraphStore: ObservableObject {
    static weak var currentForLayoutMetrics: GraphStore?
    private static weak var commandTargetStore: GraphStore?
    private static var sharedCopiedSelectionPayload: CopiedSelectionPayload?

    static func setCommandTargetStore(_ store: GraphStore?) {
        commandTargetStore = store
    }

    static func clearCommandTargetStore(if store: GraphStore) {
        if commandTargetStore === store {
            commandTargetStore = nil
        }
    }

    static var activeCommandTargetStore: GraphStore? {
        guard let commandTargetStore, commandTargetStore.isGraphWindowVisible else {
            return nil
        }
        return commandTargetStore
    }

    struct CustomFragmentPreset: Codable, Identifiable, Equatable {
        let id: UUID
        var title: String
        var detail: String
        var metalSource: String
    }

    private struct ActiveMIDINote: Equatable {
        var note: UInt8
        var channel: UInt8
        var destinationName: String
    }

    private struct MIDICCNodeRuntimeState: Equatable {
        var lastValue: UInt8?
        var currentValue = "-"
    }

    private struct MIDIInputCCNodeRuntimeState: Equatable {
        var lastEventID: UInt64?
        var triggerFrame: Int?
    }

    private struct MIDIInputNoteNodeRuntimeState: Equatable {
        var lastEventID: UInt64?
        var triggerFrame: Int?
    }

    private struct OSCInputNodeRuntimeState: Equatable {
        var lastEventID: UInt64?
        var triggerFrame: Int?
    }

    private struct OSCOutputNodeRuntimeState: Equatable {
        var lastSignature = ""
    }

    private struct MIDINodeRuntimeState: Equatable {
        var activeNote: ActiveMIDINote?
        var currentNoteName = "-"
    }

    private struct HoldNodeRuntimeState: Equatable {
        var heldValue: Double
    }

    private struct ScalarSmoothNodeRuntimeState: Equatable {
        var value: Double
        var velocity: Double = 0.0
    }

    private struct RandomNodeRuntimeState: Equatable {
        var value: Double
        var lastTriggerHigh = false
        var lastContinuousBucket: Int?
    }

    private struct PulseNodeRuntimeState: Equatable {
        var lastGateHigh = false
        var lastRiseFrame: Int?
    }

    private struct FireOnLoadNodeRuntimeState: Equatable {
        var lastActivationID: Int?
        var lastFireFrame: Int?
    }

    private struct CounterNodeRuntimeState: Equatable {
        var value: Double
        var lastTriggerHigh = false
        var lastResetHigh = false
    }

    private struct ToggleNodeRuntimeState: Equatable {
        var isOn: Bool
        var lastTriggerHigh = false
        var lastResetHigh = false
    }

    private struct DelayNodeRuntimeState: Equatable {
        var lastTriggerHigh = false
        var armedAt: CFTimeInterval?
        var firedForArm = false
        var outputFrame: Int?
    }

    private struct TimerNodeRuntimeState: Equatable {
        var lastBucket: Int?
        var outputFrame: Int?
        var lastEnabledHigh = false
    }

    private struct ScrollGestureNodeRuntimeState: Equatable {
        var lastCenter: CGPoint?
        var accumulatedY: Double = 0.0
        var isEngaged = false
    }

    private struct ZoomGestureNodeRuntimeState: Equatable {
        var lastDistance: Double?
        var zoom: Double = 1.0
        var isEngaged = false
    }

    private struct TrackballNodeRuntimeState: Equatable {
        var lastMousePosition: CGPoint?
        var orbit: Double = 0.0
        var pitch: Double = 0.0
        var rotationX: Double = 0.0
        var rotationY: Double = 0.0
        var panX: Double = 0.0
        var panY: Double = 0.0
        var distance: Double = 6.0
        var lastScrollPosition = CGPoint.zero
        var isDragging = false
        var lastDistanceScrollTime: CFTimeInterval?
    }

    private struct DepthEstimateNodeRuntimeState: Equatable {
        var smoothedDepth: Double = 0.0
    }

    private struct TransitionNodeRuntimeState: Equatable {}

    private struct SliderControlRuntimeState: Equatable {
        var isDragging = false
        var liveValue: Double?
        var pendingCommitValue: Double?
    }

