    private struct IteratorEvaluationContext {
        let iteratorNodeID: GraphNode.ID
        let index: Int
        let iterations: Int

        var progress: Double {
            guard iterations > 1 else { return 0.0 }
            return Double(index) / Double(iterations - 1)
        }
    }

    private struct BeatDetectNodeRuntimeState {
        var lastEvaluatedFrame: Int?
        var previousKickEnergy = 0.0
        var previousSnareEnergy = 0.0
        var lastKickFrame: Int?
        var lastSnareFrame: Int?
        var kickLevel = 0.0
        var snareLevel = 0.0
        var kickPulse = false
        var snarePulse = false
    }

    private var iteratorEvaluationStack: [IteratorEvaluationContext] = []
    private var iteratorVariableRuntimeContexts: [GraphNode.ID: IteratorEvaluationContext] = [:]

    private struct SessionSnapshot: Codable {
        let graph: GraphSnapshot
        let currentGraphFilePath: String?
    }

    private struct GraphHistoryEntry {
        let graphText: String
    }

    init() {
        let defaults = UserDefaults.standard
        let document = Self.blankDocument
        let initialMetal = Self.defaultEditableMetalSource
        let fragmentSources: [GraphNode.ID: String] = [:]
        self.document = document
        self.editableSource = document.source
        self.editableMetalSource = initialMetal
        self.fragmentMetalSources = fragmentSources
        self.lastGeneratedMetalSources = fragmentSources
        self.baselineUniformValues = [:]
        self.selectedNodeID = nil
        self.inspectorFocusTarget = .nodeLibrary
        self.canvasBackgroundOpacity = defaults.object(forKey: CanvasPreferenceKey.opacity) as? Double ?? 0.5
        self.canvasBackgroundColor = Self.loadCanvasColor(from: defaults) ?? .black
        self.snapToGridEnabled = defaults.object(forKey: GraphPreferenceKey.snapToGridEnabled) as? Bool ?? true
        self.currentGraphDisplayName = document.name
        self.customFragmentPresets = Self.loadCustomFragmentPresets(from: defaults)
        startKeyboardMonitoring()
        configureBindings()
        updateAudioMonitorState()
        updateVideoMonitorState()
        synchronizeWebViewControllers()
        synchronizeVideoPlayerControllers()
        validateMetalSource()
        updateMIDINodes()
        updateOSCNodes()
        updateOSCNodes()
        NotificationCenter.default.publisher(for: GaussianSplatLoadProgressStore.didChangeNotification)
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                self?.objectWillChange.send()
            }
            .store(in: &cancellables)
        resetHistoryTracking()
        lastSavedGraphText = try? currentGraphSnapshotText()
    }

    deinit {
        let keyboardKeyDownMonitor = keyboardKeyDownMonitor
        let keyboardKeyUpMonitor = keyboardKeyUpMonitor
        let keyboardFlagsChangedMonitor = keyboardFlagsChangedMonitor
        let controllers = Array(videoPlayerControllers.values)
        let clientID = monitorClientID
        MainActor.assumeIsolated {
            if let keyboardKeyDownMonitor {
                NSEvent.removeMonitor(keyboardKeyDownMonitor)
            }
            if let keyboardKeyUpMonitor {
                NSEvent.removeMonitor(keyboardKeyUpMonitor)
            }
            if let keyboardFlagsChangedMonitor {
                NSEvent.removeMonitor(keyboardFlagsChangedMonitor)
            }
            controllers.forEach { $0.close() }
            VideoInputMonitor.shared.setVideoRequested(false, for: clientID)
            VideoInputMonitor.shared.setHandTrackingEnabled(false, for: clientID)
        }
    }

    func restoreLastOpenedGraphIfNeeded() {
        guard !hasAttemptedStartupRestore else { return }
        hasAttemptedStartupRestore = true
        guard !Self.hasPerformedGlobalStartupRestore else { return }
        Self.hasPerformedGlobalStartupRestore = true
        isStartupRestoring = true
        defer { isStartupRestoring = false }
        restoreLastOpenedGraphIfPossible(from: UserDefaults.standard)
    }

    var selectedNode: GraphNode? {
        guard let selectedNodeID else { return nil }
        return document.nodes.first(where: { $0.id == selectedNodeID })
    }

    func updatePanelWidths(parameterWidth: Double? = nil, libraryWidth: Double? = nil, markDirty: Bool = true) {
        var changed = false

        if let parameterWidth {
            let clamped = max(240, min(420, parameterWidth))
            if abs(parameterInspectorWidth - clamped) > 0.5 {
                parameterInspectorWidth = clamped
                changed = true
            }
        }

        if let libraryWidth {
            let clamped = max(250, min(420, libraryWidth))
            if abs(nodeLibraryWidth - clamped) > 0.5 {
                nodeLibraryWidth = clamped
                changed = true
            }
        }

        if changed {
            guard hasAttemptedStartupRestore, !isStartupRestoring else { return }
            if markDirty {
                markCurrentGraphDirty()
            }
            persistSessionSnapshot()
        }
    }

    func makePresetNodeFromSelectedFragment() {
        guard let fragmentNode = selectedFragmentNode else {
            statusMessage = "Select a fragment node first."
            return
        }

        let preferredTitle = fragmentNode.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? "Custom Fragment"
            : fragmentNode.title
        let title = uniqueCustomFragmentPresetTitle(preferred: preferredTitle)
        let detail = "Saved from \(fragmentNode.title)"
        let preset = CustomFragmentPreset(
            id: UUID(),
            title: title,
            detail: detail,
            metalSource: metalSource(for: fragmentNode.id)
        )

        customFragmentPresets.append(preset)
        customFragmentPresets.sort { $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending }
        persistCustomFragmentPresets()
        statusMessage = "Saved \(title) to the library."
    }

    func addCustomFragmentPresetNode(_ presetID: UUID, at position: CGPoint) {
        guard let preset = customFragmentPresets.first(where: { $0.id == presetID }) else {
            statusMessage = "Preset not found."
            return
        }
        addPresetFragmentNode(title: preset.title, metalSource: preset.metalSource, at: position)
    }

    var selectedUniform: UniformDescriptor? {
        guard let selectedNode,
              case .uniform(let uniform) = selectedNode.kind else {
            return nil
        }
        return currentUniform(matching: uniform.id) ?? currentUniform(named: uniform.name)
    }

    func node(withID nodeID: GraphNode.ID) -> GraphNode? {
        document.nodes.first(where: { $0.id == nodeID })
    }

    var canCopySelectedNode: Bool {
        selectedNodesForClipboard().isEmpty == false
    }

    var canCreateMacroSelection: Bool {
        selectedNodeIDs.count >= 1
    }

    var canPasteCopiedNode: Bool {
        Self.sharedCopiedSelectionPayload != nil
    }

    var canUndoGraphChange: Bool {
        !undoHistory.isEmpty
    }

    var canRedoGraphChange: Bool {
        !redoHistory.isEmpty
    }

    var canDuplicateSelectedNode: Bool {
        selectedNodesForClipboard().isEmpty == false
    }

    var canSelectAllVisibleNodes: Bool {
        document.nodes.contains { isNodeVisibleOnCanvas($0.id) }
    }

    var canAlignSelectedNodes: Bool {
        selectedNodeIDs.count >= 2
    }

    var canSnapSelectedNodesToGrid: Bool {
        selectedNodeIDs.isEmpty == false
    }

    func toggleSnapToGrid() {
        setSnapToGridEnabled(!snapToGridEnabled)
    }

    func setSnapToGridEnabled(_ isEnabled: Bool) {
        snapToGridEnabled = isEnabled
        UserDefaults.standard.set(isEnabled, forKey: GraphPreferenceKey.snapToGridEnabled)
    }

    func updateCanvasViewportCenter(_ center: CGPoint, markDirty: Bool = false) {
        if let currentCanvasViewportCenter,
           abs(currentCanvasViewportCenter.x - center.x) < 0.5,
           abs(currentCanvasViewportCenter.y - center.y) < 0.5 {
            return
        }
        currentCanvasViewportCenter = center
        preferredCanvasViewportCenter = center
        if markDirty {
            markCurrentGraphDirty()
        }
        guard let currentGraphFileURL else { return }
        persistCanvasViewport(center, for: currentGraphFileURL)
        persistSessionSnapshot()
    }

    func requestedCanvasViewportCenter() -> CGPoint? {
        preferredCanvasViewportCenter
    }

    func copySelectedNode() {
        let selectedNodes = selectedNodesForClipboard()
        guard selectedNodes.isEmpty == false else { return }
        guard let payload = copiedSelectionPayload(for: selectedNodes) else { return }
        Self.sharedCopiedSelectionPayload = payload
        statusMessage = selectedNodes.count == 1
            ? "Copied \(selectedNodes[0].title)."
            : "Copied \(selectedNodes.count) nodes."
    }

    func pasteCopiedNode() {
        guard let payload = Self.sharedCopiedSelectionPayload else { return }
        pasteCopiedSelection(payload, offset: CGPoint(x: 48, y: 48))
    }

    func duplicateSelectedNode() {
        let selectedNodes = selectedNodesForClipboard()
        guard selectedNodes.isEmpty == false else { return }
        if selectedNodes.count == 1, let selectedNodeID {
            _ = duplicateNode(selectedNodeID)
            return
        }
        guard let payload = copiedSelectionPayload(for: selectedNodes) else { return }
        pasteCopiedSelection(payload, offset: CGPoint(x: 48, y: 48))
    }

    func createMacroFromSelection() {
        guard let macroID = createMacro(from: Array(selectedNodeIDs)) else { return }
        selectedNodeIDs = [macroID]
        selectedNodeID = macroID
    }

    func selectAllVisibleNodes() {
        let visibleNodeIDs = document.nodes
            .filter { isNodeVisibleOnCanvas($0.id) }
            .map(\.id)
        selectedNodeIDs = Set(visibleNodeIDs)
        selectedNodeID = visibleNodeIDs.first
    }

    func requestCanvasFocusSelection() {
        focusSelectionRequestID = UUID()
    }

    func requestCanvasZoomIn() {
        canvasZoomInRequestID = UUID()
    }

    func requestCanvasZoomOut() {
        canvasZoomOutRequestID = UUID()
    }

    func alignSelectedNodesLeft() {
        let selected = document.nodes.filter { selectedNodeIDs.contains($0.id) && isNodeVisibleOnCanvas($0.id) }
        guard let targetX = selected.map(\.position.x).min() else { return }
        for node in selected {
            moveNode(node.id, to: CGPoint(x: targetX, y: node.position.y))
        }
    }

    func alignSelectedNodesTop() {
        let selected = document.nodes.filter { selectedNodeIDs.contains($0.id) && isNodeVisibleOnCanvas($0.id) }
        guard let targetY = selected.map(\.position.y).min() else { return }
        for node in selected {
            moveNode(node.id, to: CGPoint(x: node.position.x, y: targetY))
        }
    }

    func snapSelectedNodesToGrid(spacing: CGFloat = 36) {
        let selected = document.nodes.filter { selectedNodeIDs.contains($0.id) && isNodeVisibleOnCanvas($0.id) }
        guard selected.isEmpty == false else { return }
        for node in selected {
            moveNode(
                node.id,
                to: CGPoint(
                    x: max(24, (node.position.x / spacing).rounded() * spacing),
                    y: max(24, (node.position.y / spacing).rounded() * spacing)
                )
            )
        }
    }

    func enterMacroEditor(for macroNodeID: GraphNode.ID) {
        guard case .macro = node(withID: macroNodeID)?.kind,
              macroNodeSettings[macroNodeID] != nil else {
            return
        }
        editingIteratorNodeID = nil
        editingMacroNodeID = macroNodeID
        selectedNodeIDs.removeAll()
        selectedNodeID = nil
        statusMessage = "Editing \(node(withID: macroNodeID)?.title ?? "Macro")."
    }

    func exitMacroEditor() {
        guard let macroNodeID = editingMacroNodeID else { return }
        editingMacroNodeID = nil
        selectedNodeIDs = [macroNodeID]
        selectedNodeID = macroNodeID
    }

    func enterIteratorEditor(for iteratorNodeID: GraphNode.ID) {
        guard case .iterator = node(withID: iteratorNodeID)?.kind,
              iteratorNodeSettings[iteratorNodeID] != nil else {
            return
        }
        editingMacroNodeID = nil
        editingIteratorNodeID = iteratorNodeID
        selectedNodeIDs.removeAll()
        selectedNodeID = nil
        statusMessage = "Editing \(node(withID: iteratorNodeID)?.title ?? "Iterator")."
    }

    func exitIteratorEditor() {
        guard let iteratorNodeID = editingIteratorNodeID else { return }
        editingIteratorNodeID = nil
        selectedNodeIDs = [iteratorNodeID]
        selectedNodeID = iteratorNodeID
    }

    var canExitContainerEditor: Bool {
        editingMacroNodeID != nil || editingIteratorNodeID != nil
    }

    func exitActiveContainerEditor() {
        if editingMacroNodeID != nil {
            exitMacroEditor()
            return
        }
        if editingIteratorNodeID != nil {
            exitIteratorEditor()
        }
    }

    func undoGraphChange() {
        guard let previous = undoHistory.popLast() else { return }
        do {
            let current = try currentGraphHistoryEntry()
            isApplyingHistory = true
            redoHistory.append(current)
            try restoreGraphSnapshot(from: previous.graphText)
            statusMessage = "Undo."
        } catch {
            if let current = try? currentGraphHistoryEntry() {
                redoHistory.removeAll()
                lastHistoryGraphText = current.graphText
            }
            statusMessage = "Undo failed: \(error.localizedDescription)"
        }
        isApplyingHistory = false
    }

    func redoGraphChange() {
        guard let next = redoHistory.popLast() else { return }
        do {
            let current = try currentGraphHistoryEntry()
            isApplyingHistory = true
            undoHistory.append(current)
            try restoreGraphSnapshot(from: next.graphText)
            statusMessage = "Redo."
        } catch {
            if let current = try? currentGraphHistoryEntry() {
                undoHistory.removeAll()
                lastHistoryGraphText = current.graphText
            }
            statusMessage = "Redo failed: \(error.localizedDescription)"
        }
        isApplyingHistory = false
    }

    @discardableResult
    func duplicateNode(_ nodeID: GraphNode.ID, offset: CGPoint = CGPoint(x: 48, y: 48)) -> GraphNode.ID? {
        guard let node = document.nodes.first(where: { $0.id == nodeID }) else { return nil }
        if case .macro = node.kind {
            guard let payload = copiedSelectionPayload(for: [node]) else { return nil }
            pasteCopiedSelection(payload, offset: offset)
            return selectedNodeID
        }
        if case .iterator = node.kind {
            guard let payload = copiedSelectionPayload(for: [node]) else { return nil }
            pasteCopiedSelection(payload, offset: offset)
            return selectedNodeID
        }
        let payload = copiedNodePayload(for: node)
        let position = CGPoint(x: node.position.x + offset.x, y: node.position.y + offset.y)
        return instantiateCopiedNode(payload, at: position)
    }

