    private func selectedNodesForClipboard() -> [GraphNode] {
        let visibleSelectedNodes = document.nodes.filter { selectedNodeIDs.contains($0.id) && isNodeVisibleOnCanvas($0.id) }
        if visibleSelectedNodes.isEmpty == false {
            return visibleSelectedNodes
        }
        if let selectedNode {
            return [selectedNode]
        }
        return []
    }

    private func copiedSelectionPayload(for selectedNodes: [GraphNode]) -> CopiedSelectionPayload? {
        guard selectedNodes.isEmpty == false else { return nil }
        let expandedNodeIDs = expandedClipboardNodeIDs(for: Set(selectedNodes.map(\.id)))
        let selectedNodeSet = expandedNodeIDs
        let expandedNodes = document.nodes.filter { expandedNodeIDs.contains($0.id) }
        guard expandedNodes.isEmpty == false else { return nil }
        let anchorPosition = selectedNodes.reduce(CGPoint(x: CGFloat.greatestFiniteMagnitude, y: CGFloat.greatestFiniteMagnitude)) { partial, node in
            CGPoint(x: min(partial.x, node.position.x), y: min(partial.y, node.position.y))
        }
        let internalConnections = document.connections.compactMap { connection -> CopiedConnectionPayload? in
            guard let sourcePort = port(withID: connection.fromPortID),
                  let targetPort = port(withID: connection.toPortID),
                  selectedNodeSet.contains(sourcePort.nodeID),
                  selectedNodeSet.contains(targetPort.nodeID) else {
                return nil
            }
            return CopiedConnectionPayload(
                fromNodeID: sourcePort.nodeID,
                fromPortID: connection.fromPortID,
                toNodeID: targetPort.nodeID,
                toPortID: connection.toPortID
            )
        }
        return CopiedSelectionPayload(
            nodes: expandedNodes.map(copiedNodePayload(for:)),
            internalConnections: internalConnections,
            anchorPosition: anchorPosition
        )
    }

    private func expandedClipboardNodeIDs(for rootNodeIDs: Set<GraphNode.ID>) -> Set<GraphNode.ID> {
        var visited = rootNodeIDs
        var stack = Array(rootNodeIDs)
        while let nodeID = stack.popLast() {
            if let settings = macroNodeSettings[nodeID] {
                for childNodeID in settings.childNodeIDs where visited.insert(childNodeID).inserted {
                    stack.append(childNodeID)
                }
            }
            if let settings = iteratorNodeSettings[nodeID] {
                for childNodeID in settings.childNodeIDs where visited.insert(childNodeID).inserted {
                    stack.append(childNodeID)
                }
            }
        }
        return visited
    }

    private func pasteCopiedSelection(_ payload: CopiedSelectionPayload, offset: CGPoint) {
        var oldToNewNodeIDs: [GraphNode.ID: GraphNode.ID] = [:]
        var oldToNewPortIDs: [GraphPort.ID: GraphPort.ID] = [:]
        var pastedNodeIDs: [GraphNode.ID] = []

        for copiedNode in payload.nodes {
            let relativePosition = CGPoint(
                x: copiedNode.node.position.x - payload.anchorPosition.x,
                y: copiedNode.node.position.y - payload.anchorPosition.y
            )
            let pastedPosition = CGPoint(
                x: payload.anchorPosition.x + offset.x + relativePosition.x,
                y: payload.anchorPosition.y + offset.y + relativePosition.y
            )
            guard let newNodeID = instantiateCopiedNode(copiedNode, at: pastedPosition, attachToActiveContainer: false),
                  let newNode = node(withID: newNodeID) else {
                continue
            }
            oldToNewNodeIDs[copiedNode.node.id] = newNodeID
            pastedNodeIDs.append(newNodeID)
            if case .macro = copiedNode.node.kind {
                continue
            }
            if case .iterator = copiedNode.node.kind {
                continue
            }
            for (oldPort, newPort) in zip(copiedNode.node.allPorts, newNode.allPorts) {
                oldToNewPortIDs[oldPort.id] = newPort.id
            }
        }

        guard pastedNodeIDs.isEmpty == false else { return }

        finalizeCopiedContainers(
            payload.nodes,
            oldToNewNodeIDs: oldToNewNodeIDs,
            oldToNewPortIDs: &oldToNewPortIDs
        )

        for pastedNodeID in pastedNodeIDs {
            attachNodeToActiveContainerIfNeeded(pastedNodeID)
        }

        var updatedDocument = document
        updatedDocument.connections.append(contentsOf: payload.internalConnections.compactMap { connection in
            guard let newFromPortID = oldToNewPortIDs[connection.fromPortID],
                  let newToPortID = oldToNewPortIDs[connection.toPortID],
                  oldToNewNodeIDs[connection.fromNodeID] != nil,
                  oldToNewNodeIDs[connection.toNodeID] != nil else {
                return nil
            }
            return GraphConnection(fromPortID: newFromPortID, toPortID: newToPortID)
        })
        document = updatedDocument
        selectedNodeIDs = Set(pastedNodeIDs)
        selectedNodeID = pastedNodeIDs.first
        statusMessage = pastedNodeIDs.count == 1
            ? "Pasted 1 node."
            : "Pasted \(pastedNodeIDs.count) nodes."
    }

    private func finalizeCopiedContainers(
        _ copiedNodes: [CopiedNodePayload],
        oldToNewNodeIDs: [GraphNode.ID: GraphNode.ID],
        oldToNewPortIDs: inout [GraphPort.ID: GraphPort.ID]
    ) {
        var pending = copiedNodes.filter {
            if case .macro = $0.node.kind { return true }
            if case .iterator = $0.node.kind { return true }
            return false
        }

        while pending.isEmpty == false {
            var madeProgress = false
            var remaining: [CopiedNodePayload] = []

            for copiedNode in pending {
                let publishedInternalPortIDs: [GraphPort.ID]
                switch copiedNode.node.kind {
                case .macro:
                    publishedInternalPortIDs = (copiedNode.macroSettings?.publishedInputs.map(\.internalPortID) ?? [])
                        + (copiedNode.macroSettings?.publishedOutputs.map(\.internalPortID) ?? [])
                case .iterator:
                    publishedInternalPortIDs = (copiedNode.iteratorSettings?.publishedInputs.map(\.internalPortID) ?? [])
                        + (copiedNode.iteratorSettings?.publishedOutputs.map(\.internalPortID) ?? [])
                default:
                    publishedInternalPortIDs = []
                }

                let canFinalize = publishedInternalPortIDs.allSatisfy { oldToNewPortIDs[$0] != nil }
                if canFinalize == false {
                    remaining.append(copiedNode)
                    continue
                }

                madeProgress = true

                switch copiedNode.node.kind {
                case .macro:
                    guard let oldSettings = copiedNode.macroSettings,
                          let newNodeID = oldToNewNodeIDs[copiedNode.node.id] else { continue }
                    let newSettings = MacroNodeSettings(
                        childNodeIDs: oldSettings.childNodeIDs.compactMap { oldToNewNodeIDs[$0] },
                        publishedInputs: oldSettings.publishedInputs.map { published in
                            MacroPublishedPortSettings(
                                macroPortID: "macro:\(newNodeID.uuidString):input:\(UUID().uuidString)",
                                internalPortID: oldToNewPortIDs[published.internalPortID] ?? published.internalPortID,
                                name: published.name,
                                kind: published.kind,
                                isPublished: published.isPublished
                            )
                        },
                        publishedOutputs: oldSettings.publishedOutputs.map { published in
                            MacroPublishedPortSettings(
                                macroPortID: "macro:\(newNodeID.uuidString):output:\(UUID().uuidString)",
                                internalPortID: oldToNewPortIDs[published.internalPortID] ?? published.internalPortID,
                                name: published.name,
                                kind: published.kind,
                                isPublished: published.isPublished
                            )
                        }
                    )
                    macroNodeSettings[newNodeID] = newSettings
                    rebuildMacroNodePorts(for: newNodeID)
                    for (oldPublished, newPublished) in zip(oldSettings.publishedInputs, newSettings.publishedInputs) {
                        oldToNewPortIDs[oldPublished.macroPortID] = newPublished.macroPortID
                    }
                    for (oldPublished, newPublished) in zip(oldSettings.publishedOutputs, newSettings.publishedOutputs) {
                        oldToNewPortIDs[oldPublished.macroPortID] = newPublished.macroPortID
                    }
                case .iterator:
                    guard let oldSettings = copiedNode.iteratorSettings,
                          let newNodeID = oldToNewNodeIDs[copiedNode.node.id] else { continue }
                    let newSettings = IteratorNodeSettings(
                        childNodeIDs: oldSettings.childNodeIDs.compactMap { oldToNewNodeIDs[$0] },
                        publishedInputs: oldSettings.publishedInputs.map { published in
                            MacroPublishedPortSettings(
                                macroPortID: "iterator:\(newNodeID.uuidString):input:\(UUID().uuidString)",
                                internalPortID: oldToNewPortIDs[published.internalPortID] ?? published.internalPortID,
                                name: published.name,
                                kind: published.kind,
                                isPublished: published.isPublished
                            )
                        },
                        publishedOutputs: oldSettings.publishedOutputs.map { published in
                            MacroPublishedPortSettings(
                                macroPortID: "iterator:\(newNodeID.uuidString):output:\(UUID().uuidString)",
                                internalPortID: oldToNewPortIDs[published.internalPortID] ?? published.internalPortID,
                                name: published.name,
                                kind: published.kind,
                                isPublished: published.isPublished
                            )
                        },
                        iterations: oldSettings.iterations
                    )
                    iteratorNodeSettings[newNodeID] = newSettings
                    rebuildIteratorNodePorts(for: newNodeID)
                    for (oldPublished, newPublished) in zip(oldSettings.publishedInputs, newSettings.publishedInputs) {
                        oldToNewPortIDs[oldPublished.macroPortID] = newPublished.macroPortID
                    }
                    for (oldPublished, newPublished) in zip(oldSettings.publishedOutputs, newSettings.publishedOutputs) {
                        oldToNewPortIDs[oldPublished.macroPortID] = newPublished.macroPortID
                    }
                default:
                    break
                }
            }

            if madeProgress == false {
                break
            }
            pending = remaining
        }
    }

