    @discardableResult
    private func instantiateDuplicatedUniformNode(_ uniform: UniformDescriptor, title: String, at position: CGPoint) -> GraphNode.ID {
        let nodeID = UUID()
        let outputPort = GraphPort(
            id: "uniform:\(nodeID.uuidString):\(uniform.name)",
            nodeID: nodeID,
            name: uniform.name,
            direction: .output,
            kind: .uniform(uniform.id)
        )
        let newNode = GraphNode(
            id: nodeID,
            title: title,
            kind: .uniform(uniform),
            position: position,
            inputPorts: [],
            outputPorts: [outputPort]
        )
        var updatedDocument = document
        updatedDocument.nodes.append(newNode)
        document = updatedDocument
        selectedNodeID = nodeID
        selectedNodeIDs = [nodeID]
        inspectorFocusTarget = .nodeLibrary
        statusMessage = "Pasted \(title)."
        return nodeID
    }

