    var selectedFragmentNode: GraphNode? {
        guard let selectedNode else { return nil }

        switch selectedNode.kind {
        case .metalFragment:
            return selectedNode
        case .renderOutput:
            guard let connectedFragmentID = connectedFragmentNodeID(forRenderNodeID: selectedNode.id) else {
                return primaryFragmentNode
            }
            return document.nodes.first(where: { $0.id == connectedFragmentID })
        case .uniform, .time, .mouse, .keyboard, .pointSplit, .pointCombine, .point3Split, .point3Combine, .point4Split, .point4Combine, .pointInterpolate, .point3Interpolate, .point4Interpolate, .pointScale, .point3Scale, .point4Scale, .colorSplit, .scroll, .handTracker, .pinch, .scrollGesture, .zoomGesture, .trackball, .depthEstimate, .math, .expression, .clamp, .mapRange, .logic, .compare, .random, .pulse, .fireOnLoad, .counter, .toggle, .delay, .timer, .scalarVariable, .stringVariable, .colorVariable, .scalarArrayVariable, .stringArrayVariable, .colorArrayVariable, .imageArrayVariable, .string, .stringFormat, .stringCompare, .stringSplit, .color, .hslColor, .scalarArray, .stringArray, .colorArray, .imageArray, .scalarArrayIndex, .stringArrayIndex, .colorArrayIndex, .imageArrayIndex, .arrayCount, .textImage, .audio, .beatDetect, .slider, .sliderStyle, .button, .buttonStyle, .polar, .hitZone, .rectHit, .screenSize, .screenBounds, .renderBounds, .renderWindow, .gridLayout, .scalarMultiplexor, .stringMultiplexor, .colorMultiplexor, .imageMultiplexor, .macro, .iterator, .iteratorVariables, .midiOut, .midiCC, .midiCCInput, .midiNoteInput, .oscInput, .oscOutput, .oscReceive, .oscSend, .oscGet4, .oscGetArray, .oscMake4, .oscMakeArray, .oscBundle, .note, .transform, .billboard, .line, .scene3DTransform, .scene3DTile, .scene3DRender, .scene3DLight, .scene3DMaterial, .scene3DPrimitive, .scene3DText, .scene3DModel, .scene3DGaussianSplat, .scene3DParticle, .select, .scalarSwitch, .stringSwitch, .colorSwitch, .transition, .circle, .clear, .image, .webView, .aiImage, .videoPlayer, .video, .coreImage, .blur, .bloom, .hueRotate, .posterize, .levels, .glow, .underwater, .feedback, .reactionDiffusion, .scale, .interpolator, .hold, .scalarSmooth, .trail, .monitor, .mix, .layers:
            return primaryFragmentNode
        }
    }

    var selectedFragmentTitle: String {
        if let codeEditorFragmentNode {
            return codeEditorFragmentNode.title
        }
        return selectedFragmentNode?.title ?? "Metal Fragment"
    }

    private var codeEditorFragmentNode: GraphNode? {
        guard let codeEditorFragmentNodeID else { return nil }
        return document.nodes.first(where: { $0.id == codeEditorFragmentNodeID })
    }

    var activePreviewRenderNodeID: GraphNode.ID? {
        if let selectedNode,
           case .renderOutput = selectedNode.kind {
            return selectedNode.id
        }

        return renderNode?.id
    }

    var hasAuxiliaryWindowsVisible: Bool {
        isPreviewVisible || isCodeEditorVisible || webViewWindowControllers.values.contains(where: \.isVisible)
    }

    func selectNode(_ nodeID: GraphNode.ID) {
        selectedNodeID = nodeID
        syncEditableMetalSourceWithSelection()
        updateInspectorFocus()
        validateMetalSource()
    }

    func selectNode(matching title: String) {
        selectedNodeID = document.nodes.first(where: { $0.title == title })?.id
        syncEditableMetalSourceWithSelection()
        updateInspectorFocus()
        validateMetalSource()
    }

    func currentUniform(matching id: UniformDescriptor.ID) -> UniformDescriptor? {
        document.uniforms.first(where: { $0.id == id })
    }

    func currentUniform(named name: String) -> UniformDescriptor? {
        document.uniforms.first(where: { $0.name == name })
    }

    func displayValue(for uniform: UniformDescriptor) -> String {
        currentUniform(matching: uniform.id)?.displayValue ?? uniform.displayValue
    }

    func fragmentUniforms(for fragmentNodeID: GraphNode.ID) -> [UniformDescriptor] {
        guard let fragmentNode = document.nodes.first(where: { $0.id == fragmentNodeID }) else {
            return []
        }

        var orderedUniforms: [UniformDescriptor] = []
        for inputPort in fragmentNode.inputPorts {
            switch inputPort.kind {
            case .uniform(let uniformID):
                if let uniform = currentUniform(matching: uniformID) {
                    orderedUniforms.append(uniform)
                }
            case .fragmentShader:
                orderedUniforms.append(imageUniformDescriptor(for: inputPort))
            default:
                break
            }
        }

        return orderedUniforms
    }

    private func imageUniformDescriptor(for inputPort: GraphPort) -> UniformDescriptor {
        if let uniform = currentUniform(named: inputPort.name), uniform.kind == .image {
            return uniform
        }

        return UniformDescriptor(
            name: inputPort.name,
            kind: .image,
            defaultValue: .image("Texture"),
            minValue: nil,
            maxValue: nil,
            label: nil
        )
    }

    func metalSource(for fragmentNodeID: GraphNode.ID) -> String {
        fragmentMetalSources[fragmentNodeID] ?? fragmentMetalSources[primaryFragmentNode?.id ?? fragmentNodeID] ?? editableMetalSource
    }

    func updateMetalSource(_ source: String, for fragmentNodeID: GraphNode.ID) {
        fragmentMetalSources[fragmentNodeID] = source
        if selectedFragmentNode?.id == fragmentNodeID {
            setEditableMetalSourceProgrammatically(source)
        }
        validateMetalSource()
    }

    func updateEditableMetalSourceFromEditor(_ source: String) {
        guard editableMetalSource != source else { return }
        editableMetalSource = source

        let targetFragmentNodeID = codeEditorFragmentNodeID
            ?? selectedFragmentNode?.id
            ?? primaryFragmentNode?.id
        guard let targetFragmentNodeID else {
            validateMetalSource()
            return
        }

        fragmentMetalSources[targetFragmentNodeID] = source
        document = syncFragmentNodePorts(in: document)
        validateMetalSource()
    }

    func runtimePreviewShaderSource(for metalSource: String, uniforms: [UniformDescriptor] = []) -> String {
        let alphaSafeMetalSource = metalSource
            .replacingOccurrences(of: "return float4(color, src.a);", with: "return float4(color, previewVisibleAlpha(src));")
            .replacingOccurrences(of: "return float4(color, current.a);", with: "return float4(color, previewVisibleAlpha(current));")
            .replacingOccurrences(of: "return float4(moshed, current.a);", with: "return float4(moshed, previewVisibleAlpha(current));")
            .replacingOccurrences(of: "return float4(melted, current.a);", with: "return float4(melted, previewVisibleAlpha(current));")
        let imageUniforms = uniforms.filter { $0.kind == .image }
        let needsPoint3Uniforms = uniforms.contains { $0.kind == .float3 } && alphaSafeMetalSource.contains("point3Uniforms") == false
        let needsPoint4Uniforms = uniforms.contains { $0.kind == .float4 } && alphaSafeMetalSource.contains("point4Uniforms") == false
        let imageAliasLines = imageUniforms.flatMap { uniform -> [String] in
            let lowercased = uniform.name.prefix(1).lowercased() + uniform.name.dropFirst()
            guard lowercased != uniform.name else { return [] }
            return [
                "#define \(lowercased) \(uniform.name)",
                "#define \(lowercased)Sampler \(uniform.name)Sampler"
            ]
        }.joined(separator: "\n")
        let extraParameters = ([needsPoint3Uniforms ? ",\n                                  constant float3* point3Uniforms [[buffer(5)]]" : nil,
                                needsPoint4Uniforms ? ",\n                                  constant float4* point4Uniforms [[buffer(6)]]" : nil]
            + imageUniforms.enumerated().map { index, uniform in
                ",\n                                  texture2d<float> \(uniform.name) [[texture(\(index))]],\n                                  sampler \(uniform.name)Sampler [[sampler(\(index))]]"
            })
            .compactMap { $0 }
            .joined()

        let fragmentSource: String
        if extraParameters.isEmpty {
            fragmentSource = alphaSafeMetalSource
        } else if alphaSafeMetalSource.contains("[[sampler(") || alphaSafeMetalSource.contains("[[texture(") {
            fragmentSource = alphaSafeMetalSource
        } else if alphaSafeMetalSource.contains("constant float4* point4Uniforms [[buffer(6)]])") {
            fragmentSource = alphaSafeMetalSource.replacingOccurrences(
                of: "constant float4* point4Uniforms [[buffer(6)]])",
                with: "constant float4* point4Uniforms [[buffer(6)]]\(extraParameters))"
            )
        } else if alphaSafeMetalSource.contains("constant float3* point3Uniforms [[buffer(5)]])") {
            fragmentSource = alphaSafeMetalSource.replacingOccurrences(
                of: "constant float3* point3Uniforms [[buffer(5)]])",
                with: "constant float3* point3Uniforms [[buffer(5)]]\(extraParameters))"
            )
        } else {
            fragmentSource = alphaSafeMetalSource.replacingOccurrences(
                of: "constant uint* boolUniforms [[buffer(4)]])",
                with: "constant uint* boolUniforms [[buffer(4)]]\(extraParameters))"
            )
        }

        return """
        #include <metal_stdlib>
        using namespace metal;

        struct RasterizerData {
            float4 position [[position]];
            float2 uv;
        };

        struct PreviewUniforms {
            float2 resolution;
            float time;
            float4 date;
        };

        float previewLuminance(float3 c) {
            return dot(c, float3(0.299, 0.587, 0.114));
        }

        float previewVisibleAlpha(float4 c) {
            return max(c.a, smoothstep(0.002, 0.04, previewLuminance(c.rgb)));
        }

        \(imageAliasLines)

        \(fragmentSource)

        vertex RasterizerData previewVertex(uint vertexID [[vertex_id]],
                                           constant PreviewUniforms& uniforms [[buffer(0)]]) {
            float2 positions[4] = {
                float2(-1.0, -1.0),
                float2(1.0, -1.0),
                float2(-1.0, 1.0),
                float2(1.0, 1.0)
            };

            float2 uvs[4] = {
                float2(0.0, 1.0),
                float2(1.0, 1.0),
                float2(0.0, 0.0),
                float2(1.0, 0.0)
            };

            RasterizerData out;
            out.position = float4(positions[vertexID], 0.0, 1.0);
            out.uv = uvs[vertexID];
            return out;
        }
        """
    }

    func previewConfiguration(forRenderNodeID renderNodeID: GraphNode.ID?) -> PreviewRenderConfiguration {
        guard let renderNodeID else {
            let uniforms = document.uniforms
            return .single(PreviewShaderPass(
                metalSource: runtimePreviewShaderSource(for: editableMetalSource, uniforms: uniforms),
                uniforms: uniforms,
                imageUniformSources: Array(repeating: nil, count: uniforms.filter { $0.kind == .image }.count)
            ))
        }

        return previewConfigurationForOutputNode(renderNodeID: renderNodeID) ?? .empty
    }

