    private func oscReceivePacketValue(for nodeID: GraphNode.ID) -> OSCPacketValue? {
        let settings = settings(forOSCInputNodeID: nodeID)
        return oscInputRouter.latestPacket(port: settings.port, address: settings.address)
    }

    private func oscGetPacketValue(for nodeID: GraphNode.ID) -> OSCPacketValue? {
        guard
            let node = document.nodes.first(where: { $0.id == nodeID }),
            let inputPort = node.inputPorts.first(where: { $0.name == "Packet" })
        else {
            return nil
        }

        return resolvedOSCPacketValue(forInputPortID: inputPort.id)
    }

    private func oscMakePacketValue(for nodeID: GraphNode.ID) -> OSCPacketValue? {
        guard let node = document.nodes.first(where: { $0.id == nodeID }) else { return nil }
        let settings = settings(forOSCMessageNodeID: nodeID)
        let values = oscOutputValues(for: node, prefix: "")
        guard values.isEmpty == false else { return nil }
        return OSCPacketValue(messages: [OSCMessageValue(address: normalizedOSCAddress(settings.address), arguments: values)])
    }

    private func oscMakeArrayPacketValue(for nodeID: GraphNode.ID) -> OSCPacketValue? {
        guard
            let node = document.nodes.first(where: { $0.id == nodeID }),
            let inputPort = node.inputPorts.first(where: { $0.name == "Array" })
        else {
            return nil
        }
        let settings = settings(forOSCMessageNodeID: nodeID)
        let values = scalarArrayValue(forInputPortID: inputPort.id, visitedNodeIDs: [nodeID]) ?? []
        let arguments = values.map { OSCValue.float(Float($0)) }
        return OSCPacketValue(messages: [OSCMessageValue(address: normalizedOSCAddress(settings.address), arguments: arguments)])
    }

    private func oscBundlePacketValue(for nodeID: GraphNode.ID) -> OSCPacketValue? {
        guard let node = document.nodes.first(where: { $0.id == nodeID }) else { return nil }
        let settings = settings(forOSCBundleNodeID: nodeID)
        let packets = node.inputPorts.prefix(settings.packetCount).compactMap { resolvedOSCPacketValue(forInputPortID: $0.id) }
        let messages = packets.flatMap(\.messages)
        guard messages.isEmpty == false else { return nil }
        return OSCPacketValue(messages: messages, forceBundle: messages.count > 1 || packets.count > 1)
    }

    private func oscPacketValueForOutputPort(_ outputPort: GraphPort) -> OSCPacketValue? {
        guard case .oscPacketSignal = outputPort.kind else { return nil }
        guard let sourceNode = document.nodes.first(where: { $0.id == outputPort.nodeID }) else { return nil }

        switch sourceNode.kind {
        case .oscReceive:
            return oscReceivePacketValue(for: sourceNode.id)
        case .oscMake4:
            return oscMakePacketValue(for: sourceNode.id)
        case .oscMakeArray:
            return oscMakeArrayPacketValue(for: sourceNode.id)
        case .oscBundle:
            return oscBundlePacketValue(for: sourceNode.id)
        default:
            return nil
        }
    }

    private func resolvedOSCPacketValue(forInputPortID portID: GraphPort.ID) -> OSCPacketValue? {
        guard
            let connection = effectiveIncomingConnection(for: portID),
            let sourcePort = resolvedSourcePort(for: connection.fromPortID)
        else {
            return nil
        }

        return oscPacketValueForOutputPort(sourcePort)
    }

    private func oscArgument(in packet: OSCPacketValue?, at index: Int) -> OSCValue? {
        guard let message = packet?.messages.first, message.arguments.indices.contains(index) else { return nil }
        return message.arguments[index]
    }

    private func oscAddress(in packet: OSCPacketValue?) -> String? {
        packet?.messages.first?.address
    }

    private func oscNumericArguments(in packet: OSCPacketValue?) -> [Double]? {
        guard let message = packet?.messages.first else { return nil }
        return message.arguments.compactMap { argument in
            switch argument {
            case .float(let value):
                return Double(value)
            case .int(let value):
                return Double(value)
            case .string:
                return nil
            }
        }
    }

    private func oscArgument(in message: OSCInputRouter.Message, at index: Int) -> OSCValue? {
        guard message.arguments.indices.contains(index) else { return nil }
        return message.arguments[index]
    }

    private func evaluateBeatDetect(for nodeID: GraphNode.ID) -> BeatDetectNodeRuntimeState {
        let settings = settings(forBeatDetectNodeID: nodeID)
        let frameID = evaluationFrameID
        var runtime = beatDetectNodeRuntimeStates[nodeID] ?? BeatDetectNodeRuntimeState()

        if runtime.lastEvaluatedFrame == frameID {
            return runtime
        }

        let spectrum = audioMonitor.spectrumValues()
        guard spectrum.isEmpty == false else {
            runtime = updateBeatDetectRuntime(
                runtime: runtime,
                frameID: frameID,
                kickIsHigh: false,
                snareIsHigh: false,
                kickLevel: 0.0,
                snareLevel: 0.0,
                kickEnergy: 0.0,
                snareEnergy: 0.0
            )
            beatDetectNodeRuntimeStates[nodeID] = runtime
            return runtime
        }

        let amplitude = audioValue(for: .amplitude)
        let low = audioValue(for: .low)
        let mid = audioValue(for: .mid)
        let high = audioValue(for: .high)

        let kickBands = average(spectrum.prefix(min(24, spectrum.count)))
        let snareStart = min(48, spectrum.count)
        let snareEnd = min(144, spectrum.count)
        let snareBands = snareStart < snareEnd ? average(spectrum[snareStart..<snareEnd]) : 0.0

        let kickEnergy = max(0.0, (low * 0.9) + (kickBands * 1.1) + (amplitude * 0.25) - (mid * 0.28))
        let snareEnergy = max(0.0, (high * 0.65) + (snareBands * 1.0) + (mid * 0.25) + (amplitude * 0.12) - (low * 0.22))

        let kickOnset = max(0.0, kickEnergy - runtime.previousKickEnergy)
        let snareOnset = max(0.0, snareEnergy - runtime.previousSnareEnergy)

        let kickLevel = kickOnset * settings.kickSensitivity
        let snareLevel = snareOnset * settings.snareSensitivity

        let kickCooldownPassed = runtime.lastKickFrame.map { frameID - $0 >= 6 } ?? true
        let snareCooldownPassed = runtime.lastSnareFrame.map { frameID - $0 >= 4 } ?? true

        let kickIsHigh =
            kickCooldownPassed &&
            kickEnergy > 0.08 &&
            kickLevel >= settings.kickThreshold &&
            kickOnset >= (snareOnset * 0.65)
        let snareIsHigh =
            snareCooldownPassed &&
            snareEnergy > 0.05 &&
            snareLevel >= settings.snareThreshold &&
            snareOnset >= (kickOnset * 0.35)
        runtime = updateBeatDetectRuntime(
            runtime: runtime,
            frameID: frameID,
            kickIsHigh: kickIsHigh,
            snareIsHigh: snareIsHigh,
            kickLevel: kickLevel,
            snareLevel: snareLevel,
            kickEnergy: kickEnergy,
            snareEnergy: snareEnergy
        )
        beatDetectNodeRuntimeStates[nodeID] = runtime
        return runtime
    }

    private func average<S: Sequence>(_ values: S) -> Double where S.Element == Double {
        var total = 0.0
        var count = 0.0
        for value in values {
            total += value
            count += 1.0
        }
        guard count > 0 else { return 0.0 }
        return total / count
    }

    private func updateBeatDetectRuntime(
        runtime: BeatDetectNodeRuntimeState,
        frameID: Int,
        kickIsHigh: Bool,
        snareIsHigh: Bool,
        kickLevel: Double,
        snareLevel: Double,
        kickEnergy: Double,
        snareEnergy: Double
    ) -> BeatDetectNodeRuntimeState {
        var runtime = runtime
        let kickPulse = kickIsHigh
        let snarePulse = snareIsHigh

        if kickPulse {
            runtime.lastKickFrame = frameID
        }

        if snarePulse {
            runtime.lastSnareFrame = frameID
        }

        runtime.previousKickEnergy = kickEnergy
        runtime.previousSnareEnergy = snareEnergy
        runtime.kickLevel = kickLevel
        runtime.snareLevel = snareLevel
        runtime.kickPulse = runtime.lastKickFrame == frameID
        runtime.snarePulse = runtime.lastSnareFrame == frameID
        runtime.lastEvaluatedFrame = frameID
        return runtime
    }

    func handPoint(isLeftHand: Bool) -> CGPoint? {
        if isLeftHand {
            return videoMonitor.handSnapshot.leftIndex
        }
        return videoMonitor.handSnapshot.rightIndex
    }

    func thumbPoint(isLeftHand: Bool) -> CGPoint? {
        if isLeftHand {
            return videoMonitor.handSnapshot.leftThumb
        }
        return videoMonitor.handSnapshot.rightThumb
    }

    func handTrackedValue(isLeftHand: Bool) -> Double {
        let point = isLeftHand ? videoMonitor.handSnapshot.leftIndex : videoMonitor.handSnapshot.rightIndex
        return point == nil ? 0.0 : 1.0
    }

    func isNodeHiddenByMacro(_ nodeID: GraphNode.ID) -> Bool {
        macroNodeSettings.values.contains { $0.childNodeIDs.contains(nodeID) }
        || iteratorNodeSettings.values.contains { $0.childNodeIDs.contains(nodeID) }
    }

    func isConnectionHiddenByMacro(_ connection: GraphConnection) -> Bool {
        guard
            let sourcePort = port(withID: connection.fromPortID),
            let targetPort = port(withID: connection.toPortID)
        else {
            return false
        }
        return isNodeHiddenByMacro(sourcePort.nodeID) || isNodeHiddenByMacro(targetPort.nodeID)
    }

    func isNodeVisibleOnCanvas(_ nodeID: GraphNode.ID) -> Bool {
        if let editingMacroNodeID,
           let settings = macroNodeSettings[editingMacroNodeID] {
            return settings.childNodeIDs.contains(nodeID)
        }
        if let editingIteratorNodeID,
           let settings = iteratorNodeSettings[editingIteratorNodeID] {
            return settings.childNodeIDs.contains(nodeID)
        }
        return !isNodeHiddenByMacro(nodeID)
    }

    func isConnectionVisibleOnCanvas(_ connection: GraphConnection) -> Bool {
        guard let sourcePort = port(withID: connection.fromPortID),
              let targetPort = port(withID: connection.toPortID) else {
            return false
        }
        if let editingMacroNodeID,
           let settings = macroNodeSettings[editingMacroNodeID] {
            let visibleNodeIDs = Set(settings.childNodeIDs)
            return visibleNodeIDs.contains(sourcePort.nodeID) && visibleNodeIDs.contains(targetPort.nodeID)
        }
        if let editingIteratorNodeID,
           let settings = iteratorNodeSettings[editingIteratorNodeID] {
            let visibleNodeIDs = Set(settings.childNodeIDs)
            return visibleNodeIDs.contains(sourcePort.nodeID) && visibleNodeIDs.contains(targetPort.nodeID)
        }
        return !isConnectionHiddenByMacro(connection)
    }

    private func macroPublishedPortKind(for kind: GraphPortKind) -> MacroPublishedPortKind? {
        switch kind {
        case .fragmentShader:
            return .fragmentShader
        case .lightSignal(let signal):
            return .scalarSignal(signal)
        case .materialSignal(let signal):
            return .materialSignal(signal)
        case .oscPacketSignal(let signal):
            return .oscPacketSignal(signal)
        case .pointSignal(let signal):
            return .pointSignal(signal)
        case .point3Signal(let signal):
            return .point3Signal(signal)
        case .point4Signal(let signal):
            return .point4Signal(signal)
        case .audio(let signal):
            return .audio(signal)
        case .scalarSignal(let signal):
            return .scalarSignal(signal)
        case .stringSignal(let signal):
            return .stringSignal(signal)
        case .colorSignal(let signal):
            return .colorSignal(signal)
        case .scalarArraySignal(let signal):
            return .scalarArraySignal(signal)
        case .stringArraySignal(let signal):
            return .stringArraySignal(signal)
        case .colorArraySignal(let signal):
            return .colorArraySignal(signal)
        case .imageArraySignal(let signal):
            return .imageArraySignal(signal)
        case .scene3DSignal, .uniform, .time, .sliderStyle, .buttonStyle:
            return nil
        }
    }

    func canPublishPort(_ port: GraphPort) -> Bool {
        macroPublishedPortKind(for: port.kind) != nil
    }

    private func graphPortKind(for kind: MacroPublishedPortKind) -> GraphPortKind {
        switch kind {
        case .fragmentShader:
            return .fragmentShader
        case .materialSignal(let signal):
            return .materialSignal(signal)
        case .oscPacketSignal(let signal):
            return .oscPacketSignal(signal)
        case .pointSignal(let signal):
            return .pointSignal(signal)
        case .point3Signal(let signal):
            return .point3Signal(signal)
        case .point4Signal(let signal):
            return .point4Signal(signal)
        case .scalarSignal(let signal):
            return .scalarSignal(signal)
        case .stringSignal(let signal):
            return .stringSignal(signal)
        case .colorSignal(let signal):
            return .colorSignal(signal)
        case .scalarArraySignal(let signal):
            return .scalarArraySignal(signal)
        case .stringArraySignal(let signal):
            return .stringArraySignal(signal)
        case .colorArraySignal(let signal):
            return .colorArraySignal(signal)
        case .imageArraySignal(let signal):
            return .imageArraySignal(signal)
        case .audio(let signal):
            return .audio(signal)
        }
    }

    private func macroPublishedInputMapping(for internalPortID: GraphPort.ID) -> MacroPublishedPortSettings? {
        macroNodeSettings.values.lazy.compactMap { settings in
            settings.publishedInputs.first(where: { $0.internalPortID == internalPortID && $0.isPublished })
        }.first
    }

    private func iteratorPublishedInputMapping(for internalPortID: GraphPort.ID, iteratorNodeID: GraphNode.ID? = nil) -> MacroPublishedPortSettings? {
        let settingsList: [IteratorNodeSettings]
        if let iteratorNodeID, let settings = iteratorNodeSettings[iteratorNodeID] {
            settingsList = [settings]
        } else {
            settingsList = Array(iteratorNodeSettings.values)
        }
        return settingsList.lazy.compactMap { settings in
            settings.publishedInputs.first(where: { $0.internalPortID == internalPortID && $0.isPublished })
        }.first
    }

    private func macroPublishedOutputMapping(for macroPortID: GraphPort.ID) -> MacroPublishedPortSettings? {
        macroNodeSettings.values.lazy.compactMap { settings in
            settings.publishedOutputs.first(where: { $0.macroPortID == macroPortID && $0.isPublished })
        }.first
    }

    private func iteratorPublishedOutputMapping(for iteratorPortID: GraphPort.ID, iteratorNodeID: GraphNode.ID? = nil) -> MacroPublishedPortSettings? {
        let settingsList: [IteratorNodeSettings]
        if let iteratorNodeID, let settings = iteratorNodeSettings[iteratorNodeID] {
            settingsList = [settings]
        } else {
            settingsList = Array(iteratorNodeSettings.values)
        }
        return settingsList.lazy.compactMap { settings in
            settings.publishedOutputs.first(where: { $0.macroPortID == iteratorPortID && $0.isPublished })
        }.first
    }

    private func visiblePublishedInputs(for nodeID: GraphNode.ID) -> [MacroPublishedPortSettings] {
        (macroNodeSettings[nodeID]?.publishedInputs ?? []).filter(\.isPublished)
    }

    private func visiblePublishedOutputs(for nodeID: GraphNode.ID) -> [MacroPublishedPortSettings] {
        (macroNodeSettings[nodeID]?.publishedOutputs ?? []).filter(\.isPublished)
    }

    func isPortPublishedOnEditingContainer(_ port: GraphPort) -> Bool {
        if let editingMacroNodeID,
           let settings = macroNodeSettings[editingMacroNodeID] {
            switch port.direction {
            case .input:
                return settings.publishedInputs.contains(where: { $0.internalPortID == port.id && $0.isPublished })
            case .output:
                return settings.publishedOutputs.contains(where: { $0.internalPortID == port.id && $0.isPublished })
            }
        }
        if let editingIteratorNodeID,
           let settings = iteratorNodeSettings[editingIteratorNodeID] {
            switch port.direction {
            case .input:
                return settings.publishedInputs.contains(where: { $0.internalPortID == port.id && $0.isPublished })
            case .output:
                return settings.publishedOutputs.contains(where: { $0.internalPortID == port.id && $0.isPublished })
            }
        }
        return false
    }

    private func iteratorVisiblePublishedInputs(for settings: IteratorNodeSettings, nodeID: GraphNode.ID) -> [GraphPort] {
        let published = settings.publishedInputs.filter(\.isPublished)
        let iterationPort = GraphPort(
            id: "iterator:\(nodeID.uuidString):iterations",
            nodeID: nodeID,
            name: "Iterations",
            direction: .input,
            kind: .scalarSignal("iterations")
        )
        return [iterationPort] + published.map { published in
            GraphPort(
                id: published.macroPortID,
                nodeID: nodeID,
                name: published.name,
                direction: .input,
                kind: graphPortKind(for: published.kind)
            )
        }
    }

    private func iteratorVisiblePublishedOutputs(for settings: IteratorNodeSettings, nodeID: GraphNode.ID) -> [GraphPort] {
        settings.publishedOutputs.filter(\.isPublished).map { published in
            GraphPort(
                id: published.macroPortID,
                nodeID: nodeID,
                name: published.name,
                direction: .output,
                kind: graphPortKind(for: published.kind)
            )
        }
    }

