    private func rebuildMacroNodePorts(for nodeID: GraphNode.ID) {
        guard let index = document.nodes.firstIndex(where: { $0.id == nodeID }),
              case .macro = document.nodes[index].kind else {
            return
        }

        let node = document.nodes[index]
        let inputPorts = visiblePublishedInputs(for: nodeID).map { published in
            GraphPort(
                id: published.macroPortID,
                nodeID: nodeID,
                name: published.name,
                direction: .input,
                kind: graphPortKind(for: published.kind)
            )
        }
        let outputPorts = visiblePublishedOutputs(for: nodeID).map { published in
            GraphPort(
                id: published.macroPortID,
                nodeID: nodeID,
                name: published.name,
                direction: .output,
                kind: graphPortKind(for: published.kind)
            )
        }

        var updatedDocument = document
        updatedDocument.nodes[index] = GraphNode(
            id: node.id,
            title: node.title,
            kind: node.kind,
            position: node.position,
            inputPorts: inputPorts,
            outputPorts: outputPorts
        )
        let livePortIDs = Set(inputPorts.map(\.id) + outputPorts.map(\.id))
        updatedDocument.connections.removeAll { connection in
            let removesDeadMacroSource = connection.fromPortID.hasPrefix("macro:\(nodeID.uuidString):")
                && !livePortIDs.contains(connection.fromPortID)
            let removesDeadMacroTarget = connection.toPortID.hasPrefix("macro:\(nodeID.uuidString):")
                && !livePortIDs.contains(connection.toPortID)
            return removesDeadMacroSource || removesDeadMacroTarget
        }
        document = updatedDocument
    }

    private func rebuildIteratorNodePorts(for nodeID: GraphNode.ID) {
        guard let index = document.nodes.firstIndex(where: { $0.id == nodeID }),
              case .iterator = document.nodes[index].kind else {
            return
        }

        let node = document.nodes[index]
        let settings = iteratorNodeSettings[nodeID] ?? IteratorNodeSettings(childNodeIDs: [], publishedInputs: [], publishedOutputs: [], iterations: 4.0)
        let inputPorts = iteratorVisiblePublishedInputs(for: settings, nodeID: nodeID)
        let outputPorts = iteratorVisiblePublishedOutputs(for: settings, nodeID: nodeID)

        var updatedDocument = document
        updatedDocument.nodes[index] = GraphNode(
            id: node.id,
            title: node.title,
            kind: node.kind,
            position: node.position,
            inputPorts: inputPorts,
            outputPorts: outputPorts
        )
        let livePortIDs = Set(inputPorts.map(\.id) + outputPorts.map(\.id))
        updatedDocument.connections.removeAll { connection in
            let removesDeadIteratorSource = connection.fromPortID.hasPrefix("iterator:\(nodeID.uuidString):")
                && !livePortIDs.contains(connection.fromPortID)
            let removesDeadIteratorTarget = connection.toPortID.hasPrefix("iterator:\(nodeID.uuidString):")
                && !livePortIDs.contains(connection.toPortID)
            return removesDeadIteratorSource || removesDeadIteratorTarget
        }
        document = updatedDocument
    }

    private func effectiveIncomingConnection(for inputPortID: GraphPort.ID) -> GraphConnection? {
        if let direct = document.connections.first(where: { $0.toPortID == inputPortID }) {
            return direct
        }
        if let mapping = macroPublishedInputMapping(for: inputPortID) {
            return document.connections.first(where: { $0.toPortID == mapping.macroPortID })
        }
        if let iteratorContext = iteratorEvaluationStack.last,
           let mapping = iteratorPublishedInputMapping(for: inputPortID, iteratorNodeID: iteratorContext.iteratorNodeID) {
            return document.connections.first(where: { $0.toPortID == mapping.macroPortID })
        }
        return nil
    }

    private func resolvedSourcePort(for outputPortID: GraphPort.ID) -> GraphPort? {
        if let mapping = macroPublishedOutputMapping(for: outputPortID) {
            return port(withID: mapping.internalPortID)
        }
        if let iteratorContext = iteratorEvaluationStack.last,
           let mapping = iteratorPublishedOutputMapping(for: outputPortID, iteratorNodeID: iteratorContext.iteratorNodeID) {
            return port(withID: mapping.internalPortID)
        }
        return port(withID: outputPortID)
    }

