    func updateMousePosition(_ point: CGPoint?) {
        let clampedPoint = point.map {
            CGPoint(
                x: min(max($0.x, 0.0), 1.0),
                y: min(max($0.y, 0.0), 1.0)
            )
        }
        guard clampedPoint != currentMousePosition else { return }
        currentMousePosition = clampedPoint
        updateMIDINodes()
        objectWillChange.send()
    }

    func updateMouseButtons(left: Bool, right: Bool) {
        guard left != currentMouseLeftButtonDown || right != currentMouseRightButtonDown else { return }
        currentMouseLeftButtonDown = left
        currentMouseRightButtonDown = right
        objectWillChange.send()
    }

    func updatePreviewModifierFlags(_ flags: NSEvent.ModifierFlags) {
        let modifiers = relevantModifierFlags(from: flags)
        guard currentKeyboardModifierFlags != modifiers else { return }
        currentKeyboardModifierFlags = modifiers
        objectWillChange.send()
    }

    private func startKeyboardMonitoring() {
        guard keyboardKeyDownMonitor == nil, keyboardKeyUpMonitor == nil, keyboardFlagsChangedMonitor == nil else { return }
        keyboardKeyDownMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { [weak self] event in
            guard let self else { return event }
            guard !self.isTextEditingActive else { return event }
            let inserted = self.currentPressedKeyCodes.insert(event.keyCode).inserted
            let modifiers = self.relevantModifierFlags(from: event.modifierFlags)
            let modifiersChanged = self.currentKeyboardModifierFlags != modifiers
            self.currentKeyboardModifierFlags = modifiers
            if inserted || modifiersChanged {
                self.synchronizePreviewWindowControllers()
                self.objectWillChange.send()
            }
            return event
        }
        keyboardKeyUpMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyUp) { [weak self] event in
            guard let self else { return event }
            guard !self.isTextEditingActive else { return event }
            let removed = self.currentPressedKeyCodes.remove(event.keyCode) != nil
            let modifiers = self.relevantModifierFlags(from: event.modifierFlags)
            let modifiersChanged = self.currentKeyboardModifierFlags != modifiers
            self.currentKeyboardModifierFlags = modifiers
            if removed || modifiersChanged {
                self.synchronizePreviewWindowControllers()
                self.objectWillChange.send()
            }
            return event
        }
        keyboardFlagsChangedMonitor = NSEvent.addLocalMonitorForEvents(matching: .flagsChanged) { [weak self] event in
            guard let self else { return event }
            guard !self.isTextEditingActive else { return event }
            let modifiers = self.relevantModifierFlags(from: event.modifierFlags)
            guard self.currentKeyboardModifierFlags != modifiers else { return event }
            self.currentKeyboardModifierFlags = modifiers
            self.synchronizePreviewWindowControllers()
            self.objectWillChange.send()
            return event
        }
    }

    private func stopKeyboardMonitoring() {
        if let keyboardKeyDownMonitor {
            NSEvent.removeMonitor(keyboardKeyDownMonitor)
            self.keyboardKeyDownMonitor = nil
        }
        if let keyboardKeyUpMonitor {
            NSEvent.removeMonitor(keyboardKeyUpMonitor)
            self.keyboardKeyUpMonitor = nil
        }
        if let keyboardFlagsChangedMonitor {
            NSEvent.removeMonitor(keyboardFlagsChangedMonitor)
            self.keyboardFlagsChangedMonitor = nil
        }
    }

    private var isTextEditingActive: Bool {
        (NSApp.keyWindow?.firstResponder ?? NSApp.mainWindow?.firstResponder) is NSTextView
    }

    private func relevantModifierFlags(from flags: NSEvent.ModifierFlags) -> NSEvent.ModifierFlags {
        flags.intersection([.command, .option, .shift, .control])
    }

    func updateScrollDelta(_ delta: CGPoint) {
        guard delta != .zero else { return }
        lastScrollEventTime = CACurrentMediaTime()
        currentScrollPosition = CGPoint(
            x: currentScrollPosition.x + delta.x,
            y: currentScrollPosition.y + delta.y
        )
        objectWillChange.send()
    }

    private var isScrollActive: Bool {
        guard let lastScrollEventTime else { return false }
        return CACurrentMediaTime() - lastScrollEventTime < 0.35
    }

    func connectPorts(from outputPortID: GraphPort.ID, to inputPortID: GraphPort.ID) {
        guard
            let outputPort = port(withID: outputPortID),
            let inputPort = port(withID: inputPortID),
            outputPort.direction == .output,
            inputPort.direction == .input,
            portsAreCompatible(outputPort, inputPort)
        else {
            statusMessage = "Port types do not match."
            return
        }

        var updatedDocument = document
        updatedDocument.connections.removeAll { $0.toPortID == inputPortID }
        if case .uniform = outputPort.kind {
            updatedDocument.connections.removeAll { $0.fromPortID == outputPortID }
        }

        let connection = GraphConnection(fromPortID: outputPortID, toPortID: inputPortID)
        updatedDocument.connections.append(connection)
        document = updatedDocument
        statusMessage = "Connected \(outputPort.name) to \(inputPort.name)."
    }

    func canCreateVariableNode(forInputPortID inputPortID: GraphPort.ID) -> Bool {
        guard let inputPort = port(withID: inputPortID) else { return false }

        switch inputPort.kind {
        case .scalarSignal, .stringSignal, .colorSignal, .scalarArraySignal, .stringArraySignal, .colorArraySignal, .imageArraySignal:
            return true
        case .uniform(let uniformID):
            guard let uniform = currentUniform(matching: uniformID) else { return false }
            switch uniform.kind {
            case .float, .color, .point2D, .float3, .float4, .bool:
                return true
            case .image:
                return false
            }
        default:
            return false
        }
    }

    func makeVariableNode(forInputPortID inputPortID: GraphPort.ID) {
        guard
            let inputPort = port(withID: inputPortID),
            let targetNode = node(withID: inputPort.nodeID),
            canCreateVariableNode(forInputPortID: inputPortID)
        else {
            return
        }

        captureHistoryCheckpointNow()

        let inputIndex = targetNode.inputPorts.firstIndex(where: { $0.id == inputPortID }) ?? 0
        let basePosition = CGPoint(
            x: max(24.0, targetNode.position.x - 220.0),
            y: max(24.0, targetNode.position.y + CGFloat(inputIndex) * 26.0)
        )

        let previousNodeIDs = Set(document.nodes.map(\.id))
        let previousConnection = effectiveIncomingConnection(for: inputPortID)

        switch inputPort.kind {
        case .stringSignal:
            let initialValue = editableStringFallbackValue(forInputPortID: inputPortID) ?? ""
            addStringVariableNode(at: basePosition, title: inputPort.name, initialValue: initialValue)
        case .scalarSignal:
            let initialValue = editableScalarFallbackValue(forInputPortID: inputPortID) ?? 0.0
            addScalarVariableNode(at: basePosition, title: inputPort.name, initialValue: initialValue)
        case .uniform(let uniformID):
            addUniformNode(uniformID, at: basePosition)
            guard
                let newNodeID = selectedNodeID,
                let newNode = node(withID: newNodeID),
                let outputPort = newNode.outputPorts.first
            else {
                return
            }
            connectPorts(from: outputPort.id, to: inputPortID)
            selectedNodeID = newNodeID
            return
        case .colorSignal:
            addColorVariableNode(at: basePosition, title: inputPort.name)
        case .scalarArraySignal:
            addScalarArrayVariableNode(at: basePosition, title: inputPort.name)
        case .stringArraySignal:
            addStringArrayVariableNode(at: basePosition, title: inputPort.name)
        case .colorArraySignal:
            addColorArrayVariableNode(at: basePosition, title: inputPort.name)
        case .imageArraySignal:
            addImageArrayVariableNode(at: basePosition, title: inputPort.name)
        default:
            return
        }

        guard
            let newNodeID = selectedNodeID,
            previousNodeIDs.contains(newNodeID) == false,
            let newNode = node(withID: newNodeID),
            let outputPort = newNode.outputPorts.first
        else {
            return
        }

        attachNodeToActiveContainerIfNeeded(newNodeID)
        if let previousConnection,
           let inputPort = newNode.inputPorts.first {
            connectPorts(from: previousConnection.fromPortID, to: inputPort.id)
        }
        connectPorts(from: outputPort.id, to: inputPortID)
        selectedNodeID = newNodeID
    }

    func effectiveUniforms(for renderNodeID: GraphNode.ID?) -> [UniformDescriptor] {
        guard
            let renderNodeID,
            let fragmentNodeID = connectedFragmentNodeID(forRenderNodeID: renderNodeID)
        else {
            return document.uniforms
        }
        return effectiveUniforms(forFragmentNodeID: fragmentNodeID)
    }

    func saveSelectedFragmentShader() {
        commitPendingEditorState()
        guard let fragmentNode = selectedFragmentNode else {
            statusMessage = "Select a fragment node first."
            return
        }
        let filename = sanitizedFilename(fragmentNode.title) + ".metal"
        let text = metalSource(for: fragmentNode.id)
        presentSavePanel(
            suggestedName: filename,
            contentType: .plainText,
            text: text,
            successMessage: "Saved Metal shader to"
        )
    }

    func saveGraphSnapshot() {
        DispatchQueue.main.async { [weak self] in
            self?.performSaveGraphSnapshot()
        }
    }

    func saveGraphSnapshotAs() {
        DispatchQueue.main.async { [weak self] in
            self?.performSaveGraphSnapshotAs()
        }
    }

    private func performSaveGraphSnapshot() {
        suppressDirtyTracking = true
        commitPendingEditorState()
        do {
            if let currentGraphFileURL {
                let text = try currentGraphSnapshotText()
                try writeGraphText(text, to: currentGraphFileURL)
                rememberCurrentGraphFile(currentGraphFileURL)
                finalizeCurrentGraphSaveState(savedGraphText: text)
                statusMessage = "Saved graph snapshot to \(currentGraphFileURL.lastPathComponent)."
            } else {
                let text = try currentGraphSnapshotText()
                presentGraphSavePanel(with: text)
            }
        } catch {
            statusMessage = "Graph save failed: \(error.localizedDescription)"
        }
        DispatchQueue.main.async { [weak self] in
            self?.suppressDirtyTracking = false
        }
    }

    private func performSaveGraphSnapshotAs() {
        suppressDirtyTracking = true
        commitPendingEditorState()
        do {
            let text = try currentGraphSnapshotText()
            presentGraphSavePanel(with: text)
        } catch {
            statusMessage = "Graph save failed: \(error.localizedDescription)"
        }
        DispatchQueue.main.async { [weak self] in
            self?.suppressDirtyTracking = false
        }
    }

