    @discardableResult
    func togglePreviewWindowFullScreen() -> Bool {
        if let selectedNodeID,
           let controller = previewWindowControllers[selectedNodeID] {
            return controller.toggleFullScreen()
        }
        if let renderNodeID = activePreviewRenderNodeID,
           let controller = previewWindowControllers[renderNodeID] {
            return controller.toggleFullScreen()
        }
        return false
    }

    func addUniformNode(_ uniformID: UniformDescriptor.ID, at position: CGPoint) {
        guard let uniform = currentUniform(matching: uniformID) else { return }

        if let existingNode = document.nodes.first(where: { node in
            guard case .uniform(let nodeUniform) = node.kind else { return false }
            return nodeUniform.id == uniformID
        }) {
            selectedNodeID = existingNode.id
            statusMessage = "\(uniform.name) is already on the graph."
            updateInspectorFocus()
            return
        }

        let nodeID = UUID()
        let outputPort = GraphPort(
            id: "uniform:\(uniform.name)",
            nodeID: nodeID,
            name: uniform.name,
            direction: .output,
            kind: .uniform(uniform.id)
        )

        let newNode = GraphNode(
            id: nodeID,
            title: uniform.name,
            kind: .uniform(uniform),
            position: position,
            inputPorts: [],
            outputPorts: [outputPort]
        )

        var updatedDocument = document
        updatedDocument.nodes.append(newNode)

        if let inputPort = preferredAutoConnectInputPort(for: uniform.id) {
            updatedDocument.connections.removeAll { $0.toPortID == inputPort.id }
            updatedDocument.connections.append(GraphConnection(fromPortID: outputPort.id, toPortID: inputPort.id))
        }

        document = updatedDocument
        selectedNodeID = newNode.id
        syncEditableMetalSourceWithSelection()
        statusMessage = "Added \(uniform.name) to the graph."
        validateMetalSource()
        updateInspectorFocus()
    }

    func addTimeNode(at position: CGPoint) {
        if let existingNode = document.nodes.first(where: {
            if case .time = $0.kind { return true }
            return false
        }) {
            selectedNodeID = existingNode.id
            statusMessage = "Time is already on the graph."
            updateInspectorFocus()
            return
        }

        let nodeID = UUID()
        let outputPort = GraphPort(
            id: "time:output",
            nodeID: nodeID,
            name: "TIME",
            direction: .output,
            kind: .time
        )

        let newNode = GraphNode(
            id: nodeID,
            title: "Time",
            kind: .time,
            position: position,
            inputPorts: [],
            outputPorts: [outputPort]
        )

        var updatedDocument = document
        updatedDocument.nodes.append(newNode)
        for fragmentNode in updatedDocument.nodes {
            guard case .metalFragment = fragmentNode.kind else { continue }
            guard let inputPort = fragmentNode.inputPorts.first(where: { $0.kind == .time }) else { continue }
            updatedDocument.connections.removeAll { $0.toPortID == inputPort.id }
            updatedDocument.connections.append(GraphConnection(fromPortID: outputPort.id, toPortID: inputPort.id))
        }
        document = updatedDocument
        selectedNodeID = newNode.id
        syncEditableMetalSourceWithSelection()
        statusMessage = "Added Time to the graph."
        validateMetalSource()
        updateInspectorFocus()
    }

