    private func addPassthroughArrayVariableNode(
        at position: CGPoint,
        title: String?,
        defaultTitle: String,
        kind: GraphNodeKind,
        inputKind: GraphPortKind,
        outputKind: GraphPortKind,
        baseID: String,
        portName: String
    ) {
        let preferredTitle = title?.trimmingCharacters(in: .whitespacesAndNewlines)
        let nodeID = UUID()
        let newNode = GraphNode(
            id: nodeID,
            title: uniqueNodeTitle(preferred: preferredTitle?.isEmpty == false ? preferredTitle! : defaultTitle),
            kind: kind,
            position: position,
            inputPorts: [
                GraphPort(
                    id: "\(baseID):\(nodeID.uuidString):input",
                    nodeID: nodeID,
                    name: portName,
                    direction: .input,
                    kind: inputKind
                )
            ],
            outputPorts: [
                GraphPort(
                    id: "\(baseID):\(nodeID.uuidString):value",
                    nodeID: nodeID,
                    name: portName,
                    direction: .output,
                    kind: outputKind
                )
            ]
        )
        var updatedDocument = document
        updatedDocument.nodes.append(newNode)
        document = updatedDocument
        selectedNodeID = newNode.id
        inspectorFocusTarget = .nodeLibrary
        statusMessage = "Added \(newNode.title) to the graph."
    }

