    func addAudioNode(at position: CGPoint) {
        if let existingNode = document.nodes.first(where: {
            if case .audio = $0.kind { return true }
            return false
        }) {
            selectedNodeID = existingNode.id
            statusMessage = "Audio is already on the graph."
            updateInspectorFocus()
            return
        }

        let nodeID = UUID()
        let outputPorts = audioOutputPorts(for: nodeID, legacyCompatible: true)

        let newNode = GraphNode(
            id: nodeID,
            title: "Audio",
            kind: .audio,
            position: position,
            inputPorts: [],
            outputPorts: outputPorts
