    private func syncSliderStyleNodePorts(in document: ShaderDocument) -> ShaderDocument {
        var updatedDocument = document
        updatedDocument.nodes = updatedDocument.nodes.map { node in
            guard case .sliderStyle = node.kind else { return node }
            if node.inputPorts.contains(where: { $0.name == "Knob Image" }) {
                return node
            }
            return GraphNode(
                id: node.id,
                title: node.title,
                kind: node.kind,
                position: node.position,
                inputPorts: node.inputPorts + [
                    GraphPort(
                        id: "sliderstyle:\(node.id.uuidString):knobImage",
                        nodeID: node.id,
                        name: "Knob Image",
                        direction: .input,
                        kind: .fragmentShader
                    )
                ],
                outputPorts: node.outputPorts
            )
        }
        return updatedDocument
    }

