    private func syncButtonStyleNodePorts(in document: ShaderDocument) -> ShaderDocument {
        var updatedDocument = document
        updatedDocument.nodes = updatedDocument.nodes.map { node in
            guard case .buttonStyle = node.kind else { return node }
            let hasImage = node.inputPorts.contains(where: { $0.name == "Image" })
            let hasHoverImage = node.inputPorts.contains(where: { $0.name == "Hover Image" })
            let hasPressedImage = node.inputPorts.contains(where: { $0.name == "Pressed Image" })
            if hasImage && hasHoverImage && hasPressedImage {
                return node
            }
            var newPorts = node.inputPorts
            if !hasImage {
                newPorts.append(
                    GraphPort(
                        id: "buttonstyle:\(node.id.uuidString):image",
                        nodeID: node.id,
                        name: "Image",
                        direction: .input,
                        kind: .fragmentShader
                    )
                )
            }
            if !hasHoverImage {
                newPorts.append(
                    GraphPort(
                        id: "buttonstyle:\(node.id.uuidString):hoverImage",
                        nodeID: node.id,
                        name: "Hover Image",
                        direction: .input,
                        kind: .fragmentShader
                    )
                )
            }
            if !hasPressedImage {
                newPorts.append(
                    GraphPort(
                        id: "buttonstyle:\(node.id.uuidString):pressedImage",
                        nodeID: node.id,
                        name: "Pressed Image",
                        direction: .input,
                        kind: .fragmentShader
                    )
                )
            }
            return GraphNode(
                id: node.id,
                title: node.title,
                kind: node.kind,
                position: node.position,
                inputPorts: newPorts,
                outputPorts: node.outputPorts
            )
        }
        return updatedDocument
    }

