    @discardableResult
    func createMacro(from nodeIDs: [GraphNode.ID]) -> GraphNode.ID? {
        let selectedIDs = Set(nodeIDs)
        guard selectedIDs.count >= 1 else {
            statusMessage = "Select at least one node to create a macro."
            return nil
        }

        let selectedNodes = document.nodes.filter { selectedIDs.contains($0.id) }
        guard selectedNodes.count == selectedIDs.count else {
            statusMessage = "Could not resolve the selected nodes."
            return nil
        }

        if selectedNodes.contains(where: \.isPrimaryFragment) || selectedNodes.contains(where: \.isPrimaryRender) {
            statusMessage = "Do not wrap the primary fragment or render node in a macro."
            return nil
        }
        if selectedNodes.contains(where: {
            if case .macro = $0.kind { return true }
            return false
        }) {
            statusMessage = "Nested macros are not supported yet."
            return nil
        }

        let selectedPortIDs = Set(selectedNodes.flatMap(\.allPorts).map(\.id))

        let publishedInputs: [MacroPublishedPortSettings] = selectedNodes.flatMap { node in
            node.inputPorts.compactMap { inputPort in
                guard macroPublishedPortKind(for: inputPort.kind) != nil else { return nil }
                let incomingConnections = document.connections.filter { $0.toPortID == inputPort.id }
                let hasExternalSource = incomingConnections.contains { !selectedPortIDs.contains($0.fromPortID) }
                if !hasExternalSource {
                    return nil
                }
                return MacroPublishedPortSettings(
                    macroPortID: "",
                    internalPortID: inputPort.id,
                    name: "\(node.title) • \(inputPort.name)",
                    kind: macroPublishedPortKind(for: inputPort.kind)!
                )
            }
        }

        let publishedOutputs: [MacroPublishedPortSettings] = selectedNodes.flatMap { node in
            node.outputPorts.compactMap { outputPort in
                guard macroPublishedPortKind(for: outputPort.kind) != nil else { return nil }
                let outgoingConnections = document.connections.filter { $0.fromPortID == outputPort.id }
                let hasExternalTarget = outgoingConnections.contains { !selectedPortIDs.contains($0.toPortID) }
                guard hasExternalTarget else { return nil }
                return MacroPublishedPortSettings(
                    macroPortID: "",
                    internalPortID: outputPort.id,
                    name: "\(node.title) • \(outputPort.name)",
                    kind: macroPublishedPortKind(for: outputPort.kind)!
                )
            }
        }

        let macroIndex = document.nodes.reduce(0) { partialResult, node in
            guard case .macro = node.kind else { return partialResult }
            return partialResult + 1
        } + 1

        let macroID = UUID()
        let centroid = CGPoint(
            x: selectedNodes.map(\.position.x).reduce(0, +) / CGFloat(selectedNodes.count),
            y: selectedNodes.map(\.position.y).reduce(0, +) / CGFloat(selectedNodes.count)
        )

        let finalizedInputs = publishedInputs.enumerated().map { index, setting in
            MacroPublishedPortSettings(
                macroPortID: "macro:\(macroID.uuidString):input:\(index)",
                internalPortID: setting.internalPortID,
                name: setting.name,
                kind: setting.kind
            )
        }
        let finalizedOutputs = publishedOutputs.enumerated().map { index, setting in
            MacroPublishedPortSettings(
                macroPortID: "macro:\(macroID.uuidString):output:\(index)",
                internalPortID: setting.internalPortID,
                name: setting.name,
                kind: setting.kind
            )
        }

        let macroNode = GraphNode(
            id: macroID,
            title: "Macro \(macroIndex)",
            kind: .macro,
            position: centroid,
            inputPorts: finalizedInputs.map { published in
                GraphPort(
                    id: published.macroPortID,
                    nodeID: macroID,
                    name: published.name,
                    direction: .input,
                    kind: graphPortKind(for: published.kind)
                )
            },
            outputPorts: finalizedOutputs.map { published in
                GraphPort(
                    id: published.macroPortID,
                    nodeID: macroID,
                    name: published.name,
                    direction: .output,
                    kind: graphPortKind(for: published.kind)
                )
            }
        )

        var updatedDocument = document
        updatedDocument.nodes.append(macroNode)
        updatedDocument.connections = updatedDocument.connections.map { connection in
            var updated = connection
            if let publishedInput = finalizedInputs.first(where: { $0.internalPortID == connection.toPortID && !selectedPortIDs.contains(connection.fromPortID) }) {
                updated = GraphConnection(fromPortID: connection.fromPortID, toPortID: publishedInput.macroPortID)
            }
            if let publishedOutput = finalizedOutputs.first(where: { $0.internalPortID == connection.fromPortID && !selectedPortIDs.contains(connection.toPortID) }) {
                updated = GraphConnection(fromPortID: publishedOutput.macroPortID, toPortID: connection.toPortID)
            }
            return updated
        }
        document = updatedDocument
        macroNodeSettings[macroID] = MacroNodeSettings(
            childNodeIDs: selectedNodes.map(\.id),
            publishedInputs: finalizedInputs,
            publishedOutputs: finalizedOutputs
        )
        selectedNodeID = macroID
        inspectorFocusTarget = .nodeLibrary
        statusMessage = "Created \(macroNode.title)."
        return macroID
    }

