    private func coreImageInputPorts(for effect: CoreImageEffectKind, nodeID: UUID) -> [GraphPort] {
        var ports: [GraphPort] = [
            GraphPort(
                id: "coreimage:\(nodeID.uuidString):source",
                nodeID: nodeID,
                name: "Source",
                direction: .input,
                kind: .fragmentShader
            ),
            GraphPort(
                id: "coreimage:\(nodeID.uuidString):primary",
                nodeID: nodeID,
                name: coreImagePrimaryLabel(for: effect),
                direction: .input,
                kind: .scalarSignal("primary")
            )
        ]

        if let secondaryLabel = coreImageSecondaryLabel(for: effect) {
            ports.append(
                GraphPort(
                    id: "coreimage:\(nodeID.uuidString):secondary",
                    nodeID: nodeID,
                    name: secondaryLabel,
                    direction: .input,
                    kind: .scalarSignal("secondary")
                )
            )
        }

        return ports
    }

    private func coreImagePrimaryLabel(for effect: CoreImageEffectKind) -> String {
        switch effect {
        case .blur, .bloom, .glow:
            return "Radius"
        case .hueRotate:
            return "Angle"
        case .posterize:
            return "Levels"
        case .levels:
            return "Black"
        case .edges:
            return "Strength"
        case .pixellate:
            return "Size"
        case .twirl:
            return "Radius"
        case .kaleidoscope:
            return "Segments"
        }
    }

    private func coreImageSecondaryLabel(for effect: CoreImageEffectKind) -> String? {
        switch effect {
        case .bloom, .glow:
            return "Intensity"
        case .twirl:
            return "Angle"
        case .kaleidoscope:
            return "Spin"
        case .levels:
            return "White"
        case .blur, .hueRotate, .posterize, .edges, .pixellate:
            return nil
        }
    }

