    func addIteratorNode(at position: CGPoint) {
        let iteratorIndex = document.nodes.reduce(0) { partialResult, node in
            guard case .iterator = node.kind else { return partialResult }
            return partialResult + 1
        } + 1
        let nodeID = UUID()
        let settings = IteratorNodeSettings(childNodeIDs: [], publishedInputs: [], publishedOutputs: [], iterations: 4.0)
        let newNode = GraphNode(
            id: nodeID,
            title: iteratorIndex == 1 ? "Iterator" : "Iterator \(iteratorIndex)",
            kind: .iterator,
            position: position,
            inputPorts: iteratorVisiblePublishedInputs(for: settings, nodeID: nodeID),
            outputPorts: iteratorVisiblePublishedOutputs(for: settings, nodeID: nodeID)
        )

        var updatedDocument = document
        updatedDocument.nodes.append(newNode)
        document = updatedDocument
        iteratorNodeSettings[nodeID] = settings
        selectedNodeID = newNode.id
        inspectorFocusTarget = .nodeLibrary
        statusMessage = "Added \(newNode.title) to the graph."
    }

    func addIteratorVariablesNode(at position: CGPoint) {
        guard editingIteratorNodeID != nil else {
            statusMessage = "Iterator Variables can only be added while editing an iterator."
            return
        }
        let iteratorVarIndex = document.nodes.reduce(0) { partialResult, node in
            guard case .iteratorVariables = node.kind else { return partialResult }
            return partialResult + 1
        } + 1
        let nodeID = UUID()
        let newNode = GraphNode(
            id: nodeID,
            title: iteratorVarIndex == 1 ? "Iterator Variables" : "Iterator Variables \(iteratorVarIndex)",
            kind: .iteratorVariables,
            position: position,
            inputPorts: [],
            outputPorts: [
                GraphPort(id: "iteratorvars:\(nodeID.uuidString):index", nodeID: nodeID, name: "Index", direction: .output, kind: .scalarSignal("index")),
                GraphPort(id: "iteratorvars:\(nodeID.uuidString):progress", nodeID: nodeID, name: "Progress", direction: .output, kind: .scalarSignal("progress")),
                GraphPort(id: "iteratorvars:\(nodeID.uuidString):iterations", nodeID: nodeID, name: "Iterations", direction: .output, kind: .scalarSignal("iterations"))
            ]
        )

        var updatedDocument = document
        updatedDocument.nodes.append(newNode)
        document = updatedDocument
        if let iteratorNodeID = editingIteratorNodeID {
            var settings = iteratorNodeSettings[iteratorNodeID] ?? IteratorNodeSettings(childNodeIDs: [], publishedInputs: [], publishedOutputs: [], iterations: 4.0)
            settings.childNodeIDs.append(nodeID)
            iteratorNodeSettings[iteratorNodeID] = settings
        }
        selectedNodeID = newNode.id
        selectedNodeIDs = [newNode.id]
        inspectorFocusTarget = .nodeLibrary
        statusMessage = "Added \(newNode.title) to the iterator."
    }

    func disconnectConnection(_ connectionID: GraphConnection.ID) {
        guard document.connections.contains(where: { $0.id == connectionID }) else { return }
        captureHistoryCheckpointNow()
        var updatedDocument = document
        updatedDocument.connections.removeAll { $0.id == connectionID }
        document = updatedDocument
        statusMessage = "Disconnected wire."
    }

    func removeNode(_ nodeID: GraphNode.ID) {
        guard let node = document.nodes.first(where: { $0.id == nodeID }) else { return }
        let isFragmentDeleteCandidate: Bool = {
            if case .metalFragment = node.kind { return true }
            return false
        }()
        if !isFragmentDeleteCandidate {
            captureHistoryCheckpointNow()
        }
        var skipExpensivePostDeleteSnapshotWork = false

        switch node.kind {
        case .uniform:
            var updatedDocument = document
            updatedDocument.nodes.removeAll { $0.id == nodeID }
            let removedPortIDs = Set(node.allPorts.map(\.id))
            updatedDocument.connections.removeAll {
                removedPortIDs.contains($0.fromPortID) || removedPortIDs.contains($0.toPortID)
            }
            document = updatedDocument
            selectedNodeID = document.nodes.first(where: {
                if case .metalFragment = $0.kind { return true }
                return false
            })?.id
            statusMessage = "\(node.title) removed from graph."
            updateInspectorFocus()
        case .scene3DTransform, .scene3DTile:
            var updatedDocument = document
            updatedDocument.nodes.removeAll { $0.id == nodeID }
            let removedPortIDs = Set(node.allPorts.map(\.id))
            updatedDocument.connections.removeAll {
                removedPortIDs.contains($0.fromPortID) || removedPortIDs.contains($0.toPortID)
            }
            document = updatedDocument
            scene3DTransformNodeSettings.removeValue(forKey: nodeID)
            scene3DTileNodeSettings.removeValue(forKey: nodeID)
            selectedNodeID = nil
            selectedNodeIDs.remove(nodeID)
            inspectorFocusTarget = .nodeLibrary
            statusMessage = "\(node.title) removed from graph."
            DispatchQueue.main.async { [weak self] in
                guard let self else { return }
                guard self.document.nodes.contains(where: { $0.id == nodeID }) == false else { return }
                self.selectedNodeID = self.primaryFragmentNode?.id ?? self.renderNode?.id ?? self.document.nodes.last?.id
                self.updateInspectorFocus()
            }
        case .scene3DRender:
            var updatedDocument = document
            updatedDocument.nodes.removeAll { $0.id == nodeID }
            let removedPortIDs = Set(node.allPorts.map(\.id))
