            var updatedDocument = document
            let childNodeIDs = Set(iteratorNodeSettings[nodeID]?.childNodeIDs ?? [])
            let removedNodeIDs = childNodeIDs.union([nodeID])
            let removedPortIDs = Set(
                updatedDocument.nodes
                    .filter { removedNodeIDs.contains($0.id) }
                    .flatMap(\.allPorts)
                    .map(\.id)
            )
            updatedDocument.nodes.removeAll { removedNodeIDs.contains($0.id) }
            updatedDocument.connections.removeAll {
                removedPortIDs.contains($0.fromPortID) || removedPortIDs.contains($0.toPortID)
