        case .mix:
            var updatedDocument = document
            updatedDocument.nodes.removeAll { $0.id == nodeID }
            let removedPortIDs = Set(node.allPorts.map(\.id))
            updatedDocument.connections.removeAll {
                removedPortIDs.contains($0.fromPortID) || removedPortIDs.contains($0.toPortID)
            }
            document = updatedDocument
            selectedNodeID = primaryFragmentNode?.id
            inspectorFocusTarget = .nodeLibrary
            statusMessage = "\(node.title) removed from graph."
        case .screenBounds, .renderBounds, .renderWindow, .scalarMultiplexor, .stringMultiplexor, .colorMultiplexor, .imageMultiplexor:
            var updatedDocument = document
            updatedDocument.nodes.removeAll { $0.id == nodeID }
            let removedPortIDs = Set(node.allPorts.map(\.id))
            updatedDocument.connections.removeAll {
                removedPortIDs.contains($0.fromPortID) || removedPortIDs.contains($0.toPortID)
            }
            document = updatedDocument
            screenBoundsNodeSettings.removeValue(forKey: nodeID)
            renderBoundsNodeSettings.removeValue(forKey: nodeID)
            renderWindowNodeSettings.removeValue(forKey: nodeID)
            scalarArrayNodeSettings.removeValue(forKey: nodeID)
            scalarArrayIndexNodeSettings.removeValue(forKey: nodeID)
            stringArrayNodeSettings.removeValue(forKey: nodeID)
            stringArrayIndexNodeSettings.removeValue(forKey: nodeID)
            colorArrayNodeSettings.removeValue(forKey: nodeID)
            colorArrayIndexNodeSettings.removeValue(forKey: nodeID)
            imageArrayNodeSettings.removeValue(forKey: nodeID)
            imageArrayIndexNodeSettings.removeValue(forKey: nodeID)
            selectedNodeID = primaryFragmentNode?.id
            inspectorFocusTarget = .nodeLibrary
            statusMessage = "\(node.title) removed from graph."
        case .metalFragment, .renderOutput:
            guard canDeleteNode(nodeID) else {
                statusMessage = "Keep at least one fragment and one render node on the canvas."
                return
            }

            if selectedNodeID == nodeID {
                selectedNodeID = nil
                inspectorFocusTarget = .nodeLibrary
            }
            selectedNodeIDs.remove(nodeID)

            var updatedDocument = document
            updatedDocument.nodes.removeAll { $0.id == nodeID }
            let removedPortIDs = Set(node.allPorts.map(\.id))
            updatedDocument.connections.removeAll {
                removedPortIDs.contains($0.fromPortID) || removedPortIDs.contains($0.toPortID)
            }

            let deletedFragmentNode = {
                if case .metalFragment = node.kind { return true }
                return false
            }()

            if deletedFragmentNode {
                // Fragment deletion mutates both the document and fragment source map.
                // Ignore the intermediate publishes and perform one clean refresh at the end.
                ignoreNextGraphChangeNotifications(immediateCount: 2)
                updatedDocument = pruneUnusedUniforms(in: updatedDocument)
                updatedDocument = reconnectPrimaryRenderIfNeeded(in: updatedDocument)
            } else {
                previewWindowControllers[nodeID]?.close()
            }

            document = updatedDocument
            baselineUniformValues = Dictionary(uniqueKeysWithValues: updatedDocument.uniforms.map { ($0.id, $0.defaultValue) })

            statusMessage = "\(node.title) removed from graph."
            if deletedFragmentNode {
                selectedNodeID = nil
                inspectorFocusTarget = .nodeLibrary
                metalCompilerMessage = nil
                skipExpensivePostDeleteSnapshotWork = true
            } else {
                selectedNodeID = primaryFragmentNode?.id ?? renderNode?.id ?? document.nodes.first?.id
                syncEditableMetalSourceWithSelection()
                validateMetalSource()
                updateInspectorFocus()
            }

            if deletedFragmentNode {
                fragmentMetalSources.removeValue(forKey: nodeID)
                lastGeneratedMetalSources.removeValue(forKey: nodeID)
                DispatchQueue.main.async { [weak self] in
                    guard let self else { return }
                    guard self.document.nodes.contains(where: { $0.id == nodeID }) == false else { return }

                    let fallbackSelection = self.primaryFragmentNode?.id
                        ?? self.renderNode?.id
                        ?? self.document.nodes.first?.id
                    self.selectedNodeID = fallbackSelection
                    self.updateInspectorFocus()
                    if self.selectedFragmentNode != nil {
                        self.syncEditableMetalSourceWithSelection()
                    }
                }
            }
        }

        if skipExpensivePostDeleteSnapshotWork {
            refreshCurrentGraphDisplayName()
            isCurrentGraphDirty = true
            return
        }

        markCurrentGraphDirty()
    }

    func addMetalFragmentNode(at position: CGPoint) {
        let fragmentIndex = document.nodes.reduce(0) { partialResult, node in
            guard case .metalFragment = node.kind else { return partialResult }
            return partialResult + 1
        } + 1
        let nodeID = UUID()
        let newNode = GraphNode(
            id: nodeID,
            title: "Metal Fragment \(fragmentIndex)",
            kind: .metalFragment(isPrimary: false),
            position: position,
            inputPorts: [Self.makeFragmentTimePort(nodeID: nodeID)] + document.uniforms.map { Self.makeFragmentInputPort(for: $0, nodeID: nodeID) },
            outputPorts: [Self.makeFragmentOutputPort(nodeID: nodeID)]
        )

        var updatedDocument = document
        updatedDocument.nodes.append(newNode)

        if let timeNode = updatedDocument.nodes.first(where: {
            if case .time = $0.kind { return true }
            return false
        }),
           let timeOutput = timeNode.outputPorts.first,
           let timeInput = newNode.inputPorts.first(where: { $0.kind == .time }) {
            updatedDocument.connections.append(GraphConnection(fromPortID: timeOutput.id, toPortID: timeInput.id))
        }

        let uniformOutputPortsByKind = Dictionary(
            uniqueKeysWithValues: updatedDocument.nodes.compactMap { node -> (GraphPortKind, GraphPort)? in
                guard case .uniform = node.kind, let outputPort = node.outputPorts.first else { return nil }
                return (outputPort.kind, outputPort)
            }
        )

        for inputPort in newNode.inputPorts where inputPort.direction == .input {
            guard case .uniform = inputPort.kind,
                  let outputPort = uniformOutputPortsByKind[inputPort.kind] else {
                continue
            }
            updatedDocument.connections.append(GraphConnection(fromPortID: outputPort.id, toPortID: inputPort.id))
        }

        fragmentMetalSources[nodeID] = Self.defaultEditableMetalSource
        lastGeneratedMetalSources[nodeID] = fragmentMetalSources[nodeID]
        document = syncFragmentNodePorts(in: updatedDocument)
        selectedNodeID = newNode.id
        syncEditableMetalSourceWithSelection()
        statusMessage = "Added \(newNode.title) to the graph."
        validateMetalSource()
        updateInspectorFocus()
    }

    func addKeyboardNode(at position: CGPoint) {
        let keyboardIndex = document.nodes.reduce(0) { partialResult, node in
            guard case .keyboard = node.kind else { return partialResult }
            return partialResult + 1
        } + 1
        let nodeID = UUID()
        let newNode = GraphNode(
            id: nodeID,
            title: keyboardIndex == 1 ? "Keyboard" : "Keyboard \(keyboardIndex)",
            kind: .keyboard,
            position: position,
            inputPorts: [],
            outputPorts: [
                GraphPort(
                    id: "keyboard:\(nodeID.uuidString):pressed",
                    nodeID: nodeID,
                    name: "Pressed",
                    direction: .output,
                    kind: .scalarSignal("keyboardPressed")
                )
            ]
        )

        var updatedDocument = document
        updatedDocument.nodes.append(newNode)
        document = updatedDocument
        keyboardNodeSettings[nodeID] = KeyboardNodeSettings()
        selectedNodeID = newNode.id
        inspectorFocusTarget = .nodeLibrary
        statusMessage = "Added \(newNode.title) to the graph."
    }

