    func addRenderNode(at position: CGPoint) {
        let isFirstRender = !document.nodes.contains(where: {
            if case .renderOutput = $0.kind { return true }
            return false
        })
        let renderIndex = document.nodes.reduce(0) { partialResult, node in
            guard case .renderOutput = node.kind else { return partialResult }
            return partialResult + 1
        } + 1
        let nodeID = UUID()
        let inputPort = GraphPort(
            id: "render:\(nodeID.uuidString):input",
            nodeID: nodeID,
            name: "Shader",
            direction: .input,
            kind: .fragmentShader
        )
        let newNode = GraphNode(
            id: nodeID,
            title: "Render Window \(renderIndex)",
            kind: .renderOutput(isPrimary: isFirstRender),
            position: position,
            inputPorts: [inputPort],
            outputPorts: []
        )

        var updatedDocument = document
        updatedDocument.nodes.append(newNode)
        document = updatedDocument
        selectedNodeID = newNode.id
        syncEditableMetalSourceWithSelection()
        statusMessage = "Added \(newNode.title) to the graph."
        validateMetalSource()
        updateInspectorFocus()
    }

    func addUniform(named rawName: String, kind: UniformKind) {
        guard let fragmentNodeID = selectedFragmentNode?.id ?? primaryFragmentNode?.id else {
            statusMessage = "Select a fragment node first."
            return
        }

        let trimmedName = rawName.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedName.isEmpty else {
            statusMessage = "Uniform name is required."
            return
        }

        let uniqueName = uniqueUniformName(from: trimmedName)
        let uniform = UniformDescriptor(
            name: uniqueName,
            kind: kind,
            defaultValue: defaultUniformValue(for: kind),
            minValue: kind == .float ? 0.0 : nil,
            maxValue: kind == .float ? 1.0 : nil,
            label: nil
        )

        var updatedDocument = document
        updatedDocument.uniforms.append(uniform)

        let existingSource = metalSource(for: fragmentNodeID)
        let updatedSource = sourceByAddingUniform(uniform, to: existingSource)
        fragmentMetalSources[fragmentNodeID] = updatedSource
        lastGeneratedMetalSources[fragmentNodeID] = updatedSource

        document = syncFragmentNodePorts(in: updatedDocument)
        baselineUniformValues = Dictionary(uniqueKeysWithValues: document.uniforms.map { ($0.id, $0.defaultValue) })
        selectedNodeID = fragmentNodeID
        inspectorFocusTarget = .fragmentNode
        syncEditableMetalSourceWithSelection()
        statusMessage = "Added uniform \(uniqueName) to \(selectedFragmentNode?.title ?? "fragment")."
        validateMetalSource()
    }

    func moveNode(_ nodeID: GraphNode.ID, to position: CGPoint) {
        guard let index = document.nodes.firstIndex(where: { $0.id == nodeID }) else { return }
        var updatedDocument = document
        let node = updatedDocument.nodes[index]
        let delta = CGPoint(x: position.x - node.position.x, y: position.y - node.position.y)
        updatedDocument.nodes[index] = GraphNode(
            id: node.id,
            title: node.title,
            kind: node.kind,
            position: position,
            inputPorts: node.inputPorts,
            outputPorts: node.outputPorts
        )
        if case .macro = node.kind, let settings = macroNodeSettings[nodeID] {
            for childID in settings.childNodeIDs {
                guard let childIndex = updatedDocument.nodes.firstIndex(where: { $0.id == childID }) else { continue }
                let child = updatedDocument.nodes[childIndex]
                updatedDocument.nodes[childIndex] = GraphNode(
                    id: child.id,
                    title: child.title,
                    kind: child.kind,
                    position: CGPoint(x: child.position.x + delta.x, y: child.position.y + delta.y),
                    inputPorts: child.inputPorts,
                    outputPorts: child.outputPorts
                )
            }
        }
        document = updatedDocument
    }

    func renameNode(_ nodeID: GraphNode.ID, to title: String) {
        let trimmedTitle = title.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedTitle.isEmpty else { return }
        guard let index = document.nodes.firstIndex(where: { $0.id == nodeID }) else { return }
        guard document.nodes[index].title != trimmedTitle else { return }

        var updatedDocument = document
        let node = updatedDocument.nodes[index]
        updatedDocument.nodes[index] = GraphNode(
            id: node.id,
            title: trimmedTitle,
            kind: node.kind,
            position: node.position,
            inputPorts: node.inputPorts,
            outputPorts: node.outputPorts
        )
        document = updatedDocument
        statusMessage = "Renamed node to \(trimmedTitle)."
    }

    func updateUniform(_ uniformID: UniformDescriptor.ID, value: UniformValue) {
        guard let index = document.uniforms.firstIndex(where: { $0.id == uniformID }) else { return }
        guard document.uniforms[index].defaultValue != value else { return }
        var updatedDocument = document
        updatedDocument.uniforms[index].defaultValue = value
        document = updatedDocument
        if shouldUpdateBaseline(for: uniformID) {
            baselineUniformValues[uniformID] = value
        }
        validateMetalSource()
    }

    func editableFloatUniform(forInputPortID inputPortID: GraphPort.ID) -> UniformDescriptor? {
        guard
            let port = port(withID: inputPortID),
            case .uniform(let uniformID) = port.kind,
            let uniform = currentUniform(matching: uniformID),
            uniform.kind == .float
        else {
            return nil
        }
        return uniform
    }

    func editableBoolUniform(forInputPortID inputPortID: GraphPort.ID) -> UniformDescriptor? {
        guard
            let port = port(withID: inputPortID),
            case .uniform(let uniformID) = port.kind,
            let uniform = currentUniform(matching: uniformID),
            uniform.kind == .bool
        else {
            return nil
        }
        return uniform
    }

    func editableScalarFallbackValue(forInputPortID inputPortID: GraphPort.ID) -> Double? {
        guard let port = port(withID: inputPortID),
              let node = node(withID: port.nodeID) else {
            return nil
        }

        switch node.kind {
        case .math where port.name == "A":
            return settings(forMathNodeID: node.id).a
        case .math where port.name == "B":
            return settings(forMathNodeID: node.id).b
        case .expression:
            return settings(forExpressionNodeID: node.id).variables[port.name] ?? 0.0
        case .pointCombine where port.name == "X":
            return settings(forPointCombineNodeID: node.id).x
        case .pointCombine where port.name == "Y":
            return settings(forPointCombineNodeID: node.id).y
        case .point3Combine where port.name == "X":
            return settings(forPoint3CombineNodeID: node.id).x
        case .point3Combine where port.name == "Y":
            return settings(forPoint3CombineNodeID: node.id).y
        case .point3Combine where port.name == "Z":
            return settings(forPoint3CombineNodeID: node.id).z
        case .point4Combine where port.name == "X":
            return settings(forPoint4CombineNodeID: node.id).x
        case .point4Combine where port.name == "Y":
            return settings(forPoint4CombineNodeID: node.id).y
        case .point4Combine where port.name == "Z":
            return settings(forPoint4CombineNodeID: node.id).z
        case .point4Combine where port.name == "W":
            return settings(forPoint4CombineNodeID: node.id).w
        case .stringSplit where port.name == "Index":
            return settings(forStringSplitNodeID: node.id).index
        case .scalarArray:
            if let index = arrayItemIndex(from: port.name) {
                let settings = normalizedScalarArraySettings(settings(forScalarArrayNodeID: node.id))
                if settings.values.indices.contains(index) {
                    return settings.values[index]
                }
            }
            return nil
        case .scalarArrayIndex where port.name == "Index":
            return settings(forScalarArrayIndexNodeID: node.id).index
