        case .oscMake4 where port.name == "Float 2":
            return settings(forOSCMessageNodeID: node.id).float2
        case .oscMake4 where port.name == "Int 2":
            return settings(forOSCMessageNodeID: node.id).int2
        case .oscMake4 where port.name == "Float 3":
            return settings(forOSCMessageNodeID: node.id).float3
        case .oscMake4 where port.name == "Int 3":
            return settings(forOSCMessageNodeID: node.id).int3
        case .oscMake4 where port.name == "Float 4":
            return settings(forOSCMessageNodeID: node.id).float4
        case .oscMake4 where port.name == "Int 4":
            return settings(forOSCMessageNodeID: node.id).int4
        case .layers:
            let settings = settings(forLayerNodeID: node.id)
            if port.name == "Opacity" {
                return settings.opacity
            }
            if let indexString = port.name.split(separator: " ").last,
               let index = Int(indexString),
               index >= 1,
               index <= settings.layerOpacities.count {
                return settings.layerOpacities[index - 1]
            }
            return nil
        default:
            break
        }

        if resolvedCoreImageEffect(for: node) != nil {
            let settings = settings(forCoreImageNodeID: node.id)
            if port.name == coreImagePrimaryLabel(for: settings.effect) {
                return settings.primary
            }
            if port.name == coreImageSecondaryLabel(for: settings.effect) {
                return settings.secondary
            }
        }

        switch node.kind {
        default:
            return nil
        }
    }

    func editableStringFallbackValue(forInputPortID inputPortID: GraphPort.ID) -> String? {
        guard let port = port(withID: inputPortID),
              let node = node(withID: port.nodeID) else {
            return nil
        }

        switch node.kind {
        case .stringFormat:
            let settings = settings(forStringFormatNodeID: node.id)
            if let indexString = port.name.split(separator: " ").last,
               let index = Int(indexString) {
                return stringFormatFallbackText(for: index - 1, settings: settings)
            }
            return nil
        case .stringCompare where port.name == "A":
            return settings(forStringCompareNodeID: node.id).left
        case .stringCompare where port.name == "B":
            return settings(forStringCompareNodeID: node.id).right
        case .stringSplit where port.name == "Text":
            return settings(forStringSplitNodeID: node.id).text
        case .stringArray:
            if let index = arrayItemIndex(from: port.name) {
                let settings = normalizedStringArraySettings(settings(forStringArrayNodeID: node.id))
                if settings.values.indices.contains(index) {
                    return settings.values[index]
                }
            }
            return nil
        case .textImage where port.name == "Text":
            return settings(forTextImageNodeID: node.id).text
        case .stringMultiplexor:
            if let index = arrayItemIndex(from: port.name) {
                let settings = normalizedStringArraySettings(settings(forStringArrayNodeID: node.id))
                if settings.values.indices.contains(index) {
                    return settings.values[index]
                }
            }
            return nil
        case .stringSwitch where port.name == "A":
            return settings(forSelectNodeID: node.id).stringA
        case .stringSwitch where port.name == "B":
            return settings(forSelectNodeID: node.id).stringB
        case .oscMake4 where port.name == "Text 1":
            return settings(forOSCMessageNodeID: node.id).text1
        case .oscMake4 where port.name == "Text 2":
            return settings(forOSCMessageNodeID: node.id).text2
        case .oscMake4 where port.name == "Text 3":
            return settings(forOSCMessageNodeID: node.id).text3
        case .oscMake4 where port.name == "Text 4":
            return settings(forOSCMessageNodeID: node.id).text4
        default:
            return nil
        }
    }

    func editableColorFallbackValue(forInputPortID inputPortID: GraphPort.ID) -> ArrayColorValue? {
        guard let port = port(withID: inputPortID),
              let node = node(withID: port.nodeID) else {
            return nil
        }

        if case .uniform(let uniformID) = port.kind,
           let uniform = currentUniform(matching: uniformID),
           uniform.kind == .color,
           case .color(let value) = uniform.defaultValue {
            return ArrayColorValue(
                red: Double(value.x),
                green: Double(value.y),
                blue: Double(value.z),
                alpha: Double(value.w)
            )
        }

        switch node.kind {
        case .colorSplit where port.name == "Color":
            let settings = settings(forColorNodeID: node.id)
            return ArrayColorValue(
                red: settings.red,
                green: settings.green,
                blue: settings.blue,
                alpha: settings.alpha
            )
        case .colorArray:
            if let index = arrayItemIndex(from: port.name) {
                let settings = normalizedColorArraySettings(settings(forColorArrayNodeID: node.id))
                if settings.values.indices.contains(index) {
                    return settings.values[index]
                }
            }
            return nil
        case .colorMultiplexor:
            if let index = arrayItemIndex(from: port.name) {
                let settings = normalizedColorArraySettings(settings(forColorArrayNodeID: node.id))
                if settings.values.indices.contains(index) {
                    return settings.values[index]
                }
            }
            return nil
        case .colorSwitch where port.name == "A":
            return settings(forSelectNodeID: node.id).colorA
        case .colorSwitch where port.name == "B":
            return settings(forSelectNodeID: node.id).colorB
        case .scene3DPrimitive where port.name == "Color":
            let settings = settings(forScene3DPrimitiveNodeID: node.id)
            return ArrayColorValue(
                red: settings.materialRed,
                green: settings.materialGreen,
                blue: settings.materialBlue,
                alpha: settings.materialAlpha
            )
        case .scene3DText where port.name == "Color":
            let settings = settings(forScene3DTextNodeID: node.id)
            return ArrayColorValue(
                red: settings.materialRed,
                green: settings.materialGreen,
                blue: settings.materialBlue,
                alpha: settings.materialAlpha
            )
        case .scene3DParticle where port.name == "Color":
            let settings = settings(forScene3DParticleNodeID: node.id)
            return ArrayColorValue(
                red: settings.red,
                green: settings.green,
                blue: settings.blue,
                alpha: settings.alpha
            )
        case .scene3DMaterial where port.name == "Base Color":
            let settings = settings(forScene3DMaterialNodeID: node.id)
            return ArrayColorValue(
                red: settings.red,
                green: settings.green,
                blue: settings.blue,
                alpha: settings.alpha
            )
        default:
            return nil
        }
    }

    func updateFloatUniform(forInputPortID inputPortID: GraphPort.ID, value: Double) {
        guard let uniform = editableFloatUniform(forInputPortID: inputPortID) else { return }
        let clampedValue = min(max(value, uniform.minValue ?? value), uniform.maxValue ?? value)
        updateUniform(uniform.id, value: .float(clampedValue))
    }

    func updateScalarFallbackValue(forInputPortID inputPortID: GraphPort.ID, value: Double) {
        guard let port = port(withID: inputPortID),
              let node = node(withID: port.nodeID) else {
            return
        }

        switch node.kind {
        case .math where port.name == "A":
            updateMathNodeSettings(node.id) { $0.a = value }
        case .math where port.name == "B":
            updateMathNodeSettings(node.id) { $0.b = value }
        case .expression:
            updateExpressionNodeSettings(node.id) { $0.variables[port.name] = value }
        case .pointCombine where port.name == "X":
            pointCombineNodeSettings[node.id] = {
                var settings = settings(forPointCombineNodeID: node.id)
                settings.x = value
                return settings
            }()
        case .pointCombine where port.name == "Y":
            pointCombineNodeSettings[node.id] = {
                var settings = settings(forPointCombineNodeID: node.id)
                settings.y = value
                return settings
            }()
        case .point3Combine where port.name == "X":
            point3CombineNodeSettings[node.id] = {
                var settings = settings(forPoint3CombineNodeID: node.id)
                settings.x = value
                return settings
            }()
        case .point3Combine where port.name == "Y":
            point3CombineNodeSettings[node.id] = {
                var settings = settings(forPoint3CombineNodeID: node.id)
                settings.y = value
                return settings
            }()
        case .point3Combine where port.name == "Z":
            point3CombineNodeSettings[node.id] = {
                var settings = settings(forPoint3CombineNodeID: node.id)
                settings.z = value
                return settings
            }()
        case .point4Combine where port.name == "X":
            point4CombineNodeSettings[node.id] = {
                var settings = settings(forPoint4CombineNodeID: node.id)
                settings.x = value
                return settings
            }()
        case .point4Combine where port.name == "Y":
            point4CombineNodeSettings[node.id] = {
                var settings = settings(forPoint4CombineNodeID: node.id)
                settings.y = value
                return settings
            }()
        case .point4Combine where port.name == "Z":
            point4CombineNodeSettings[node.id] = {
                var settings = settings(forPoint4CombineNodeID: node.id)
                settings.z = value
                return settings
            }()
        case .point4Combine where port.name == "W":
            point4CombineNodeSettings[node.id] = {
                var settings = settings(forPoint4CombineNodeID: node.id)
                settings.w = value
                return settings
            }()
        case .stringSplit where port.name == "Index":
            updateStringSplitNodeSettings(node.id) { $0.index = value }
        case .scalarArray:
            if let index = arrayItemIndex(from: port.name) {
                updateScalarArrayNodeSettings(node.id) { settings in
                    let normalized = normalizedScalarArraySettings(settings)
                    settings.count = normalized.count
                    settings.values = normalized.values
                    settings.values[index] = value
                }
            }
        case .scalarArrayIndex where port.name == "Index":
            updateScalarArrayIndexNodeSettings(node.id) { $0.index = value }
        case .stringArrayIndex where port.name == "Index":
            updateStringArrayIndexNodeSettings(node.id) { $0.index = value }
        case .colorArrayIndex where port.name == "Index":
            updateColorArrayIndexNodeSettings(node.id) { $0.index = value }
        case .imageArrayIndex where port.name == "Index":
            updateImageArrayIndexNodeSettings(node.id) { $0.index = value }
        case .compare where port.name == "Number":
            updateCompareNodeSettings(node.id) { $0.referenceValue = value }
        case .compare where port.name == "Threshold":
            updateCompareNodeSettings(node.id) { $0.epsilon = value }
        case .random where port.name == "Min":
            updateRandomNodeSettings(node.id) { $0.min = value }
        case .random where port.name == "Max":
            updateRandomNodeSettings(node.id) { $0.max = value }
        case .random where port.name == "Trigger":
            updateRandomNodeSettings(node.id) { $0.trigger = value }
        case .random where port.name == "Rate":
            updateRandomNodeSettings(node.id) { $0.rate = value }
        case .pulse where port.name == "Gate":
            updatePulseNodeSettings(node.id) { $0.gate = value }
        case .counter where port.name == "Trigger":
            updateCounterNodeSettings(node.id) { $0.trigger = value }
        case .counter where port.name == "Reset":
            updateCounterNodeSettings(node.id) { $0.reset = value }
        case .counter where port.name == "Step":
            updateCounterNodeSettings(node.id) { $0.step = value }
        case .counter where port.name == "Min":
            updateCounterNodeSettings(node.id) { $0.minimum = value }
        case .counter where port.name == "Max":
            updateCounterNodeSettings(node.id) { $0.maximum = value }
        case .toggle where port.name == "Trigger":
            updateToggleNodeSettings(node.id) { $0.trigger = value }
        case .toggle where port.name == "Reset":
            updateToggleNodeSettings(node.id) { $0.reset = value }
        case .delay where port.name == "Trigger":
            updateDelayNodeSettings(node.id) { $0.trigger = value }
        case .delay where port.name == "Duration":
            updateDelayNodeSettings(node.id) { $0.duration = value }
        case .timer where port.name == "Enabled":
