            updateScene3DParticleNodeSettings(node.id) { $0.spread = value }
        case .scene3DParticle where port.name == "Box Width":
            updateScene3DParticleNodeSettings(node.id) { $0.boxWidth = value }
        case .scene3DParticle where port.name == "Box Height":
            updateScene3DParticleNodeSettings(node.id) { $0.boxHeight = value }
        case .scene3DParticle where port.name == "Box Depth":
            updateScene3DParticleNodeSettings(node.id) { $0.boxDepth = value }
        case .scene3DParticle where port.name == "Size":
            updateScene3DParticleNodeSettings(node.id) { $0.size = value }
        case .scene3DParticle where port.name == "Gravity Y":
            updateScene3DParticleNodeSettings(node.id) { $0.gravityY = value }
        case .oscMake4 where port.name == "Float 1":
            updateOSCMessageNodeSettings(node.id) { $0.float1 = value }
        case .oscMake4 where port.name == "Int 1":
            updateOSCMessageNodeSettings(node.id) { $0.int1 = value }
        case .oscMake4 where port.name == "Float 2":
            updateOSCMessageNodeSettings(node.id) { $0.float2 = value }
        case .oscMake4 where port.name == "Int 2":
            updateOSCMessageNodeSettings(node.id) { $0.int2 = value }
        case .oscMake4 where port.name == "Float 3":
            updateOSCMessageNodeSettings(node.id) { $0.float3 = value }
        case .oscMake4 where port.name == "Int 3":
            updateOSCMessageNodeSettings(node.id) { $0.int3 = value }
        case .oscMake4 where port.name == "Float 4":
            updateOSCMessageNodeSettings(node.id) { $0.float4 = value }
        case .oscMake4 where port.name == "Int 4":
            updateOSCMessageNodeSettings(node.id) { $0.int4 = value }
        case .layers:
            if port.name == "Opacity" {
                updateLayerNodeSettings(node.id) { $0.opacity = value }
                return
            }
            if let indexString = port.name.split(separator: " ").last,
               let index = Int(indexString),
               index >= 1 {
                updateLayerNodeSettings(node.id) { settings in
                    while settings.layerOpacities.count < index {
                        settings.layerOpacities.append(1.0)
                    }
                    settings.layerOpacities[index - 1] = value
                }
                return
            }
        default:
            break
        }

        if resolvedCoreImageEffect(for: node) != nil {
            let effect = settings(forCoreImageNodeID: node.id).effect
            if port.name == coreImagePrimaryLabel(for: effect) {
                updateCoreImageNodeSettings(node.id) { $0.primary = value }
                return
            }
            if port.name == coreImageSecondaryLabel(for: effect) {
                updateCoreImageNodeSettings(node.id) { $0.secondary = value }
                return
            }
        }

        switch node.kind {
        default:
            break
        }
    }

    func updateStringFallbackValue(forInputPortID inputPortID: GraphPort.ID, value: String) {
        guard let port = port(withID: inputPortID),
              let node = node(withID: port.nodeID) else {
            return
        }

        switch node.kind {
        case .stringFormat:
            if let indexString = port.name.split(separator: " ").last,
               let index = Int(indexString) {
                updateStringFormatNodeSettings(node.id) { settings in
                    updateStringFormatFallbackText(index - 1, value: value, settings: &settings)
                }
            }
        case .stringCompare where port.name == "A":
            updateStringCompareNodeSettings(node.id) { $0.left = value }
        case .stringCompare where port.name == "B":
            updateStringCompareNodeSettings(node.id) { $0.right = value }
        case .stringSplit where port.name == "Text":
            updateStringSplitNodeSettings(node.id) { $0.text = value }
        case .stringArray:
            if let index = arrayItemIndex(from: port.name) {
                updateStringArrayNodeSettings(node.id) { settings in
                    let normalized = normalizedStringArraySettings(settings)
                    settings.count = normalized.count
                    settings.values = normalized.values
                    settings.values[index] = value
                }
            }
        case .textImage where port.name == "Text":
            updateTextImageNodeSettings(node.id) { $0.text = value }
        case .stringMultiplexor:
            if let index = arrayItemIndex(from: port.name) {
                updateStringArrayNodeSettings(node.id) { settings in
                    let normalized = normalizedStringArraySettings(settings)
                    settings.count = normalized.count
                    settings.values = normalized.values
                    settings.values[index] = value
                }
            }
        case .stringSwitch where port.name == "A":
            updateSelectNodeSettings(node.id) { $0.stringA = value }
        case .stringSwitch where port.name == "B":
            updateSelectNodeSettings(node.id) { $0.stringB = value }
        case .oscMake4 where port.name == "Text 1":
            updateOSCMessageNodeSettings(node.id) { $0.text1 = value }
        case .oscMake4 where port.name == "Text 2":
            updateOSCMessageNodeSettings(node.id) { $0.text2 = value }
        case .oscMake4 where port.name == "Text 3":
            updateOSCMessageNodeSettings(node.id) { $0.text3 = value }
        case .oscMake4 where port.name == "Text 4":
            updateOSCMessageNodeSettings(node.id) { $0.text4 = value }
        default:
            break
        }
    }

    func updateColorFallbackValue(forInputPortID inputPortID: GraphPort.ID, value: ArrayColorValue) {
        guard let port = port(withID: inputPortID),
              let node = node(withID: port.nodeID) else {
            return
        }

        if case .uniform(let uniformID) = port.kind,
           let uniform = currentUniform(matching: uniformID),
           uniform.kind == .color {
            updateUniform(
                uniformID,
                value: .color(SIMD4<Float>(
                    Float(value.red),
                    Float(value.green),
                    Float(value.blue),
                    Float(value.alpha)
                ))
            )
            return
        }

        switch node.kind {
        case .colorSplit where port.name == "Color":
            updateColorNodeSettings(node.id) { settings in
                settings.red = value.red
                settings.green = value.green
                settings.blue = value.blue
                settings.alpha = value.alpha
            }
        case .colorArray:
            if let index = arrayItemIndex(from: port.name) {
                updateColorArrayNodeSettings(node.id) { settings in
                    let normalized = normalizedColorArraySettings(settings)
                    settings.count = normalized.count
                    settings.values = normalized.values
                    settings.values[index] = value
                }
            }
        case .colorMultiplexor:
            if let index = arrayItemIndex(from: port.name) {
                updateColorArrayNodeSettings(node.id) { settings in
                    let normalized = normalizedColorArraySettings(settings)
                    settings.count = normalized.count
                    settings.values = normalized.values
                    settings.values[index] = value
                }
            }
        case .colorSwitch where port.name == "A":
            updateSelectNodeSettings(node.id) { $0.colorA = value }
        case .colorSwitch where port.name == "B":
            updateSelectNodeSettings(node.id) { $0.colorB = value }
        case .scene3DPrimitive where port.name == "Color":
            updateScene3DPrimitiveNodeSettings(node.id) { settings in
                settings.materialRed = value.red
                settings.materialGreen = value.green
                settings.materialBlue = value.blue
                settings.materialAlpha = value.alpha
            }
        case .scene3DText where port.name == "Color":
            updateScene3DTextNodeSettings(node.id) { settings in
                settings.materialRed = value.red
                settings.materialGreen = value.green
                settings.materialBlue = value.blue
                settings.materialAlpha = value.alpha
            }
        case .scene3DParticle where port.name == "Color":
            updateScene3DParticleNodeSettings(node.id) { settings in
                settings.red = value.red
                settings.green = value.green
                settings.blue = value.blue
                settings.alpha = value.alpha
            }
        case .scene3DMaterial where port.name == "Base Color":
            updateScene3DMaterialNodeSettings(node.id) { settings in
                settings.red = value.red
                settings.green = value.green
                settings.blue = value.blue
                settings.alpha = value.alpha
            }
        default:
            break
        }
    }

    func updateBoolUniform(forInputPortID inputPortID: GraphPort.ID, value: Bool) {
        guard
            let port = port(withID: inputPortID),
            case .uniform(let uniformID) = port.kind,
            let uniform = currentUniform(matching: uniformID),
            uniform.kind == .bool
        else {
            return
        }
        updateUniform(uniformID, value: .bool(value))
    }

    func updateUniformRange(_ uniformID: UniformDescriptor.ID, minValue: Double, maxValue: Double) {
        guard let index = document.uniforms.firstIndex(where: { $0.id == uniformID }) else { return }
        let clampedMin = min(minValue, maxValue)
        let clampedMax = max(minValue, maxValue)

        var updatedDocument = document
        updatedDocument.uniforms[index].minValue = clampedMin
        updatedDocument.uniforms[index].maxValue = clampedMax

        if case .float(let currentValue) = updatedDocument.uniforms[index].defaultValue {
            let clampedValue = min(max(currentValue, clampedMin), clampedMax)
            updatedDocument.uniforms[index].defaultValue = .float(clampedValue)
            if shouldUpdateBaseline(for: uniformID) {
                baselineUniformValues[uniformID] = .float(clampedValue)
            }
        }

        document = updatedDocument
        validateMetalSource()
    }

