    func updateMacroInputPort(_ macroPortID: GraphPort.ID, on nodeID: GraphNode.ID, name: String? = nil, isPublished: Bool? = nil) {
        guard var settings = macroNodeSettings[nodeID],
              let index = settings.publishedInputs.firstIndex(where: { $0.macroPortID == macroPortID }) else {
            return
        }
        if let name {
            let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
            if !trimmed.isEmpty {
                settings.publishedInputs[index].name = trimmed
            }
        }
        if let isPublished {
            settings.publishedInputs[index].isPublished = isPublished
        }
        macroNodeSettings[nodeID] = settings
        rebuildMacroNodePorts(for: nodeID)
    }

