    func publishPortFromEditingMacro(_ port: GraphPort) {
        guard canPublishPort(port) else { return }

        if let macroNodeID = editingMacroNodeID,
           var settings = macroNodeSettings[macroNodeID],
           port.nodeID != macroNodeID {
            let kind = macroPublishedPortKind(for: port.kind)!
            switch port.direction {
            case .input:
                if let index = settings.publishedInputs.firstIndex(where: { $0.internalPortID == port.id }) {
                    settings.publishedInputs[index].isPublished = true
                    settings.publishedInputs[index].name = port.name
                } else {
                    let macroPortID = "macro:\(macroNodeID.uuidString):input:\(settings.publishedInputs.count)"
                    settings.publishedInputs.append(
                        MacroPublishedPortSettings(macroPortID: macroPortID, internalPortID: port.id, name: port.name, kind: kind, isPublished: true)
                    )
                }
            case .output:
                if let index = settings.publishedOutputs.firstIndex(where: { $0.internalPortID == port.id }) {
                    settings.publishedOutputs[index].isPublished = true
                    settings.publishedOutputs[index].name = port.name
                } else {
                    let macroPortID = "macro:\(macroNodeID.uuidString):output:\(settings.publishedOutputs.count)"
                    settings.publishedOutputs.append(
                        MacroPublishedPortSettings(macroPortID: macroPortID, internalPortID: port.id, name: port.name, kind: kind, isPublished: true)
                    )
                }
            }
            macroNodeSettings[macroNodeID] = settings
            rebuildMacroNodePorts(for: macroNodeID)
            return
        }

        if let iteratorNodeID = editingIteratorNodeID,
           var settings = iteratorNodeSettings[iteratorNodeID],
           port.nodeID != iteratorNodeID {
            let kind = macroPublishedPortKind(for: port.kind)!
            switch port.direction {
            case .input:
                if let index = settings.publishedInputs.firstIndex(where: { $0.internalPortID == port.id }) {
                    settings.publishedInputs[index].isPublished = true
                    settings.publishedInputs[index].name = port.name
                } else {
                    let iteratorPortID = "iterator:\(iteratorNodeID.uuidString):input:\(settings.publishedInputs.count)"
                    settings.publishedInputs.append(
                        MacroPublishedPortSettings(macroPortID: iteratorPortID, internalPortID: port.id, name: port.name, kind: kind, isPublished: true)
                    )
                }
            case .output:
                if let index = settings.publishedOutputs.firstIndex(where: { $0.internalPortID == port.id }) {
                    settings.publishedOutputs[index].isPublished = true
                    settings.publishedOutputs[index].name = port.name
                } else {
                    let iteratorPortID = "iterator:\(iteratorNodeID.uuidString):output:\(settings.publishedOutputs.count)"
                    settings.publishedOutputs.append(
                        MacroPublishedPortSettings(macroPortID: iteratorPortID, internalPortID: port.id, name: port.name, kind: kind, isPublished: true)
                    )
                }
            }
            iteratorNodeSettings[iteratorNodeID] = settings
            rebuildIteratorNodePorts(for: iteratorNodeID)
        }
    }

    func attachNodeToActiveContainerIfNeeded(_ nodeID: GraphNode.ID) {
        guard let node = node(withID: nodeID) else { return }
        let isIteratorVariables: Bool = {
            if case .iteratorVariables = node.kind { return true }
            return false
        }()
        if let macroNodeID = editingMacroNodeID,
           nodeID != macroNodeID,
           isIteratorVariables == false {
            var settings = macroNodeSettings[macroNodeID] ?? MacroNodeSettings(childNodeIDs: [], publishedInputs: [], publishedOutputs: [])
            if settings.childNodeIDs.contains(nodeID) == false {
                settings.childNodeIDs.append(nodeID)
                macroNodeSettings[macroNodeID] = settings
                selectedNodeID = nodeID
                selectedNodeIDs = [nodeID]
                statusMessage = "Added \(node.title) to the macro."
            }
            return
        }

        if let iteratorNodeID = editingIteratorNodeID,
           nodeID != iteratorNodeID {
            var settings = iteratorNodeSettings[iteratorNodeID] ?? IteratorNodeSettings(childNodeIDs: [], publishedInputs: [], publishedOutputs: [], iterations: 4.0)
            if settings.childNodeIDs.contains(nodeID) == false {
                settings.childNodeIDs.append(nodeID)
                iteratorNodeSettings[iteratorNodeID] = settings
                selectedNodeID = nodeID
                selectedNodeIDs = [nodeID]
                statusMessage = "Added \(node.title) to the iterator."
            }
        }
    }

