    func scalarValue(forMonitorNodeID nodeID: GraphNode.ID) -> Double? {
        guard
            let monitorNode = document.nodes.first(where: { $0.id == nodeID }),
            case .monitor = monitorNode.kind,
            let inputPort = monitorNode.inputPorts.first
        else {
            return nil
        }

        return resolvedScalarValue(forInputPortID: inputPort.id)
    }

    func stringValue(forMonitorNodeID nodeID: GraphNode.ID) -> String? {
        guard
            let monitorNode = document.nodes.first(where: { $0.id == nodeID }),
            case .monitor = monitorNode.kind,
            let inputPort = monitorNode.inputPorts.first
        else {
            return nil
        }

        return resolvedStringValue(forInputPortID: inputPort.id)
    }

    func scalarOutputValue(forNodeID nodeID: GraphNode.ID, outputName: String) -> Double? {
        guard
            let node = document.nodes.first(where: { $0.id == nodeID }),
            let outputPort = node.outputPorts.first(where: { $0.name == outputName })
        else {
            return nil
        }

        switch outputPort.kind {
        case .audio(let signal):
            return audioValue(for: signal)
        case .scalarSignal:
            return scalarValueForOutputPort(outputPort)
        default:
            return nil
        }
    }

    func renderOutputNodes() -> [GraphNode] {
        document.nodes.filter {
            if case .renderOutput = $0.kind { return true }
            return false
        }
        .sorted { $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending }
    }

    func renderTitle(for renderNodeID: GraphNode.ID?) -> String {
        guard
            let renderNodeID,
            let node = document.nodes.first(where: { $0.id == renderNodeID }),
            case .renderOutput = node.kind
        else {
            return "Active Render"
        }
        return node.title
    }

    private func effectiveRenderWindowTitle(forRenderNodeID renderNodeID: GraphNode.ID) -> String {
        for node in document.nodes {
            guard case .renderWindow = node.kind else { continue }
            guard targetRenderNodeID(forRenderWindowNodeID: node.id) == renderNodeID else { continue }
            let settings = settings(forRenderWindowNodeID: node.id)
            let customTitle = settings.title.trimmingCharacters(in: .whitespacesAndNewlines)
            if !customTitle.isEmpty {
                return customTitle
            }
        }
        return renderTitle(for: renderNodeID)
    }

    func stringOutputValue(forNodeID nodeID: GraphNode.ID, outputName: String) -> String? {
        guard
            let node = document.nodes.first(where: { $0.id == nodeID }),
            let outputPort = node.outputPorts.first(where: { $0.name == outputName })
        else {
            return nil
        }

        guard case .stringSignal = outputPort.kind else {
            return nil
        }

        return stringValueForOutputPort(outputPort)
