    func updateRandomNodeSettings(_ nodeID: GraphNode.ID, mutate: (inout RandomNodeSettings) -> Void) {
        var settings = settings(forRandomNodeID: nodeID)
        mutate(&settings)
        if settings.min > settings.max {
            swap(&settings.min, &settings.max)
        }
        settings.rate = max(0.1, settings.rate)
        settings.threshold = min(max(settings.threshold, 0.0), 1.0)
        randomNodeSettings[nodeID] = settings
        var runtime = randomNodeRuntimeStates[nodeID] ?? RandomNodeRuntimeState(
            value: randomValue(for: settings.min, max: settings.max),
            lastTriggerHigh: false,
            lastContinuousBucket: nil
        )
        runtime.value = min(max(runtime.value, settings.min), settings.max)
        randomNodeRuntimeStates[nodeID] = runtime
        objectWillChange.send()
    }

