    func updateLayerNodeSettings(_ nodeID: GraphNode.ID, mutate: (inout LayerNodeSettings) -> Void) {
        var settings = normalizedLayerSettings(layerNodeSettings[nodeID] ?? LayerNodeSettings())
        let previousLayerCount = max(2, settings.layerCount)
        mutate(&settings)
        settings.layerCount = max(2, settings.layerCount)
        settings = normalizedLayerSettings(settings)
        layerNodeSettings[nodeID] = settings
        if settings.layerCount != previousLayerCount {
            document = syncLayerNodePorts(in: document)
        }
        objectWillChange.send()
    }

