    func rebuildFromEditableSource() {
        let selectedFragmentID = selectedFragmentNode?.id
        let shouldReplaceMetal = selectedFragmentID.map {
            editableMetalSource == lastGeneratedMetalSources[$0]
        } ?? false
        let parsed = ISFParser.parse(shaderSource: editableSource)
        document = parsed
        document = syncArrayNodePorts(in: document)
        pruneSliderNodeSettings()
        pruneSliderStyleNodeSettings()
        pruneButtonNodeSettings()
        pruneButtonStyleNodeSettings()
        pruneSelectNodeSettings()
        pruneScaleNodeSettings()
        pruneInterpolatorNodeSettings()
        pruneHoldNodeSettings()
        pruneScalarSmoothNodeSettings()
        pruneHitZoneNodeSettings()
        pruneRectHitNodeSettings()
        pruneGridLayoutNodeSettings()
        pruneMacroNodeSettings()
        prunePolarNodeSettings()
        pruneHandTrackerNodeSettings()
        prunePinchNodeSettings()
        pruneScrollGestureNodeSettings()
        pruneZoomGestureNodeSettings()
        pruneTrackballNodeSettings()
        pruneDepthEstimateNodeSettings()
        pruneBeatDetectNodeSettings()
        pruneMathNodeSettings()
        pruneExpressionNodeSettings()
        pruneClampNodeSettings()
        pruneMapRangeNodeSettings()
        pruneLogicNodeSettings()
        pruneCompareNodeSettings()
        pruneRandomNodeSettings()
        prunePulseNodeSettings()
        pruneFireOnLoadNodeSettings()
        pruneCounterNodeSettings()
        pruneToggleNodeSettings()
        pruneDelayNodeSettings()
        pruneTimerNodeSettings()
        pruneScalarVariableNodeSettings()
        pruneStringVariableNodeSettings()
        pruneStringNodeSettings()
        pruneStringFormatNodeSettings()
        pruneStringCompareNodeSettings()
        pruneStringSplitNodeSettings()
        pruneColorNodeSettings()
        pruneHSLColorNodeSettings()
        pruneScalarArrayNodeSettings()
        pruneStringArrayNodeSettings()
        pruneColorArrayNodeSettings()
        pruneImageArrayNodeSettings()
        pruneScalarArrayIndexNodeSettings()
        pruneStringArrayIndexNodeSettings()
        pruneColorArrayIndexNodeSettings()
        pruneImageArrayIndexNodeSettings()
        pruneTextImageNodeSettings()
        pruneMIDIOutNodeSettings()
        pruneMIDICCNodeSettings()
        pruneMIDIInputNodeSettings()
        pruneOSCNodeSettings()
        pruneNoteNodeSettings()
        pruneTransformNodeSettings()
        pruneScene3DTransformNodeSettings()
        pruneScene3DTileNodeSettings()
        pruneBillboardNodeSettings()
        pruneTransitionNodeSettings()
        pruneTrailNodeSettings()
        pruneCircleNodeSettings()
        pruneClearNodeSettings()
        pruneImageNodeSettings()
        pruneWebViewNodeSettings()
        pruneAIImageNodeSettings()
        pruneVideoPlayerNodeSettings()
        pruneLayerNodeSettings()
        pruneOSCNodeSettings()
        pruneFeedbackNodeSettings()
        pruneReactionDiffusionNodeSettings()
        pruneCoreImageNodeSettings()
        pruneUnderwaterNodeSettings()
        setEditableSourceProgrammatically(parsed.source)

        if shouldReplaceMetal {
            let generated = Self.makeMetalStub(from: parsed)
            let primaryFragmentID = parsed.nodes.first(where: \.isPrimaryFragment)?.id
            fragmentMetalSources = primaryFragmentID.map { [$0: generated] } ?? [:]
            lastGeneratedMetalSources = fragmentMetalSources
        }

        document = syncFragmentNodePorts(in: document)
        baselineUniformValues = Dictionary(uniqueKeysWithValues: document.uniforms.map { ($0.id, $0.defaultValue) })
        selectedNodeID = parsed.nodes.first?.id
        syncEditableMetalSourceWithSelection()
        updateInspectorFocus()
        statusMessage = "Graph rebuilt from current source."
        validateMetalSource()
        updateMIDINodes()
        updateOSCNodes()
    }

    func rebuildCurrentGraph() {
        if let fragmentNodeID = selectedFragmentNode?.id {
            fragmentMetalSources[fragmentNodeID] = editableMetalSource
        }

        var updatedDocument = document
        if editableSource != updatedDocument.source {
            updatedDocument = ShaderDocument(
                name: updatedDocument.name,
                description: updatedDocument.description,
                source: editableSource,
                shaderPrelude: updatedDocument.shaderPrelude,
                shaderBody: updatedDocument.shaderBody,
                uniforms: updatedDocument.uniforms,
                nodes: updatedDocument.nodes,
                connections: updatedDocument.connections
            )
        }

        updatedDocument = syncFragmentNodePorts(in: updatedDocument)
        updatedDocument = syncCompareNodePorts(in: updatedDocument)
        updatedDocument = syncStringFormatNodePorts(in: updatedDocument)
        updatedDocument = syncExpressionNodePorts(in: updatedDocument)
        updatedDocument = syncArrayNodePorts(in: updatedDocument)
        updatedDocument = syncTextImageNodePorts(in: updatedDocument)
        updatedDocument = syncHSLColorNodePorts(in: updatedDocument)
        document = updatedDocument
        pruneScaleNodeSettings()
        pruneInterpolatorNodeSettings()
        pruneHoldNodeSettings()
        pruneScalarSmoothNodeSettings()
        pruneHitZoneNodeSettings()
        pruneRectHitNodeSettings()
        pruneGridLayoutNodeSettings()
        pruneMacroNodeSettings()
        prunePolarNodeSettings()
        pruneHandTrackerNodeSettings()
        prunePinchNodeSettings()
        pruneScrollGestureNodeSettings()
        pruneZoomGestureNodeSettings()
        pruneTrackballNodeSettings()
        pruneDepthEstimateNodeSettings()
        pruneBeatDetectNodeSettings()
        pruneMathNodeSettings()
        pruneExpressionNodeSettings()
        pruneClampNodeSettings()
        pruneMapRangeNodeSettings()
        pruneLogicNodeSettings()
