        pruneFeedbackNodeSettings()
        pruneReactionDiffusionNodeSettings()
        pruneCoreImageNodeSettings()
        pruneUnderwaterNodeSettings()
        reconnectPrimaryRenderIfNeeded()
        updateMIDINodes()

        if let selectedNodeID,
           document.nodes.contains(where: { $0.id == selectedNodeID }) {
            self.selectedNodeID = selectedNodeID
        } else {
            self.selectedNodeID = primaryFragmentNode?.id ?? renderNode?.id ?? document.nodes.first?.id
        }

        syncEditableMetalSourceWithSelection()
        updateInspectorFocus()
        statusMessage = "Graph rebuilt from current nodes."
        validateMetalSource()
    }

    func regenerateMetalStub() {
        let generated = Self.makeMetalStub(from: document)
        guard let fragmentNodeID = selectedFragmentNode?.id ?? primaryFragmentNode?.id else { return }
        fragmentMetalSources[fragmentNodeID] = generated
        lastGeneratedMetalSources[fragmentNodeID] = generated
        syncEditableMetalSourceWithSelection()
        statusMessage = "Metal fragment stub refreshed."
        validateMetalSource()
    }

    private func uniqueCustomFragmentPresetTitle(preferred base: String) -> String {
        let trimmedBase = base.trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedBase = trimmedBase.replacingOccurrences(
            of: #"\s+\d+$"#,
            with: "",
            options: .regularExpression
        )
        let existingTitles = Set(customFragmentPresets.map { $0.title.lowercased() })
        let conflictsBuiltIn = Self.presetMetalSource(named: trimmedBase) != nil
        if !existingTitles.contains(trimmedBase.lowercased()) && !conflictsBuiltIn {
            return trimmedBase
        }

        var index = 2
        while existingTitles.contains("\(normalizedBase.lowercased()) \(index)")
            || Self.presetMetalSource(named: "\(normalizedBase) \(index)") != nil {
            index += 1
        }
        return "\(normalizedBase) \(index)"
    }

    private func persistCustomFragmentPresets() {
        let defaults = UserDefaults.standard
        if let data = try? JSONEncoder().encode(customFragmentPresets) {
            defaults.set(data, forKey: GraphPreferenceKey.customFragmentPresets)
        }
    }

    private static func loadCustomFragmentPresets(from defaults: UserDefaults) -> [CustomFragmentPreset] {
        guard let data = defaults.data(forKey: GraphPreferenceKey.customFragmentPresets),
              let presets = try? JSONDecoder().decode([CustomFragmentPreset].self, from: data) else {
            return []
        }
        return presets.sorted { $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending }
    }

    func importISF(result: Result<[URL], Error>) {
        do {
            guard let url = try result.get().first else { return }
            let source = try readSecurityScopedFile(at: url)
            let parsed = ISFParser.parse(shaderSource: source)
            let generated = Self.makeMetalStub(from: parsed)
            if shouldReplaceTemplateGraphOnImport {
                replaceTemplateGraph(
                    with: parsed,
                    source: source,
                    generatedMetal: generated
                )
            } else {
                appendImportedShader(
                    name: parsed.name,
                    source: source,
                    generatedMetal: generated,
                    importedUniforms: parsed.uniforms
                )
            }
            syncEditableMetalSourceWithSelection()
            updateInspectorFocus()
            validateMetalSource()
            statusMessage = "Imported \(url.lastPathComponent)."
        } catch {
            statusMessage = "Import failed: \(error.localizedDescription)"
        }
    }

    func importMetal(result: Result<[URL], Error>) {
        do {
            guard let url = try result.get().first else { return }
            let source = try readSecurityScopedFile(at: url)
            let title = uniqueNodeTitle(preferred: url.deletingPathExtension().lastPathComponent)
            appendMetalFragment(title: title, metalSource: source, at: CGPoint(x: 340, y: 260))
            statusMessage = "Imported \(url.lastPathComponent)."
        } catch {
            statusMessage = "Metal import failed: \(error.localizedDescription)"
        }
    }

    func importGraphSnapshot(result: Result<[URL], Error>) {
        do {
            guard let url = try result.get().first else { return }
            let source = try readSecurityScopedFile(at: url)
            try restoreGraphSnapshot(from: source)
            rememberCurrentGraphFile(url)
            restartOSCInputRouting()
            statusMessage = "Loaded graph snapshot \(url.lastPathComponent)."
        } catch {
            statusMessage = "Graph open failed: \(error.localizedDescription)"
        }
    }

    func runGraph() {
        resumeGraphClock()
        graphExecutionState = .running
        updateAudioMonitorState()
        updateVideoMonitorState()
        updateMIDINodes()
        updateOSCNodes()
        if isPreviewVisible == false {
            let renderNodes = renderOutputNodes()
            for renderNode in renderNodes {
                openPreviewWindow(for: renderNode.id)
            }
        }
        statusMessage = "Graph running."
    }

    func pauseGraph() {
        pauseGraphClock()
        graphExecutionState = .paused
        updateAudioMonitorState()
        updateVideoMonitorState()
        updateMIDINodes()
        updateOSCNodes()
        closeAllPreviewWindows()
        statusMessage = "Graph paused."
    }

    func restartGraphExecution() {
        let shouldReopenRender = !renderOutputNodes().isEmpty
        pauseGraph()
        resumeGraphClock()
        graphExecutionState = .running
        updateAudioMonitorState()
        updateVideoMonitorState()
        updateMIDINodes()
        restartOSCInputRouting()
        updateOSCNodes()
        if shouldReopenRender {
            let renderNodes = renderOutputNodes()
            for renderNode in renderNodes {
                openPreviewWindow(for: renderNode.id)
            }
        }
        statusMessage = "Graph restarted."
    }

    func togglePreviewWindow() {
        if isPreviewVisible {
            closeAllPreviewWindows()
            return
        }

        let renderNodes = renderOutputNodes()
        guard renderNodes.isEmpty == false else { return }
        for renderNode in renderNodes {
            openPreviewWindow(for: renderNode.id)
        }
    }

    func openPreviewWindow(for renderNodeID: GraphNode.ID) {
        guard let node = node(withID: renderNodeID), case .renderOutput = node.kind else { return }
        selectNode(renderNodeID)
        let controller = previewWindowControllers[renderNodeID] ?? PreviewWindowController(store: self, renderNodeID: renderNodeID)
        previewWindowControllers[renderNodeID] = controller
        controller.show(
            title: effectiveRenderWindowTitle(forRenderNodeID: renderNodeID),
            preferredContentSize: preferredPreviewWindowContentSize(for: renderNodeID),
            preferredOrigin: preferredPreviewWindowOrigin(for: renderNodeID),
            preferredLevelMode: preferredPreviewWindowLevelMode(for: renderNodeID),
            preferredFullScreen: preferredPreviewWindowFullScreen(for: renderNodeID)
        )
    }

    func previewVideoRecorder(forRenderNodeID renderNodeID: GraphNode.ID) -> PreviewVideoRecorder? {
        activePreviewVideoExportRenderNodeID == renderNodeID ? activePreviewVideoRecorder : nil
    }

    func exportPreviewMovie() {
        guard activePreviewVideoRecorder == nil else {
            statusMessage = "Movie export already running."
            return
        }

        let targetRenderNodeID = selectedNode.flatMap { node -> GraphNode.ID? in
            if case .renderOutput = node.kind { return node.id }
            return nil
        } ?? renderOutputNodes().first?.id

        guard let targetRenderNodeID else {
            statusMessage = "Add a Render Output node before exporting a movie."
            return
        }

        let durationField = NSTextField(string: "10")
        durationField.placeholderString = "Seconds"
        let fpsField = NSTextField(string: "60")
        fpsField.placeholderString = "FPS"

        let stack = NSStackView()
        stack.orientation = .vertical
        stack.spacing = 8
        stack.edgeInsets = NSEdgeInsets(top: 8, left: 0, bottom: 0, right: 0)
        stack.addArrangedSubview(exportPanelRow(label: "Duration", field: durationField))
        stack.addArrangedSubview(exportPanelRow(label: "FPS", field: fpsField))
        stack.frame = NSRect(x: 0, y: 0, width: 260, height: 72)

        DispatchQueue.main.async { [weak self] in
            guard let self, self.isPresentingOpenPanel == false else { return }
            self.isPresentingOpenPanel = true
            let shouldResumeGraph = self.isGraphRunning
            if shouldResumeGraph {
                self.suspendGraphExecutionForModalPanel()
            }
            self.statusMessage = "Choose a movie export location..."

            DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) { [weak self] in
                guard let self else { return }
                let panel = NSSavePanel()
                panel.allowedContentTypes = [.quickTimeMovie]
                panel.nameFieldStringValue = "\(self.currentGraphDisplayName)-export.mov"
                panel.accessoryView = stack

                let finish: (NSApplication.ModalResponse, URL?) -> Void = { [weak self] response, url in
                    guard let self else { return }
                    self.isPresentingOpenPanel = false
                    if shouldResumeGraph {
                        self.resumeGraphExecutionAfterModalPanel()
                    }
                    guard response == .OK, let url else {
                        self.statusMessage = "Movie export cancelled."
                        return
                    }

                    let duration = max(0.1, min(3600.0, durationField.doubleValue))
                    let fps = Int32(max(1, min(120, fpsField.integerValue)))
                    self.startPreviewMovieExport(to: url, renderNodeID: targetRenderNodeID, duration: duration, fps: fps)
                }

                if let window = NSApp.keyWindow ?? NSApp.mainWindow {
                    panel.beginSheetModal(for: window) { response in
                        finish(response, panel.url)
                    }
                } else {
                    finish(panel.runModal(), panel.url)
                }
            }
        }
    }

    private func exportPanelRow(label: String, field: NSTextField) -> NSView {
        let row = NSStackView()
        row.orientation = .horizontal
        row.spacing = 8

        let labelView = NSTextField(labelWithString: label)
        labelView.frame = NSRect(x: 0, y: 0, width: 80, height: 22)
        field.frame = NSRect(x: 0, y: 0, width: 120, height: 22)

        row.addArrangedSubview(labelView)
        row.addArrangedSubview(field)
        return row
    }

    private func startPreviewMovieExport(to url: URL, renderNodeID: GraphNode.ID, duration: Double, fps: Int32) {
        openPreviewWindow(for: renderNodeID)
        activePreviewVideoExportRenderNodeID = renderNodeID
        let recorder = PreviewVideoRecorder(
            outputURL: url,
            duration: duration,
            fps: fps,
            audioFormat: audioMonitor.currentRecordingFormat(),
            progress: { [weak self] message in
                self?.statusMessage = message
            }
        ) { [weak self] result in
            guard let self else { return }
            self.activePreviewVideoRecorder = nil
            self.activePreviewVideoExportRenderNodeID = nil
            self.isMovieAudioCaptureActive = false
            self.audioMonitor.setExportTap(nil)
            self.updateAudioMonitorState()
            switch result {
            case .success(let url):
                self.statusMessage = "Exported movie to \(url.lastPathComponent)."
            case .failure(let error):
                self.statusMessage = "Movie export failed: \(error.localizedDescription)"
            }
        }
        isMovieAudioCaptureActive = true
        audioMonitor.setExportTap { [weak recorder] buffer in
            recorder?.captureAudio(buffer: buffer)
        }
        activePreviewVideoRecorder = recorder
        runGraph()
        updateAudioMonitorState()
        statusMessage = "Recording \(Int(duration))s movie at \(fps) FPS..."
    }

    func hideAuxiliaryWindows() {
        closeAllPreviewWindows()
        codeEditorWindowController.close()
        for controller in webViewWindowControllers.values {
            controller.close()
        }
    }

    private func closeAllPreviewWindows() {
        let controllers = Array(previewWindowControllers.values)
        for controller in controllers {
            controller.close()
        }
    }

    func openCodeEditorWindow() {
        let targetFragmentNodeID = selectedFragmentNode?.id ?? primaryFragmentNode?.id
        codeEditorFragmentNodeID = targetFragmentNodeID
        if let targetFragmentNodeID {
            setEditableMetalSourceProgrammatically(metalSource(for: targetFragmentNodeID))
        }
        codeEditorWindowController.show()
    }

    func openWebViewWindow(for nodeID: GraphNode.ID) {
        guard let node = node(withID: nodeID), case .webView = node.kind else { return }
        let controller = webViewWindowControllers[nodeID] ?? WebViewWindowController(store: self, nodeID: nodeID)
        webViewWindowControllers[nodeID] = controller
        controller.show()
    }

    func refreshWebViewWindow(for nodeID: GraphNode.ID) {
        openWebViewWindow(for: nodeID)
        webViewWindowControllers[nodeID]?.reloadCurrentURL()
    }

    fileprivate func webViewControlState(for nodeID: GraphNode.ID) -> WebViewControlState {
        guard let node = node(withID: nodeID), case .webView = node.kind else {
            return WebViewControlState(pointer: nil, click: 0.0, scrollX: 0.0, scrollY: 0.0, zoom: 1.0)
        }

        let pointer = node.inputPorts.first(where: { $0.name == "Pointer" }).flatMap { resolvedPointValue(forInputPortID: $0.id) }
        let click = node.inputPorts.first(where: { $0.name == "Click" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? 0.0
        let scrollX = node.inputPorts.first(where: { $0.name == "Scroll X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? 0.0
        let scrollY = node.inputPorts.first(where: { $0.name == "Scroll Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? 0.0
        let zoom = node.inputPorts.first(where: { $0.name == "Zoom" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? 1.0

        return WebViewControlState(pointer: pointer, click: click, scrollX: scrollX, scrollY: scrollY, zoom: zoom)
    }

    fileprivate func videoPlayerControlState(for nodeID: GraphNode.ID) -> VideoPlayerControlState {
        guard let node = node(withID: nodeID), case .videoPlayer = node.kind else {
            return VideoPlayerControlState(play: 1.0, rate: 1.0, seek: nil, volume: 1.0)
        }

        let settings = settings(forVideoPlayerNodeID: nodeID)
        let play = node.inputPorts.first(where: { $0.name == "Play" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? (settings.isPlaying ? 1.0 : 0.0)
        let rate = node.inputPorts.first(where: { $0.name == "Rate" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rate
        let seek = node.inputPorts.first(where: { $0.name == "Seek" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.seekPosition
        let volume = node.inputPorts.first(where: { $0.name == "Volume" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.volume

        return VideoPlayerControlState(
            play: play,
            rate: max(0.0, min(4.0, rate)),
            seek: max(0.0, min(1.0, seek)),
            volume: max(0.0, min(1.0, volume))
        )
    }

    fileprivate func nodeHasRenderableConsumer(_ nodeID: GraphNode.ID) -> Bool {
        guard let node = node(withID: nodeID) else { return false }
        let outputPortIDs = Set(node.outputPorts.map(\.id))
        return document.connections.contains { outputPortIDs.contains($0.fromPortID) }
    }

    private func midpoint(_ a: CGPoint?, _ b: CGPoint?) -> CGPoint? {
        guard let a, let b else { return nil }
        return CGPoint(x: (a.x + b.x) * 0.5, y: (a.y + b.y) * 0.5)
    }

    private func normalizedDepthValue(span: Double, settings: DepthEstimateNodeSettings) -> Double {
        let near = settings.nearSpan
        let far = settings.farSpan
        let denominator = near - far
        guard abs(denominator) > .ulpOfOne else { return 0.0 }
        var depth = (span - far) / denominator
        depth = min(max(depth, 0.0), 1.0)
        return settings.invert ? (1.0 - depth) : depth
    }

    private func depthEstimateOutput(
        from sourceNode: GraphNode,
        outputName: String,
        visitedNodeIDs: Set<GraphNode.ID>
    ) -> Double? {
        guard case .depthEstimate = sourceNode.kind else { return nil }
        let fingerInput = sourceNode.inputPorts.first(where: { $0.name == "Finger" })
        let thumbInput = sourceNode.inputPorts.first(where: { $0.name == "Thumb" })
        let nearInput = sourceNode.inputPorts.first(where: { $0.name == "Near" })
        let farInput = sourceNode.inputPorts.first(where: { $0.name == "Far" })
        let touchInput = sourceNode.inputPorts.first(where: { $0.name == "Touch" })
        let finger = fingerInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
        let thumb = thumbInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
        var settings = settings(forDepthEstimateNodeID: sourceNode.id)
        if let nearInput {
            settings.nearSpan = scalarValue(forInputPortID: nearInput.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) ?? settings.nearSpan
        }
        if let farInput {
            settings.farSpan = scalarValue(forInputPortID: farInput.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) ?? settings.farSpan
        }
        if let touchInput {
            settings.touchThreshold = scalarValue(forInputPortID: touchInput.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) ?? settings.touchThreshold
        }

        guard let finger, let thumb else {
            depthEstimateNodeRuntimeStates[sourceNode.id] = DepthEstimateNodeRuntimeState(smoothedDepth: 0.0)
            return outputName == "Touching" ? 0.0 : (outputName == "Depth" ? 0.0 : nil)
        }

        let dx = Double(finger.x - thumb.x)
        let dy = Double(finger.y - thumb.y)
        let span = sqrt((dx * dx) + (dy * dy))
        let depth = normalizedDepthValue(span: span, settings: settings)
        let previous = depthEstimateNodeRuntimeStates[sourceNode.id]?.smoothedDepth ?? depth
        let smoothed = previous + ((depth - previous) * settings.smoothing)
        depthEstimateNodeRuntimeStates[sourceNode.id] = DepthEstimateNodeRuntimeState(smoothedDepth: smoothed)

        switch outputName {
        case "Depth":
            return smoothed
        case "Span":
            return span
        case "Touching":
            return smoothed >= settings.touchThreshold ? 1.0 : 0.0
        default:
            return nil
        }
    }

    func closeCodeEditorWindow() {
        codeEditorWindowController.close()
        codeEditorFragmentNodeID = nil
    }

    func toggleCodeEditorWindow() {
        if isCodeEditorVisible {
            closeCodeEditorWindow()
        } else {
            openCodeEditorWindow()
        }
    }

    fileprivate func previewDidOpen(renderNodeID: GraphNode.ID) {
        isPreviewVisible = previewWindowControllers[renderNodeID]?.isVisible == true || previewWindowControllers.values.contains(where: \.isVisible)
    }

    fileprivate func previewDidClose(renderNodeID: GraphNode.ID) {
        previewWindowContentSizes.removeValue(forKey: renderNodeID)
        previewWindowControllers.removeValue(forKey: renderNodeID)
        isPreviewVisible = previewWindowControllers.values.contains(where: \.isVisible)
    }

    fileprivate func previewWindowDidResize(renderNodeID: GraphNode.ID, contentSize: CGSize) {
        previewWindowContentSizes[renderNodeID] = contentSize
        var didChange = false
        for node in document.nodes {
            guard case .renderWindow = node.kind else { continue }
            guard targetRenderNodeID(forRenderWindowNodeID: node.id) == renderNodeID else { continue }
            var settings = settings(forRenderWindowNodeID: node.id)
            let nextWidth = Double(contentSize.width)
            let nextHeight = Double(contentSize.height)
            guard abs(settings.width - nextWidth) > 0.5 || abs(settings.height - nextHeight) > 0.5 else { continue }
            settings.width = nextWidth
            settings.height = nextHeight
            renderWindowNodeSettings[node.id] = settings
            didChange = true
        }
        if didChange || previewWindowContentSizes[renderNodeID] != contentSize {
            objectWillChange.send()
        }
    }

    fileprivate func previewWindowDidMove(renderNodeID: GraphNode.ID, origin: CGPoint) {
        var didChange = false
        for node in document.nodes {
            guard case .renderWindow = node.kind else { continue }
            guard targetRenderNodeID(forRenderWindowNodeID: node.id) == renderNodeID else { continue }
            var settings = settings(forRenderWindowNodeID: node.id)
            let nextX = Double(origin.x)
            let nextY = Double(origin.y)
            guard abs(settings.x - nextX) > 0.5 || abs(settings.y - nextY) > 0.5 else { continue }
            settings.x = nextX
            settings.y = nextY
            renderWindowNodeSettings[node.id] = settings
            didChange = true
        }
        if didChange {
            objectWillChange.send()
        }
    }

    fileprivate func previewWindowDidChangeFullScreen(renderNodeID: GraphNode.ID, isFullScreen: Bool) {
        var didChange = false
        for node in document.nodes {
            guard case .renderWindow = node.kind else { continue }
            guard targetRenderNodeID(forRenderWindowNodeID: node.id) == renderNodeID else { continue }
            var settings = settings(forRenderWindowNodeID: node.id)
            let nextValue = isFullScreen ? 1.0 : 0.0
            guard abs(settings.fullscreen - nextValue) > 0.5 else { continue }
            settings.fullscreen = nextValue
            renderWindowNodeSettings[node.id] = settings
            didChange = true
        }
        if didChange {
            objectWillChange.send()
        }
    }

    func preferredPreviewWindowFramesPerSecond(for renderNodeID: GraphNode.ID) -> Int {
        for node in document.nodes {
            guard case .renderWindow = node.kind else { continue }
            guard targetRenderNodeID(forRenderWindowNodeID: node.id) == renderNodeID else { continue }
            return resolvedRenderWindowFramesPerSecond(forRenderWindowNodeID: node.id)
        }
        return 60
    }

    func preferredPreviewWindowSyphonServerName(for renderNodeID: GraphNode.ID) -> String? {
        for node in document.nodes {
            guard case .renderWindow = node.kind else { continue }
            guard targetRenderNodeID(forRenderWindowNodeID: node.id) == renderNodeID else { continue }
            let settings = settings(forRenderWindowNodeID: node.id)
            guard settings.syphonEnabled else { return nil }
            let trimmedName = settings.syphonName.trimmingCharacters(in: .whitespacesAndNewlines)
            if trimmedName.isEmpty == false {
                return trimmedName
            }
            return "Metal Composer - \(effectiveRenderWindowTitle(forRenderNodeID: renderNodeID))"
        }
        return nil
    }

    private func targetRenderNodeID(forRenderWindowNodeID nodeID: GraphNode.ID) -> GraphNode.ID? {
        let settings = settings(forRenderWindowNodeID: nodeID)
        if let targetID = settings.targetRenderNodeID,
           let targetNode = node(withID: targetID),
           case .renderOutput = targetNode.kind {
            return targetID
        }
        return activePreviewRenderNodeID ?? renderOutputNodes().first?.id
    }

    private func resolvedRenderWindowContentSize(forRenderWindowNodeID nodeID: GraphNode.ID) -> CGSize {
        guard let sourceNode = node(withID: nodeID), case .renderWindow = sourceNode.kind else {
            return CGSize(width: 960, height: 640)
        }
        let settings = settings(forRenderWindowNodeID: nodeID)
        let width = sourceNode.inputPorts.first(where: { $0.name == "Width" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.width
        let height = sourceNode.inputPorts.first(where: { $0.name == "Height" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.height
        return CGSize(width: max(1.0, width), height: max(1.0, height))
    }

    private func resolvedRenderWindowOrigin(forRenderWindowNodeID nodeID: GraphNode.ID) -> CGPoint {
        guard let sourceNode = node(withID: nodeID), case .renderWindow = sourceNode.kind else {
            return CGPoint(x: 180.0, y: 180.0)
        }
        let settings = settings(forRenderWindowNodeID: nodeID)
        let x = sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.x
        let y = sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.y
        return CGPoint(x: x, y: y)
    }

    private func resolvedRenderWindowFullScreen(forRenderWindowNodeID nodeID: GraphNode.ID) -> Bool {
        guard let sourceNode = node(withID: nodeID), case .renderWindow = sourceNode.kind else {
            return false
        }
        let settings = settings(forRenderWindowNodeID: nodeID)
        let value = sourceNode.inputPorts.first(where: { $0.name == "Fullscreen" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.fullscreen
        return value >= 0.5
    }

    private func resolvedRenderWindowLevelMode(forRenderWindowNodeID nodeID: GraphNode.ID) -> RenderWindowLevelMode {
        settings(forRenderWindowNodeID: nodeID).levelMode
    }

    private func resolvedRenderWindowFramesPerSecond(forRenderWindowNodeID nodeID: GraphNode.ID) -> Int {
        guard let sourceNode = node(withID: nodeID), case .renderWindow = sourceNode.kind else {
            return 60
        }
        let settings = settings(forRenderWindowNodeID: nodeID)
        let value = sourceNode.inputPorts.first(where: { $0.name == "FPS" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.fps
        return Int(max(1.0, min(120.0, value)).rounded())
    }

    private func preferredPreviewWindowContentSize(for renderNodeID: GraphNode.ID) -> CGSize? {
        for node in document.nodes {
            guard case .renderWindow = node.kind else { continue }
            guard targetRenderNodeID(forRenderWindowNodeID: node.id) == renderNodeID else { continue }
            return resolvedRenderWindowContentSize(forRenderWindowNodeID: node.id)
        }
        return nil
    }

    private func preferredPreviewWindowOrigin(for renderNodeID: GraphNode.ID) -> CGPoint? {
        for node in document.nodes {
            guard case .renderWindow = node.kind else { continue }
            guard targetRenderNodeID(forRenderWindowNodeID: node.id) == renderNodeID else { continue }
            return resolvedRenderWindowOrigin(forRenderWindowNodeID: node.id)
        }
        return nil
    }

    private func preferredPreviewWindowFullScreen(for renderNodeID: GraphNode.ID) -> Bool? {
        for node in document.nodes {
            guard case .renderWindow = node.kind else { continue }
            guard targetRenderNodeID(forRenderWindowNodeID: node.id) == renderNodeID else { continue }
            return resolvedRenderWindowFullScreen(forRenderWindowNodeID: node.id)
        }
        return nil
    }

    private func preferredPreviewWindowLevelMode(for renderNodeID: GraphNode.ID) -> RenderWindowLevelMode? {
        for node in document.nodes {
            guard case .renderWindow = node.kind else { continue }
            guard targetRenderNodeID(forRenderWindowNodeID: node.id) == renderNodeID else { continue }
            return resolvedRenderWindowLevelMode(forRenderWindowNodeID: node.id)
        }
        return nil
    }

    private func synchronizePreviewWindowControllers() {
        for renderNode in renderOutputNodes() {
            previewWindowControllers[renderNode.id]?.updateTitle(effectiveRenderWindowTitle(forRenderNodeID: renderNode.id))
            if let preferredSize = preferredPreviewWindowContentSize(for: renderNode.id) {
                previewWindowControllers[renderNode.id]?.setContentSize(preferredSize)
            }
            if let preferredOrigin = preferredPreviewWindowOrigin(for: renderNode.id) {
                previewWindowControllers[renderNode.id]?.setOrigin(preferredOrigin)
            }
            if let preferredLevelMode = preferredPreviewWindowLevelMode(for: renderNode.id) {
                previewWindowControllers[renderNode.id]?.setLevelMode(preferredLevelMode)
            }
            if let preferredFullScreen = preferredPreviewWindowFullScreen(for: renderNode.id) {
                previewWindowControllers[renderNode.id]?.setFullScreen(preferredFullScreen)
            }
        }
    }

