    private func synchronizeWebViewControllers() {
        let liveWebViewNodeIDs = Set(document.nodes.compactMap { node -> GraphNode.ID? in
            guard case .webView = node.kind else { return nil }
            return node.id
        })

        let staleControllers = webViewWindowControllers.filter { !liveWebViewNodeIDs.contains($0.key) }
        for (nodeID, controller) in staleControllers {
            controller.close()
            webViewWindowControllers.removeValue(forKey: nodeID)
        }

        for nodeID in liveWebViewNodeIDs {
            let controller = webViewWindowControllers[nodeID] ?? WebViewWindowController(store: self, nodeID: nodeID)
            webViewWindowControllers[nodeID] = controller
            controller.ensureRunning()
        }
    }

    private func synchronizeVideoPlayerControllers() {
        let liveNodeIDs = Set(document.nodes.compactMap { node -> GraphNode.ID? in
            guard case .videoPlayer = node.kind else { return nil }
            return node.id
        })

        let staleControllers = videoPlayerControllers.filter { !liveNodeIDs.contains($0.key) }
        for (nodeID, controller) in staleControllers {
            controller.close()
            videoPlayerControllers.removeValue(forKey: nodeID)
            videoPlayerFrameData.removeValue(forKey: nodeID)
            videoPlayerNodeStatus.removeValue(forKey: nodeID)
            VideoPlayerFrameRegistry.shared.removePixelBuffer(for: nodeID)
        }

        for nodeID in liveNodeIDs {
            let controller = videoPlayerControllers[nodeID] ?? VideoPlayerController(store: self, nodeID: nodeID)
            videoPlayerControllers[nodeID] = controller
            controller.ensureRunning()
        }
    }

    func validateMetalSource() {
        guard let device else {
            metalCompilerMessage = "Metal unavailable on this machine."
            return
        }

        do {
            let metadataUniforms = ISFParser.parse(shaderSource: editableMetalSource).uniforms
            let validationUniforms = mergedUniforms(existing: document.uniforms, additional: metadataUniforms)
            let inferredValidationUniforms = inferredUniforms(from: [editableMetalSource], existing: validationUniforms)
            let finalValidationUniforms = mergedUniforms(existing: validationUniforms, additional: inferredValidationUniforms)
            let validationSource = runtimePreviewShaderSource(for: editableMetalSource, uniforms: finalValidationUniforms)
            let library = try device.makeLibrary(source: validationSource, options: nil)
            let descriptor = MTLRenderPipelineDescriptor()
            descriptor.vertexFunction = library.makeFunction(name: "previewVertex")
            descriptor.fragmentFunction = library.makeFunction(name: "generatedFragment")
            descriptor.colorAttachments[0].pixelFormat = .bgra8Unorm
            _ = try device.makeRenderPipelineState(descriptor: descriptor)
            metalCompilerMessage = nil
        } catch {
            metalCompilerMessage = String(describing: error)
        }
    }

