    private func configureBindings() {
        $editableSource
            .dropFirst()
            .removeDuplicates()
            .debounce(for: .milliseconds(450), scheduler: RunLoop.main)
            .sink { [weak self] _ in
                guard let self else { return }
                if self.ignoredEditableSourceChanges > 0 {
                    self.ignoredEditableSourceChanges -= 1
                    return
                }
                self.rebuildFromEditableSource()
            }
            .store(in: &cancellables)

        $editableMetalSource
            .dropFirst()
            .removeDuplicates()
            .debounce(for: .milliseconds(300), scheduler: RunLoop.main)
            .sink { [weak self] source in
                guard let self else { return }
                if self.ignoredEditableMetalSourceChanges > 0 {
                    self.ignoredEditableMetalSourceChanges -= 1
                    return
                }
                if let fragmentNodeID = self.codeEditorFragmentNodeID ?? self.selectedFragmentNode?.id {
                    self.fragmentMetalSources[fragmentNodeID] = source
                    self.document = self.syncFragmentNodePorts(in: self.document)
                }
                self.validateMetalSource()
            }
            .store(in: &cancellables)

        videoMonitor.$handSnapshot
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                guard let self, self.isGraphRunning else { return }
                self.updateMIDINodes()
                self.updateOSCNodes()
                self.objectWillChange.send()
            }
            .store(in: &cancellables)

        Timer.publish(every: 1.0 / 30.0, on: .main, in: .common)
            .autoconnect()
            .sink { [weak self] _ in
                guard let self else { return }
                guard self.isGraphRunning else { return }
                self.updateMIDINodes()
                self.updateOSCNodes()
                self.objectWillChange.send()
            }
            .store(in: &cancellables)

        $document
            .dropFirst()
            .sink { [weak self] _ in
                self?.updateAudioMonitorState()
                self?.updateVideoMonitorState()
                self?.updateMIDINodes()
                self?.updateOSCNodes()
                self?.synchronizeWebViewControllers()
                self?.synchronizeVideoPlayerControllers()
            }
            .store(in: &cancellables)

        let graphChangePublishers: [AnyPublisher<Void, Never>] = [
            $document.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $fragmentMetalSources.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $sliderNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $sliderStyleNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $buttonNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $buttonStyleNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $selectNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $scaleNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $interpolatorNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $pointCombineNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $point3CombineNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $point4CombineNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $pointInterpolatorNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $point3InterpolatorNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $point4InterpolatorNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $pointScaleNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $point3ScaleNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $point4ScaleNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $holdNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $scalarSmoothNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $handTrackerNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $pinchNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $scrollGestureNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $zoomGestureNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $depthEstimateNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $beatDetectNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $mathNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $expressionNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $clampNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $mapRangeNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $logicNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $compareNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $randomNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $pulseNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $counterNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $keyboardNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $scalarVariableNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $stringVariableNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $stringNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $stringFormatNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $stringCompareNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $stringSplitNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $colorNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $hslColorNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $scalarArrayNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $stringArrayNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $colorArrayNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $imageArrayNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $scalarArrayIndexNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $stringArrayIndexNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $colorArrayIndexNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $imageArrayIndexNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $textImageNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $polarNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $hitZoneNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $rectHitNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $screenBoundsNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $renderBoundsNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $renderWindowNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $gridLayoutNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $macroNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $iteratorNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $midiOutNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $midiCCNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $oscInputNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $oscOutputNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $oscSendNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $oscMessageNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $noteNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $transformNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $billboardNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $lineNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $scene3DPrimitiveNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $transitionNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $trailNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $circleNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $clearNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $videoPlayerNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $imageNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $webViewNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $aiImageNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $layerNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $feedbackNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $reactionDiffusionNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $coreImageNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher(),
            $underwaterNodeSettings.dropFirst().map { _ in () }.eraseToAnyPublisher()
        ]
        let graphChangePublisher = Publishers.MergeMany(graphChangePublishers)

        graphChangePublisher
            .sink { [weak self] _ in
                guard let self else { return }
                if self.ignoredGraphChangeNotifications > 0 {
                    self.ignoredGraphChangeNotifications -= 1
                    return
                }
                DispatchQueue.main.async { [weak self] in
                    self?.captureHistoryCheckpointIfNeeded()
                    self?.markCurrentGraphDirty()
                }
            }
            .store(in: &cancellables)

        graphChangePublisher
        .debounce(for: .milliseconds(300), scheduler: RunLoop.main)
        .sink { [weak self] _ in
            guard let self else { return }
            if self.ignoredGraphPersistenceNotifications > 0 {
                self.ignoredGraphPersistenceNotifications -= 1
                return
            }
            self.persistSessionSnapshot()
            self.autosaveCurrentGraphFileIfNeeded()
        }
        .store(in: &cancellables)

        $canvasBackgroundOpacity
            .dropFirst()
            .removeDuplicates()
            .sink { opacity in
                UserDefaults.standard.set(opacity, forKey: CanvasPreferenceKey.opacity)
            }
            .store(in: &cancellables)

        $canvasBackgroundColor
            .dropFirst()
            .sink { color in
                Self.saveCanvasColor(color)
            }
            .store(in: &cancellables)

        NotificationCenter.default.publisher(for: NSApplication.willTerminateNotification)
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                self?.flushSessionSnapshot()
            }
            .store(in: &cancellables)

        NotificationCenter.default.publisher(for: NSApplication.willResignActiveNotification)
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                self?.flushSessionSnapshot()
            }
            .store(in: &cancellables)
    }

    private func updateAudioMonitorState() {
        guard isGraphRunning else {
            audioMonitor.setMonitoringEnabled(false)
            return
        }
        let hasAudioNode = document.nodes.contains { node in
            if case .audio = node.kind { return true }
            if case .beatDetect = node.kind { return true }
            return false
        }
        audioMonitor.setMonitoringEnabled(hasAudioNode || isMovieAudioCaptureActive)
    }

    private func updateVideoMonitorState() {
        guard isGraphRunning else {
            videoMonitor.setVideoRequested(false, for: monitorClientID)
            videoMonitor.setHandTrackingEnabled(false, for: monitorClientID)
            return
        }
        let hasVideoNode = document.nodes.contains { node in
            if case .video = node.kind { return true }
            return false
        }
        let hasHandTrackerNode = document.nodes.contains { node in
            if case .handTracker = node.kind { return true }
            return false
        }

        videoMonitor.setVideoRequested(hasVideoNode, for: monitorClientID)
        videoMonitor.setHandTrackingEnabled(hasHandTrackerNode, for: monitorClientID)
    }

    private func updateMIDINodes() {
        guard isGraphRunning else {
            stopAllMIDINodes()
            midiCCNodeRuntimeStates.removeAll()
            return
        }

        let liveMIDINodeIDs = Set(document.nodes.compactMap { node -> GraphNode.ID? in
            if case .midiOut = node.kind { return node.id }
            return nil
        })
        let liveMIDICCNodeIDs = Set(document.nodes.compactMap { node -> GraphNode.ID? in
            if case .midiCC = node.kind { return node.id }
            return nil
        })

        for nodeID in midiNodeRuntimeStates.keys where !liveMIDINodeIDs.contains(nodeID) {
            stopMIDINode(nodeID)
            midiNodeRuntimeStates.removeValue(forKey: nodeID)
        }
        for nodeID in midiCCNodeRuntimeStates.keys where !liveMIDICCNodeIDs.contains(nodeID) {
            midiCCNodeRuntimeStates.removeValue(forKey: nodeID)
        }

        for node in document.nodes {
            switch node.kind {
            case .midiOut:
                guard let pointInput = node.inputPorts.first(where: { $0.name == "Point" }) else {
                    stopMIDINode(node.id)
                    continue
                }

                guard let point = resolvedPointValue(forInputPortID: pointInput.id) else {
                    stopMIDINode(node.id)
                    continue
                }

                let settings = settings(forMIDIOutNodeID: node.id)
                guard let note = midiNote(for: point, settings: settings) else {
                    stopMIDINode(node.id)
                    continue
                }

                let destinationName = resolvedMIDIDestinationName(for: settings)
                let channel = UInt8(settings.channel)
                let velocity = UInt8(settings.velocity)
                let active = ActiveMIDINote(note: note, channel: channel, destinationName: destinationName)
                let runtime = midiNodeRuntimeStates[node.id] ?? MIDINodeRuntimeState()

                if runtime.activeNote != active {
                    if let current = runtime.activeNote {
                        _ = midiRouter.sendNoteOff(note: current.note, channel: current.channel, destinationName: current.destinationName)
                    }
                    _ = midiRouter.sendNoteOn(note: note, velocity: velocity, channel: channel, destinationName: destinationName)
                }

                midiNodeRuntimeStates[node.id] = MIDINodeRuntimeState(
                    activeNote: active,
                    currentNoteName: midiNoteName(note)
                )
            case .midiCC:
                guard let valueInput = node.inputPorts.first(where: { $0.name == "Value" }) else {
                    midiCCNodeRuntimeStates[node.id] = MIDICCNodeRuntimeState(lastValue: nil, currentValue: "-")
                    continue
                }

                guard let value = resolvedScalarValue(forInputPortID: valueInput.id) else {
                    midiCCNodeRuntimeStates[node.id] = MIDICCNodeRuntimeState(lastValue: nil, currentValue: "-")
                    continue
                }

                let settings = settings(forMIDICCNodeID: node.id)
                let denominator = settings.sourceMax - settings.sourceMin
                let normalized: Double
                if abs(denominator) <= .ulpOfOne {
                    normalized = 0.0
                } else {
                    normalized = (value - settings.sourceMin) / denominator
                }
                let clamped = min(max(normalized, 0.0), 1.0)
                let ccValue = UInt8(min(max(Int(round(clamped * 127.0)), 0), 127))
                let runtime = midiCCNodeRuntimeStates[node.id] ?? MIDICCNodeRuntimeState()
                let destinationName = resolvedMIDIDestinationName(for: settings)

                if runtime.lastValue != ccValue {
                    _ = midiRouter.sendCC(
                        controller: UInt8(settings.ccNumber),
                        value: ccValue,
                        channel: UInt8(settings.channel),
                        destinationName: destinationName
                    )
                }

                midiCCNodeRuntimeStates[node.id] = MIDICCNodeRuntimeState(
                    lastValue: ccValue,
                    currentValue: "\(ccValue)"
                )
            default:
                continue
            }
        }
    }

    private func updateOSCNodes() {
        guard isGraphRunning else {
            oscInputRouter.syncListening(on: [])
            oscInputNodeRuntimeStates.removeAll()
            oscOutputNodeRuntimeStates.removeAll()
            return
        }

        oscInputRouter.syncListening(on: activeOSCInputPorts())

        let liveInputNodeIDs = Set(document.nodes.compactMap { node -> GraphNode.ID? in
            switch node.kind {
            case .oscInput, .oscReceive:
                return node.id
            default:
                return nil
            }
        })
        let liveOutputNodeIDs = Set(document.nodes.compactMap { node -> GraphNode.ID? in
            switch node.kind {
            case .oscOutput, .oscSend:
                return node.id
            default:
                return nil
            }
        })

        for nodeID in oscInputNodeRuntimeStates.keys where !liveInputNodeIDs.contains(nodeID) {
            oscInputNodeRuntimeStates.removeValue(forKey: nodeID)
        }
        for nodeID in oscOutputNodeRuntimeStates.keys where !liveOutputNodeIDs.contains(nodeID) {
            oscOutputNodeRuntimeStates.removeValue(forKey: nodeID)
        }

        for node in document.nodes {
            switch node.kind {
            case .oscInput, .oscReceive:
                let settings = settings(forOSCInputNodeID: node.id)
                oscInputRouter.ensureListening(on: settings.port)
            case .oscOutput:
                let settings = settings(forOSCOutputNodeID: node.id)
                let values = oscOutputValues(for: node)
                guard values.isEmpty == false else { continue }

                let signature = "\(settings.host):\(settings.port):\(settings.address):" + values.map(\.signatureComponent).joined(separator: "|")
                let runtime = oscOutputNodeRuntimeStates[node.id] ?? OSCOutputNodeRuntimeState()
                if runtime.lastSignature != signature {
                    _ = oscOutputRouter.send(
                        host: settings.host,
                        port: settings.port,
                        address: settings.address,
                        values: values
                    )
                    oscOutputNodeRuntimeStates[node.id] = OSCOutputNodeRuntimeState(lastSignature: signature)
                }
            case .oscSend:
                let settings = settings(forOSCSendNodeID: node.id)
                guard
                    let packetInput = node.inputPorts.first(where: { $0.name == "Packet" }),
                    let packet = resolvedOSCPacketValue(forInputPortID: packetInput.id)
                else {
                    continue
                }

                let signature = "\(settings.host):\(settings.port):\(packet.signatureComponent)"
                let runtime = oscOutputNodeRuntimeStates[node.id] ?? OSCOutputNodeRuntimeState()
                if runtime.lastSignature != signature {
                    _ = oscOutputRouter.send(host: settings.host, port: settings.port, packet: packet)
                    oscOutputNodeRuntimeStates[node.id] = OSCOutputNodeRuntimeState(lastSignature: signature)
                }
            default:
                continue
            }
        }
    }

    private func activeOSCInputPorts() -> Set<Int> {
        Set(document.nodes.compactMap { node -> Int? in
            switch node.kind {
            case .oscInput, .oscReceive:
                return settings(forOSCInputNodeID: node.id).port
            default:
                return nil
            }
        }.map { max(1, min(65535, $0)) })
    }

    private func restartOSCInputRouting() {
        oscInputRouter.restartListening(on: activeOSCInputPorts())
    }

    private func stopAllMIDINodes() {
        for nodeID in midiNodeRuntimeStates.keys {
            stopMIDINode(nodeID)
        }
    }

    private func oscOutputValues(for node: GraphNode, prefix: String = "") -> [OSCValue] {
        let slotNames: [(float: String, int: String, text: String)] = {
            switch node.kind {
            case .oscOutput where prefix.isEmpty:
                return [
                    ("Float", "Int", "Text"),
                    ("Float 2", "Int 2", "Text 2"),
                    ("Float 3", "Int 3", "Text 3"),
                    ("Float 4", "Int 4", "Text 4")
                ]
            default:
                return [
                    ("\(prefix)Float 1", "\(prefix)Int 1", "\(prefix)Text 1"),
                    ("\(prefix)Float 2", "\(prefix)Int 2", "\(prefix)Text 2"),
                    ("\(prefix)Float 3", "\(prefix)Int 3", "\(prefix)Text 3"),
                    ("\(prefix)Float 4", "\(prefix)Int 4", "\(prefix)Text 4")
                ]
            }
        }()

        func connectedPort(named name: String) -> GraphPort? {
            guard let port = node.inputPorts.first(where: { $0.name == name }) else { return nil }
            guard effectiveIncomingConnection(for: port.id) != nil else { return nil }
            return port
        }

        return slotNames.compactMap { names in
            if let floatPort = connectedPort(named: names.float),
               let value = resolvedScalarValue(forInputPortID: floatPort.id) {
                return .float(Float(value))
            }

            if let intPort = connectedPort(named: names.int),
               let value = resolvedScalarValue(forInputPortID: intPort.id) {
                let clamped = max(Double(Int32.min), min(Double(Int32.max), value.rounded()))
                return .int(Int32(clamped))
            }

            if let textPort = connectedPort(named: names.text),
               let value = resolvedStringValue(forInputPortID: textPort.id),
               value.isEmpty == false {
                return .string(value)
            }

            return nil
        }
    }

    private func stopMIDINode(_ nodeID: GraphNode.ID) {
        guard let runtime = midiNodeRuntimeStates[nodeID] else { return }
        if let active = runtime.activeNote {
            _ = midiRouter.sendNoteOff(note: active.note, channel: active.channel, destinationName: active.destinationName)
        }
        midiNodeRuntimeStates[nodeID] = MIDINodeRuntimeState(activeNote: nil, currentNoteName: "-")
    }

    private func resolvedMIDIDestinationName(for settings: MIDIOutNodeSettings) -> String {
        if !settings.destinationName.isEmpty {
            return settings.destinationName
        }
        return midiRouter.preferredDestinationName() ?? ""
    }

    private func resolvedMIDIDestinationName(for settings: MIDICCNodeSettings) -> String {
        if !settings.destinationName.isEmpty {
            return settings.destinationName
        }
        return midiRouter.preferredDestinationName() ?? ""
    }

    private func normalizedOSCAddress(_ address: String) -> String {
        let trimmed = address.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.isEmpty == false else { return "" }
        return trimmed.hasPrefix("/") ? trimmed : "/\(trimmed)"
    }

    private func midiNote(for point: CGPoint, settings: MIDIOutNodeSettings) -> UInt8? {
        guard let rootIndex = Self.midiRootNotes.firstIndex(of: settings.rootNote) else { return nil }
        let octaveRange = settings.lowOctave...settings.highOctave
        let rows = Array(octaveRange)
        guard !rows.isEmpty else { return nil }

        let clampedX = max(0.0, min(1.0, point.x))
        let clampedY = max(0.0, min(1.0, point.y))
        let rowIndex = min(Int((1.0 - clampedY) * Double(rows.count)), rows.count - 1)
        let intervals = settings.scale.intervals
        guard !intervals.isEmpty else { return nil }
        let columnIndex = min(Int(clampedX * Double(intervals.count)), intervals.count - 1)
        let octave = rows[rowIndex]
        let noteValue = octave * 12 + rootIndex + intervals[columnIndex]
        return UInt8(min(max(0, noteValue), 127))
    }

    private func midiNoteName(_ note: UInt8) -> String {
        let noteInt = Int(note)
        let name = Self.midiRootNotes[noteInt % 12]
        let octave = noteInt / 12
        return "\(name)\(octave)"
    }

    private func commitPendingEditorState() {
        if let fragmentNodeID = selectedFragmentNode?.id {
            fragmentMetalSources[fragmentNodeID] = editableMetalSource
            document = syncFragmentNodePorts(in: document)
        }

        if editableSource != document.source {
            var updatedDocument = document
            updatedDocument = ShaderDocument(
                name: updatedDocument.name,
                description: updatedDocument.description,
                source: editableSource,
                shaderPrelude: updatedDocument.shaderPrelude,
                shaderBody: updatedDocument.shaderBody,
                uniforms: updatedDocument.uniforms,
                nodes: updatedDocument.nodes,
                connections: updatedDocument.connections
            )
            document = updatedDocument
        }
    }

