    private func currentGraphSnapshotText() throws -> String {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        let data = try encoder.encode(currentGraphSnapshot())
        guard let text = String(data: data, encoding: .utf8) else {
            throw CocoaError(.fileWriteUnknown)
        }
        return text
    }

    private func currentGraphHistoryEntry() throws -> GraphHistoryEntry {
        GraphHistoryEntry(graphText: try currentGraphSnapshotText())
    }

    private func resetHistoryTracking(currentGraphText: String? = nil) {
        undoHistory.removeAll()
        redoHistory.removeAll()
        lastHistoryGraphText = currentGraphText ?? (try? currentGraphSnapshotText())
    }

    private func captureHistoryCheckpointIfNeeded() {
        guard !isApplyingHistory else { return }
        guard let currentText = try? currentGraphSnapshotText() else { return }

        guard let lastHistoryGraphText else {
            self.lastHistoryGraphText = currentText
            return
        }

        guard currentText != lastHistoryGraphText else { return }

        undoHistory.append(GraphHistoryEntry(graphText: lastHistoryGraphText))
        if undoHistory.count > Self.maxHistoryEntries {
            undoHistory.removeFirst(undoHistory.count - Self.maxHistoryEntries)
        }
        redoHistory.removeAll()
        self.lastHistoryGraphText = currentText
    }

    private func captureHistoryCheckpointNow() {
        guard !isApplyingHistory else { return }
        guard let currentText = try? currentGraphSnapshotText() else { return }

        if lastHistoryGraphText == nil {
            lastHistoryGraphText = currentText
            return
        }

        guard currentText != lastHistoryGraphText else { return }
        undoHistory.append(GraphHistoryEntry(graphText: lastHistoryGraphText ?? currentText))
        if undoHistory.count > Self.maxHistoryEntries {
            undoHistory.removeFirst(undoHistory.count - Self.maxHistoryEntries)
        }
        redoHistory.removeAll()
        lastHistoryGraphText = currentText
    }

    private static func loadCanvasColor(from defaults: UserDefaults) -> Color? {
        guard defaults.object(forKey: CanvasPreferenceKey.red) != nil,
              defaults.object(forKey: CanvasPreferenceKey.green) != nil,
              defaults.object(forKey: CanvasPreferenceKey.blue) != nil else {
            return nil
        }

        return Color(
            red: defaults.double(forKey: CanvasPreferenceKey.red),
            green: defaults.double(forKey: CanvasPreferenceKey.green),
            blue: defaults.double(forKey: CanvasPreferenceKey.blue)
        )
    }

    private static func saveCanvasColor(_ color: Color) {
        guard let nsColor = NSColor(color).usingColorSpace(.deviceRGB) else { return }
        let defaults = UserDefaults.standard
        defaults.set(Double(nsColor.redComponent), forKey: CanvasPreferenceKey.red)
        defaults.set(Double(nsColor.greenComponent), forKey: CanvasPreferenceKey.green)
        defaults.set(Double(nsColor.blueComponent), forKey: CanvasPreferenceKey.blue)
    }

    private func ignoreNextGraphChangeNotifications(immediateCount: Int, persistenceCount: Int? = nil) {
        ignoredGraphChangeNotifications += max(0, immediateCount)
        ignoredGraphPersistenceNotifications += max(0, persistenceCount ?? immediateCount)
    }

    private func syncFragmentNodePorts(in document: ShaderDocument) -> ShaderDocument {
        let fragmentIndices = document.nodes.indices.filter {
            if case .metalFragment = document.nodes[$0].kind { return true }
            return false
        }

        guard !fragmentIndices.isEmpty else {
            return document
        }

        var updatedDocument = document
        var globalImageUniforms: [UniformDescriptor] = []
        var fragmentScopedUniforms: [UniformDescriptor] = []
        var claimedFragmentUniformIDs = Set<UniformDescriptor.ID>()
        var validInputPortIDs = Set<String>()

        for fragmentIndex in fragmentIndices {
            let fragmentNode = updatedDocument.nodes[fragmentIndex]
            let fragmentSource = metalSource(for: fragmentNode.id)
            let declaredUniforms = fragmentDeclaredUniforms(
                for: fragmentNode,
                metalSource: fragmentSource,
                availableUniforms: updatedDocument.uniforms
            )
            let imageUniforms = declaredUniforms.filter { $0.kind == .image }
            let scopedNonImageUniforms = declaredUniforms.filter { $0.kind != .image }.map { uniform in
                guard claimedFragmentUniformIDs.contains(uniform.id) else {
                    claimedFragmentUniformIDs.insert(uniform.id)
                    return uniform
                }

                let duplicated = UniformDescriptor(
                    name: uniform.name,
                    kind: uniform.kind,
                    defaultValue: uniform.defaultValue,
                    minValue: uniform.minValue,
                    maxValue: uniform.maxValue,
                    label: uniform.label
                )
                claimedFragmentUniformIDs.insert(duplicated.id)
                return duplicated
            }
            let scopedDeclaredUniforms = imageUniforms + scopedNonImageUniforms
            globalImageUniforms = mergedUniforms(existing: globalImageUniforms, additional: imageUniforms)
            fragmentScopedUniforms.append(contentsOf: scopedNonImageUniforms)
            var rebuiltInputPorts: [GraphPort] = []
            if usesTime(in: fragmentSource) {
                rebuiltInputPorts.append(Self.makeFragmentTimePort(nodeID: fragmentNode.id))
            }
            rebuiltInputPorts.append(contentsOf: scopedDeclaredUniforms.map {
                Self.makeFragmentInputPort(for: $0, nodeID: fragmentNode.id)
            })
            validInputPortIDs.formUnion(rebuiltInputPorts.map(\.id))
            updatedDocument.nodes[fragmentIndex] = GraphNode(
                id: fragmentNode.id,
                title: fragmentNode.title,
                kind: fragmentNode.kind,
                position: fragmentNode.position,
                inputPorts: rebuiltInputPorts,
                outputPorts: [Self.makeFragmentOutputPort(nodeID: fragmentNode.id)]
            )
        }

        updatedDocument.uniforms = globalImageUniforms + fragmentScopedUniforms

        updatedDocument.connections.removeAll { connection in
            guard let inputPort = updatedDocument.nodes.flatMap(\.inputPorts).first(where: { $0.id == connection.toPortID }) else {
                return false
            }
            switch inputPort.kind {
            case .time, .uniform:
                return inputPort.nodeID != renderNode?.id && !validInputPortIDs.contains(connection.toPortID)
            case .audio, .scalarSignal, .pointSignal, .point3Signal, .point4Signal, .stringSignal, .colorSignal, .scalarArraySignal, .stringArraySignal, .colorArraySignal, .imageArraySignal, .sliderStyle, .buttonStyle, .fragmentShader, .lightSignal, .materialSignal, .scene3DSignal, .oscPacketSignal:
                return false
            }
        }
        return pruneUnusedUniforms(in: updatedDocument)
    }

    private func fragmentDeclaredUniforms(
        for fragmentNode: GraphNode,
        metalSource: String,
        availableUniforms: [UniformDescriptor]
    ) -> [UniformDescriptor] {
        let metadataUniforms = ISFParser.parse(shaderSource: metalSource).uniforms
        let inferred = inferredUniforms(from: [metalSource], existing: metadataUniforms)
        let sourceUniforms = mergedUniforms(existing: metadataUniforms, additional: inferred)
        var existingFragmentUniforms: [String: UniformDescriptor] = [:]
        for inputPort in fragmentNode.inputPorts {
            guard case .uniform(let uniformID) = inputPort.kind,
                  let uniform = availableUniforms.first(where: { $0.id == uniformID }) else {
                continue
            }
            let key = uniform.name.lowercased()
            if existingFragmentUniforms[key] == nil {
                existingFragmentUniforms[key] = uniform
            }
        }

        return sourceUniforms.map { uniform in
            guard uniform.kind != .image,
                  let existing = existingFragmentUniforms[uniform.name.lowercased()],
                  existing.kind == uniform.kind else {
                return uniform
            }

            return UniformDescriptor(
                id: existing.id,
                name: uniform.name,
                kind: uniform.kind,
                defaultValue: existing.defaultValue,
                minValue: uniform.minValue ?? existing.minValue,
                maxValue: uniform.maxValue ?? existing.maxValue,
                label: uniform.label ?? existing.label
            )
        }
    }

    private func inferredUniforms(from metalSources: [String], existing: [UniformDescriptor]) -> [UniformDescriptor] {
        var inferred: [UniformDescriptor] = []
        var existingByName: [String: UniformDescriptor] = [:]
        for uniform in existing {
            let key = uniform.name.lowercased()
            if existingByName[key] == nil {
                existingByName[key] = uniform
            }
        }
        var seenNames = Set(existing.map { $0.name.lowercased() })

        for metalSource in metalSources {
            for field in metalUniformFields(in: metalSource) {
                let nameKey = field.name.lowercased()
                guard !seenNames.contains(nameKey) else { continue }
                seenNames.insert(nameKey)

                if let existingUniform = existingByName[nameKey] {
                    inferred.append(existingUniform)
                    continue
                }

                if let uniform = inferredUniformDescriptor(for: field.name, metalType: field.type) {
                    inferred.append(uniform)
                }
            }
        }

        return inferred
    }

    private func metalUniformFields(in metalSource: String) -> [(name: String, type: String)] {
        guard
            let regex = try? NSRegularExpression(pattern: #"struct\s+Uniforms\s*\{([\s\S]*?)\};"#),
            let match = regex.firstMatch(in: metalSource, range: NSRange(metalSource.startIndex..., in: metalSource)),
            let bodyRange = Range(match.range(at: 1), in: metalSource)
        else {
            return []
        }

        let body = String(metalSource[bodyRange])
        guard let fieldRegex = try? NSRegularExpression(pattern: #"\b([A-Za-z_][A-Za-z0-9_<>]*)\s+([A-Za-z_][A-Za-z0-9_]*)\s*;"#) else {
            return []
        }

        let ignoredNames = Set(["resolution", "time", "date"])
        let nsRange = NSRange(body.startIndex..., in: body)

        return fieldRegex.matches(in: body, range: nsRange).compactMap { match in
            guard
                let typeRange = Range(match.range(at: 1), in: body),
                let nameRange = Range(match.range(at: 2), in: body)
            else {
                return nil
            }

            let type = String(body[typeRange])
            let name = String(body[nameRange])
            guard !ignoredNames.contains(name.lowercased()) else { return nil }
            return (name: name, type: type)
        }
    }

    private func inferredUniformDescriptor(for name: String, metalType: String) -> UniformDescriptor? {
        let normalizedName = name.lowercased()
        switch metalType {
        case "float":
            return UniformDescriptor(
                name: name,
                kind: .float,
                defaultValue: .float(0.5),
                minValue: 0.0,
                maxValue: 1.0,
                label: nil
            )
        case "float2":
            return UniformDescriptor(
                name: name,
                kind: .point2D,
                defaultValue: .point(CGPoint(x: 0.5, y: 0.5)),
                minValue: nil,
                maxValue: nil,
                label: nil
            )
        case "float3":
            return UniformDescriptor(
                name: name,
                kind: .float3,
                defaultValue: .point3(Point3Value(x: 0.0, y: 0.0, z: 0.0)),
                minValue: nil,
                maxValue: nil,
                label: nil
            )
        case "float4":
            if normalizedName.contains("color") || normalizedName.contains("tint") {
                return UniformDescriptor(
                    name: name,
                    kind: .color,
                    defaultValue: .color(SIMD4<Float>(1, 1, 1, 1)),
                    minValue: nil,
                    maxValue: nil,
                    label: nil
                )
            }
            return UniformDescriptor(
                name: name,
                kind: .float4,
                defaultValue: .point4(Point4Value(x: 0.0, y: 0.0, z: 0.0, w: 0.0)),
                minValue: nil,
                maxValue: nil,
                label: nil
            )
        case "bool":
            return UniformDescriptor(
                name: name,
                kind: .bool,
                defaultValue: .bool(false),
                minValue: nil,
                maxValue: nil,
                label: nil
            )
        default:
            return nil
        }
    }

    private func referencedUniforms(in metalSource: String, from uniforms: [UniformDescriptor]) -> [UniformDescriptor] {
        uniforms.filter { uniform in
            let pattern = "\\b" + NSRegularExpression.escapedPattern(for: uniform.name) + "\\b"
            return metalSource.range(of: pattern, options: .regularExpression) != nil
        }
    }

    private func effectiveUniforms(forFragmentNodeID fragmentNodeID: GraphNode.ID) -> [UniformDescriptor] {
        var resolvedByID = Dictionary(uniqueKeysWithValues: document.uniforms.map { uniform -> (UniformDescriptor.ID, UniformDescriptor) in
            var resolved = uniform
            if let baselineValue = baselineUniformValues[uniform.id] {
                resolved.defaultValue = baselineValue
            }
            return (uniform.id, resolved)
        })

        guard let fragmentNode = document.nodes.first(where: { $0.id == fragmentNodeID }) else {
            return document.uniforms
        }

        let fragmentUniformIDs = fragmentNode.inputPorts.compactMap { inputPort -> UniformDescriptor.ID? in
            guard case .uniform(let uniformID) = inputPort.kind else {
                return nil
            }
            return uniformID
        }
        for inputPort in fragmentNode.inputPorts {
            guard
                case .uniform(let targetUniformID) = inputPort.kind,
                let targetUniform = resolvedByID[targetUniformID]
            else {
                continue
            }

            var remappedUniform = targetUniform
        switch targetUniform.kind {
        case .float:
            if let resolvedValue = resolvedScalarValue(forInputPortID: inputPort.id) {
                remappedUniform.defaultValue = .float(resolvedValue)
                resolvedByID[targetUniformID] = remappedUniform
            }
        case .point2D:
                if let resolvedPoint = resolvedPointValue(forInputPortID: inputPort.id) {
                    remappedUniform.defaultValue = .point(resolvedPoint)
                    resolvedByID[targetUniformID] = remappedUniform
                    continue
                }
                guard
                    let connection = effectiveIncomingConnection(for: inputPort.id),
                    let sourcePort = resolvedSourcePort(for: connection.fromPortID),
                    case .uniform(let sourceUniformID) = sourcePort.kind,
                    let sourceUniform = currentUniform(matching: sourceUniformID),
                    sourceUniform.kind == targetUniform.kind
                else {
                    continue
                }
                remappedUniform.defaultValue = sourceUniform.defaultValue
                resolvedByID[targetUniformID] = remappedUniform
            case .float3:
                if let resolvedPoint = resolvedPoint3Value(forInputPortID: inputPort.id) {
                    remappedUniform.defaultValue = .point3(resolvedPoint)
                    resolvedByID[targetUniformID] = remappedUniform
                    continue
                }
                guard
                    let connection = effectiveIncomingConnection(for: inputPort.id),
                    let sourcePort = resolvedSourcePort(for: connection.fromPortID),
                    case .uniform(let sourceUniformID) = sourcePort.kind,
                    let sourceUniform = currentUniform(matching: sourceUniformID),
                    sourceUniform.kind == targetUniform.kind
                else {
                    continue
                }
                remappedUniform.defaultValue = sourceUniform.defaultValue
                resolvedByID[targetUniformID] = remappedUniform
            case .float4:
                if let resolvedPoint = resolvedPoint4Value(forInputPortID: inputPort.id) {
                    remappedUniform.defaultValue = .point4(resolvedPoint)
                    resolvedByID[targetUniformID] = remappedUniform
                    continue
                }
                guard
                    let connection = effectiveIncomingConnection(for: inputPort.id),
                    let sourcePort = resolvedSourcePort(for: connection.fromPortID),
                    case .uniform(let sourceUniformID) = sourcePort.kind,
                    let sourceUniform = currentUniform(matching: sourceUniformID),
                    sourceUniform.kind == targetUniform.kind
                else {
                    continue
                }
                remappedUniform.defaultValue = sourceUniform.defaultValue
                resolvedByID[targetUniformID] = remappedUniform
            default:
                guard
                    let connection = effectiveIncomingConnection(for: inputPort.id),
                    let sourcePort = resolvedSourcePort(for: connection.fromPortID),
                    case .uniform(let sourceUniformID) = sourcePort.kind,
                    let sourceUniform = currentUniform(matching: sourceUniformID),
                    sourceUniform.kind == targetUniform.kind
                else {
                    continue
                }
                remappedUniform.defaultValue = sourceUniform.defaultValue
                resolvedByID[targetUniformID] = remappedUniform
            }
        }

        let orderedRegularUniforms = fragmentUniformIDs.compactMap { resolvedByID[$0] }
        let orderedImageUniforms = fragmentNode.inputPorts.compactMap { inputPort -> UniformDescriptor? in
            guard case .fragmentShader = inputPort.kind else { return nil }
            return imageUniformDescriptor(for: inputPort)
        }
        return orderedRegularUniforms + orderedImageUniforms
    }

    private func imageUniformSources(
        forFragmentNodeID fragmentNodeID: GraphNode.ID,
        visitedNodeIDs: Set<GraphNode.ID> = [],
        activeFeedbackNodeID: GraphNode.ID? = nil
    ) -> [PreviewPassSource?] {
        guard let fragmentNode = document.nodes.first(where: { $0.id == fragmentNodeID }) else {
            return []
        }

        let imageUniformNames = effectiveUniforms(forFragmentNodeID: fragmentNodeID)
            .filter { $0.kind == .image }
            .map(\.name)

        return imageUniformNames.map { uniformName -> PreviewPassSource? in
            guard
                let inputPort = fragmentNode.inputPorts.first(where: { port in
                    guard case .fragmentShader = port.kind else { return false }
                    return port.name == uniformName
                })
            else {
                return nil
            }
            if inputPort.name.lowercased() == "feedback",
               let connection = effectiveIncomingConnection(for: inputPort.id),
               let sourcePort = resolvedSourcePort(for: connection.fromPortID),
               let sourceNode = document.nodes.first(where: { $0.id == sourcePort.nodeID }),
               case .feedback = sourceNode.kind {
                return .feedbackHistory(nodeID: sourceNode.id)
            }
            return previewPassSourceForVisualInputPortID(
                inputPort.id,
                visitedNodeIDs: visitedNodeIDs,
                activeFeedbackNodeID: activeFeedbackNodeID
            )
        }
    }

    func portsAreCompatible(_ outputPort: GraphPort, _ inputPort: GraphPort) -> Bool {
        if outputPort.kind == inputPort.kind {
            return true
        }

        if case .audio = outputPort.kind {
            if case .uniform(let inputUniformID) = inputPort.kind,
               let inputUniform = currentUniform(matching: inputUniformID) {
                return inputUniform.kind == .float
            }
            if case .scalarSignal = inputPort.kind {
                return true
            }
            if case .stringSignal = inputPort.kind {
                return true
            }
        }

        if case .scalarSignal = outputPort.kind {
            if case .uniform(let inputUniformID) = inputPort.kind,
               let inputUniform = currentUniform(matching: inputUniformID) {
                return inputUniform.kind == .float
            }
            if case .scalarSignal = inputPort.kind {
                return true
            }
            if case .stringSignal = inputPort.kind {
                return true
            }
        }

        if case .scalarSignal = inputPort.kind,
           case .uniform(let outputUniformID) = outputPort.kind,
           let outputUniform = currentUniform(matching: outputUniformID) {
            return outputUniform.kind == .float
        }

        if case .stringSignal = inputPort.kind,
           case .uniform(let outputUniformID) = outputPort.kind,
           let outputUniform = currentUniform(matching: outputUniformID) {
            return outputUniform.kind == .float
        }

        if case .pointSignal = outputPort.kind,
           case .uniform(let inputUniformID) = inputPort.kind,
           let inputUniform = currentUniform(matching: inputUniformID) {
            return inputUniform.kind == .point2D
        }

        if case .point3Signal = outputPort.kind,
           case .uniform(let inputUniformID) = inputPort.kind,
           let inputUniform = currentUniform(matching: inputUniformID) {
            return inputUniform.kind == .float3
        }

        if case .point4Signal = outputPort.kind,
           case .uniform(let inputUniformID) = inputPort.kind,
           let inputUniform = currentUniform(matching: inputUniformID) {
            return inputUniform.kind == .float4
        }

        if case .pointSignal = outputPort.kind,
           case .pointSignal = inputPort.kind {
            return true
        }

        if case .point3Signal = outputPort.kind,
           case .point3Signal = inputPort.kind {
            return true
        }

        if case .point4Signal = outputPort.kind,
           case .point4Signal = inputPort.kind {
            return true
        }

        if case .pointSignal = inputPort.kind,
           case .uniform(let outputUniformID) = outputPort.kind,
           let outputUniform = currentUniform(matching: outputUniformID) {
            return outputUniform.kind == .point2D
        }

        if case .point3Signal = inputPort.kind,
           case .uniform(let outputUniformID) = outputPort.kind,
           let outputUniform = currentUniform(matching: outputUniformID) {
            return outputUniform.kind == .float3
        }

        if case .point4Signal = inputPort.kind,
           case .uniform(let outputUniformID) = outputPort.kind,
           let outputUniform = currentUniform(matching: outputUniformID) {
            return outputUniform.kind == .float4
        }

        if case .stringSignal = outputPort.kind,
           case .stringSignal = inputPort.kind {
            return true
        }

        if case .colorSignal = outputPort.kind,
           case .colorSignal = inputPort.kind {
            return true
        }

        if case .scalarArraySignal = outputPort.kind,
           case .scalarArraySignal = inputPort.kind {
            return true
        }

        if case .stringArraySignal = outputPort.kind,
           case .stringArraySignal = inputPort.kind {
            return true
        }

        if case .colorArraySignal = outputPort.kind,
           case .colorArraySignal = inputPort.kind {
            return true
        }

        if case .lightSignal = outputPort.kind,
           case .lightSignal = inputPort.kind {
            return true
        }

        if case .materialSignal = outputPort.kind,
           case .materialSignal = inputPort.kind {
            return true
        }

        if case .scene3DSignal = outputPort.kind,
           case .scene3DSignal = inputPort.kind {
            return true
        }

        if case .oscPacketSignal = outputPort.kind,
           case .oscPacketSignal = inputPort.kind {
            return true
        }

        if case .imageArraySignal = outputPort.kind,
           case .imageArraySignal = inputPort.kind {
            return true
        }

        if inputPort.name == "Array",
           case .scalarArraySignal = inputPort.kind {
            if case .stringArraySignal = outputPort.kind { return true }
            if case .colorArraySignal = outputPort.kind { return true }
            if case .imageArraySignal = outputPort.kind { return true }
        }

        if case .scalarSignal = outputPort.kind,
           case .stringSignal = inputPort.kind {
            return true
        }

        guard
            case .uniform(let outputUniformID) = outputPort.kind,
            case .uniform(let inputUniformID) = inputPort.kind,
            let outputUniform = currentUniform(matching: outputUniformID),
            let inputUniform = currentUniform(matching: inputUniformID)
        else {
            return false
        }

        return outputUniform.kind == inputUniform.kind
    }

    private func usesTime(in metalSource: String) -> Bool {
        metalSource.range(of: #"\bTIME\b"#, options: .regularExpression) != nil
        || metalSource.range(of: #"uniforms\.time\b"#, options: .regularExpression) != nil
    }

    private func resolvedPointValue(forInputPortID portID: GraphPort.ID) -> CGPoint? {
        guard
            let connection = effectiveIncomingConnection(for: portID),
            let sourcePort = resolvedSourcePort(for: connection.fromPortID)
        else {
            return nil
        }

        switch sourcePort.kind {
        case .pointSignal:
            guard let sourceNode = document.nodes.first(where: { $0.id == sourcePort.nodeID }) else {
                return currentMousePosition
            }
            switch sourceNode.kind {
            case .mouse:
                return currentMousePosition
            case .pointCombine:
                let settings = settings(forPointCombineNodeID: sourceNode.id)
                let x = sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.x
                let y = sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.y
                return CGPoint(x: x, y: y)
            case .pointInterpolate:
                let settings = settings(forPointInterpolatorNodeID: sourceNode.id)
                let start = sourceNode.inputPorts.first(where: { $0.name == "Start" }).flatMap { resolvedPointValue(forInputPortID: $0.id) }
                    ?? CGPoint(x: settings.startX, y: settings.startY)
                let end = sourceNode.inputPorts.first(where: { $0.name == "End" }).flatMap { resolvedPointValue(forInputPortID: $0.id) }
                    ?? CGPoint(x: settings.endX, y: settings.endY)
                let progress = interpolatorProgress(duration: settings.duration, phase: settings.phase, autoreverses: settings.autoreverses, easing: settings.easing)
                return CGPoint(
                    x: start.x + ((end.x - start.x) * progress),
                    y: start.y + ((end.y - start.y) * progress)
                )
            case .pointScale:
                let settings = settings(forPointScaleNodeID: sourceNode.id)
                let point = sourceNode.inputPorts.first(where: { $0.name == "Point" }).flatMap { resolvedPointValue(forInputPortID: $0.id) }
                    ?? CGPoint(x: settings.x, y: settings.y)
                let scale = sourceNode.inputPorts.first(where: { $0.name == "Scale" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scale
                return CGPoint(x: point.x * scale, y: point.y * scale)
            case .handTracker:
                let settings = settings(forHandTrackerNodeID: sourceNode.id)
                let basePoint: CGPoint?
                if case .pointSignal(let signal) = sourcePort.kind, signal == "leftHand" {
                    basePoint = videoMonitor.handSnapshot.leftIndex
                } else if case .pointSignal(let signal) = sourcePort.kind, signal == "rightHand" {
                    basePoint = videoMonitor.handSnapshot.rightIndex
                } else if case .pointSignal(let signal) = sourcePort.kind, signal == "leftThumb" {
                    basePoint = videoMonitor.handSnapshot.leftThumb
                } else if case .pointSignal(let signal) = sourcePort.kind, signal == "rightThumb" {
                    basePoint = videoMonitor.handSnapshot.rightThumb
                } else {
                    basePoint = nil
                }

                guard let basePoint else { return nil }
                return CGPoint(
                    x: min(max(basePoint.x + settings.offsetX, 0.0), 1.0),
                    y: min(max(basePoint.y + settings.offsetY, 0.0), 1.0)
                )
            case .gridLayout:
                let settings = settings(forGridLayoutNodeID: sourceNode.id)
                let index = sourceNode.inputPorts.first(where: { $0.name == "Index" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.index
                let columns = sourceNode.inputPorts.first(where: { $0.name == "Columns" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.columns
                let originX = sourceNode.inputPorts.first(where: { $0.name == "Origin X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.originX
                let originY = sourceNode.inputPorts.first(where: { $0.name == "Origin Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.originY
                let spacingX = sourceNode.inputPorts.first(where: { $0.name == "Spacing X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.spacingX
                let spacingY = sourceNode.inputPorts.first(where: { $0.name == "Spacing Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.spacingY
                let resolvedColumns = max(1, Int(columns.rounded()))
                let resolvedIndex = max(0, Int(index.rounded()))
                let column = resolvedIndex % resolvedColumns
                let row = resolvedIndex / resolvedColumns
                return CGPoint(
                    x: originX + (Double(column) * spacingX),
                    y: originY + (Double(row) * spacingY)
                )
            default:
                return nil
            }
        case .uniform(let uniformID):
            guard
                let uniform = currentUniform(matching: uniformID),
                case .point(let point) = uniform.defaultValue
            else {
                return nil
            }
            return point
        default:
            return nil
        }
    }

    private func resolvedPoint3Value(forInputPortID portID: GraphPort.ID) -> Point3Value? {
        guard
            let connection = effectiveIncomingConnection(for: portID),
            let sourcePort = resolvedSourcePort(for: connection.fromPortID)
        else {
            return nil
        }

        if case .uniform(let uniformID) = sourcePort.kind {
            guard
                let uniform = currentUniform(matching: uniformID),
                case .point3(let point) = uniform.defaultValue
            else {
                return nil
            }
            return point
        }

        guard case .point3Signal = sourcePort.kind,
              let sourceNode = document.nodes.first(where: { $0.id == sourcePort.nodeID }) else {
            return nil
        }

        switch sourceNode.kind {
        case .point3Combine:
            let settings = settings(forPoint3CombineNodeID: sourceNode.id)
            let x = sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.x
            let y = sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.y
            let z = sourceNode.inputPorts.first(where: { $0.name == "Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.z
            return Point3Value(x: x, y: y, z: z)
        case .point3Interpolate:
            let settings = settings(forPoint3InterpolatorNodeID: sourceNode.id)
            let start = sourceNode.inputPorts.first(where: { $0.name == "Start" }).flatMap { resolvedPoint3Value(forInputPortID: $0.id) } ?? settings.start
            let end = sourceNode.inputPorts.first(where: { $0.name == "End" }).flatMap { resolvedPoint3Value(forInputPortID: $0.id) } ?? settings.end
            let progress = interpolatorProgress(duration: settings.duration, phase: settings.phase, autoreverses: settings.autoreverses, easing: settings.easing)
            return Point3Value(
                x: start.x + ((end.x - start.x) * progress),
                y: start.y + ((end.y - start.y) * progress),
                z: start.z + ((end.z - start.z) * progress)
            )
        case .point3Scale:
            let settings = settings(forPoint3ScaleNodeID: sourceNode.id)
            let point = sourceNode.inputPorts.first(where: { $0.name == "Point3" }).flatMap { resolvedPoint3Value(forInputPortID: $0.id) } ?? settings.value
            let scale = sourceNode.inputPorts.first(where: { $0.name == "Scale" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scale
            return Point3Value(x: point.x * scale, y: point.y * scale, z: point.z * scale)
        default:
            return nil
        }
    }

    private func resolvedPoint4Value(forInputPortID portID: GraphPort.ID) -> Point4Value? {
        guard
            let connection = effectiveIncomingConnection(for: portID),
            let sourcePort = resolvedSourcePort(for: connection.fromPortID)
        else {
            return nil
        }

        if case .uniform(let uniformID) = sourcePort.kind {
            guard
                let uniform = currentUniform(matching: uniformID),
                case .point4(let point) = uniform.defaultValue
            else {
                return nil
            }
            return point
        }

        guard case .point4Signal = sourcePort.kind,
              let sourceNode = document.nodes.first(where: { $0.id == sourcePort.nodeID }) else {
            return nil
        }

        switch sourceNode.kind {
        case .point4Combine:
            let settings = settings(forPoint4CombineNodeID: sourceNode.id)
            let x = sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.x
            let y = sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.y
            let z = sourceNode.inputPorts.first(where: { $0.name == "Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.z
            let w = sourceNode.inputPorts.first(where: { $0.name == "W" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.w
            return Point4Value(x: x, y: y, z: z, w: w)
        case .point4Interpolate:
            let settings = settings(forPoint4InterpolatorNodeID: sourceNode.id)
            let start = sourceNode.inputPorts.first(where: { $0.name == "Start" }).flatMap { resolvedPoint4Value(forInputPortID: $0.id) } ?? settings.start
            let end = sourceNode.inputPorts.first(where: { $0.name == "End" }).flatMap { resolvedPoint4Value(forInputPortID: $0.id) } ?? settings.end
            let progress = interpolatorProgress(duration: settings.duration, phase: settings.phase, autoreverses: settings.autoreverses, easing: settings.easing)
            return Point4Value(
                x: start.x + ((end.x - start.x) * progress),
                y: start.y + ((end.y - start.y) * progress),
                z: start.z + ((end.z - start.z) * progress),
                w: start.w + ((end.w - start.w) * progress)
            )
        case .point4Scale:
            let settings = settings(forPoint4ScaleNodeID: sourceNode.id)
            let point = sourceNode.inputPorts.first(where: { $0.name == "Point4" }).flatMap { resolvedPoint4Value(forInputPortID: $0.id) } ?? settings.value
            let scale = sourceNode.inputPorts.first(where: { $0.name == "Scale" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scale
            return Point4Value(x: point.x * scale, y: point.y * scale, z: point.z * scale, w: point.w * scale)
        default:
            return nil
        }
    }

    private func interpolatorProgress(duration: Double, phase: Double, autoreverses: Bool, easing: InterpolatorEasing) -> Double {
        let clampedDuration = max(duration, 0.0001)
        let elapsed = max(0.0, graphClockTime + phase)
        let normalizedTime = elapsed / clampedDuration
        let cyclePosition: Double
        if autoreverses {
            let wrapped = normalizedTime.truncatingRemainder(dividingBy: 2.0)
            cyclePosition = wrapped <= 1.0 ? wrapped : (2.0 - wrapped)
        } else {
            cyclePosition = normalizedTime.truncatingRemainder(dividingBy: 1.0)
        }

        switch easing {
        case .linear:
            return cyclePosition
        case .easeIn:
            return cyclePosition * cyclePosition
        case .easeOut:
            let inverse = 1.0 - cyclePosition
            return 1.0 - (inverse * inverse)
        case .easeInOut:
            if cyclePosition < 0.5 {
                return 2.0 * cyclePosition * cyclePosition
            }
            let inverse = -2.0 * cyclePosition + 2.0
            return 1.0 - ((inverse * inverse) / 2.0)
        }
    }

    private func sourceByAddingUniform(_ uniform: UniformDescriptor, to source: String) -> String {
        let pattern = #"/\*\s*(\{[\s\S]*?\})\s*\*/"#
        guard let regex = try? NSRegularExpression(pattern: pattern) else {
            return source
        }

        let range = NSRange(source.startIndex..., in: source)
        var metadata: [String: Any] = [:]
        var fullCommentRange: Range<String.Index>?

        if let match = regex.firstMatch(in: source, range: range),
           let jsonRange = Range(match.range(at: 1), in: source),
           let commentRange = Range(match.range(at: 0), in: source),
           let jsonData = String(source[jsonRange]).data(using: .utf8),
           let parsedMetadata = (try? JSONSerialization.jsonObject(with: jsonData)) as? [String: Any] {
            metadata = parsedMetadata
            fullCommentRange = commentRange
        }

        var inputs = metadata["INPUTS"] as? [[String: Any]] ?? []
        inputs.append(dictionary(for: uniform))
        metadata["INPUTS"] = inputs
        if metadata["DESCRIPTION"] == nil {
            metadata["DESCRIPTION"] = document.name
        }

        guard
            let jsonData = try? JSONSerialization.data(withJSONObject: metadata, options: [.prettyPrinted]),
            let jsonString = String(data: jsonData, encoding: .utf8)
        else {
            return source
        }

        let metadataComment = "/*\n\(jsonString)\n*/"
        if let fullCommentRange {
            var updatedSource = source
            updatedSource.replaceSubrange(fullCommentRange, with: metadataComment)
            return updatedSource
        }

        return metadataComment + "\n\n" + source
    }

    private func setEditableSourceProgrammatically(_ source: String) {
        ignoredEditableSourceChanges += 1
        editableSource = source
    }

    private func setEditableMetalSourceProgrammatically(_ source: String) {
        ignoredEditableMetalSourceChanges += 1
        editableMetalSource = source
    }

    private func ensurePrimaryGraphInfrastructure(
        in document: inout ShaderDocument,
        primaryFragmentNodeID: GraphNode.ID,
        fragmentPosition: CGPoint
    ) {
        var timeNode: GraphNode?
        if let existingTime = document.nodes.first(where: {
            if case .time = $0.kind { return true }
            return false
        }) {
            timeNode = existingTime
        } else {
            let timeNodeID = UUID()
            let newTimeNode = GraphNode(
                id: timeNodeID,
                title: "Time",
                kind: .time,
                position: CGPoint(x: max(40, fragmentPosition.x - 280), y: max(40, fragmentPosition.y - 40)),
                inputPorts: [],
                outputPorts: [
                    GraphPort(
                        id: "time:output",
                        nodeID: timeNodeID,
                        name: "TIME",
                        direction: .output,
                        kind: .time
                    )
                ]
            )
            document.nodes.append(newTimeNode)
            timeNode = newTimeNode
        }

        var renderNode: GraphNode?
        if let existingRender = document.nodes.first(where: {
            if case .renderOutput(let isPrimary) = $0.kind { return isPrimary }
            return false
        }) {
            renderNode = existingRender
        } else {
            let renderNodeID = UUID()
            let inputPort = GraphPort(
                id: "render:\(renderNodeID.uuidString):input",
                nodeID: renderNodeID,
                name: "Shader",
                direction: .input,
                kind: .fragmentShader
            )
            let newRenderNode = GraphNode(
                id: renderNodeID,
                title: "Render",
                kind: .renderOutput(isPrimary: true),
                position: CGPoint(x: fragmentPosition.x + 320, y: fragmentPosition.y),
                inputPorts: [inputPort],
                outputPorts: []
            )
            document.nodes.append(newRenderNode)
            renderNode = newRenderNode
        }

        guard let fragmentNode = document.nodes.first(where: { $0.id == primaryFragmentNodeID }) else {
            return
        }

        if let timeNode,
           let timeOutput = timeNode.outputPorts.first,
           let timeInput = fragmentNode.inputPorts.first(where: { $0.kind == .time }) {
            document.connections.removeAll { $0.toPortID == timeInput.id }
            document.connections.append(GraphConnection(fromPortID: timeOutput.id, toPortID: timeInput.id))
        }

        if let renderNode,
           let renderInput = renderNode.inputPorts.first(where: { $0.kind == .fragmentShader }),
           document.connections.contains(where: { $0.toPortID == renderInput.id }) == false,
           let fragmentOutput = fragmentNode.outputPorts.first(where: { $0.kind == .fragmentShader }) {
            document.connections.append(GraphConnection(fromPortID: fragmentOutput.id, toPortID: renderInput.id))
        }
    }

    private func appendMetalFragment(title preferredTitle: String, metalSource: String, at position: CGPoint) {
        let isFirstFragment = !document.nodes.contains(where: {
            if case .metalFragment = $0.kind { return true }
            return false
        })
        let nodeID = UUID()
        let title = uniqueNodeTitle(preferred: preferredTitle)
        let newNode = GraphNode(
            id: nodeID,
            title: title,
            kind: .metalFragment(isPrimary: isFirstFragment),
            position: position,
            inputPorts: [],
            outputPorts: [Self.makeFragmentOutputPort(nodeID: nodeID)]
        )

        var updatedDocument = document
        updatedDocument.nodes.append(newNode)
        fragmentMetalSources[nodeID] = metalSource
        lastGeneratedMetalSources[nodeID] = metalSource
        document = syncFragmentNodePorts(in: updatedDocument)

        if isFirstFragment {
            var synchronized = document
            ensurePrimaryGraphInfrastructure(in: &synchronized, primaryFragmentNodeID: nodeID, fragmentPosition: position)
            document = synchronized
        }

        if let timeNode = document.nodes.first(where: {
            if case .time = $0.kind { return true }
            return false
        }),
           let timeOutput = timeNode.outputPorts.first,
           let timeInput = document.nodes.first(where: { $0.id == nodeID })?.inputPorts.first(where: { $0.kind == .time }) {
            connectPorts(from: timeOutput.id, to: timeInput.id)
        }

        selectedNodeID = nodeID
        syncEditableMetalSourceWithSelection()
        validateMetalSource()
        updateInspectorFocus()
    }

    private func addPresetFragmentNode(title: String, metalSource: String, at position: CGPoint) {
        appendMetalFragment(title: title, metalSource: metalSource, at: position)
        statusMessage = "Added \(selectedNode?.title ?? title) preset to the graph."
    }

    private func appendImportedShader(
        name: String,
        source: String,
        generatedMetal: String,
        importedUniforms: [UniformDescriptor]
    ) {
        let existingFragmentCount = document.nodes.reduce(0) { partialResult, node in
            guard case .metalFragment = node.kind else { return partialResult }
            return partialResult + 1
        }
        let isFirstFragment = existingFragmentCount == 0
        let mergedUniforms = mergedUniforms(with: importedUniforms)
        let nodeID = UUID()
        let fragmentCount = existingFragmentCount
        let title = uniqueNodeTitle(preferred: name.isEmpty ? "Imported Fragment" : name)
        let newNode = GraphNode(
            id: nodeID,
            title: title,
            kind: .metalFragment(isPrimary: isFirstFragment),
            position: CGPoint(x: 320 + CGFloat(fragmentCount) * 280, y: 220 + CGFloat(fragmentCount % 3) * 80),
            inputPorts: [],
            outputPorts: [Self.makeFragmentOutputPort(nodeID: nodeID)]
        )

        var updatedDocument = document
        updatedDocument.uniforms = mergedUniforms
        updatedDocument.nodes.append(newNode)
        document = updatedDocument
        fragmentMetalSources[nodeID] = generatedMetal
        lastGeneratedMetalSources[nodeID] = generatedMetal
        document = syncFragmentNodePorts(in: document)

        if isFirstFragment {
            var synchronized = document
            ensurePrimaryGraphInfrastructure(in: &synchronized, primaryFragmentNodeID: nodeID, fragmentPosition: newNode.position)
            document = synchronized
        }

        if let timeNode = document.nodes.first(where: {
            if case .time = $0.kind { return true }
            return false
        }),
           let timeOutput = timeNode.outputPorts.first,
           let timeInput = document.nodes.first(where: { $0.id == nodeID })?.inputPorts.first(where: { $0.kind == .time }) {
            connectPorts(from: timeOutput.id, to: timeInput.id)
        }

        baselineUniformValues.merge(Dictionary(uniqueKeysWithValues: mergedUniforms.map { ($0.id, $0.defaultValue) })) { current, _ in current }
        selectedNodeID = nodeID
    }

    private var shouldReplaceTemplateGraphOnImport: Bool {
        let fragmentNodes = document.nodes.filter {
            if case .metalFragment = $0.kind { return true }
            return false
        }
        let renderNodes = document.nodes.filter {
            if case .renderOutput = $0.kind { return true }
            return false
        }
        let hasOnlyTemplateNodes = document.nodes.count == 3
            && document.nodes.contains(where: { if case .time = $0.kind { return true }; return false })
            && fragmentNodes.count == 1
            && renderNodes.count == 1
        return hasOnlyTemplateNodes
            && currentGraphFileURL == nil
            && document.source == Self.sampleISF
    }

    private func replaceTemplateGraph(
        with parsed: ShaderDocument,
        source: String,
        generatedMetal: String
    ) {
        document = parsed
        let primaryFragmentID = parsed.nodes.first(where: \.isPrimaryFragment)?.id
        fragmentMetalSources = primaryFragmentID.map { [$0: generatedMetal] } ?? [:]
        lastGeneratedMetalSources = fragmentMetalSources
        baselineUniformValues = Dictionary(uniqueKeysWithValues: parsed.uniforms.map { ($0.id, $0.defaultValue) })
        setEditableSourceProgrammatically(source)
        selectedNodeID = primaryFragmentID ?? parsed.nodes.first?.id
    }

    private func pruneUnusedUniforms(in document: ShaderDocument) -> ShaderDocument {
        let usedUniformIDs = Set(
            document.nodes
                .flatMap(\.inputPorts)
                .compactMap { port -> UniformDescriptor.ID? in
                    switch port.kind {
                    case .uniform(let uniformID):
                        return uniformID
                    case .fragmentShader:
                        guard let uniform = document.uniforms.first(where: {
                            $0.kind == .image && $0.name.caseInsensitiveCompare(port.name) == .orderedSame
                        }) else {
                            return nil
                        }
                        return uniform.id
                    default:
                        return nil
                    }
                }
        )

        guard usedUniformIDs.count < document.uniforms.count else {
            return document
        }

        var updatedDocument = document
        updatedDocument.uniforms.removeAll { !usedUniformIDs.contains($0.id) }

        let removedUniformNodeIDs = Set(
            updatedDocument.nodes.compactMap { node -> GraphNode.ID? in
                guard case .uniform(let descriptor) = node.kind, !usedUniformIDs.contains(descriptor.id) else { return nil }
                return node.id
            }
        )
        let removedPortIDs = Set(
            updatedDocument.nodes
                .filter { removedUniformNodeIDs.contains($0.id) }
                .flatMap(\.allPorts)
                .map(\.id)
        )
        updatedDocument.nodes.removeAll { removedUniformNodeIDs.contains($0.id) }
        updatedDocument.connections.removeAll {
            removedPortIDs.contains($0.fromPortID) || removedPortIDs.contains($0.toPortID)
        }

        baselineUniformValues = baselineUniformValues.filter { usedUniformIDs.contains($0.key) }
        return updatedDocument
    }

    private func reconnectPrimaryRenderIfNeeded(in document: ShaderDocument) -> ShaderDocument {
        guard
            let primaryRender = document.nodes.first(where: {
                if case .renderOutput(let isPrimary) = $0.kind { return isPrimary }
                return false
            }),
            let renderInput = primaryRender.inputPorts.first(where: { $0.kind == .fragmentShader }),
            !document.connections.contains(where: { $0.toPortID == renderInput.id }),
            let fallbackFragment = document.nodes.first(where: {
                if case .metalFragment = $0.kind { return true }
                return false
            }),
            let fragmentOutput = fallbackFragment.outputPorts.first(where: { $0.kind == .fragmentShader })
        else {
            return document
        }

        var updatedDocument = document
        updatedDocument.connections.append(GraphConnection(fromPortID: fragmentOutput.id, toPortID: renderInput.id))
        return updatedDocument
    }

    private func reconnectPrimaryRenderIfNeeded() {
        document = reconnectPrimaryRenderIfNeeded(in: document)
    }

    private func reconnectTimeNodesIfNeeded() {
        guard
            let timeNode = document.nodes.first(where: {
                if case .time = $0.kind { return true }
                return false
            }),
            let timeOutput = timeNode.outputPorts.first(where: { $0.kind == .time })
        else {
            return
        }

        var updatedDocument = document
        var didChange = false

        for node in updatedDocument.nodes {
            guard case .metalFragment = node.kind else { continue }
            guard let timeInput = node.inputPorts.first(where: { $0.kind == .time }) else { continue }
            guard !updatedDocument.connections.contains(where: { $0.toPortID == timeInput.id }) else { continue }
            updatedDocument.connections.append(GraphConnection(fromPortID: timeOutput.id, toPortID: timeInput.id))
            didChange = true
        }

        if didChange {
            document = updatedDocument
        }
    }

    private func reconnectRenderNodesIfNeeded() {
        var updatedDocument = document
        var didChange = false

        let fallbackOutputs = updatedDocument.nodes.compactMap { node -> GraphPort? in
            switch node.kind {
            case .renderOutput:
                return nil
            default:
                return node.outputPorts.first(where: { $0.kind == .fragmentShader })
            }
        }

        for node in updatedDocument.nodes {
            guard case .renderOutput = node.kind else { continue }
            guard let renderInput = node.inputPorts.first(where: { $0.kind == .fragmentShader }) else { continue }
            guard !updatedDocument.connections.contains(where: { $0.toPortID == renderInput.id }) else { continue }
            let fallbackOutput: GraphPort?
            if let primaryFragmentOutput = updatedDocument.nodes
                .first(where: {
                    if case .metalFragment(isPrimary: true) = $0.kind { return true }
                    return false
                })?
                .outputPorts.first(where: { $0.kind == .fragmentShader }) {
                fallbackOutput = primaryFragmentOutput
            } else if fallbackOutputs.count == 1 {
                fallbackOutput = fallbackOutputs.first
            } else {
                fallbackOutput = nil
            }

            guard let fallbackOutput else { continue }
            updatedDocument.connections.append(GraphConnection(fromPortID: fallbackOutput.id, toPortID: renderInput.id))
            didChange = true
        }

        if didChange {
            document = updatedDocument
        }
    }

    private func mergedUniforms(with importedUniforms: [UniformDescriptor]) -> [UniformDescriptor] {
        mergedUniforms(existing: document.uniforms, additional: importedUniforms)
    }

    private func mergedUniforms(existing: [UniformDescriptor], additional: [UniformDescriptor]) -> [UniformDescriptor] {
        var merged = existing
        var existingNames = Set(merged.map { $0.name.lowercased() })

        for uniform in additional where !existingNames.contains(uniform.name.lowercased()) {
            merged.append(uniform)
            existingNames.insert(uniform.name.lowercased())
        }

        return merged
    }

    private func uniqueNodeTitle(preferred base: String) -> String {
        let trimmedBase = base.trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedBase = trimmedBase.replacingOccurrences(
            of: #"\s+\d+$"#,
            with: "",
            options: .regularExpression
        )
        let existingTitles = Set(document.nodes.map { $0.title.lowercased() })
        if !existingTitles.contains(trimmedBase.lowercased()) {
            return trimmedBase
        }

        var index = 2
        while existingTitles.contains("\(normalizedBase.lowercased()) \(index)") {
            index += 1
        }
        return "\(normalizedBase) \(index)"
    }

    private func dictionary(for uniform: UniformDescriptor) -> [String: Any] {
        var dictionary: [String: Any] = [
            "NAME": uniform.name,
            "TYPE": metadataType(for: uniform.kind)
        ]

        switch uniform.defaultValue {
        case .float(let value):
            dictionary["DEFAULT"] = value
            if let minValue = uniform.minValue {
                dictionary["MIN"] = minValue
            }
            if let maxValue = uniform.maxValue {
                dictionary["MAX"] = maxValue
            }
        case .color(let color):
            dictionary["DEFAULT"] = [Double(color.x), Double(color.y), Double(color.z), Double(color.w)]
        case .point(let point):
            dictionary["DEFAULT"] = [point.x, point.y]
        case .point3(let point):
            dictionary["DEFAULT"] = [point.x, point.y, point.z]
        case .point4(let point):
            dictionary["DEFAULT"] = [point.x, point.y, point.z, point.w]
        case .bool(let value):
            dictionary["DEFAULT"] = value
        case .image(let name):
            dictionary["DEFAULT"] = name
        }

        return dictionary
    }

    private func metadataType(for kind: UniformKind) -> String {
        switch kind {
        case .float:
            return "float"
        case .color:
            return "color"
        case .point2D:
            return "point2D"
        case .float3:
            return "float3"
        case .float4:
            return "float4"
        case .image:
            return "image"
        case .bool:
            return "bool"
        }
    }

    private func uniqueUniformName(from base: String) -> String {
        let existingNames = Set(document.uniforms.map { $0.name.lowercased() })
        if !existingNames.contains(base.lowercased()) {
            return base
        }

        var index = 2
        while existingNames.contains("\(base.lowercased())\(index)") {
            index += 1
        }
        return "\(base)\(index)"
    }

    private func defaultUniformValue(for kind: UniformKind) -> UniformValue {
        switch kind {
        case .float:
            return .float(0.5)
        case .color:
            return .color(SIMD4<Float>(1, 1, 1, 1))
        case .point2D:
            return .point(CGPoint(x: 0.5, y: 0.5))
        case .float3:
            return .point3(Point3Value(x: 0.0, y: 0.0, z: 0.0))
        case .float4:
            return .point4(Point4Value(x: 0.0, y: 0.0, z: 0.0, w: 0.0))
        case .image:
            return .image("Texture")
        case .bool:
            return .bool(false)
        }
    }

    private func readSecurityScopedFile(at url: URL) throws -> String {
        let didAccess = url.startAccessingSecurityScopedResource()
        defer {
            if didAccess {
                url.stopAccessingSecurityScopedResource()
            }
        }

        var coordinatedError: NSError?
        var fileContents: String?
        var readError: Error?

        NSFileCoordinator().coordinate(readingItemAt: url, options: [], error: &coordinatedError) { coordinatedURL in
            do {
                fileContents = try String(contentsOf: coordinatedURL, encoding: .utf8)
            } catch {
                readError = error
            }
        }

        if let readError {
            throw readError
        }

        if let coordinatedError {
            throw coordinatedError
        }

        guard let fileContents else {
            throw CocoaError(.fileReadUnknown)
        }

        return fileContents
    }

    private func readSecurityScopedData(at url: URL) throws -> Data {
        let didAccess = url.startAccessingSecurityScopedResource()
        defer {
            if didAccess {
                url.stopAccessingSecurityScopedResource()
            }
        }

        var coordinatedError: NSError?
        var fileContents: Data?
        var readError: Error?

        NSFileCoordinator().coordinate(readingItemAt: url, options: [], error: &coordinatedError) { coordinatedURL in
            do {
                fileContents = try Data(contentsOf: coordinatedURL)
            } catch {
                readError = error
            }
        }

        if let readError {
            throw readError
        }

        if let coordinatedError {
            throw coordinatedError
        }

        guard let fileContents else {
            throw CocoaError(.fileReadUnknown)
        }

        return fileContents
    }

    private func writeGraphText(_ text: String, to url: URL) throws {
        let writeURL = resolvedSecurityScopedGraphURL(for: url) ?? url
        let didAccess = writeURL.startAccessingSecurityScopedResource()
        defer {
            if didAccess {
                writeURL.stopAccessingSecurityScopedResource()
            }
        }

        var coordinatedError: NSError?
        var writeError: Error?

        NSFileCoordinator().coordinate(writingItemAt: writeURL, options: .forReplacing, error: &coordinatedError) { coordinatedURL in
            do {
                try text.write(to: coordinatedURL, atomically: true, encoding: .utf8)
            } catch {
                writeError = error
            }
        }

        if let writeError {
            throw writeError
        }

        if let coordinatedError {
            throw coordinatedError
        }
    }

    private func resolvedSecurityScopedGraphURL(for url: URL) -> URL? {
        guard let bookmark = UserDefaults.standard.data(forKey: GraphPreferenceKey.lastGraphBookmark) else {
            return nil
        }

        var isStale = false
        guard let resolvedURL = try? URL(
            resolvingBookmarkData: bookmark,
            options: [.withSecurityScope],
            relativeTo: nil,
            bookmarkDataIsStale: &isStale
        ) else {
            return nil
        }

        guard resolvedURL.path == url.path else {
            return nil
        }

        if isStale,
           let refreshedBookmark = try? resolvedURL.bookmarkData(options: .withSecurityScope, includingResourceValuesForKeys: nil, relativeTo: nil) {
            UserDefaults.standard.set(refreshedBookmark, forKey: GraphPreferenceKey.lastGraphBookmark)
        }

        return resolvedURL
    }

    func generateAIImage(for nodeID: GraphNode.ID) {
        guard var settings = aiImageNodeSettings[nodeID] else { return }
        let trimmedPrompt = settings.prompt.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedPrompt.isEmpty else {
            aiImageNodeStatus[nodeID] = "Enter a prompt first."
            statusMessage = "Enter a prompt first."
            return
        }

        if #available(macOS 15.1, *) {
            guard ImagePlaygroundViewController.isAvailable else {
                let message = "Image Playground is unavailable on this Mac."
                aiImageNodeStatus[nodeID] = message
                statusMessage = message
                return
            }
        }

        aiImageNodeStatus[nodeID] = "Generating..."
        statusMessage = "Generating image for \(document.nodes.first(where: { $0.id == nodeID })?.title ?? "AI Image")…"

        Task {
            do {
                if #available(macOS 15.4, *) {
                    let creator = try await ImageCreator()
                    let concepts = [ImagePlaygroundConcept.text(trimmedPrompt)]
                    let style = imagePlaygroundStyle(for: settings.style)
                    var firstImage: CGImage?

                    for try await image in creator.images(for: concepts, style: style, limit: 1) {
                        firstImage = image.cgImage
                        break
                    }

                    guard let firstImage,
                          let imageData = imageData(from: firstImage) else {
                        await MainActor.run {
                            self.aiImageNodeStatus[nodeID] = "Image generation failed."
                            self.statusMessage = "Image generation failed."
                        }
                        return
                    }

                    let filename = sanitizedFilename(trimmedPrompt).prefix(32)
                    await MainActor.run {
                        settings.filename = "\(filename).png"
                        settings.imageData = imageData
                        self.aiImageNodeSettings[nodeID] = settings
                        self.aiImageNodeStatus[nodeID] = "Generated."
                        self.statusMessage = "Generated image for \(trimmedPrompt)."
                        self.objectWillChange.send()
                    }
                } else {
                    await MainActor.run {
                        let message = "Use the Image Playground sheet on macOS 15.1+."
                        self.aiImageNodeStatus[nodeID] = message
                        self.statusMessage = message
                    }
                }
            } catch {
                await MainActor.run {
                    let message = self.aiImageErrorMessage(for: error)
                    self.aiImageNodeStatus[nodeID] = message
                    self.statusMessage = message
                }
            }
        }
    }

    func completeAIImageGeneration(for nodeID: GraphNode.ID, imageURL: URL) {
        guard var settings = aiImageNodeSettings[nodeID] else { return }

        do {
            let imageData = try Data(contentsOf: imageURL)
            let trimmedPrompt = settings.prompt.trimmingCharacters(in: .whitespacesAndNewlines)
            let fallbackName = trimmedPrompt.isEmpty ? "AI Image" : String(sanitizedFilename(trimmedPrompt).prefix(32))
            let preferredName = imageURL.lastPathComponent.isEmpty ? fallbackName : imageURL.deletingPathExtension().lastPathComponent
            let ext = imageURL.pathExtension.isEmpty ? "png" : imageURL.pathExtension

            settings.imageData = imageData
            settings.filename = "\(preferredName).\(ext)"
            aiImageNodeSettings[nodeID] = settings
            aiImageNodeStatus[nodeID] = "Generated."
            statusMessage = "Generated image for \(trimmedPrompt.isEmpty ? preferredName : trimmedPrompt)."
            objectWillChange.send()
        } catch {
            let message = "Failed to load generated image: \(error.localizedDescription)"
            aiImageNodeStatus[nodeID] = message
            statusMessage = message
        }
    }

    func cancelAIImageGeneration(for nodeID: GraphNode.ID) {
        aiImageNodeStatus[nodeID] = "Generation cancelled."
        statusMessage = "Image generation cancelled."
    }

    func setAIImageNodeStatus(_ status: String?, for nodeID: GraphNode.ID) {
        aiImageNodeStatus[nodeID] = status
    }

    @available(macOS 15.4, *)
    private func imagePlaygroundStyle(for style: AIImageStyle) -> ImagePlaygroundStyle {
        switch style {
        case .illustration:
            return .illustration
        case .animation:
            return .animation
        case .sketch:
            return .sketch
        }
    }

    private func imageData(from cgImage: CGImage) -> Data? {
        let rep = NSBitmapImageRep(cgImage: cgImage)
        return rep.representation(using: .png, properties: [:]) ?? rep.tiffRepresentation
    }

    private func sliderRect(for settings: SliderNodeSettings) -> CGRect {
        CGRect(
            x: settings.x - (settings.width * 0.5),
            y: settings.y - (settings.height * 0.5),
            width: settings.width,
            height: settings.height
        )
    }

    private func buttonRect(for settings: ButtonNodeSettings) -> CGRect {
        CGRect(
            x: settings.x - (settings.width * 0.5),
            y: settings.y - (settings.height * 0.5),
            width: settings.width,
            height: settings.height
        )
    }

    private func sliderValue(for nodeID: GraphNode.ID) -> Double {
        guard let settings = sliderNodeSettings[nodeID] else { return 0.0 }
        var runtime = sliderControlRuntimeStates[nodeID] ?? SliderControlRuntimeState()
        let rect = sliderRect(for: settings)
        let pointerInside = currentMousePosition.map { rect.contains($0) } ?? false
        let persistedValue = settings.value

        if currentMouseLeftButtonDown {
            if pointerInside || runtime.isDragging {
                runtime.isDragging = true
                if let pointer = currentMousePosition {
                    let fraction = min(max((pointer.x - rect.minX) / max(rect.width, 0.0001), 0.0), 1.0)
                    let newValue = settings.min + (fraction * (settings.max - settings.min))
                    if abs(newValue - (runtime.liveValue ?? persistedValue)) > 0.0001 {
                        runtime.liveValue = newValue
                    }
                }
            }
        } else {
            if runtime.isDragging,
               let liveValue = runtime.liveValue,
               abs(liveValue - persistedValue) > 0.0001 {
                runtime.pendingCommitValue = liveValue
            }
            runtime.isDragging = false
            runtime.liveValue = nil
        }

        sliderControlRuntimeStates[nodeID] = runtime
        if let pendingCommitValue = runtime.pendingCommitValue {
            DispatchQueue.main.async { [weak self] in
                guard let self else { return }
                guard var currentRuntime = self.sliderControlRuntimeStates[nodeID],
                      currentRuntime.pendingCommitValue == pendingCommitValue else {
                    return
                }
                currentRuntime.pendingCommitValue = nil
                self.sliderControlRuntimeStates[nodeID] = currentRuntime
                self.updateSliderNodeSettings(nodeID) { $0.value = pendingCommitValue }
            }
        }
        return runtime.liveValue ?? persistedValue
    }

    private func resolvedSliderStyleSettings(forSliderNodeID nodeID: GraphNode.ID) -> SliderStyleNodeSettings {
        guard let sliderNode = node(withID: nodeID),
              let styleInput = sliderNode.inputPorts.first(where: { $0.kind == .sliderStyle }),
              let connection = effectiveIncomingConnection(for: styleInput.id),
              let sourcePort = resolvedSourcePort(for: connection.fromPortID),
              let styleSettings = sliderStyleNodeSettings[sourcePort.nodeID] else {
            return SliderStyleNodeSettings()
        }
        return styleSettings
    }

    private func resolvedSliderStyleKnobImage(forSliderNodeID nodeID: GraphNode.ID) -> NSImage? {
        guard let sliderNode = node(withID: nodeID),
              let styleInput = sliderNode.inputPorts.first(where: { $0.kind == .sliderStyle }),
              let styleConnection = effectiveIncomingConnection(for: styleInput.id),
              let styleSourcePort = resolvedSourcePort(for: styleConnection.fromPortID),
              let styleNode = node(withID: styleSourcePort.nodeID),
              case .sliderStyle = styleNode.kind,
              let knobImageInput = styleNode.inputPorts.first(where: { $0.name == "Knob Image" }),
              let knobConnection = effectiveIncomingConnection(for: knobImageInput.id),
              let knobSourcePort = resolvedSourcePort(for: knobConnection.fromPortID),
              let imageData = renderedImageData(forSourceNodeID: knobSourcePort.nodeID) else {
            return nil
        }
        return NSImage(data: imageData)
    }

    private func renderedImageData(forSourceNodeID nodeID: GraphNode.ID) -> Data? {
        guard let sourceNode = node(withID: nodeID) else { return nil }

        switch sourceNode.kind {
        case .image:
            return settings(forImageNodeID: sourceNode.id)?.imageData
        case .webView:
            return settings(forWebViewNodeID: sourceNode.id).snapshotData
        case .aiImage:
            return settings(forAIImageNodeID: sourceNode.id).imageData
        case .videoPlayer:
            return videoPlayerFrameData[sourceNode.id]
        case .note:
            return renderedNoteImageData(for: sourceNode.id)
        case .slider:
            return renderedSliderImageData(for: sourceNode.id)
        case .button:
            return renderedButtonImageData(for: sourceNode.id)
        default:
            return nil
        }
    }

    private func resolvedButtonStyleSettings(forButtonNodeID nodeID: GraphNode.ID) -> ButtonStyleNodeSettings {
        guard let buttonNode = node(withID: nodeID),
              let styleInput = buttonNode.inputPorts.first(where: { $0.kind == .buttonStyle }),
              let connection = effectiveIncomingConnection(for: styleInput.id),
              let sourcePort = resolvedSourcePort(for: connection.fromPortID),
              let styleSettings = buttonStyleNodeSettings[sourcePort.nodeID] else {
            return ButtonStyleNodeSettings()
        }
        return styleSettings
    }

    private func resolvedButtonStyleImage(forButtonNodeID nodeID: GraphNode.ID, portName: String) -> NSImage? {
        guard let buttonNode = node(withID: nodeID),
              let styleInput = buttonNode.inputPorts.first(where: { $0.kind == .buttonStyle }),
              let styleConnection = effectiveIncomingConnection(for: styleInput.id),
              let styleSourcePort = resolvedSourcePort(for: styleConnection.fromPortID),
              let styleNode = node(withID: styleSourcePort.nodeID),
              case .buttonStyle = styleNode.kind,
              let imageInput = styleNode.inputPorts.first(where: { $0.name == portName }),
              let imageConnection = effectiveIncomingConnection(for: imageInput.id),
              let imageSourcePort = resolvedSourcePort(for: imageConnection.fromPortID),
              let imageData = renderedImageData(forSourceNodeID: imageSourcePort.nodeID) else {
            return nil
        }
        return NSImage(data: imageData)
    }

    private func buttonHoverValue(for nodeID: GraphNode.ID) -> Double {
        guard let settings = buttonNodeSettings[nodeID],
              let pointer = currentMousePosition else {
            return 0.0
        }
        return buttonRect(for: settings).contains(pointer) ? 1.0 : 0.0
    }

    private func buttonPressedValue(for nodeID: GraphNode.ID) -> Double {
        guard let settings = buttonNodeSettings[nodeID],
              let pointer = currentMousePosition else {
            return 0.0
        }
        return (currentMouseLeftButtonDown && buttonRect(for: settings).contains(pointer)) ? 1.0 : 0.0
    }

    private func renderedSliderImageData(for nodeID: GraphNode.ID) -> Data? {
        let settings = settings(forSliderNodeID: nodeID)
        let style = resolvedSliderStyleSettings(forSliderNodeID: nodeID)
        let knobImage = resolvedSliderStyleKnobImage(forSliderNodeID: nodeID)
        let value = sliderValue(for: nodeID)
        let size = NSSize(width: 1024, height: 1024)
        guard let rep = NSBitmapImageRep(
            bitmapDataPlanes: nil,
            pixelsWide: Int(size.width),
            pixelsHigh: Int(size.height),
            bitsPerSample: 8,
            samplesPerPixel: 4,
            hasAlpha: true,
            isPlanar: false,
            colorSpaceName: .deviceRGB,
            bytesPerRow: 0,
            bitsPerPixel: 0
        ), let context = NSGraphicsContext(bitmapImageRep: rep) else {
            return nil
        }

        rep.size = size
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = context
        defer { NSGraphicsContext.restoreGraphicsState() }

        NSColor.clear.setFill()
        NSBezierPath(rect: NSRect(origin: .zero, size: size)).fill()

        let rect = sliderRect(for: settings)
        let pixelRect = NSRect(
            x: rect.minX * size.width,
            y: (1.0 - rect.maxY) * size.height,
            width: rect.width * size.width,
            height: rect.height * size.height
        )
        let trackInset = pixelRect.height * 0.28
        let trackHeight = max(pixelRect.height * CGFloat(style.trackThickness), 10)
        let trackRect = NSRect(
            x: pixelRect.minX + trackInset,
            y: pixelRect.midY - trackHeight * 0.5,
            width: pixelRect.width - trackInset * 2,
            height: trackHeight
        )
        let trackPath = NSBezierPath(roundedRect: trackRect, xRadius: trackRect.height * 0.5, yRadius: trackRect.height * 0.5)
        NSColor(
            calibratedRed: style.trackRed,
            green: style.trackGreen,
            blue: style.trackBlue,
            alpha: 1.0
        ).setFill()
        trackPath.fill()

        let fraction = (settings.max - settings.min).magnitude > .ulpOfOne ? (value - settings.min) / (settings.max - settings.min) : 0.0
        let knobX = trackRect.minX + CGFloat(min(max(fraction, 0.0), 1.0)) * trackRect.width
        let knobWidth = pixelRect.height * 0.44 * CGFloat(style.knobScale)
        let knobHeight = pixelRect.height * 0.72 * CGFloat(style.knobScale)
        let knobRect = NSRect(
            x: knobX - knobWidth * 0.5,
            y: pixelRect.midY - knobHeight * 0.5,
            width: knobWidth,
            height: knobHeight
        )
        if let knobImage {
            knobImage.draw(in: knobRect, from: .zero, operation: .sourceOver, fraction: 1.0)
        } else {
            NSColor(
                calibratedRed: style.knobRed,
                green: style.knobGreen,
                blue: style.knobBlue,
                alpha: 1.0
            ).setFill()
            NSBezierPath(roundedRect: knobRect, xRadius: knobRect.width * 0.5, yRadius: knobRect.width * 0.5).fill()
        }

        if knobImage == nil,
           !style.knobSymbol.isEmpty,
           let symbolImage = NSImage(systemSymbolName: style.knobSymbol, accessibilityDescription: settings.label) {
            let symbolConfig = NSImage.SymbolConfiguration(pointSize: knobRect.height * 0.48, weight: .semibold)
            let configured = symbolImage.withSymbolConfiguration(symbolConfig) ?? symbolImage
            let symbolRect = knobRect.insetBy(dx: knobRect.width * 0.22, dy: knobRect.height * 0.22)
            configured.draw(in: symbolRect, from: .zero, operation: .sourceOver, fraction: 1.0)
        }

        let fontWeight: NSFont.Weight
        switch style.fontWeight {
        case .regular:
            fontWeight = .regular
        case .medium:
            fontWeight = .medium
        case .semibold:
            fontWeight = .semibold
        case .bold:
            fontWeight = .bold
        }

        let fontPointSize = pixelRect.height * CGFloat(style.fontSize)
        let resolvedFont = style.fontName.isEmpty
            ? NSFont.systemFont(ofSize: fontPointSize, weight: fontWeight)
            : (NSFont(name: style.fontName, size: fontPointSize) ?? NSFont.systemFont(ofSize: fontPointSize, weight: fontWeight))

        let labelAttributes: [NSAttributedString.Key: Any] = [
            .font: resolvedFont,
            .foregroundColor: NSColor(
                calibratedRed: style.textRed,
                green: style.textGreen,
                blue: style.textBlue,
                alpha: 1.0
            )
        ]
        let trimmedLabel = settings.label.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmedLabel.isEmpty {
            NSString(string: trimmedLabel).draw(
                at: CGPoint(x: pixelRect.minX + 16, y: pixelRect.maxY - pixelRect.height * 0.28),
                withAttributes: labelAttributes
            )
        }

        let valueString = String(format: "%.2f", value)
        NSString(string: valueString).draw(
            at: CGPoint(x: pixelRect.maxX - 80, y: pixelRect.maxY - pixelRect.height * 0.28),
            withAttributes: labelAttributes
        )

        return rep.representation(using: .png, properties: [:]) ?? rep.tiffRepresentation
    }

    private func renderedButtonImageData(for nodeID: GraphNode.ID) -> Data? {
        let settings = settings(forButtonNodeID: nodeID)
        let style = resolvedButtonStyleSettings(forButtonNodeID: nodeID)
        let pressed = buttonPressedValue(for: nodeID) > 0.5
        let hovered = buttonHoverValue(for: nodeID) > 0.5
        let pressedImage = resolvedButtonStyleImage(forButtonNodeID: nodeID, portName: "Pressed Image")
        let hoverImage = resolvedButtonStyleImage(forButtonNodeID: nodeID, portName: "Hover Image")
        let baseImage = resolvedButtonStyleImage(forButtonNodeID: nodeID, portName: "Image")
        let styleImage = pressed ? (pressedImage ?? hoverImage ?? baseImage) : (hovered ? (hoverImage ?? baseImage) : baseImage)
        let size = NSSize(width: 1024, height: 1024)
        guard let rep = NSBitmapImageRep(
            bitmapDataPlanes: nil,
            pixelsWide: Int(size.width),
            pixelsHigh: Int(size.height),
            bitsPerSample: 8,
            samplesPerPixel: 4,
            hasAlpha: true,
            isPlanar: false,
            colorSpaceName: .deviceRGB,
            bytesPerRow: 0,
            bitsPerPixel: 0
        ), let context = NSGraphicsContext(bitmapImageRep: rep) else {
            return nil
        }

        rep.size = size
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = context
        defer { NSGraphicsContext.restoreGraphicsState() }

        NSColor.clear.setFill()
        NSBezierPath(rect: NSRect(origin: .zero, size: size)).fill()

        let rect = buttonRect(for: settings)
        let pixelRect = NSRect(
            x: rect.minX * size.width,
            y: (1.0 - rect.maxY) * size.height,
            width: rect.width * size.width,
            height: rect.height * size.height
        )
        if let styleImage {
            styleImage.draw(in: pixelRect, from: .zero, operation: .sourceOver, fraction: 1.0)
        } else {
            let buttonPath = NSBezierPath(roundedRect: pixelRect, xRadius: 24, yRadius: 24)
            let fillColor: NSColor
            if pressed {
                fillColor = NSColor(
                    calibratedRed: style.pressedRed,
                    green: style.pressedGreen,
                    blue: style.pressedBlue,
                    alpha: 0.92
                )
            } else if hovered {
                fillColor = NSColor(
                    calibratedRed: style.hoverRed,
                    green: style.hoverGreen,
                    blue: style.hoverBlue,
                    alpha: 0.92
                )
            } else {
                fillColor = NSColor(
                    calibratedRed: style.fillRed,
                    green: style.fillGreen,
                    blue: style.fillBlue,
                    alpha: 0.92
                )
            }
            fillColor.setFill()
            buttonPath.fill()
        }

        let trimmedTitle = settings.title.trimmingCharacters(in: .whitespacesAndNewlines)
        let trimmedSymbol = settings.sfSymbol.trimmingCharacters(in: .whitespacesAndNewlines)
        let symbolRect = NSRect(x: pixelRect.minX + 20, y: pixelRect.midY - pixelRect.height * 0.16, width: pixelRect.height * 0.32, height: pixelRect.height * 0.32)
        if !trimmedSymbol.isEmpty {
            let symbolConfig = NSImage.SymbolConfiguration(pointSize: pixelRect.height * 0.32, weight: .semibold)
            let symbolImage = NSImage(systemSymbolName: trimmedSymbol, accessibilityDescription: trimmedTitle)?
                .withSymbolConfiguration(symbolConfig)
            symbolImage?.draw(in: symbolRect)
        }

        let textAttributes: [NSAttributedString.Key: Any] = [
            .font: NSFont.systemFont(ofSize: pixelRect.height * 0.24, weight: .semibold),
            .foregroundColor: NSColor(
                calibratedRed: style.textRed,
                green: style.textGreen,
                blue: style.textBlue,
                alpha: 1.0
            )
        ]
        if !trimmedTitle.isEmpty {
            let textX = trimmedSymbol.isEmpty ? pixelRect.minX + 20 : pixelRect.minX + 20 + symbolRect.width + 12
            NSString(string: trimmedTitle).draw(
                at: CGPoint(x: textX, y: pixelRect.midY - pixelRect.height * 0.13),
                withAttributes: textAttributes
            )
        }

        return rep.representation(using: .png, properties: [:]) ?? rep.tiffRepresentation
    }

    private func renderedNoteImageData(for nodeID: GraphNode.ID) -> Data? {
        let settings = settings(forNoteNodeID: nodeID)
        let size = NSSize(width: 1024, height: 1024)
        guard let rep = NSBitmapImageRep(
            bitmapDataPlanes: nil,
            pixelsWide: Int(size.width),
            pixelsHigh: Int(size.height),
            bitsPerSample: 8,
            samplesPerPixel: 4,
            hasAlpha: true,
            isPlanar: false,
            colorSpaceName: .deviceRGB,
            bytesPerRow: 0,
            bitsPerPixel: 0
        ) else {
            return nil
        }

        rep.size = size
        guard let context = NSGraphicsContext(bitmapImageRep: rep) else {
            return nil
        }

        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = context
        defer {
            NSGraphicsContext.restoreGraphicsState()
        }

        NSColor.clear.setFill()
        NSBezierPath(rect: NSRect(origin: .zero, size: size)).fill()

        let inset: CGFloat = 48
        let rect = NSRect(
            x: inset,
            y: inset,
            width: size.width - inset * 2,
            height: size.height - inset * 2
        )

        let paragraph = NSMutableParagraphStyle()
        paragraph.alignment = .left
        paragraph.lineBreakMode = .byWordWrapping

        let backgroundColor = NSColor(
            calibratedRed: settings.backgroundRed,
            green: settings.backgroundGreen,
            blue: settings.backgroundBlue,
            alpha: settings.backgroundAlpha
        )
        backgroundColor.setFill()
        NSBezierPath(roundedRect: rect, xRadius: 28, yRadius: 28).fill()

        let attributes: [NSAttributedString.Key: Any] = [
            .font: NSFont.systemFont(ofSize: settings.fontSize, weight: .semibold),
            .foregroundColor: NSColor(
                calibratedRed: settings.textRed,
                green: settings.textGreen,
                blue: settings.textBlue,
                alpha: 1.0
            ),
            .paragraphStyle: paragraph
        ]
        let textRect = rect.insetBy(dx: 28, dy: 28)
        NSString(string: settings.text).draw(in: textRect, withAttributes: attributes)
        return rep.representation(using: .png, properties: [:])
    }

    private func renderedTextImageData(for nodeID: GraphNode.ID) -> Data? {
        let settings = settings(forTextImageNodeID: nodeID)
        let resolvedNode = node(withID: nodeID)
        let resolvedText = resolvedNode.flatMap { textImageNode in
            textImageNode.inputPorts.first(where: { $0.name == "Text" }).flatMap {
                resolvedStringValue(forInputPortID: $0.id)
            }
        } ?? settings.text
        let resolvedX = resolvedNode.flatMap { textImageNode in
            textImageNode.inputPorts.first(where: { $0.name == "X" }).flatMap {
                resolvedScalarValue(forInputPortID: $0.id)
            }
        } ?? settings.x
        let resolvedY = resolvedNode.flatMap { textImageNode in
            textImageNode.inputPorts.first(where: { $0.name == "Y" }).flatMap {
                resolvedScalarValue(forInputPortID: $0.id)
            }
        } ?? settings.y
        let resolvedTextColor = resolvedNode.flatMap { textImageNode in
            textImageNode.inputPorts.first(where: { $0.name == "Color" }).flatMap {
                resolvedColorValue(forInputPortID: $0.id)
            }
        } ?? SIMD4<Float>(Float(settings.textRed), Float(settings.textGreen), Float(settings.textBlue), 1.0)

        let size = NSSize(width: 1024, height: 1024)
        guard let rep = NSBitmapImageRep(
            bitmapDataPlanes: nil,
            pixelsWide: Int(size.width),
            pixelsHigh: Int(size.height),
            bitsPerSample: 8,
            samplesPerPixel: 4,
            hasAlpha: true,
            isPlanar: false,
            colorSpaceName: .deviceRGB,
            bytesPerRow: 0,
            bitsPerPixel: 0
        ), let context = NSGraphicsContext(bitmapImageRep: rep) else {
            return nil
        }

        rep.size = size
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = context
        defer { NSGraphicsContext.restoreGraphicsState() }

        NSColor.clear.setFill()
        NSBezierPath(rect: NSRect(origin: .zero, size: size)).fill()

        let inset: CGFloat = 48
        let rect = NSRect(x: inset, y: inset, width: size.width - inset * 2, height: size.height - inset * 2)
        let backgroundColor = NSColor(
            calibratedRed: settings.backgroundRed,
            green: settings.backgroundGreen,
            blue: settings.backgroundBlue,
            alpha: settings.backgroundAlpha
        )

        let paragraph = NSMutableParagraphStyle()
        paragraph.alignment = .left
        paragraph.lineBreakMode = .byWordWrapping
        let resolvedFont = settings.fontName.isEmpty
            ? NSFont.systemFont(ofSize: settings.fontSize, weight: .regular)
            : (NSFont(name: settings.fontName, size: settings.fontSize)
                ?? NSFont.systemFont(ofSize: settings.fontSize, weight: .regular))
        let attributes: [NSAttributedString.Key: Any] = [
            .font: resolvedFont,
            .foregroundColor: NSColor(
                calibratedRed: CGFloat(resolvedTextColor.x),
                green: CGFloat(resolvedTextColor.y),
                blue: CGFloat(resolvedTextColor.z),
                alpha: CGFloat(resolvedTextColor.w)
            ),
            .paragraphStyle: paragraph
        ]
        let textRect = rect.insetBy(dx: 24, dy: 24)
        let attributedText = NSAttributedString(string: resolvedText, attributes: attributes)
        let measuredRect = attributedText.boundingRect(
            with: CGSize(width: textRect.width, height: .greatestFiniteMagnitude),
            options: [.usesLineFragmentOrigin, .usesFontLeading]
        ).integral
        let clampedX = min(max(CGFloat(resolvedX), 0.0), 1.0)
        let clampedY = min(max(CGFloat(resolvedY), 0.0), 1.0)
        let drawOrigin = CGPoint(
            x: textRect.minX + (textRect.width - measuredRect.width) * clampedX,
            y: textRect.minY + (textRect.height - measuredRect.height) * (1.0 - clampedY)
        )
        let drawRect = NSRect(origin: drawOrigin, size: CGSize(width: measuredRect.width, height: measuredRect.height))

        if settings.backgroundAlpha > 0.001 {
            backgroundColor.setFill()
            NSBezierPath(roundedRect: drawRect.insetBy(dx: -24, dy: -18), xRadius: 28, yRadius: 28).fill()
        }

        attributedText.draw(
            with: drawRect,
            options: [.usesLineFragmentOrigin, .usesFontLeading]
        )
        return rep.representation(using: .png, properties: [:])
    }

    private func aiImageErrorMessage(for error: Error) -> String {
        if #available(macOS 15.4, *), let imageError = error as? ImageCreator.Error {
            switch imageError {
            case .notSupported:
                return "Image Playground is not supported on this Mac."
            case .unavailable:
                return "Image Playground is currently unavailable."
            case .creationCancelled:
                return "Image generation cancelled."
            case .faceInImageTooSmall:
                return "The source face is too small for generation."
            case .unsupportedLanguage:
                return "The prompt language is unsupported."
            case .unsupportedInputImage:
                return "The input image is unsupported."
            case .backgroundCreationForbidden:
                return "Background generation is forbidden. Use the Playground sheet."
            case .creationFailed:
                return "Image Playground failed to create an image."
            case .conceptsRequirePersonIdentity:
                return "This prompt requires person identity concepts, which are unavailable."
            @unknown default:
                return "Image generation failed."
            }
        }

        let message = error.localizedDescription.trimmingCharacters(in: .whitespacesAndNewlines)
        return message.isEmpty ? "Image generation failed." : "Image generation failed: \(message)"
    }

    private static func makeMetalStub(from document: ShaderDocument) -> String {
        ISFMetalTranslator.translate(document: document)
    }

    private static let plasmaPresetMetalSource = """
    #include <metal_stdlib>
    using namespace metal;

    struct Uniforms {
        float Speed;
        float Zoom;
        float HueShift;
        float Pulse;
        float Warp;
        float Grain;
        float AudioAmp;
        float Contrast;
    };

    float hash21(float2 p) {
        p = fract(p * float2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
    }

    float noise2(float2 p) {
        float2 i = floor(p);
        float2 f = fract(p);

        float a = hash21(i);
        float b = hash21(i + float2(1.0, 0.0));
        float c = hash21(i + float2(0.0, 1.0));
        float d = hash21(i + float2(1.0, 1.0));

        float2 u = f * f * (3.0 - 2.0 * f);

        return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
    }

    float fbm(float2 p) {
        float value = 0.0;
        float amplitude = 0.5;

        for (int i = 0; i < 5; ++i) {
            value += amplitude * noise2(p);
            p = p * 2.03 + float2(0.37, 0.61);
            amplitude *= 0.5;
        }

        return value;
    }

    float2 rotate2D(float2 p, float a) {
        float c = cos(a);
        float s = sin(a);
        return float2(c * p.x - s * p.y, s * p.x + c * p.y);
    }

    float3 hsv2rgb(float3 c) {
        float3 rgb = clamp(abs(fract(c.x + float3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
        rgb = rgb * rgb * (3.0 - 2.0 * rgb);
        return c.z * mix(float3(1.0), rgb, c.y);
    }

    fragment float4 generatedFragment(RasterizerData in [[stage_in]],
                                      constant PreviewUniforms& uniforms [[buffer(0)]],
                                      constant float* floatUniforms [[buffer(1)]],
                                      constant float4* colorUniforms [[buffer(2)]],
                                      constant float2* pointUniforms [[buffer(3)]],
                                      constant uint* boolUniforms [[buffer(4)]]) {
        float Speed = floatUniforms[0];
        float Zoom = floatUniforms[1];
        float HueShift = floatUniforms[2];
        float Pulse = floatUniforms[3];
        float Warp = floatUniforms[4];
        float Grain = floatUniforms[5];
        float AudioAmp = floatUniforms[6];
        float Contrast = floatUniforms[7];

        float TIME = uniforms.time;
        float2 RENDERSIZE = uniforms.resolution;

        float2 uv = in.uv * 2.0 - 1.0;
        uv.x *= RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
        uv *= max(Zoom, 0.001);

        float t = TIME * Speed;
        float amp = AudioAmp;

        float2 q = uv;
        q = rotate2D(q, 0.18 * t + amp * 0.6);

        float2 flowA = float2(
            fbm(q * 1.3 + float2(0.0, 0.23 * t)),
            fbm(q * 1.3 + float2(4.2, -0.17 * t))
        );

        float2 flowB = float2(
            fbm(q * 2.1 - flowA * 1.4 + float2(1.7, 0.11 * t)),
            fbm(q * 2.1 + flowA.yx * 1.2 + float2(-2.4, -0.09 * t))
        );

        float2 warped = q + (flowA - 0.5) * Warp * 1.8 + (flowB - 0.5) * 0.9;
        float field = fbm(warped * 2.4 + float2(0.13 * t, -0.07 * t));

        float rings = sin(length(warped) * 10.0 - t * 1.7 + field * 4.0);
        float plasma = sin(warped.x * 4.0 + t)
                     + sin(warped.y * 5.3 - t * 1.2)
                     + sin((warped.x + warped.y) * 3.7 + t * 0.7);

        plasma = plasma * 0.25 + field * 1.2 + rings * 0.35;

        float pulse = 0.5 + 0.5 * sin(t * 1.6 + field * 6.0);
        float brightness = max(0.0, plasma * 0.55 + pulse * Pulse * (0.7 + amp * 1.6));

        float hue = fract(0.58 + HueShift + plasma * 0.12 + field * 0.18 + amp * 0.15);
        float sat = 0.78 + 0.18 * sin(field * 8.0 + t * 0.5);
        float val = pow(max(brightness, 0.0), max(0.25, Contrast));

        float3 color = hsv2rgb(float3(hue, clamp(sat, 0.0, 1.0), val));

        float sparkle = pow(max(0.0, 1.0 - length(warped) * 0.9), 6.0) * (0.4 + amp * 1.4);
        color += float3(1.0, 0.7, 0.25) * sparkle;

        float grain = (hash21(in.uv * RENDERSIZE + t) - 0.5) * Grain;
        color += grain;

        color = clamp(color, 0.0, 1.0);
        return float4(color, 1.0);
    }
    """

    private static let lavaLampPresetMetalSource = """
    #include <metal_stdlib>
    using namespace metal;

    struct Uniforms {
        float Speed;
        float Scale;
        float Glow;
        float Amplitude;
        float HueShift;
    };

    float hash21(float2 p) {
        p = fract(p * float2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
    }

    float noise2d(float2 p) {
        float2 i = floor(p);
        float2 f = fract(p);

        float a = hash21(i);
        float b = hash21(i + float2(1.0, 0.0));
        float c = hash21(i + float2(0.0, 1.0));
        float d = hash21(i + float2(1.0, 1.0));

        float2 u = f * f * (3.0 - 2.0 * f);
        return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
    }

    float fbm(float2 p) {
        float v = 0.0;
        float a = 0.5;

        v += noise2d(p) * a; p *= 2.02; a *= 0.5;
        v += noise2d(p) * a; p *= 2.03; a *= 0.5;
        v += noise2d(p) * a; p *= 2.01; a *= 0.5;
        v += noise2d(p) * a;

        return v;
    }

    float blob(float2 p, float2 c, float r) {
        return exp(-length(p - c) * r);
    }

    float3 hsv2rgb(float3 c) {
        float3 rgb = clamp(abs(fract(c.x + float3(0.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
        rgb = rgb * rgb * (3.0 - 2.0 * rgb);
        return c.z * mix(float3(1.0), rgb, c.y);
    }

    fragment float4 generatedFragment(RasterizerData in [[stage_in]],
                                      constant PreviewUniforms& uniforms [[buffer(0)]],
                                      constant float* floatUniforms [[buffer(1)]],
                                      constant float4* colorUniforms [[buffer(2)]],
                                      constant float2* pointUniforms [[buffer(3)]],
                                      constant uint* boolUniforms [[buffer(4)]]) {
        float Speed     = floatUniforms[0];
        float Scale     = floatUniforms[1];
        float Glow      = floatUniforms[2];
        float Amplitude = floatUniforms[3];
        float HueShift  = floatUniforms[4];

        float2 uv = in.uv * 2.0 - 1.0;
        uv.x *= uniforms.resolution.x / max(uniforms.resolution.y, 1.0);

        float speed = mix(0.05, 1.35, clamp(Speed, 0.0, 1.0));
        float scale = mix(0.65, 2.1, clamp(Scale, 0.0, 1.0));
        float glowAmt = mix(0.3, 2.4, clamp(Glow, 0.0, 1.0));
        float amp = clamp(Amplitude, 0.0, 1.0);
        float hue = fract(HueShift);

        float t = uniforms.time * speed;
        float2 p = uv * scale;

        float motionBoost = 1.0 + amp * 0.7;
        float radiusBoost = 1.0 - amp * 0.18;

        float2 c1 = float2(sin(t * 0.90) * 0.72, cos(t * 1.15) * 0.52);
        float2 c2 = float2(cos(t * 0.72 + 1.7) * 0.68, sin(t * 0.98 + 0.8) * 0.58);
        float2 c3 = float2(sin(t * 1.08 + 2.4) * 0.62, cos(t * 0.82 + 1.9) * 0.70);
        float2 c4 = float2(cos(t * 0.63 + 3.2) * 0.66, sin(t * 1.24 + 2.8) * 0.50);
        float2 c5 = float2(sin(t * 1.34 + 4.1) * 0.50, cos(t * 0.74 + 5.0) * 0.64);
        float2 c6 = float2(cos(t * 0.84 + 0.4) * 0.56, sin(t * 1.42 + 1.3) * 0.66);

        c1 *= motionBoost;
        c2 *= motionBoost;
        c3 *= motionBoost;
        c4 *= motionBoost;
        c5 *= motionBoost;
        c6 *= motionBoost;

        float field = 0.0;
        field += blob(p, c1, 3.10 * radiusBoost);
        field += blob(p, c2, 2.95 * radiusBoost);
        field += blob(p, c3, 3.25 * radiusBoost);
        field += blob(p, c4, 2.85 * radiusBoost);
        field += blob(p, c5, 3.00 * radiusBoost);
        field += blob(p, c6, 3.20 * radiusBoost);

        float warp1 = fbm(p * 1.5 + float2(t * 0.18, -t * 0.14));
        float warp2 = fbm(p * 2.6 + float2(-t * 0.12, t * 0.18));
        float shimmer = fbm(p * 4.8 - float2(t * 0.12, t * 0.09));

        field += (warp1 - 0.5) * 0.22;
        field += (warp2 - 0.5) * 0.08 * (0.6 + amp * 0.5);

        float shape = smoothstep(0.72 - amp * 0.04, 1.46 - amp * 0.03, field);
        float inner = smoothstep(1.08, 1.95, field);

        float edgeOuter = smoothstep(0.88, 1.06, field);
        float edgeInner = smoothstep(1.06, 1.24, field);
        float edge = clamp(edgeOuter - edgeInner, 0.0, 1.0);

        float pulse = 0.9 + 0.1 * sin(t * 4.2 + field * 2.5 + amp * 3.0);

        float3 bg   = hsv2rgb(float3(fract(hue + 0.78), 0.70, 0.08));
        float3 body = hsv2rgb(float3(fract(hue + 0.00), 0.82, 0.88));
        float3 mid  = hsv2rgb(float3(fract(hue + 0.08), 0.68, 1.00));
        float3 hot  = hsv2rgb(float3(fract(hue + 0.14), 0.35, 1.00));

        float3 color = mix(bg, body, shape);
        color = mix(color, mid, inner * 0.72);
        color = mix(color, hot, clamp(inner * (0.38 + amp * 0.20) + shimmer * 0.16, 0.0, 1.0));
        color += edge * glowAmt * (0.75 + amp * 0.45) * hsv2rgb(float3(fract(hue + 0.10), 0.50, 0.45));
        color *= pulse;

        return float4(color, 1.0);
    }
    """

    private static let organicMotionPresetMetalSource = """
    #include <metal_stdlib>
    using namespace metal;

    struct Uniforms {
        float TimeScale;
        float2 Mouse;
    };

    float noise2(float2 p, float t) {
        float2 i = floor(p);
        float2 f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        float a = sin(i.x + i.y * 31.23 + t);
        float b = sin(i.x + 1.0 + i.y * 31.23 + t);
        float c = sin(i.x + (i.y + 1.0) * 31.23 + t);
        float d = sin(i.x + 1.0 + (i.y + 1.0) * 31.23 + t);
        return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
    }

    float fbm(float2 p, float t) {
        float sum = 0.0;
        float amp = 1.0;
        float freq = 1.0;
        for (int i = 0; i < 6; i++) {
            sum += noise2(p * freq, t) * amp;
            amp *= 0.5;
            freq *= 2.0;
            p += float2(3.123, 1.732);
        }
        return sum;
    }

    fragment float4 generatedFragment(RasterizerData in [[stage_in]],
                                      constant PreviewUniforms& uniforms [[buffer(0)]],
                                      constant float* floatUniforms [[buffer(1)]],
                                      constant float4* colorUniforms [[buffer(2)]],
                                      constant float2* pointUniforms [[buffer(3)]],
                                      constant uint* boolUniforms [[buffer(4)]]) {
        float TimeScale = floatUniforms[0];
        float2 Mouse = pointUniforms[0];
        float TIME = uniforms.time;
        float2 RENDERSIZE = uniforms.resolution;

        float2 uv = in.uv;
        float2 aspect = float2(RENDERSIZE.x / max(RENDERSIZE.y, 1.0), 1.0);
        uv = uv * 2.0 - 1.0;
        uv *= aspect;

        float2 mouseInfluence = (Mouse * 2.0 - 1.0) * aspect;
        float mouseDist = length(uv - mouseInfluence);
        float mouseEffect = smoothstep(0.5, 0.0, mouseDist);

        float t = TIME * 0.2 * TimeScale;
        float2 movement = float2(sin(t * 0.5), cos(t * 0.7));

        float n1 = fbm(uv * 3.0 + movement + mouseEffect, TIME * TimeScale);
        float n2 = fbm(uv * 2.0 - movement - mouseEffect, TIME * TimeScale);
        float n3 = fbm(uv * 4.0 + float2(n1, n2), TIME * TimeScale);

        float3 col1 = float3(0.2, 0.5, 0.8);
        float3 col2 = float3(0.8, 0.2, 0.5);
        float3 col3 = float3(0.1, 0.8, 0.4);

        float3 finalColor = mix(col1, col2, n1 * 0.5 + 0.5);
        finalColor = mix(finalColor, col3, (n2 * 0.5 + 0.5) * 0.5);
        finalColor += n3 * 0.2;
        finalColor += float3(mouseEffect * 0.2);

        return float4(clamp(finalColor, 0.0, 1.0), 1.0);
    }
    """

    private static let colorDiffusionFlowPresetMetalSource = """
    // Imported ISF shader: from http://glslsandbox.com/e#35553.0
    // ISF metadata converted into graph uniforms and a Metal fragment scaffold.
    // Generated from ISF body using heuristic GLSL -> Metal rewrites.

    ///////////////////////////////////////////
    // ColorDiffusionFlow  by mojovideotech
    //
    // based on :
    // glslsandbox.com/\\e#35553.0
    //
    // Creative Commons Attribution-NonCommercial-ShareAlike 3.0
    ///////////////////////////////////////////

    #include <metal_stdlib>
    using namespace metal;

    struct Uniforms {
        float rate1;
        float rate2;
        float loopcycle;
        float color1;
        float color2;
        float cycle1;
        float cycle2;
        float nudge;
        float depthX;
        float depthY;
    };

    #define pi 3.141592653589793

    fragment float4 generatedFragment(RasterizerData in [[stage_in]],
                                      constant PreviewUniforms& uniforms [[buffer(0)]],
                                      constant float* floatUniforms [[buffer(1)]],
                                      constant float4* colorUniforms [[buffer(2)]],
                                      constant float2* pointUniforms [[buffer(3)]],
                                      constant uint* boolUniforms [[buffer(4)]]) {
        float2 isf_FragNormCoord = in.uv;
        float rate1 = floatUniforms[0];
        float rate2 = floatUniforms[1];
        float loopcycle = floatUniforms[2];
        float color1 = floatUniforms[3];
        float color2 = floatUniforms[4];
        float cycle1 = floatUniforms[5];
        float cycle2 = floatUniforms[6];
        float nudge = floatUniforms[7];
        float depthX = floatUniforms[8];
        float depthY = floatUniforms[9];
        float TIME = uniforms.time;
        float4 DATE = uniforms.date;

        float T = TIME * rate1;
        float TT = TIME * rate2;
        float2 p = 2.0 * isf_FragNormCoord;
        for (int i = 1; i < 11; i++) {
            float2 newp = p;
            float ii = float(i);
            newp.x += depthX / ii * sin(ii * pi * p.y + T * nudge + cos((TT / (5.0 * ii)) * ii));
            newp.y += depthY / ii * cos(ii * pi * p.x + TT + nudge + sin((T / (5.0 * ii)) * ii));
            p = newp + log(DATE.w) / loopcycle;
        }
        float3 col = float3(
            cos(p.x + p.y + 3.0 * color1) * 0.5 + 0.5,
            sin(p.x + p.y + 6.0 * cycle1) * 0.5 + 0.5,
            (sin(p.x + p.y + 9.0 * color2) + cos(p.x + p.y + 12.0 * cycle2)) * 0.25 + 0.5
        );
        return float4(col * col, 1.0);
    }
    """

    private static let liquidChromePresetMetalSource = """
    #include <metal_stdlib>
    using namespace metal;

    struct Uniforms {
        float FlowSpeed;
        float Zoom;
        float Warp;
        float Ripple;
        float HueShift;
        float Highlight;
        float AudioAmp;
        float Contrast;
    };

    float hash21(float2 p) {
        p = fract(p * float2(234.34, 435.345));
        p += dot(p, p + 34.23);
        return fract(p.x * p.y);
    }

    float noise2(float2 p) {
        float2 i = floor(p);
        float2 f = fract(p);
        float a = hash21(i);
        float b = hash21(i + float2(1.0, 0.0));
        float c = hash21(i + float2(0.0, 1.0));
        float d = hash21(i + float2(1.0, 1.0));
        float2 u = f * f * (3.0 - 2.0 * f);
        return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
    }

    float fbm(float2 p) {
        float value = 0.0;
        float amp = 0.5;
        for (int i = 0; i < 6; ++i) {
            value += amp * noise2(p);
            p = p * 2.02 + float2(1.7, -1.3);
            amp *= 0.52;
        }
        return value;
    }

    float2 flowField(float2 p, float t, float warp) {
        float2 q = float2(
            fbm(p * 1.4 + float2(0.0, t * 0.18)),
            fbm(p * 1.4 + float2(5.2, -t * 0.15))
        );
        float2 r = float2(
            fbm(p * 2.3 + q * 1.5 + float2(1.7, t * 0.11)),
            fbm(p * 2.3 + q.yx * 1.6 + float2(-3.4, -t * 0.09))
        );
        return p + (q - 0.5) * warp * 1.8 + (r - 0.5) * warp;
    }

    float sceneField(float2 p, float t, float warp, float ripple) {
        float2 w = flowField(p, t, warp);
        float base = fbm(w * 2.1);
        float rings = sin(length(w) * 14.0 - t * 2.4 + base * 6.0) * 0.5 + 0.5;
        float ridges = 1.0 - abs(sin(w.x * 3.2 + base * 4.0) * cos(w.y * 3.8 - t * 0.7));
        return mix(base, rings * ridges, ripple);
    }

    float3 chromeColor(float light, float hueShift, float highlight, float contrast, float amp) {
        float chrome = pow(clamp(light, 0.0, 1.0), max(0.2, contrast));
        float3 steel = mix(float3(0.03, 0.035, 0.04), float3(0.72, 0.76, 0.82), chrome);
        float tintPhase = hueShift + chrome * 0.12 + amp * 0.08;
        float3 tint = 0.08 + 0.92 * float3(
            0.5 + 0.5 * sin(6.28318 * (tintPhase + 0.00)),
            0.5 + 0.5 * sin(6.28318 * (tintPhase + 0.33)),
            0.5 + 0.5 * sin(6.28318 * (tintPhase + 0.66))
        );
        float spec = pow(clamp(light, 0.0, 1.0), 18.0) * highlight;
        return steel + tint * spec * 0.35 + float3(spec);
    }

    fragment float4 generatedFragment(RasterizerData in [[stage_in]],
                                      constant PreviewUniforms& uniforms [[buffer(0)]],
                                      constant float* floatUniforms [[buffer(1)]],
                                      constant float4* colorUniforms [[buffer(2)]],
                                      constant float2* pointUniforms [[buffer(3)]],
                                      constant uint* boolUniforms [[buffer(4)]]) {
        float FlowSpeed = floatUniforms[0];
        float Zoom = floatUniforms[1];
        float Warp = floatUniforms[2];
        float Ripple = floatUniforms[3];
        float HueShift = floatUniforms[4];
        float Highlight = floatUniforms[5];
        float AudioAmp = floatUniforms[6];
        float Contrast = floatUniforms[7];

        float TIME = uniforms.time;
        float2 RENDERSIZE = uniforms.resolution;

        float2 uv = in.uv * 2.0 - 1.0;
        uv.x *= RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
        uv *= max(Zoom, 0.001);

        float amp = AudioAmp;
        float t = TIME * FlowSpeed * (0.65 + amp * 1.8);
        float field = sceneField(uv, t, Warp * (0.7 + amp), Ripple);

        float eps = 0.0035;
        float fx = sceneField(uv + float2(eps, 0.0), t, Warp * (0.7 + amp), Ripple) - sceneField(uv - float2(eps, 0.0), t, Warp * (0.7 + amp), Ripple);
        float fy = sceneField(uv + float2(0.0, eps), t, Warp * (0.7 + amp), Ripple) - sceneField(uv - float2(0.0, eps), t, Warp * (0.7 + amp), Ripple);

        float3 normal = normalize(float3(-fx, -fy, 0.22 + 0.15 * sin(t + field * 8.0)));
        float3 lightDir = normalize(float3(-0.45, 0.55, 0.7));
        float3 viewDir = normalize(float3(0.0, 0.0, 1.0));
        float3 halfVec = normalize(lightDir + viewDir);

        float diffuse = clamp(dot(normal, lightDir), 0.0, 1.0);
        float specular = pow(clamp(dot(normal, halfVec), 0.0, 1.0), 36.0) * Highlight * (1.0 + amp * 1.4);
        float fresnel = pow(1.0 - clamp(dot(normal, viewDir), 0.0, 1.0), 3.0);
        float liquid = clamp(field * 1.2 + diffuse * 0.55 + fresnel * 0.45, 0.0, 1.0);

        float3 color = chromeColor(liquid + specular, HueShift, Highlight, Contrast, amp);
        color += float3(0.9, 0.95, 1.0) * fresnel * 0.22;
        color += specular;

        float vignette = smoothstep(1.65, 0.2, length(uv));
        color *= vignette;

        return float4(clamp(color, 0.0, 1.0), 1.0);
    }
    """

    private static let nebulaPresetMetalSource = """
    #include <metal_stdlib>
    using namespace metal;

    struct Uniforms {
        float DriftSpeed;
        float Zoom;
        float HueShift;
        float Density;
        float StarGlow;
        float ShadowDepth;
        float AudioAmp;
        float Contrast;
    };

    float hash21(float2 p) {
        p = fract(p * float2(123.45, 456.78));
        p += dot(p, p + 19.19);
        return fract(p.x * p.y);
    }

    float noise2(float2 p) {
        float2 i = floor(p);
        float2 f = fract(p);

        float a = hash21(i);
        float b = hash21(i + float2(1.0, 0.0));
        float c = hash21(i + float2(0.0, 1.0));
        float d = hash21(i + float2(1.0, 1.0));

        float2 u = f * f * (3.0 - 2.0 * f);
        return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
    }

    float fbm(float2 p) {
        float value = 0.0;
        float amplitude = 0.5;

        for (int i = 0; i < 6; ++i) {
            value += amplitude * noise2(p);
            p = p * 2.04 + float2(1.23, -0.87);
            amplitude *= 0.53;
        }

        return value;
    }

    float ridge(float x) {
        return 1.0 - abs(x * 2.0 - 1.0);
    }

    float3 hsv2rgb(float3 c) {
        float3 rgb = clamp(abs(fract(c.x + float3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
        rgb = rgb * rgb * (3.0 - 2.0 * rgb);
        return c.z * mix(float3(1.0), rgb, c.y);
    }

    fragment float4 generatedFragment(RasterizerData in [[stage_in]],
                                      constant PreviewUniforms& uniforms [[buffer(0)]],
                                      constant float* floatUniforms [[buffer(1)]],
                                      constant float4* colorUniforms [[buffer(2)]],
                                      constant float2* pointUniforms [[buffer(3)]],
                                      constant uint* boolUniforms [[buffer(4)]]) {
        float DriftSpeed = floatUniforms[0];
        float Zoom = floatUniforms[1];
        float HueShift = floatUniforms[2];
        float Density = floatUniforms[3];
        float StarGlow = floatUniforms[4];
        float ShadowDepth = floatUniforms[5];
        float AudioAmp = floatUniforms[6];
        float Contrast = floatUniforms[7];

        float TIME = uniforms.time;
        float2 RENDERSIZE = uniforms.resolution;

        float2 uv = in.uv * 2.0 - 1.0;
        uv.x *= RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
        uv *= max(Zoom, 0.001);

        float t = TIME * DriftSpeed;
        float amp = AudioAmp;

        float2 drift = float2(cos(t * 0.11), sin(t * 0.09)) * (0.25 + amp * 0.18);
        float2 q = uv + drift;

        float baseA = fbm(q * 1.2 + float2(0.0, t * 0.08));
        float baseB = fbm(q * 2.0 - float2(t * 0.04, 1.7));
        float veil = fbm(q * 3.4 + float2(2.3, -t * 0.05));
        float tendrils = ridge(fbm(q * 2.8 + float2(-1.5, t * 0.06)));
        float dust = fbm(q * 6.0 + veil + baseA);

        float nebula = mix(baseA, baseB, 0.45) + tendrils * Density * 0.8;
        nebula += veil * 0.45 + amp * 0.35;
        nebula = smoothstep(0.22 - Density * 0.08, 1.15, nebula);

        float shadowMask = smoothstep(0.18, 0.82, fbm(q * 1.7 - float2(1.1, -0.8)));
        shadowMask = pow(shadowMask, mix(2.8, 1.2, ShadowDepth));
        nebula *= mix(1.0, shadowMask, ShadowDepth);

        float core = exp(-length(uv - float2(0.0, 0.1 + 0.12 * sin(t * 0.3))) * (2.8 - amp * 0.8));
        float starField = step(0.9945 - StarGlow * 0.0025, hash21(floor((uv + 1.0) * RENDERSIZE * 0.35)));
        float starTwinkle = 0.55 + 0.45 * sin(t * 2.0 + dust * 12.0);
        float stars = starField * starTwinkle * (0.35 + StarGlow * 1.4);

        float hue = fract(0.62 + HueShift + nebula * 0.18 + tendrils * 0.09 + amp * 0.12);
        float sat = clamp(0.55 + nebula * 0.35 + amp * 0.18, 0.0, 1.0);
        float val = pow(max(nebula + core * 0.85, 0.0), max(0.25, Contrast));

        float3 color = hsv2rgb(float3(hue, sat, val));
        color += float3(0.92, 0.66, 0.42) * core * (0.45 + amp * 0.7);
        color += float3(1.0) * stars;
        color += dust * 0.06;
        color = clamp(color, 0.0, 1.0);

        return float4(color, 1.0);
    }
    """

    private static let liquidFluxPresetMetalSource = """
    #include <metal_stdlib>
