                                      constant float2* pointUniforms [[buffer(3)]],
                                      constant uint* boolUniforms [[buffer(4)]]) {
        float FlowSpeed = floatUniforms[0];
        float Zoom = floatUniforms[1];
        float HueShift = floatUniforms[2];
        float Collision = floatUniforms[3];
        float Swirl = floatUniforms[4];
        float Pulse = floatUniforms[5];
        float AudioAmp = floatUniforms[6];
        float Contrast = floatUniforms[7];

        float TIME = uniforms.time;
        float2 RENDERSIZE = uniforms.resolution;

        float speed = mix(0.08, 1.85, clamp(FlowSpeed, 0.0, 1.0));
        float zoom = mix(0.65, 2.6, clamp(Zoom, 0.0, 1.0));
        float collision = mix(0.15, 2.2, clamp(Collision, 0.0, 1.0));
        float swirl = mix(0.1, 2.8, clamp(Swirl, 0.0, 1.0));
        float pulse = mix(0.2, 2.2, clamp(Pulse, 0.0, 1.0));
        float contrast = mix(0.55, 2.2, clamp(Contrast, 0.0, 1.0));
        float amp = clamp(AudioAmp, 0.0, 1.0);

        float2 uv = in.uv * 2.0 - 1.0;
        uv.x *= RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
        uv *= zoom;

        float t = TIME * speed;
        float2 q = rotate2D(uv, 0.17 * t + amp * 0.5);

        float2 flowA = float2(
            fbm(q * 1.35 + float2(0.0, 0.21 * t)),
            fbm(q * 1.35 + float2(4.6, -0.18 * t))
        );
        float2 flowB = float2(
            fbm(q * 2.1 + flowA * 1.6 + float2(1.7, 0.16 * t)),
            fbm(q * 2.1 - flowA.yx * 1.4 + float2(-2.9, -0.12 * t))
        );

        float2 liquid = q + (flowA - 0.5) * swirl + (flowB - 0.5) * (1.1 + amp * 1.2);
        float fieldA = fbm(liquid * (2.0 + collision * 0.45) + float2(0.14 * t, -0.11 * t));
        float fieldB = fbm(rotate2D(liquid, 1.15) * (2.4 + collision * 0.65) - float2(0.09 * t, 0.13 * t));
        float fieldC = fbm((liquid + float2(fieldA, fieldB)) * 2.8);

        float collide = smoothstep(0.18, 0.92, abs(fieldA - fieldB) * (1.2 + collision * 1.8));
        float rivers = smoothstep(0.32, 0.88, fieldC + fieldA * 0.35);
        float bloom = exp(-3.2 * length(liquid)) * (0.4 + amp * 1.8);
        float ripple = 0.5 + 0.5 * sin((fieldA - fieldB) * 8.0 + t * (1.3 + pulse) + amp * 6.0);

        float brightness = max(0.0, mix(rivers, collide, 0.55) + ripple * pulse * 0.38 + bloom);
        brightness = pow(brightness, contrast);

        float hueA = fract(0.52 + HueShift + fieldA * 0.24 + amp * 0.12);
        float hueB = fract(0.86 + HueShift + fieldB * 0.19 + collide * 0.08);
        float hue = mix(hueA, hueB, collide);
        float sat = clamp(0.68 + collide * 0.25 + amp * 0.18, 0.0, 1.0);

        float3 base = hsv2rgb(float3(hue, sat, brightness));
        float3 accent = hsv2rgb(float3(fract(hue + 0.14 + amp * 0.06), 0.92, brightness * (0.55 + collide * 0.8)));
        float3 color = mix(base, accent, collide * (0.45 + amp * 0.35));

        float spark = pow(max(0.0, 1.0 - abs(fieldA - fieldB) * 2.2), 6.0) * (0.3 + amp * 1.2);
        color += float3(1.0, 0.85, 0.55) * spark;
        color = clamp(color, 0.0, 1.0);

    return float4(color, 1.0);
    }
    """

    private static let prismRingsPresetMetalSource = """
    #include <metal_stdlib>
    using namespace metal;

    struct Uniforms {
        float Speed;
        float HueShift;
        float Bands;
    };

    float3 hsv2rgb(float3 c) {
        float3 rgb = clamp(abs(fract(c.x + float3(0.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
        rgb = rgb * rgb * (3.0 - 2.0 * rgb);
