    fragment float4 generatedFragment(RasterizerData in [[stage_in]],
                                      constant PreviewUniforms& uniforms [[buffer(0)]],
                                      constant float* floatUniforms [[buffer(1)]],
                                      constant float4* colorUniforms [[buffer(2)]],
                                      constant float2* pointUniforms [[buffer(3)]],
                                      constant uint* boolUniforms [[buffer(4)]]) {
        float Rotation = floatUniforms[0];
        float HueShift = floatUniforms[1];
        float Bass = floatUniforms[2];
        float Mid = floatUniforms[3];
        float Treble = floatUniforms[4];
        float Amplitude = floatUniforms[5];
        float RingRadius = floatUniforms[6];
        float RingHeight = floatUniforms[7];
        float DeckGlow = floatUniforms[8];

        float2 uv = in.uv * 2.0 - 1.0;
        uv.x *= uniforms.resolution.x / max(uniforms.resolution.y, 1.0);

        float r = length(uv);
        float angle = atan2(uv.y, uv.x);
        float tau = 6.28318530718;
        float normalizedAngle = fract((angle / tau) + 0.5 + Rotation);

        float bassPattern = 0.5 + 0.5 * sin(normalizedAngle * tau * 8.0 + uniforms.time * 0.8);
        float midPattern = 0.5 + 0.5 * sin(normalizedAngle * tau * 16.0 - uniforms.time * 1.1);
        float treblePattern = 0.5 + 0.5 * sin(normalizedAngle * tau * 32.0 + uniforms.time * 1.7);

        float spectrum = bassPattern * Bass + midPattern * Mid + treblePattern * Treble;
        float ringRadius = mix(0.38, 0.82, clamp(RingRadius, 0.0, 1.0));
        float ringHeight = mix(0.02, 0.28, clamp(RingHeight, 0.0, 1.0));
        float targetRadius = ringRadius + spectrum * ringHeight;

        float outerLine = smoothstep(targetRadius + 0.012, targetRadius + 0.001, r);
        float innerCut = smoothstep(targetRadius - 0.025, targetRadius - 0.002, r);
        float spectrumRing = max(outerLine - innerCut, 0.0);

        float platter = smoothstep(0.78, 0.76, r);
        float label = smoothstep(0.18, 0.17, r);
        float spindle = smoothstep(0.03, 0.02, r);

        float grooves = 0.5 + 0.5 * sin((r - Rotation * 0.25) * 220.0);
        grooves *= smoothstep(0.22, 0.26, r) * (1.0 - smoothstep(0.70, 0.78, r));

        float highlight = pow(max(0.0, dot(normalize(float2(-0.6, 0.8)), normalize(uv + 0.0001))), 24.0);
        float glow = exp(-4.5 * r) * (0.15 + DeckGlow * 0.75 + Amplitude * 0.6);

        float3 baseDeck = mix(float3(0.03, 0.03, 0.04), float3(0.16, 0.16, 0.18), platter);
        baseDeck += grooves * 0.08;
        baseDeck += highlight * 0.22;

        float hue = fract(HueShift + normalizedAngle * 0.35 + uniforms.time * 0.02 + Amplitude * 0.08);
        float3 spectrumColor = hsv2rgb(float3(hue, 0.85, 0.8 + Amplitude * 0.4));
        spectrumColor += float3(0.18, 0.1, 0.04) * Bass;

        float3 labelColor = hsv2rgb(float3(fract(HueShift + 0.6 + uniforms.time * 0.01), 0.6, 0.95));
        float3 color = baseDeck;
        color = mix(color, spectrumColor, spectrumRing);
        color = mix(color, labelColor, label);
        color = mix(color, float3(0.92), spindle);
        color += glow * spectrumColor;

        float platterAlpha = smoothstep(0.84, 0.76, r);
        float glowAlpha = clamp(glow * 1.25, 0.0, 1.0);
        float alpha = max(platterAlpha, max(spectrumRing, glowAlpha));
        color *= alpha;

        return float4(clamp(color, 0.0, 1.0), clamp(alpha, 0.0, 1.0));
    }
    """

    private static let hologramScanPresetMetalSource = """
    #include <metal_stdlib>
    using namespace metal;

    struct Uniforms {
        float Speed;
        float Density;
        float Flicker;
    };

    float hash21(float2 p) {
        p = fract(p * float2(234.34, 435.345));
        p += dot(p, p + 34.23);
        return fract(p.x * p.y);
    }

    float noise2d(float2 p) {
        float2 i = floor(p);
        float2 f = fract(p);

        float a = hash21(i);
        float b = hash21(i + float2(1.0, 0.0));
        float c = hash21(i + float2(0.0, 1.0));
        float d = hash21(i + float2(1.0, 1.0));

        float2 u = f * f * (3.0 - 2.0 * f);
        return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
    }

    fragment float4 generatedFragment(RasterizerData in [[stage_in]],
                                      constant PreviewUniforms& uniforms [[buffer(0)]],
                                      constant float* floatUniforms [[buffer(1)]],
                                      constant float4* colorUniforms [[buffer(2)]],
                                      constant float2* pointUniforms [[buffer(3)]],
                                      constant uint* boolUniforms [[buffer(4)]]) {
        float Speed   = floatUniforms[0];
        float Density = floatUniforms[1];
        float Flicker = floatUniforms[2];

        float2 uv = in.uv;
        float2 p = uv * 2.0 - 1.0;
        p.x *= uniforms.resolution.x / max(uniforms.resolution.y, 1.0);

        float speed = mix(0.2, 3.0, clamp(Speed, 0.0, 1.0));
        float density = mix(40.0, 240.0, clamp(Density, 0.0, 1.0));
        float flickerAmt = mix(0.0, 1.0, clamp(Flicker, 0.0, 1.0));
        float t = uniforms.time * speed;

        float scanlines = 0.5 + 0.5 * sin(uv.y * density + t * 8.0);
        scanlines = pow(scanlines, 2.5);

        float band = sin(uv.y * 18.0 - t * 3.5);
        band = smoothstep(0.65, 1.0, band);

        float vertical = 0.5 + 0.5 * sin(uv.x * 22.0 + t * 2.4);
        vertical = pow(vertical, 6.0) * 0.25;

        float gridX = abs(fract(uv.x * 12.0) - 0.5);
        float gridY = abs(fract(uv.y * 18.0) - 0.5);
        float grid = 1.0 - smoothstep(0.46, 0.5, min(gridX, gridY));
        grid *= 0.18;

        float glitchNoise = noise2d(float2(floor(uv.y * 90.0), floor(t * 8.0)));
        float glitchMask = step(0.82, glitchNoise) * flickerAmt;
        float glitchShift = (noise2d(float2(floor(uv.y * 40.0), floor(t * 14.0))) - 0.5) * 0.08 * glitchMask;

        float shiftedLines = 0.5 + 0.5 * sin((uv.y + glitchShift) * density + t * 8.0);
        shiftedLines = pow(shiftedLines, 2.5);

        float flicker = 1.0 - flickerAmt * 0.22 + flickerAmt * 0.22 * sin(t * 17.0 + uv.y * 35.0);
        float pulse = 0.5 + 0.5 * sin(t * 1.8);

        float edge = 1.0 - length(p) * 0.7;
        edge = clamp(edge, 0.0, 1.0);

        float signal = shiftedLines * 0.55 + band * 0.55 + vertical + grid;
        signal *= flicker;
        signal += glitchMask * 0.25;
        signal *= 0.65 + 0.35 * pulse;
        signal *= edge;
        signal = clamp(signal, 0.0, 1.0);

        float3 baseColor = float3(0.02, 0.08, 0.10);
        float3 holoColor = float3(0.10, 0.95, 0.85);
        float3 hotColor = float3(0.65, 1.0, 0.98);

        float3 color = mix(baseColor, holoColor, signal);
        color = mix(color, hotColor, pow(signal, 3.0));
        color += glitchMask * float3(0.08, 0.18, 0.18);

        return float4(color, 1.0);
    }
    """

