        float Mix = floatUniforms[3];
        float4 Tint = colorUniforms[0];
        bool UseGlitch = boolUniforms[0] != 0;

        float2 uv = in.uv;
        float2 p = uv * 2.0 - 1.0;
        p.x *= uniforms.resolution.x / max(uniforms.resolution.y, 1.0);

        float speed = mix(0.2, 3.0, clamp(Speed, 0.0, 1.0));
        float density = mix(40.0, 240.0, clamp(Density, 0.0, 1.0));
        float flickerAmt = mix(0.0, 1.0, clamp(Flicker, 0.0, 1.0));
        float imageMix = clamp(Mix, 0.0, 1.0);

        float t = uniforms.time * speed;

        float4 src = texture.sample(textureSampler, uv);

        float scanlines = 0.5 + 0.5 * sin(uv.y * density + t * 8.0);
        scanlines = pow(scanlines, 2.5);

        float sweep = sin(uv.y * 18.0 - t * 3.5);
        sweep = smoothstep(0.65, 1.0, sweep);

        float vertical = 0.5 + 0.5 * sin(uv.x * 22.0 + t * 2.4);
        vertical = pow(vertical, 6.0) * 0.22;

        float gridX = abs(fract(uv.x * 12.0) - 0.5);
        float gridY = abs(fract(uv.y * 18.0) - 0.5);
        float grid = 1.0 - smoothstep(0.46, 0.5, min(gridX, gridY));
        grid *= 0.16;

        float glitchMask = 0.0;
        float glitchShift = 0.0;
        if (UseGlitch) {
            float g1 = noise2d(float2(floor(uv.y * 90.0), floor(t * 8.0)));
            glitchMask = step(0.82, g1) * flickerAmt;
            float g2 = noise2d(float2(floor(uv.y * 40.0), floor(t * 14.0)));
            glitchShift = (g2 - 0.5) * 0.08 * glitchMask;
        }

        float2 shiftedUV = uv;
        shiftedUV.x += glitchShift;

        float4 shiftedSrc = texture.sample(textureSampler, clamp(shiftedUV, 0.0, 1.0));

        float shiftedLines = 0.5 + 0.5 * sin((uv.y + glitchShift) * density + t * 8.0);
        shiftedLines = pow(shiftedLines, 2.5);

        float flick = 1.0 - flickerAmt * 0.22 + flickerAmt * 0.22 * sin(t * 17.0 + uv.y * 35.0);
        float pulse = 0.5 + 0.5 * sin(t * 1.8);

        float edge = 1.0 - length(p) * 0.7;
        edge = clamp(edge, 0.0, 1.0);

        float hologramField = 0.0;
        hologramField += shiftedLines * 0.55;
        hologramField += sweep * 0.55;
        hologramField += vertical;
        hologramField += grid;
        hologramField *= flick;
        hologramField += glitchMask * 0.22;
        hologramField *= 0.65 + 0.35 * pulse;
        hologramField *= edge;
        hologramField = clamp(hologramField, 0.0, 1.0);

