    private static let badTVGlitchPresetMetalSource = """
    /*
    {
      "DESCRIPTION": "Glitch displacement video effect",
      "INPUTS": [
        { "NAME": "Speed", "TYPE": "float", "DEFAULT": 0.45, "MIN": 0.0, "MAX": 1.0 },
        { "NAME": "Amount", "TYPE": "float", "DEFAULT": 0.55, "MIN": 0.0, "MAX": 1.0 },
