        float4 Tint = colorUniforms[0];
        bool UseBlocks = boolUniforms[0] != 0;

        float2 uv = in.uv;

        float speed = mix(0.1, 3.0, clamp(Speed, 0.0, 1.0));
        float amount = mix(0.0, 0.12, clamp(Amount, 0.0, 1.0));
        float rgbSplit = mix(0.0, 0.03, clamp(RGBSplit, 0.0, 1.0));
        float imageMix = clamp(Mix, 0.0, 1.0);

        float t = uniforms.time * speed;

        float4 src = texture.sample(textureSampler, uv);

        float stripCell = floor(uv.y * mix(20.0, 120.0, clamp(Amount, 0.0, 1.0)));
        float stripNoise = noise2d(float2(stripCell, floor(t * 8.0)));
        float stripMask = smoothstep(0.72, 1.0, stripNoise);

        float stripShift = (noise2d(float2(stripCell + 17.3, floor(t * 11.0))) - 0.5);
        stripShift *= amount * (0.5 + 0.5 * stripMask);

        float jitter = (noise2d(float2(floor(uv.y * 220.0), floor(t * 18.0))) - 0.5) * amount * 0.18;

        float xShift = stripShift + jitter;

        float blockMask = 0.0;
        float blockNoise = 0.0;
        if (UseBlocks) {
            float2 blockCoord = floor(uv * float2(24.0, 18.0) + float2(floor(t * 3.0), floor(t * 2.0)));
            blockNoise = noise2d(blockCoord);
            blockMask = step(0.86, blockNoise) * clamp(Amount * 1.4, 0.0, 1.0);
        }

        float blockShift = (blockNoise - 0.5) * amount * 0.35;
        xShift += blockMask * blockShift;

        float2 uvR = clamp(float2(uv.x + xShift + rgbSplit, uv.y), 0.0, 1.0);
        float2 uvG = clamp(float2(uv.x + xShift, uv.y), 0.0, 1.0);
        float2 uvB = clamp(float2(uv.x + xShift - rgbSplit, uv.y), 0.0, 1.0);

        float r = texture.sample(textureSampler, uvR).r;
        float g = texture.sample(textureSampler, uvG).g;
        float b = texture.sample(textureSampler, uvB).b;

        float3 glitchColor = float3(r, g, b);

        float flicker = 1.0 - Amount * 0.12 + 0.12 * Amount * sin(t * 19.0 + uv.y * 50.0);
        float scan = 0.96 + 0.04 * sin(uv.y * uniforms.resolution.y * 0.6 + t * 5.0);
        glitchColor *= flicker * scan;

