        curtain += exp(-abs(p.y - 0.25 * wave) * (6.0 + glow * 4.0));
        curtain += exp(-abs(p.y - 0.35 * wave2 - 0.18) * (5.0 + glow * 3.0)) * 0.7;
        curtain += exp(-abs(p.y - 0.20 * sin(p.x * 5.0 + t + drift2 * 2.0) + 0.32) * 10.0) * 0.35;

