    private static let digitalRainPresetMetalSource = """
    #include <metal_stdlib>
    using namespace metal;

    struct Uniforms {
        float Speed;
        float Density;
        float Glow;
        float HueShift;
    };

    float hash11(float p) {
        p = fract(p * 0.1031);
        p *= p + 33.33;
        p *= p + p;
        return fract(p);
    }

    float hash21(float2 p) {
        p = fract(p * float2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
    }

    float3 hsv2rgb(float3 c) {
        float3 rgb = clamp(abs(fract(c.x + float3(0.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
        rgb = rgb * rgb * (3.0 - 2.0 * rgb);
        return c.z * mix(float3(1.0), rgb, c.y);
    }

    float glyph(float2 p, float seed) {
        p = fract(p);

        float bars = 0.0;
        bars += step(0.15, p.y) * step(p.y, 0.22) * step(0.2, p.x) * step(p.x, 0.8);
        bars += step(0.42, p.y) * step(p.y, 0.5) * step(0.15, p.x) * step(p.x, 0.7);
        bars += step(0.72, p.y) * step(p.y, 0.8) * step(0.3, p.x) * step(p.x, 0.85);

        float verts = 0.0;
        verts += step(0.18, p.x) * step(p.x, 0.26) * step(0.1, p.y) * step(p.y, 0.9);
        verts += step(0.68, p.x) * step(p.x, 0.76) * step(0.15, p.y) * step(p.y, 0.85);

        float diag = step(0.0, sin((p.x + p.y + seed * 3.1) * 18.0)) * 0.6;
        diag *= step(0.2, p.x) * step(p.x, 0.8) * step(0.2, p.y) * step(p.y, 0.8);

        float mode = floor(seed * 4.0);
        float g = 0.0;

        if (mode < 1.0) {
            g = max(bars, verts);
        } else if (mode < 2.0) {
            g = max(bars * 0.8, diag);
        } else if (mode < 3.0) {
            g = max(verts, diag);
        } else {
            g = max(max(bars, verts), diag * 0.8);
        }

        return clamp(g, 0.0, 1.0);
    }

    fragment float4 generatedFragment(RasterizerData in [[stage_in]],
                                      constant PreviewUniforms& uniforms [[buffer(0)]],
                                      constant float* floatUniforms [[buffer(1)]],
                                      constant float4* colorUniforms [[buffer(2)]],
                                      constant float2* pointUniforms [[buffer(3)]],
                                      constant uint* boolUniforms [[buffer(4)]]) {
        float Speed = floatUniforms[0];
        float Density = floatUniforms[1];
        float Glow = floatUniforms[2];
        float HueShift = floatUniforms[3];

        float2 uv = in.uv;
        float aspect = uniforms.resolution.x / max(uniforms.resolution.y, 1.0);

        float speed = mix(0.2, 3.0, clamp(Speed, 0.0, 1.0));
        float density = mix(12.0, 48.0, clamp(Density, 0.0, 1.0));
        float glowAmt = mix(0.2, 2.0, clamp(Glow, 0.0, 1.0));

        float t = uniforms.time * speed;

        float2 grid = float2(density * aspect * 0.55, density);
        float2 gp = uv * grid;

        float2 cell = floor(gp);
        float2 local = fract(gp);

        float colSpeed = mix(0.6, 1.8, hash11(cell.x * 0.31 + 2.1));
        float colOffset = hash11(cell.x * 0.77 + 5.2) * 20.0;
        float streamLength = mix(4.0, 18.0, hash11(cell.x * 0.49 + 8.3));

        float dropHead = fract((-t * colSpeed + colOffset) / max(grid.y, 1.0)) * grid.y;
        float dy = cell.y - dropHead;
        if (dy < 0.0) dy += grid.y;

        float trail = exp(-dy / streamLength);
        float head = exp(-dy * 1.4);

        float charSeed = hash21(cell + floor(t * 8.0 + dy));
        float charShape = glyph(local, charSeed);

        float flicker = 0.75 + 0.25 * sin(t * 14.0 + cell.x * 1.7 + cell.y * 0.35);
        float activity = charShape * trail * flicker;

        float sparseMask = step(0.28, hash11(cell.x * 1.91 + floor((cell.y + t * 2.0) * 0.5)));
        activity *= sparseMask;

        float headGlow = charShape * head * (1.2 + glowAmt * 0.8);
        float signal = activity + headGlow;
        signal = clamp(signal, 0.0, 1.0);

        float scan = 0.96 + 0.04 * sin(uv.y * uniforms.resolution.y * 0.7);
