    private static let cyberTunnelPresetMetalSource = """
    #include <metal_stdlib>
    using namespace metal;

    struct Uniforms {
        float Speed;
        float Density;
        float Glow;
    };

    float3 hsv2rgb(float3 c) {
        float3 rgb = clamp(abs(fract(c.x + float3(0.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
        rgb = rgb * rgb * (3.0 - 2.0 * rgb);
        return c.z * mix(float3(1.0), rgb, c.y);
    }

    fragment float4 generatedFragment(RasterizerData in [[stage_in]],
                                      constant PreviewUniforms& uniforms [[buffer(0)]],
                                      constant float* floatUniforms [[buffer(1)]],
                                      constant float4* colorUniforms [[buffer(2)]],
                                      constant float2* pointUniforms [[buffer(3)]],
                                      constant uint* boolUniforms [[buffer(4)]]) {

        float Speed = floatUniforms[0];
        float Density = floatUniforms[1];
        float Glow = floatUniforms[2];

        float2 uv = in.uv * 2.0 - 1.0;
        uv.x *= uniforms.resolution.x / max(uniforms.resolution.y, 1.0);

        float speed = mix(0.2, 3.0, clamp(Speed, 0.0, 1.0));
        float density = mix(4.0, 20.0, clamp(Density, 0.0, 1.0));
        float glowAmt = mix(0.4, 2.5, clamp(Glow, 0.0, 1.0));

        float t = uniforms.time * speed;

        float r = length(uv);
        float a = atan2(uv.y, uv.x);

        float tunnel = 1.0 / max(r, 0.08);

        float stripes = sin(tunnel * density * 2.0 + t * 6.0);
        float rings = sin(tunnel * density * 6.0 - t * 4.0);
        float spokes = sin(a * 8.0 + t * 2.0);

        float signal = 0.5 + 0.5 * stripes;
        signal += 0.35 * (0.5 + 0.5 * rings);
        signal += 0.25 * (0.5 + 0.5 * spokes);

        signal *= smoothstep(1.5, 0.05, r);
        signal = pow(signal, 1.6);

        float hue = fract(0.6 + tunnel * 0.08 - t * 0.05);
        float3 color = hsv2rgb(float3(hue, 0.85, signal));

        float glow = exp(-r * (5.0 + glowAmt * 6.0));
        color += glow * float3(0.4, 0.6, 1.0);

        return float4(color, 1.0);
    }
