        float n2 = fbm(p * 4.0 + float2(-t * 0.16, t * 0.21));
        float n3 = fbm(p * 7.5 + float2(t * 0.08, t * 0.11));

        float2 flow = float2(
            (n1 - 0.5) + (n3 - 0.5) * 0.45,
            (n2 - 0.5) + (n3 - 0.5) * 0.25
