    float fbm(float2 p) {
        float v = 0.0;
        float a = 0.5;
        v += noise2d(p) * a; p *= 2.02; a *= 0.5;
        v += noise2d(p) * a; p *= 2.03; a *= 0.5;
        v += noise2d(p) * a; p *= 2.01; a *= 0.5;
        v += noise2d(p) * a;
        return v;
    }

