    private static func makeFragmentInputPort(for uniform: UniformDescriptor, nodeID: GraphNode.ID) -> GraphPort {
        GraphPort(
            id: ISFParser.fragmentUniformInputID(for: uniform, nodeID: nodeID),
            nodeID: nodeID,
            name: uniform.name,
            direction: .input,
            kind: uniform.kind == .image ? .fragmentShader : .uniform(uniform.id)
        )
    }

    private static func makeFragmentTimePort(nodeID: GraphNode.ID) -> GraphPort {
        GraphPort(
            id: ISFParser.fragmentTimeInputID(for: nodeID),
            nodeID: nodeID,
            name: "TIME",
            direction: .input,
            kind: .time
        )
    }

    private static func makeFragmentOutputPort(nodeID: GraphNode.ID) -> GraphPort {
        GraphPort(
            id: ISFParser.fragmentOutputID(for: nodeID),
            nodeID: nodeID,
            name: "Shader",
            direction: .output,
            kind: .fragmentShader
        )
    }

    private var primaryFragmentNode: GraphNode? {
        document.nodes.first(where: { $0.isPrimaryFragment })
    }

    private var renderNode: GraphNode? {
        document.nodes.first(where: {
            $0.isPrimaryRender
        })
    }

    private func connectedFragmentNodeID(forRenderNodeID renderNodeID: GraphNode.ID) -> GraphNode.ID? {
        guard let sourceNode = connectedSourceNode(forOutputNodeID: renderNodeID) else {
            return nil
        }

        switch sourceNode.kind {
        case .metalFragment:
            return sourceNode.id
        case .mix:
            return fragmentNodeID(forMixNodeID: sourceNode.id, inputName: "Shader A")
                ?? fragmentNodeID(forMixNodeID: sourceNode.id, inputName: "Shader B")
        case .trail, .note, .textImage, .transform, .billboard, .line, .scene3DTransform, .scene3DTile, .scene3DRender, .scene3DLight, .scene3DMaterial, .scene3DPrimitive, .scene3DText, .scene3DModel, .scene3DGaussianSplat, .scene3DParticle, .select, .scalarSwitch, .stringSwitch, .colorSwitch, .circle, .clear, .image, .webView, .aiImage, .videoPlayer, .video, .coreImage, .blur, .bloom, .hueRotate, .posterize, .levels, .glow, .underwater, .feedback, .reactionDiffusion, .transition, .layers, .uniform, .time, .mouse, .keyboard, .pointSplit, .pointCombine, .point3Split, .point3Combine, .point4Split, .point4Combine, .pointInterpolate, .point3Interpolate, .point4Interpolate, .pointScale, .point3Scale, .point4Scale, .colorSplit, .scroll, .handTracker, .pinch, .scrollGesture, .zoomGesture, .trackball, .depthEstimate, .math, .expression, .clamp, .mapRange, .logic, .compare, .random, .pulse, .fireOnLoad, .counter, .toggle, .delay, .timer, .scalarVariable, .stringVariable, .colorVariable, .scalarArrayVariable, .stringArrayVariable, .colorArrayVariable, .imageArrayVariable, .string, .stringFormat, .stringCompare, .stringSplit, .color, .hslColor, .scalarArray, .stringArray, .colorArray, .imageArray, .scalarArrayIndex, .stringArrayIndex, .colorArrayIndex, .imageArrayIndex, .arrayCount, .audio, .beatDetect, .slider, .sliderStyle, .button, .buttonStyle, .polar, .hitZone, .rectHit, .screenSize, .screenBounds, .renderBounds, .renderWindow, .gridLayout, .scalarMultiplexor, .stringMultiplexor, .colorMultiplexor, .imageMultiplexor, .macro, .iterator, .iteratorVariables, .midiOut, .midiCC, .midiCCInput, .midiNoteInput, .oscInput, .oscOutput, .oscReceive, .oscSend, .oscGet4, .oscGetArray, .oscMake4, .oscMakeArray, .oscBundle, .scale, .interpolator, .hold, .scalarSmooth, .monitor, .renderOutput:
            return nil
        }
    }

    private func connectedSourceNode(forOutputNodeID outputNodeID: GraphNode.ID) -> GraphNode? {
        guard
            let outputNode = document.nodes.first(where: { $0.id == outputNodeID }),
            let inputPort = outputNode.inputPorts.first(where: { $0.kind == .fragmentShader }),
            let connection = effectiveIncomingConnection(for: inputPort.id),
            let outputPort = resolvedSourcePort(for: connection.fromPortID)
        else {
            return nil
        }

        return document.nodes.first(where: { $0.id == outputPort.nodeID })
    }

    private func fragmentNodeID(forMixNodeID mixNodeID: GraphNode.ID, inputName: String) -> GraphNode.ID? {
        guard
            let mixNode = document.nodes.first(where: { $0.id == mixNodeID }),
            let inputPort = mixNode.inputPorts.first(where: { $0.name == inputName }),
            let connection = effectiveIncomingConnection(for: inputPort.id),
            let sourcePort = resolvedSourcePort(for: connection.fromPortID)
        else {
            return nil
        }

        guard let sourceNode = document.nodes.first(where: { $0.id == sourcePort.nodeID }) else {
            return nil
        }
        if case .metalFragment = sourceNode.kind {
            return sourceNode.id
        }
        return nil
    }

