    private func colorFromSettings(_ settings: ColorNodeSettings) -> SIMD4<Float> {
        SIMD4(Float(settings.red), Float(settings.green), Float(settings.blue), Float(settings.alpha))
    }

    private func colorFromSettings(_ settings: HSLColorNodeSettings) -> SIMD4<Float> {
        let h = settings.hue
        let s = settings.saturation
        let l = settings.lightness
        let a = settings.alpha

        if s <= 0.0001 {
            let v = Float(l)
            return SIMD4(v, v, v, Float(a))
        }

        let q = l < 0.5 ? l * (1.0 + s) : l + s - l * s
        let p = 2.0 * l - q

        func hueToRGB(_ t: Double) -> Double {
            var value = t
            if value < 0.0 { value += 1.0 }
            if value > 1.0 { value -= 1.0 }
            if value < 1.0 / 6.0 { return p + (q - p) * 6.0 * value }
            if value < 1.0 / 2.0 { return q }
            if value < 2.0 / 3.0 { return p + (q - p) * (2.0 / 3.0 - value) * 6.0 }
            return p
        }

        return SIMD4(
            Float(hueToRGB(h + 1.0 / 3.0)),
            Float(hueToRGB(h)),
            Float(hueToRGB(h - 1.0 / 3.0)),
            Float(a)
        )
    }

    private func colorFromSettings(_ settings: BillboardNodeSettings) -> SIMD4<Float> {
        SIMD4(Float(settings.red), Float(settings.green), Float(settings.blue), Float(settings.alpha))
    }

    private func colorFromSettings(_ settings: Scene3DPrimitiveNodeSettings) -> SIMD4<Float> {
        SIMD4(Float(settings.materialRed), Float(settings.materialGreen), Float(settings.materialBlue), Float(settings.materialAlpha))
    }

    private func randomValue(for minValue: Double, max maxValue: Double) -> Double {
        let lower = min(minValue, maxValue)
        let upper = max(minValue, maxValue)
        guard upper > lower else { return lower }
        return Double.random(in: lower...upper)
    }

    private func resolvedRandomOutput(
        for sourceNode: GraphNode,
        visitedNodeIDs: Set<GraphNode.ID>
    ) -> Double {
        let settings = settings(forRandomNodeID: sourceNode.id)
        let scope = visitedNodeIDs.union([sourceNode.id])
        let minValue = sourceNode.inputPorts.first(where: { $0.name == "Min" }).flatMap {
            scalarValue(forInputPortID: $0.id, visitedNodeIDs: scope)
        } ?? settings.min
        let maxValue = sourceNode.inputPorts.first(where: { $0.name == "Max" }).flatMap {
            scalarValue(forInputPortID: $0.id, visitedNodeIDs: scope)
        } ?? settings.max
        let rate = max(0.1, sourceNode.inputPorts.first(where: { $0.name == "Rate" }).flatMap {
            scalarValue(forInputPortID: $0.id, visitedNodeIDs: scope)
        } ?? settings.rate)
        let triggerValue = sourceNode.inputPorts.first(where: { $0.name == "Trigger" }).flatMap {
            scalarValue(forInputPortID: $0.id, visitedNodeIDs: scope)
        } ?? settings.trigger
        let isTriggerHigh = triggerValue >= settings.threshold
        let bucket = Int(floor(CACurrentMediaTime() * rate))

        var runtime = randomNodeRuntimeStates[sourceNode.id] ?? RandomNodeRuntimeState(
            value: randomValue(for: minValue, max: maxValue),
            lastTriggerHigh: false,
            lastContinuousBucket: nil
        )

        if settings.continuous {
            if runtime.lastContinuousBucket != bucket {
                runtime.value = randomValue(for: minValue, max: maxValue)
                runtime.lastContinuousBucket = bucket
            }
        } else if isTriggerHigh {
            if runtime.lastTriggerHigh == false || runtime.lastContinuousBucket != bucket {
                runtime.value = randomValue(for: minValue, max: maxValue)
                runtime.lastContinuousBucket = bucket
            }
        } else {
            runtime.lastContinuousBucket = nil
        }

        runtime.lastTriggerHigh = isTriggerHigh
        randomNodeRuntimeStates[sourceNode.id] = runtime
        return runtime.value
    }

    private func colorFromValue(_ value: ArrayColorValue) -> SIMD4<Float> {
        SIMD4(Float(value.red), Float(value.green), Float(value.blue), Float(value.alpha))
