    private func stringArrayValues(from settings: StringArrayNodeSettings) -> [String] {
        normalizedStringArraySettings(settings).values
    }

    private func colorArrayValues(from settings: ColorArrayNodeSettings) -> [SIMD4<Float>] {
        normalizedColorArraySettings(settings).values.map(colorFromValue(_:))
    }

    private func sortedArrayItemPorts(_ ports: [GraphPort]) -> [GraphPort] {
        ports.sorted { lhs, rhs in
            let lhsIndex = arrayItemIndex(from: lhs.name) ?? .max
            let rhsIndex = arrayItemIndex(from: rhs.name) ?? .max
            if lhsIndex == rhsIndex {
                return lhs.name < rhs.name
            }
            return lhsIndex < rhsIndex
        }
    }

    private func stringValueForOutputPort(_ outputPort: GraphPort) -> String? {
        guard case .stringSignal = outputPort.kind else { return nil }
        guard let sourceNode = document.nodes.first(where: { $0.id == outputPort.nodeID }) else { return nil }

        switch sourceNode.kind {
        case .stringVariable:
            return settings(forStringVariableNodeID: sourceNode.id).value
        case .string:
            return settings(forStringNodeID: sourceNode.id).value
        case .stringFormat:
            let settings = settings(forStringFormatNodeID: sourceNode.id)
            var result = settings.template
            for index in 0...3 {
                let inputName = "Text \(index + 1)"
                let replacement = sourceNode.inputPorts.first(where: { $0.name == inputName }).flatMap {
                    stringValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
                } ?? stringFormatFallbackText(for: index, settings: settings)
                result = result.replacingOccurrences(of: "{\(index)}", with: replacement)
            }
            return result
        case .stringSplit:
            let settings = settings(forStringSplitNodeID: sourceNode.id)
            let text = sourceNode.inputPorts.first(where: { $0.name == "Text" }).flatMap {
                stringValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.text
            let index = sourceNode.inputPorts.first(where: { $0.name == "Index" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.index
            let separator = settings.separator
            let parts = separator.isEmpty
                ? Array(text).map(String.init)
                : text.components(separatedBy: separator).map {
                    $0.trimmingCharacters(in: .whitespacesAndNewlines)
                }
            let resolvedIndex = min(max(Int(index.rounded()), 0), max(parts.count - 1, 0))
            return parts.isEmpty ? "" : parts[resolvedIndex]
        case .oscInput:
            return oscInputStringValue(for: sourceNode.id, outputName: outputPort.name)
        case .oscReceive:
            return oscReceiveStringValue(for: sourceNode.id, outputName: outputPort.name)
        case .oscGet4:
            let packet = oscGetPacketValue(for: sourceNode.id)
            switch outputPort.name {
            case "Address":
                return oscAddress(in: packet)
            case "Text 1":
                if case .string(let value) = oscArgument(in: packet, at: 0) { return value }
                if case .float(let value) = oscArgument(in: packet, at: 0) { return String(format: "%.3f", Double(value)) }
                if case .int(let value) = oscArgument(in: packet, at: 0) { return "\(value)" }
                return nil
            case "Text 2":
                if case .string(let value) = oscArgument(in: packet, at: 1) { return value }
                if case .float(let value) = oscArgument(in: packet, at: 1) { return String(format: "%.3f", Double(value)) }
                if case .int(let value) = oscArgument(in: packet, at: 1) { return "\(value)" }
                return nil
            case "Text 3":
                if case .string(let value) = oscArgument(in: packet, at: 2) { return value }
                if case .float(let value) = oscArgument(in: packet, at: 2) { return String(format: "%.3f", Double(value)) }
                if case .int(let value) = oscArgument(in: packet, at: 2) { return "\(value)" }
                return nil
            case "Text 4":
                if case .string(let value) = oscArgument(in: packet, at: 3) { return value }
                if case .float(let value) = oscArgument(in: packet, at: 3) { return String(format: "%.3f", Double(value)) }
                if case .int(let value) = oscArgument(in: packet, at: 3) { return "\(value)" }
                return nil
            default:
                return nil
            }
        case .oscGetArray:
            switch outputPort.name {
            case "Address":
                return oscAddress(in: oscGetPacketValue(for: sourceNode.id))
            default:
                return nil
            }
        case .scene3DGaussianSplat:
            guard outputPort.name == "Status" else { return nil }
            return GaussianSplatLoadProgressStore.shared.status(for: sourceNode.id).message
        case .stringArrayIndex:
            let settings = settings(forStringArrayIndexNodeID: sourceNode.id)
            guard
                let arrayInput = sourceNode.inputPorts.first(where: { $0.name == "Array" }),
                let values = stringArrayValue(forInputPortID: arrayInput.id, visitedNodeIDs: [sourceNode.id]),
                values.isEmpty == false
            else {
                return nil
            }
            let index = sourceNode.inputPorts.first(where: { $0.name == "Index" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.index
            let resolvedIndex = min(max(Int(index.rounded()), 0), values.count - 1)
            return values[resolvedIndex]
        case .stringSwitch:
            let settings = settings(forSelectNodeID: sourceNode.id)
            let selectValue = sourceNode.inputPorts.first(where: { $0.name == "Select" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.selectValue
            let selectedName = selectValue >= settings.threshold ? "B" : "A"
            let fallbackValue = selectedName == "B" ? settings.stringB : settings.stringA
            return sourceNode.inputPorts.first(where: { $0.name == selectedName }).flatMap {
                stringValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? fallbackValue
        case .stringMultiplexor:
            let arraySettings = normalizedStringArraySettings(settings(forStringArrayNodeID: sourceNode.id))
            let multiplexSettings = self.settings(forStringArrayIndexNodeID: sourceNode.id)
            guard arraySettings.values.isEmpty == false else { return nil }
            let index = sourceNode.inputPorts.first(where: { $0.name == "Index" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? multiplexSettings.index
            let resolvedIndex = min(max(Int(index.rounded()), 0), arraySettings.values.count - 1)
            let itemPorts = sortedArrayItemPorts(sourceNode.inputPorts.filter { $0.name.hasPrefix("Item ") })
            let inputPort = itemPorts.indices.contains(resolvedIndex) ? itemPorts[resolvedIndex] : nil
            return inputPort.flatMap { stringValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id]) } ?? arraySettings.values[resolvedIndex]
        default:
            return nil
        }
    }

    private func colorValueForOutputPort(_ outputPort: GraphPort) -> SIMD4<Float>? {
        guard case .colorSignal = outputPort.kind else { return nil }
        guard let sourceNode = document.nodes.first(where: { $0.id == outputPort.nodeID }) else { return nil }

        switch sourceNode.kind {
        case .color:
            return colorFromSettings(settings(forColorNodeID: sourceNode.id))
        case .hslColor:
            let settings = settings(forHSLColorNodeID: sourceNode.id)
            let hue = sourceNode.inputPorts.first(where: { $0.name == "Hue" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.hue
            let saturation = sourceNode.inputPorts.first(where: { $0.name == "Saturation" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.saturation
            let lightness = sourceNode.inputPorts.first(where: { $0.name == "Lightness" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.lightness
            let alpha = sourceNode.inputPorts.first(where: { $0.name == "Alpha" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.alpha
            return colorFromSettings(HSLColorNodeSettings(
                hue: hue,
                saturation: saturation,
                lightness: lightness,
                alpha: alpha
            ))
        case .colorArrayIndex:
            let settings = settings(forColorArrayIndexNodeID: sourceNode.id)
            guard
                let arrayInput = sourceNode.inputPorts.first(where: { $0.name == "Array" }),
                let values = colorArrayValue(forInputPortID: arrayInput.id, visitedNodeIDs: [sourceNode.id]),
                values.isEmpty == false
            else {
                return nil
            }
            let index = sourceNode.inputPorts.first(where: { $0.name == "Index" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.index
            let resolvedIndex = min(max(Int(index.rounded()), 0), values.count - 1)
            return values[resolvedIndex]
        case .colorVariable:
            guard let inputPort = sourceNode.inputPorts.first(where: { $0.name == "Color" }) else {
                return nil
            }
            return resolvedColorValue(forInputPortID: inputPort.id)
        case .colorSwitch:
            let settings = settings(forSelectNodeID: sourceNode.id)
            let selectValue = sourceNode.inputPorts.first(where: { $0.name == "Select" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.selectValue
            let selectedName = selectValue >= settings.threshold ? "B" : "A"
            let fallbackValue = selectedName == "B" ? settings.colorB : settings.colorA
            return sourceNode.inputPorts.first(where: { $0.name == selectedName }).flatMap {
                colorValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? SIMD4<Float>(
                Float(fallbackValue.red),
                Float(fallbackValue.green),
                Float(fallbackValue.blue),
                Float(fallbackValue.alpha)
            )
        case .colorMultiplexor:
            let arraySettings = normalizedColorArraySettings(settings(forColorArrayNodeID: sourceNode.id))
            let multiplexSettings = self.settings(forScalarArrayIndexNodeID: sourceNode.id)
            guard arraySettings.values.isEmpty == false else { return nil }
            let index = sourceNode.inputPorts.first(where: { $0.name == "Index" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? multiplexSettings.index
            let resolvedIndex = min(max(Int(index.rounded()), 0), arraySettings.values.count - 1)
            let itemPorts = sortedArrayItemPorts(sourceNode.inputPorts.filter { $0.name.hasPrefix("Item ") })
            let inputPort = itemPorts.indices.contains(resolvedIndex) ? itemPorts[resolvedIndex] : nil
            let fallbackValue = arraySettings.values[resolvedIndex]
            return inputPort.flatMap { colorValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id]) } ?? SIMD4<Float>(
                Float(fallbackValue.red),
                Float(fallbackValue.green),
                Float(fallbackValue.blue),
                Float(fallbackValue.alpha)
            )
        default:
            return nil
        }
    }

    private func scalarArrayValueForOutputPort(_ outputPort: GraphPort) -> [Double]? {
        guard case .scalarArraySignal = outputPort.kind else { return nil }
        guard let sourceNode = document.nodes.first(where: { $0.id == outputPort.nodeID }) else { return nil }
        switch sourceNode.kind {
        case .audio:
            return outputPort.name == "Spectrum" ? audioSpectrumValues() : nil
        case .scalarArray:
            let settings = settings(forScalarArrayNodeID: sourceNode.id)
            let fallbackValues = scalarArrayValues(from: settings)
            return sortedArrayItemPorts(sourceNode.inputPorts).enumerated().map { index, inputPort in
                scalarValue(forInputPortID: inputPort.id, visitedNodeIDs: [sourceNode.id]) ?? fallbackValues[index]
            }
        case .oscGetArray:
            return oscNumericArguments(in: oscGetPacketValue(for: sourceNode.id)) ?? []
        case .scalarArrayVariable:
            guard let inputPort = sourceNode.inputPorts.first(where: { $0.name == "Array" }) else {
                return nil
            }
            return scalarArrayValue(forInputPortID: inputPort.id, visitedNodeIDs: [sourceNode.id])
        default:
            return nil
        }
    }

