        guard case .stringArraySignal = outputPort.kind else { return nil }
        guard let sourceNode = document.nodes.first(where: { $0.id == outputPort.nodeID }) else { return nil }
        switch sourceNode.kind {
        case .stringArray:
            let settings = settings(forStringArrayNodeID: sourceNode.id)
            let fallbackValues = stringArrayValues(from: settings)
            return sortedArrayItemPorts(sourceNode.inputPorts).enumerated().map { index, inputPort in
                stringValue(forInputPortID: inputPort.id, visitedNodeIDs: [sourceNode.id]) ?? fallbackValues[index]
            }
        case .stringArrayVariable:
            guard let inputPort = sourceNode.inputPorts.first(where: { $0.name == "Array" }) else {
                return nil
            }
            return stringArrayValue(forInputPortID: inputPort.id, visitedNodeIDs: [sourceNode.id])
        default:
            return nil
        }
    }

    private func colorArrayValueForOutputPort(_ outputPort: GraphPort) -> [SIMD4<Float>]? {
        guard case .colorArraySignal = outputPort.kind else { return nil }
        guard let sourceNode = document.nodes.first(where: { $0.id == outputPort.nodeID }) else { return nil }
        switch sourceNode.kind {
