    private func imageArraySourcesWithHoles(for node: GraphNode) -> [PreviewPassSource?] {
        guard case .imageArray = node.kind else { return [] }
        return sortedArrayItemPorts(node.inputPorts).map { previewPassSourceForVisualInputPortID($0.id) }
    }

    private func audioOutputPorts(for nodeID: GraphNode.ID, legacyCompatible: Bool) -> [GraphPort] {
        let scalarPorts = AudioSignalKind.allCases.map { signal in
            GraphPort(
                id: legacyCompatible ? "audio:\(signal.rawValue)" : "audio:\(nodeID.uuidString):\(signal.rawValue)",
                nodeID: nodeID,
                name: signal.label,
                direction: .output,
                kind: .audio(signal)
            )
        }
        return scalarPorts + [
            GraphPort(
                id: legacyCompatible ? "audio:spectrum" : "audio:\(nodeID.uuidString):spectrum",
                nodeID: nodeID,
                name: "Spectrum",
                direction: .output,
                kind: .scalarArraySignal("spectrum")
            )
        ]
    }

    private func beatDetectOutputPorts(for nodeID: GraphNode.ID) -> [GraphPort] {
        [
            GraphPort(
                id: "beat:\(nodeID.uuidString):kick",
                nodeID: nodeID,
                name: "Kick",
                direction: .output,
                kind: .scalarSignal("kick")
            ),
            GraphPort(
                id: "beat:\(nodeID.uuidString):snare",
                nodeID: nodeID,
                name: "Snare",
                direction: .output,
                kind: .scalarSignal("snare")
            ),
            GraphPort(
                id: "beat:\(nodeID.uuidString):kickLevel",
                nodeID: nodeID,
                name: "Kick Level",
                direction: .output,
                kind: .scalarSignal("kickLevel")
            ),
            GraphPort(
                id: "beat:\(nodeID.uuidString):snareLevel",
                nodeID: nodeID,
                name: "Snare Level",
                direction: .output,
                kind: .scalarSignal("snareLevel")
            )
        ]
    }

    private func imageArraySourcesWithHoles(forInputPortID portID: GraphPort.ID, visitedNodeIDs: Set<GraphNode.ID>) -> [PreviewPassSource?]? {
        guard
            let inputPort = port(withID: portID),
            let connection = effectiveIncomingConnection(for: inputPort.id),
            let sourcePort = resolvedSourcePort(for: connection.fromPortID),
            case .imageArraySignal = sourcePort.kind,
            let sourceNode = document.nodes.first(where: { $0.id == sourcePort.nodeID }),
            !visitedNodeIDs.contains(sourceNode.id)
        else {
            return nil
        }

        switch sourceNode.kind {
        case .imageArray:
            return imageArraySourcesWithHoles(for: sourceNode)
        case .imageArrayVariable:
            guard let arrayInput = sourceNode.inputPorts.first(where: { $0.name == "Array" }) else {
                return nil
            }
            return imageArraySourcesWithHoles(forInputPortID: arrayInput.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
        default:
            return nil
        }
    }

    private func imageArrayValueForOutputPort(_ outputPort: GraphPort) -> [PreviewPassSource]? {
        guard case .imageArraySignal = outputPort.kind else { return nil }
        guard let sourceNode = document.nodes.first(where: { $0.id == outputPort.nodeID }) else { return nil }
        switch sourceNode.kind {
        case .imageArray:
            return imageArraySourcesWithHoles(for: sourceNode).compactMap { $0 }
        case .imageArrayVariable:
            guard let inputPort = sourceNode.inputPorts.first(where: { $0.name == "Array" }) else {
                return nil
            }
            return imageArrayValue(forInputPortID: inputPort.id, visitedNodeIDs: [sourceNode.id])
        default:
            return nil
        }
    }

    private func scalarValueForOutputPort(_ outputPort: GraphPort) -> Double? {
        guard case .scalarSignal = outputPort.kind else { return nil }
        guard let sourceNode = document.nodes.first(where: { $0.id == outputPort.nodeID }) else { return nil }

        switch sourceNode.kind {
        case .iteratorVariables:
            guard let context = iteratorEvaluationStack.last ?? iteratorVariableRuntimeContexts[sourceNode.id] else { return nil }
            switch outputPort.name {
            case "Index":
                return Double(context.index)
            case "Progress":
                return context.progress
            case "Iterations":
                return Double(context.iterations)
            default:
                return nil
            }
        case .scene3DGaussianSplat:
            let status = GaussianSplatLoadProgressStore.shared.status(for: sourceNode.id)
            switch outputPort.name {
            case "Loading":
                return status.isLoading ? 1.0 : 0.0
            case "Progress":
                return status.progress
            default:
                return nil
            }
        case .scalarVariable:
            return settings(forScalarVariableNodeID: sourceNode.id).value
        case .mouse:
            switch outputPort.name {
            case "Left Click":
                return currentMouseLeftButtonDown ? 1.0 : 0.0
            case "Right Click":
                return currentMouseRightButtonDown ? 1.0 : 0.0
            default:
                return nil
            }
        case .keyboard:
            let settings = settings(forKeyboardNodeID: sourceNode.id)
            let modifiers = currentKeyboardModifierFlags
            let matches =
                currentPressedKeyCodes.contains(settings.key.keyCode) &&
                modifiers.contains(.command) == settings.requiresCommand &&
                modifiers.contains(.option) == settings.requiresOption &&
                modifiers.contains(.shift) == settings.requiresShift &&
                modifiers.contains(.control) == settings.requiresControl
            switch outputPort.name {
            case "Pressed":
                return matches ? 1.0 : 0.0
            default:
                return nil
            }
        case .pointSplit:
            guard
                let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point" }),
                let point = resolvedPointValue(forInputPortID: pointInput.id)
            else {
                return nil
            }
            switch outputPort.name {
            case "X":
                return point.x
            case "Y":
                return point.y
            default:
                return nil
            }
        case .pointCombine:
            let settings = settings(forPointCombineNodeID: sourceNode.id)
            switch outputPort.name {
            case "X":
                return sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
                } ?? settings.x
            case "Y":
                return sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
                } ?? settings.y
            default:
                return nil
            }
        case .point3Split:
            guard
                let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point3" }),
                let point = resolvedPoint3Value(forInputPortID: pointInput.id)
            else {
                return nil
            }
            switch outputPort.name {
            case "X":
                return point.x
            case "Y":
                return point.y
            case "Z":
                return point.z
            default:
                return nil
            }
        case .point3Combine:
            let settings = settings(forPoint3CombineNodeID: sourceNode.id)
            switch outputPort.name {
            case "X":
                return sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
                } ?? settings.x
            case "Y":
                return sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
                } ?? settings.y
            case "Z":
                return sourceNode.inputPorts.first(where: { $0.name == "Z" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
                } ?? settings.z
            default:
                return nil
            }
        case .point4Split:
            guard
                let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point4" }),
                let point = resolvedPoint4Value(forInputPortID: pointInput.id)
            else {
                return nil
            }
            switch outputPort.name {
            case "X":
                return point.x
            case "Y":
                return point.y
            case "Z":
                return point.z
            case "W":
                return point.w
            default:
                return nil
            }
        case .point4Combine:
            let settings = settings(forPoint4CombineNodeID: sourceNode.id)
            switch outputPort.name {
            case "X":
                return sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
                } ?? settings.x
            case "Y":
                return sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
                } ?? settings.y
            case "Z":
                return sourceNode.inputPorts.first(where: { $0.name == "Z" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
                } ?? settings.z
            case "W":
                return sourceNode.inputPorts.first(where: { $0.name == "W" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
                } ?? settings.w
            default:
                return nil
            }
        case .pointInterpolate, .point3Interpolate, .point4Interpolate, .pointScale, .point3Scale, .point4Scale:
            return nil
        case .colorSplit:
            guard
                let colorInput = sourceNode.inputPorts.first(where: { $0.name == "Color" }),
                let color = resolvedColorValue(forInputPortID: colorInput.id)
            else {
                return nil
            }
            switch outputPort.name {
            case "R":
                return Double(color.x)
            case "G":
                return Double(color.y)
            case "B":
                return Double(color.z)
            case "A":
                return Double(color.w)
            default:
                return nil
            }
        case .scroll:
            switch outputPort.name {
            case "X":
                return currentScrollPosition.x
            case "Y":
                return currentScrollPosition.y
            case "Active":
                return isScrollActive ? 1.0 : 0.0
            default:
                return nil
            }
        case .pinch:
            guard let fingerInput = sourceNode.inputPorts.first(where: { $0.name == "Finger" }),
                  let thumbInput = sourceNode.inputPorts.first(where: { $0.name == "Thumb" }),
                  let finger = resolvedPointValue(forInputPortID: fingerInput.id),
                  let thumb = resolvedPointValue(forInputPortID: thumbInput.id) else {
                return outputPort.name == "Pinched" ? 0.0 : nil
            }
            let threshold = settings(forPinchNodeID: sourceNode.id).threshold
            let dx = Double(finger.x - thumb.x)
            let dy = Double(finger.y - thumb.y)
            let distance = sqrt((dx * dx) + (dy * dy))
            switch outputPort.name {
            case "Distance":
                return distance
            case "Strength":
                guard threshold > 0.0001 else { return 0.0 }
                return max(0.0, min(1.0, 1.0 - (distance / threshold)))
            case "Pinched":
                return distance <= threshold ? 1.0 : 0.0
            default:
                return nil
            }
        case .scrollGesture:
            let settings = settings(forScrollGestureNodeID: sourceNode.id)
            let pointAInput = sourceNode.inputPorts.first(where: { $0.name == "Point A" })
            let pointBInput = sourceNode.inputPorts.first(where: { $0.name == "Point B" })
            let engageInput = sourceNode.inputPorts.first(where: { $0.name == "Engage" })
            let pointA = pointAInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
            let pointB = pointBInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
            let gate = engageInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id]) } ?? 0.0
            let hasGateConnection = engageInput.map { gatePort in
                document.connections.contains(where: { $0.toPortID == gatePort.id })
            } ?? false
            var runtime = scrollGestureNodeRuntimeStates[sourceNode.id] ?? ScrollGestureNodeRuntimeState()
            let center = pointB.map { midpoint(pointA, Optional($0)) } ?? pointA
            let engaged = center != nil && (!hasGateConnection || gate >= settings.threshold)
            if engaged, let center {
                if let previous = runtime.lastCenter {
                    let deltaY = Double(center.y - previous.y) * settings.sensitivity * (settings.invertY ? -1.0 : 1.0)
                    runtime.accumulatedY += deltaY
                }
                runtime.lastCenter = center
            } else {
                runtime.lastCenter = nil
            }
            runtime.isEngaged = engaged
            scrollGestureNodeRuntimeStates[sourceNode.id] = runtime
            return outputPort.name == "Y" ? runtime.accumulatedY : nil
        case .zoomGesture:
            let settings = settings(forZoomGestureNodeID: sourceNode.id)
            let pointAInput = sourceNode.inputPorts.first(where: { $0.name == "Point A" })
            let pointBInput = sourceNode.inputPorts.first(where: { $0.name == "Point B" })
            let engageInput = sourceNode.inputPorts.first(where: { $0.name == "Engage" })
            let pointA = pointAInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
            let pointB = pointBInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
            let gate = engageInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id]) } ?? 0.0
            let hasGateConnection = engageInput.map { gatePort in
                document.connections.contains(where: { $0.toPortID == gatePort.id })
            } ?? false
            var runtime = zoomGestureNodeRuntimeStates[sourceNode.id] ?? ZoomGestureNodeRuntimeState(zoom: settings.initialZoom)
            let distance = pointA.flatMap { a in pointB.map { b in
                let dx = Double(a.x - b.x)
                let dy = Double(a.y - b.y)
                return sqrt((dx * dx) + (dy * dy))
            }}
            let engaged = distance != nil && (!hasGateConnection || gate >= settings.threshold)
            if engaged, let distance {
                if let previous = runtime.lastDistance {
                    let delta = (distance - previous) * settings.sensitivity
                    runtime.zoom = min(max(runtime.zoom + delta, settings.minZoom), settings.maxZoom)
                } else {
                    runtime.zoom = min(max(runtime.zoom, settings.minZoom), settings.maxZoom)
                }
                runtime.lastDistance = distance
            } else {
                runtime.lastDistance = nil
            }
            runtime.isEngaged = engaged
            zoomGestureNodeRuntimeStates[sourceNode.id] = runtime
            return outputPort.name == "Zoom" ? runtime.zoom : nil
        case .trackball:
            let settings = settings(forTrackballNodeID: sourceNode.id)
            var runtime = trackballNodeRuntimeStates[sourceNode.id] ?? TrackballNodeRuntimeState(
                orbit: settings.initialOrbit,
                pitch: settings.initialPitch,
                rotationX: settings.initialPitch,
                rotationY: settings.initialOrbit,
                panX: settings.initialPanX,
                panY: settings.initialPanY,
                distance: settings.initialDistance
            )
            let modifiers = currentKeyboardModifierFlags
            let panDragging = currentMouseLeftButtonDown && currentMousePosition != nil && modifiers.contains(.option) && modifiers.contains(.shift)
            let orbitDragging = currentMouseLeftButtonDown && currentMousePosition != nil && panDragging == false
            let dragging = orbitDragging || panDragging
            if dragging, let mousePosition = currentMousePosition {
                if let previous = runtime.lastMousePosition {
                    let deltaX = Double(mousePosition.x - previous.x)
                    let deltaY = Double(mousePosition.y - previous.y)
                    let verticalScale = settings.invertY ? 1.0 : -1.0
                    if panDragging {
                        // Keep pan in stable scene units. Scaling by camera distance made
                        // large 3D/splat scenes jump by tens of units per drag.
                        let panScale = settings.panSensitivity * 2.0
                        runtime.panX -= deltaX * panScale
                        runtime.panY += deltaY * panScale * verticalScale
                    } else {
                        runtime.orbit += deltaX * 360.0 * settings.sensitivity
                        runtime.pitch += deltaY * 180.0 * settings.sensitivity * verticalScale
                        runtime.pitch = min(max(runtime.pitch, -89.0), 89.0)
                        runtime.rotationY += deltaX * 360.0 * settings.sensitivity
                        runtime.rotationX += deltaY * 180.0 * settings.sensitivity * verticalScale
                    }
                }
                runtime.lastMousePosition = mousePosition
            } else {
                runtime.lastMousePosition = nil
            }
            let scrollDeltaY = currentScrollPosition.y - runtime.lastScrollPosition.y
            if abs(scrollDeltaY) > 0.0001 {
                runtime.distance -= scrollDeltaY * settings.zoomSensitivity
                runtime.distance = min(max(runtime.distance, settings.minDistance), settings.maxDistance)
                runtime.lastDistanceScrollTime = CACurrentMediaTime()
                runtime.lastScrollPosition = currentScrollPosition
            } else {
                runtime.lastScrollPosition = currentScrollPosition
            }
            runtime.isDragging = dragging
            trackballNodeRuntimeStates[sourceNode.id] = runtime
            switch outputPort.name {
            case "Orbit":
                return runtime.orbit
            case "Pitch":
                return runtime.pitch
            case "Pan X":
                return runtime.panX
            case "Pan Y":
                return runtime.panY
            case "Distance":
                return runtime.distance
            case "Rotation X":
                return runtime.rotationX
            case "Rotation Y":
                return runtime.rotationY
            case "Dragging":
                return runtime.isDragging ? 1.0 : 0.0
            case "Scroll Active":
                if let lastDistanceScrollTime = runtime.lastDistanceScrollTime,
                   CACurrentMediaTime() - lastDistanceScrollTime < 0.35 {
                    return 1.0
                }
                return 0.0
            default:
                return nil
            }
        case .scene3DTransform, .scene3DTile:
            return nil
        case .depthEstimate:
            return depthEstimateOutput(from: sourceNode, outputName: outputPort.name, visitedNodeIDs: [sourceNode.id])
        case .math:
            let settings = settings(forMathNodeID: sourceNode.id)
            let a = sourceNode.inputPorts.first(where: { $0.name == "A" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.a
            let b = sourceNode.inputPorts.first(where: { $0.name == "B" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.b
            let result: Double
            switch settings.operation {
            case .add:
                result = a + b
            case .subtract:
                result = a - b
            case .multiply:
                result = a * b
            case .divide:
                result = abs(b) > .ulpOfOne ? (a / b) : 0.0
            case .minimum:
                result = min(a, b)
            case .maximum:
                result = max(a, b)
            case .power:
                result = Foundation.pow(a, b)
            case .sine:
                result = Foundation.sin(a)
            case .cosine:
                result = Foundation.cos(a)
            case .round:
                result = a.rounded()
            case .floor:
                result = Foundation.floor(a)
            case .ceil:
                result = Foundation.ceil(a)
            }
            return outputPort.name == "Result" ? result : nil
        case .expression:
            guard outputPort.name == "Result" else { return nil }
            let settings = settings(forExpressionNodeID: sourceNode.id)
            return evaluateExpressionNode(sourceNode, settings: settings, visitedNodeIDs: [sourceNode.id])
        case .scalarSwitch:
            let settings = settings(forSelectNodeID: sourceNode.id)
            let selectValue = sourceNode.inputPorts.first(where: { $0.name == "Select" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.selectValue
            let selectedName = selectValue >= settings.threshold ? "B" : "A"
            let fallbackValue = selectedName == "B" ? settings.scalarB : settings.scalarA
            return sourceNode.inputPorts.first(where: { $0.name == selectedName }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? fallbackValue
        case .scalarMultiplexor:
            let arraySettings = normalizedScalarArraySettings(settings(forScalarArrayNodeID: sourceNode.id))
            let multiplexSettings = self.settings(forScalarArrayIndexNodeID: sourceNode.id)
            guard arraySettings.values.isEmpty == false else { return nil }
            let index = sourceNode.inputPorts.first(where: { $0.name == "Index" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? multiplexSettings.index
            let resolvedIndex = min(max(Int(index.rounded()), 0), arraySettings.values.count - 1)
            let itemPorts = sortedArrayItemPorts(sourceNode.inputPorts.filter { $0.name.hasPrefix("Item ") })
            let inputPort = itemPorts.indices.contains(resolvedIndex) ? itemPorts[resolvedIndex] : nil
            return inputPort.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id]) } ?? arraySettings.values[resolvedIndex]
        case .scalarArrayIndex:
            let settings = settings(forScalarArrayIndexNodeID: sourceNode.id)
            guard
                let arrayInput = sourceNode.inputPorts.first(where: { $0.name == "Array" }),
                let values = scalarArrayValue(forInputPortID: arrayInput.id, visitedNodeIDs: [sourceNode.id]),
                values.isEmpty == false
            else {
                return nil
            }
            let index = sourceNode.inputPorts.first(where: { $0.name == "Index" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.index
            let resolvedIndex = min(max(Int(index.rounded()), 0), values.count - 1)
            return values[resolvedIndex]
        case .arrayCount:
            guard let arrayInput = sourceNode.inputPorts.first(where: { $0.name == "Array" }) else {
                return 0
            }
            if let values = scalarArrayValue(forInputPortID: arrayInput.id, visitedNodeIDs: [sourceNode.id]) {
                return Double(values.count)
            }
            if let values = stringArrayValue(forInputPortID: arrayInput.id, visitedNodeIDs: [sourceNode.id]) {
                return Double(values.count)
            }
            if let values = colorArrayValue(forInputPortID: arrayInput.id, visitedNodeIDs: [sourceNode.id]) {
                return Double(values.count)
            }
            if let values = imageArrayValue(forInputPortID: arrayInput.id, visitedNodeIDs: [sourceNode.id]) {
                return Double(values.count)
            }
            return 0
        case .clamp:
            let settings = settings(forClampNodeID: sourceNode.id)
            let value = sourceNode.inputPorts.first(where: { $0.name == "Value" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? 0.0
            let minimum = sourceNode.inputPorts.first(where: { $0.name == "Min" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.minimum
            let maximum = sourceNode.inputPorts.first(where: { $0.name == "Max" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.maximum
            let lower = min(minimum, maximum)
            let upper = max(minimum, maximum)
            return outputPort.name == "Result" ? min(max(value, lower), upper) : nil
        case .mapRange:
            let settings = settings(forMapRangeNodeID: sourceNode.id)
            let value = sourceNode.inputPorts.first(where: { $0.name == "Value" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? 0.0
            let inputMinimum = sourceNode.inputPorts.first(where: { $0.name == "In Min" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.inputMinimum
            let inputMaximum = sourceNode.inputPorts.first(where: { $0.name == "In Max" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.inputMaximum
            let outputMinimum = sourceNode.inputPorts.first(where: { $0.name == "Out Min" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.outputMinimum
            let outputMaximum = sourceNode.inputPorts.first(where: { $0.name == "Out Max" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.outputMaximum
            let denominator = inputMaximum - inputMinimum
            let result: Double
            if abs(denominator) > .ulpOfOne {
                result = outputMinimum + ((value - inputMinimum) * (outputMaximum - outputMinimum) / denominator)
            } else {
                result = outputMinimum
            }
            return outputPort.name == "Result" ? result : nil
        case .logic:
            let settings = settings(forLogicNodeID: sourceNode.id)
            let a = sourceNode.inputPorts.first(where: { $0.name == "A" }).flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id]) } ?? 0.0
            let b = sourceNode.inputPorts.first(where: { $0.name == "B" }).flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id]) } ?? 0.0
            let aBool = a >= settings.threshold
            let bBool = b >= settings.threshold
            let result: Bool
            switch settings.operation {
            case .and:
                result = aBool && bBool
            case .or:
                result = aBool || bBool
            case .xor:
                result = aBool != bBool
            case .not:
                result = !aBool
            }
            return outputPort.name == "Value" ? (result ? 1.0 : 0.0) : nil
        case .compare:
            let settings = settings(forCompareNodeID: sourceNode.id)
            let value = sourceNode.inputPorts.first(where: { $0.name == "Value" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? 0.0
            let referenceValue = sourceNode.inputPorts.first(where: { $0.name == "Number" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.referenceValue
            let threshold = sourceNode.inputPorts.first(where: { $0.name == "Threshold" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.epsilon
            let result: Bool
            switch settings.operation {
            case .lessThan:
                result = value < referenceValue
            case .lessThanOrEqual:
                result = value <= referenceValue
            case .greaterThan:
                result = value > referenceValue
            case .greaterThanOrEqual:
                result = value >= referenceValue
            case .equal:
                result = abs(value - referenceValue) <= threshold
            case .notEqual:
                result = abs(value - referenceValue) > threshold
            }
            return outputPort.name == "Result" ? (result ? 1.0 : 0.0) : nil
        case .beatDetect:
            return beatDetectValue(for: sourceNode.id, outputName: outputPort.name)
        case .midiCCInput:
            return midiInputCCValue(for: sourceNode.id, outputName: outputPort.name)
        case .midiNoteInput:
            return midiInputNoteValue(for: sourceNode.id, outputName: outputPort.name)
        case .oscInput:
            return oscInputScalarValue(for: sourceNode.id, outputName: outputPort.name)
        case .oscReceive:
            return oscReceiveScalarValue(for: sourceNode.id, outputName: outputPort.name)
        case .oscGet4:
            let packet = oscGetPacketValue(for: sourceNode.id)
            switch outputPort.name {
            case "Float 1":
                switch oscArgument(in: packet, at: 0) {
                case .float(let value): return Double(value)
                case .int(let value): return Double(value)
                default: return nil
                }
            case "Float 2":
                switch oscArgument(in: packet, at: 1) {
                case .float(let value): return Double(value)
                case .int(let value): return Double(value)
                default: return nil
                }
            case "Float 3":
                switch oscArgument(in: packet, at: 2) {
                case .float(let value): return Double(value)
                case .int(let value): return Double(value)
                default: return nil
                }
            case "Float 4":
                switch oscArgument(in: packet, at: 3) {
                case .float(let value): return Double(value)
                case .int(let value): return Double(value)
                default: return nil
                }
            case "Int 1":
                switch oscArgument(in: packet, at: 0) {
                case .float(let value): return Double(Int(value.rounded()))
                case .int(let value): return Double(value)
                default: return nil
                }
            case "Int 2":
                switch oscArgument(in: packet, at: 1) {
                case .float(let value): return Double(Int(value.rounded()))
                case .int(let value): return Double(value)
                default: return nil
                }
            case "Int 3":
                switch oscArgument(in: packet, at: 2) {
                case .float(let value): return Double(Int(value.rounded()))
                case .int(let value): return Double(value)
                default: return nil
                }
            case "Int 4":
                switch oscArgument(in: packet, at: 3) {
                case .float(let value): return Double(Int(value.rounded()))
                case .int(let value): return Double(value)
                default: return nil
                }
            default:
                return nil
            }
        case .oscGetArray:
            return nil
        case .random:
            return outputPort.name == "Value" ? resolvedRandomOutput(for: sourceNode, visitedNodeIDs: [sourceNode.id]) : nil
        case .pulse:
            let settings = settings(forPulseNodeID: sourceNode.id)
            let gateValue = sourceNode.inputPorts.first(where: { $0.name == "Gate" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.gate
            let isGateHigh = gateValue >= settings.threshold
            let frameID = evaluationFrameID
            var runtime = pulseNodeRuntimeStates[sourceNode.id] ?? PulseNodeRuntimeState()
            if isGateHigh && runtime.lastGateHigh == false {
                runtime.lastRiseFrame = frameID
            } else if isGateHigh == false, runtime.lastRiseFrame != frameID {
                runtime.lastRiseFrame = nil
            }
            runtime.lastGateHigh = isGateHigh
            pulseNodeRuntimeStates[sourceNode.id] = runtime
            return outputPort.name == "Value" ? ((runtime.lastRiseFrame == frameID) ? 1.0 : 0.0) : nil
        case .fireOnLoad:
            let frameID = evaluationFrameID
            var runtime = fireOnLoadNodeRuntimeStates[sourceNode.id] ?? FireOnLoadNodeRuntimeState()
            if runtime.lastActivationID != graphActivationID {
                runtime.lastActivationID = graphActivationID
                runtime.lastFireFrame = frameID
            }
            fireOnLoadNodeRuntimeStates[sourceNode.id] = runtime
            return outputPort.name == "Value" ? ((runtime.lastFireFrame == frameID) ? 1.0 : 0.0) : nil
        case .counter:
            let settings = settings(forCounterNodeID: sourceNode.id)
            let trigger = sourceNode.inputPorts.first(where: { $0.name == "Trigger" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.trigger
            let reset = sourceNode.inputPorts.first(where: { $0.name == "Reset" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.reset
            let step = sourceNode.inputPorts.first(where: { $0.name == "Step" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.step
            let minimum = sourceNode.inputPorts.first(where: { $0.name == "Min" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.minimum
            let maximum = sourceNode.inputPorts.first(where: { $0.name == "Max" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.maximum
            let isTriggerHigh = trigger >= settings.threshold
            let isResetHigh = reset >= settings.threshold
            var runtime = counterNodeRuntimeStates[sourceNode.id] ?? CounterNodeRuntimeState(value: settings.initialValue)
            if isResetHigh && runtime.lastResetHigh == false {
                runtime.value = min(max(settings.initialValue, minimum), maximum)
            } else if isTriggerHigh && runtime.lastTriggerHigh == false {
                let nextValue = runtime.value + step
                if settings.wrap {
                    if nextValue > maximum {
                        runtime.value = minimum
                    } else if nextValue < minimum {
                        runtime.value = maximum
                    } else {
                        runtime.value = nextValue
                    }
                } else {
                    runtime.value = min(max(nextValue, minimum), maximum)
                }
            }
            runtime.lastTriggerHigh = isTriggerHigh
            runtime.lastResetHigh = isResetHigh
            counterNodeRuntimeStates[sourceNode.id] = runtime
            return outputPort.name == "Value" ? runtime.value : nil
        case .toggle:
            let settings = settings(forToggleNodeID: sourceNode.id)
            let trigger = sourceNode.inputPorts.first(where: { $0.name == "Trigger" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.trigger
            let reset = sourceNode.inputPorts.first(where: { $0.name == "Reset" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.reset
            let isTriggerHigh = trigger >= settings.threshold
            let isResetHigh = reset >= settings.threshold
            var runtime = toggleNodeRuntimeStates[sourceNode.id] ?? ToggleNodeRuntimeState(isOn: settings.initialOn)
            if isResetHigh && runtime.lastResetHigh == false {
                runtime.isOn = settings.initialOn
            } else if isTriggerHigh && runtime.lastTriggerHigh == false {
                runtime.isOn.toggle()
            }
            runtime.lastTriggerHigh = isTriggerHigh
            runtime.lastResetHigh = isResetHigh
            toggleNodeRuntimeStates[sourceNode.id] = runtime
            return outputPort.name == "Value" ? (runtime.isOn ? 1.0 : 0.0) : nil
        case .delay:
            let settings = settings(forDelayNodeID: sourceNode.id)
            let trigger = sourceNode.inputPorts.first(where: { $0.name == "Trigger" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.trigger
            let duration = sourceNode.inputPorts.first(where: { $0.name == "Duration" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.duration
            let isTriggerHigh = trigger >= settings.threshold
            let now = CACurrentMediaTime()
            let frameID = evaluationFrameID
            var runtime = delayNodeRuntimeStates[sourceNode.id] ?? DelayNodeRuntimeState()
            if isTriggerHigh && runtime.lastTriggerHigh == false {
                runtime.armedAt = now
                runtime.firedForArm = false
                runtime.outputFrame = nil
            }
            if let armedAt = runtime.armedAt,
               runtime.firedForArm == false,
               now - armedAt >= max(0.0, duration) {
                runtime.firedForArm = true
                runtime.outputFrame = frameID
            }
            runtime.lastTriggerHigh = isTriggerHigh
            delayNodeRuntimeStates[sourceNode.id] = runtime
            return outputPort.name == "Value" ? ((runtime.outputFrame == frameID) ? 1.0 : 0.0) : nil
        case .timer:
            let settings = settings(forTimerNodeID: sourceNode.id)
            if isGraphRunning == false {
                var runtime = timerNodeRuntimeStates[sourceNode.id] ?? TimerNodeRuntimeState()
                runtime.outputFrame = nil
                timerNodeRuntimeStates[sourceNode.id] = runtime
                return outputPort.name == "Value" ? 0.0 : nil
            }
            let enabled = sourceNode.inputPorts.first(where: { $0.name == "Enabled" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.enabled
            let interval = sourceNode.inputPorts.first(where: { $0.name == "Interval" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.interval
            let isEnabledHigh = enabled >= settings.threshold
            let safeInterval = max(0.01, interval)
            let frameID = evaluationFrameID
            var runtime = timerNodeRuntimeStates[sourceNode.id] ?? TimerNodeRuntimeState()
            if isEnabledHigh {
                let bucket = Int(floor(graphClockTime / safeInterval))
                if runtime.lastEnabledHigh == false {
                    runtime.lastBucket = bucket
                    runtime.outputFrame = nil
                } else if runtime.lastBucket != bucket {
                    runtime.lastBucket = bucket
                    runtime.outputFrame = frameID
                }
            } else {
                runtime.lastBucket = nil
                runtime.outputFrame = nil
            }
            runtime.lastEnabledHigh = isEnabledHigh
            timerNodeRuntimeStates[sourceNode.id] = runtime
            return outputPort.name == "Value" ? ((runtime.outputFrame == frameID) ? 1.0 : 0.0) : nil
        case .stringCompare:
            let settings = settings(forStringCompareNodeID: sourceNode.id)
            let left = sourceNode.inputPorts.first(where: { $0.name == "A" }).flatMap {
                stringValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.left
            let right = sourceNode.inputPorts.first(where: { $0.name == "B" }).flatMap {
                stringValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id])
            } ?? settings.right
            let lhs = settings.caseSensitive ? left : left.lowercased()
            let rhs = settings.caseSensitive ? right : right.lowercased()
            let result: Bool
            switch settings.operation {
            case .equal:
                result = lhs == rhs
            case .notEqual:
                result = lhs != rhs
            case .contains:
                result = lhs.contains(rhs)
            case .startsWith:
                result = lhs.hasPrefix(rhs)
            case .endsWith:
                result = lhs.hasSuffix(rhs)
            }
            return outputPort.name == "Result" ? (result ? 1.0 : 0.0) : nil
        case .button:
            switch outputPort.name {
            case "Pressed":
                return buttonPressedValue(for: sourceNode.id)
            case "Hover":
                return buttonHoverValue(for: sourceNode.id)
            default:
                return nil
            }
        case .handTracker:
            switch outputPort.name {
            case "Finger 1 Tracked":
                return handTrackedValue(isLeftHand: true)
            case "Finger 2 Tracked":
                return handTrackedValue(isLeftHand: false)
            default:
                return nil
            }
        case .sliderStyle:
            return nil
        case .buttonStyle:
            return nil
        case .slider:
            return outputPort.name == "Value" ? sliderValue(for: sourceNode.id) : nil
        case .hitZone:
            guard let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point" }) else {
                return nil
            }
            guard let point = resolvedPointValue(forInputPortID: pointInput.id) else {
                return outputPort.name == "Inside" ? 0.0 : nil
            }
            let settings = settings(forHitZoneNodeID: sourceNode.id)
            let centerInput = sourceNode.inputPorts.first(where: { $0.name == "Center" })
            let center = centerInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
                ?? CGPoint(x: settings.centerX, y: settings.centerY)
            let dx = Double(point.x - center.x)
            let dy = Double(point.y - center.y)
            let distance = sqrt((dx * dx) + (dy * dy))
            switch outputPort.name {
            case "Inside":
                return (distance >= settings.innerRadius && distance <= settings.outerRadius) ? 1.0 : 0.0
            case "Distance":
                return distance
            default:
                return nil
            }
        case .rectHit:
            guard let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point" }) else {
                return nil
            }
            guard let point = resolvedPointValue(forInputPortID: pointInput.id) else {
                return outputPort.name == "Inside" ? 0.0 : nil
            }
            let settings = settings(forRectHitNodeID: sourceNode.id)
            let centerInput = sourceNode.inputPorts.first(where: { $0.name == "Center" })
            let center = centerInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
                ?? CGPoint(x: settings.centerX, y: settings.centerY)
            let width = sourceNode.inputPorts.first(where: { $0.name == "Width" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.width
            let height = sourceNode.inputPorts.first(where: { $0.name == "Height" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.height
            let halfWidth = max(0.0, width) * 0.5
            let halfHeight = max(0.0, height) * 0.5
            let inside = abs(point.x - center.x) <= halfWidth && abs(point.y - center.y) <= halfHeight
            return outputPort.name == "Inside" ? (inside ? 1.0 : 0.0) : nil
        case .screenSize:
            let frame = NSScreen.main?.visibleFrame ?? .zero
            switch outputPort.name {
            case "Width":
                return Double(max(frame.width, 1.0))
            case "Height":
                return Double(max(frame.height, 1.0))
            case "Aspect":
                let width = max(Double(frame.width), 1.0)
                let height = max(Double(frame.height), 1.0)
                return width / height
            default:
                return nil
            }
        case .screenBounds:
            let frame = NSScreen.main?.visibleFrame ?? .zero
            let settings = screenBoundsNodeSettings[sourceNode.id] ?? ScreenBoundsNodeSettings()
            let width = max(Double(frame.width), 1.0)
            let height = max(Double(frame.height), 1.0)
            let left: Double
            let right: Double
            let bottom: Double
            let top: Double
            switch settings.mode {
            case .normalized:
                left = 0.0
                right = 1.0
                bottom = 0.0
                top = 1.0
            case .centered:
                left = -1.0
                right = 1.0
                bottom = -1.0
                top = 1.0
            case .pixels:
                left = 0.0
                right = width
                bottom = 0.0
                top = height
            }
            switch outputPort.name {
            case "Left": return left
            case "Right": return right
            case "Bottom": return bottom
            case "Top": return top
            case "Width": return right - left
            case "Height": return top - bottom
            case "Center X": return (left + right) * 0.5
            case "Center Y": return (bottom + top) * 0.5
            case "Aspect": return width / height
            default: return nil
            }
        case .renderBounds:
            let settings = renderBoundsNodeSettings[sourceNode.id] ?? RenderBoundsNodeSettings()
            let targetRenderID: GraphNode.ID? = {
                if let target = settings.targetRenderNodeID,
                   let node = document.nodes.first(where: { $0.id == target }),
                   case .renderOutput = node.kind {
                    return target
                }
                if let activePreviewRenderNodeID {
                    return activePreviewRenderNodeID
                }
                return renderOutputNodes().first?.id
            }()
            let contentSize = targetRenderID.flatMap { previewWindowContentSizes[$0] } ?? CGSize(width: 960, height: 640)
            let width: Double = Swift.max(Double(contentSize.width), 1.0)
            let height: Double = Swift.max(Double(contentSize.height), 1.0)
            switch outputPort.name {
            case "Left": return 0.0
            case "Right": return width
            case "Bottom": return 0.0
            case "Top": return height
            case "Width": return width
            case "Height": return height
            case "Center X": return width * 0.5
            case "Center Y": return height * 0.5
            case "Aspect": return width / height
            default: return nil
            }
        case .gridLayout:
            let settings = settings(forGridLayoutNodeID: sourceNode.id)
            let index = sourceNode.inputPorts.first(where: { $0.name == "Index" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.index
            let columns = sourceNode.inputPorts.first(where: { $0.name == "Columns" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.columns
            let originX = sourceNode.inputPorts.first(where: { $0.name == "Origin X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.originX
            let originY = sourceNode.inputPorts.first(where: { $0.name == "Origin Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.originY
            let spacingX = sourceNode.inputPorts.first(where: { $0.name == "Spacing X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.spacingX
            let spacingY = sourceNode.inputPorts.first(where: { $0.name == "Spacing Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.spacingY
            let resolvedColumns = max(1, Int(columns.rounded()))
            let resolvedIndex = max(0, Int(index.rounded()))
            let column = resolvedIndex % resolvedColumns
            let row = resolvedIndex / resolvedColumns
            switch outputPort.name {
            case "X":
                return originX + (Double(column) * spacingX)
            case "Y":
                return originY + (Double(row) * spacingY)
            case "Column":
                return Double(column)
            case "Row":
                return Double(row)
            default:
                return nil
            }
        case .hold:
            let settings = settings(forHoldNodeID: sourceNode.id)
            let gateInput = sourceNode.inputPorts.first(where: { $0.name == "Gate" })
            let valueInput = sourceNode.inputPorts.first(where: { $0.name == "Value" })
            let hasGateConnection = gateInput.map { gatePort in
                document.connections.contains(where: { $0.toPortID == gatePort.id })
            } ?? false
            let gate = gateInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id]) } ?? 0.0
            let incomingValue = valueInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: [sourceNode.id]) }
            let currentHeld = holdNodeRuntimeStates[sourceNode.id]?.heldValue ?? settings.initialValue
            if !hasGateConnection, let incomingValue {
                holdNodeRuntimeStates[sourceNode.id] = HoldNodeRuntimeState(heldValue: incomingValue)
                return incomingValue
            }
            if gate >= settings.threshold, let incomingValue {
                holdNodeRuntimeStates[sourceNode.id] = HoldNodeRuntimeState(heldValue: incomingValue)
                return incomingValue
            }
            holdNodeRuntimeStates[sourceNode.id] = HoldNodeRuntimeState(heldValue: currentHeld)
            return currentHeld
        case .scalarSmooth:
            return scalarSmoothValue(for: sourceNode, visitedNodeIDs: [sourceNode.id])
        case .scale:
            guard let valueInput = sourceNode.inputPorts.first(where: { $0.name == "Value" }),
                  let incomingValue = scalarValue(forInputPortID: valueInput.id, visitedNodeIDs: [sourceNode.id]) else {
                return nil
            }
            let settings = settings(forScaleNodeID: sourceNode.id)
            let minInput = sourceNode.inputPorts.first(where: { $0.name == "Min" })
            let maxInput = sourceNode.inputPorts.first(where: { $0.name == "Max" })
            let scaledMinInput = sourceNode.inputPorts.first(where: { $0.name == "Scaled Min" })
            let scaledMaxInput = sourceNode.inputPorts.first(where: { $0.name == "Scaled Max" })
            let minValue = minInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.min
            let maxValue = maxInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.max
            let scaledMinValue = scaledMinInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scaledMin
            let scaledMaxValue = scaledMaxInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scaledMax
            let denominator = maxValue - minValue
            guard abs(denominator) > .ulpOfOne else {
                return scaledMinValue
            }
            return scaledMinValue + ((incomingValue - minValue) * (scaledMaxValue - scaledMinValue) / denominator)
        case .interpolator:
            let settings = settings(forInterpolatorNodeID: sourceNode.id)
            let duration = max(settings.duration, 0.0001)
            let elapsed = max(0.0, graphClockTime + settings.phase)
            let normalizedTime = elapsed / duration
            let cyclePosition: Double
            if settings.autoreverses {
                let wrapped = normalizedTime.truncatingRemainder(dividingBy: 2.0)
                cyclePosition = wrapped <= 1.0 ? wrapped : (2.0 - wrapped)
            } else {
                cyclePosition = normalizedTime.truncatingRemainder(dividingBy: 1.0)
            }

            let easedProgress: Double
            switch settings.easing {
            case .linear:
                easedProgress = cyclePosition
            case .easeIn:
                easedProgress = cyclePosition * cyclePosition
            case .easeOut:
                let inverse = 1.0 - cyclePosition
                easedProgress = 1.0 - (inverse * inverse)
            case .easeInOut:
                if cyclePosition < 0.5 {
                    easedProgress = 2.0 * cyclePosition * cyclePosition
                } else {
                    let inverse = -2.0 * cyclePosition + 2.0
                    easedProgress = 1.0 - ((inverse * inverse) / 2.0)
                }
            }

            return settings.start + ((settings.end - settings.start) * easedProgress)
        case .polar:
            guard let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point" }),
                  let point = resolvedPointValue(forInputPortID: pointInput.id) else {
                return nil
            }
            let settings = settings(forPolarNodeID: sourceNode.id)
            let centerInput = sourceNode.inputPorts.first(where: { $0.name == "Center" })
            let center = centerInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
                ?? CGPoint(x: settings.centerX, y: settings.centerY)
            let dx = Double(point.x - center.x)
            let dy = Double(point.y - center.y)
            let rawAngle = atan2(dy, dx)
            var degrees = rawAngle * 180.0 / .pi
            if settings.clockwise {
                degrees = -degrees
            }
            degrees += settings.angleOffsetDegrees
            degrees.formTruncatingRemainder(dividingBy: 360.0)
            if degrees < 0 {
                degrees += 360.0
            }
            switch outputPort.name {
            case "Angle":
                return degrees * .pi / 180.0
            case "Degrees":
                return degrees
            case "Normalized":
                return degrees / 360.0
            case "Radius":
                return sqrt((dx * dx) + (dy * dy))
            default:
                return nil
            }
        default:
            return nil
        }
    }

    private func colorValue(forInputPortID portID: GraphPort.ID, visitedNodeIDs: Set<GraphNode.ID>) -> SIMD4<Float>? {
        guard let inputPort = port(withID: portID) else {
            return nil
        }

        if effectiveIncomingConnection(for: inputPort.id) == nil,
           let inputNode = document.nodes.first(where: { $0.id == inputPort.nodeID }),
           case .colorSplit = inputNode.kind,
           inputPort.name == "Color" {
            return colorFromSettings(settings(forColorNodeID: inputNode.id))
        }

        guard
            let connection = effectiveIncomingConnection(for: inputPort.id),
            let sourcePort = resolvedSourcePort(for: connection.fromPortID)
        else {
            return nil
        }

        guard case .colorSignal = sourcePort.kind,
              let sourceNode = document.nodes.first(where: { $0.id == sourcePort.nodeID }),
              !visitedNodeIDs.contains(sourceNode.id)
        else {
            return nil
        }

        switch sourceNode.kind {
        case .color:
            return colorFromSettings(settings(forColorNodeID: sourceNode.id))
        case .hslColor:
            return colorValueForOutputPort(sourcePort)
        case .colorArrayIndex:
            return colorValueForOutputPort(sourcePort)
        case .colorSwitch:
            return colorValueForOutputPort(sourcePort)
        case .colorMultiplexor:
            return colorValueForOutputPort(sourcePort)
        default:
            return nil
        }
    }

