    private func scalarValue(forInputPortID portID: GraphPort.ID, visitedNodeIDs: Set<GraphNode.ID>) -> Double? {
        guard
            let connection = effectiveIncomingConnection(for: portID),
            let sourcePort = resolvedSourcePort(for: connection.fromPortID)
        else {
            return nil
        }

        switch sourcePort.kind {
        case .audio(let signal):
            return audioValue(for: signal)
        case .uniform(let uniformID):
            guard
                let uniform = currentUniform(matching: uniformID),
                case .float(let value) = uniform.defaultValue
            else {
                return nil
            }
            return value
        case .stringSignal, .colorSignal, .point3Signal, .point4Signal, .scalarArraySignal, .stringArraySignal, .colorArraySignal, .imageArraySignal, .lightSignal, .materialSignal, .scene3DSignal, .oscPacketSignal:
            return nil
        case .scalarSignal:
            guard let sourceNode = document.nodes.first(where: { $0.id == sourcePort.nodeID }) else {
                return nil
            }
            guard !visitedNodeIDs.contains(sourceNode.id) else {
                return nil
            }
            switch sourceNode.kind {
            case .iteratorVariables:
                guard let context = iteratorEvaluationStack.last ?? iteratorVariableRuntimeContexts[sourceNode.id] else {
                    return nil
                }
                switch sourcePort.name {
                case "Index":
                    return Double(context.index)
                case "Progress":
                    return context.progress
                case "Iterations":
                    return Double(context.iterations)
                default:
                    return nil
                }
            case .scalarVariable:
                return settings(forScalarVariableNodeID: sourceNode.id).value
            case .mouse:
                switch sourcePort.name {
                case "Left Click":
                    return currentMouseLeftButtonDown ? 1.0 : 0.0
                case "Right Click":
                    return currentMouseRightButtonDown ? 1.0 : 0.0
                default:
                    return nil
                }
            case .keyboard:
                let settings = settings(forKeyboardNodeID: sourceNode.id)
                let modifiers = currentKeyboardModifierFlags
                let matches =
                    currentPressedKeyCodes.contains(settings.key.keyCode) &&
                    modifiers.contains(.command) == settings.requiresCommand &&
                    modifiers.contains(.option) == settings.requiresOption &&
                    modifiers.contains(.shift) == settings.requiresShift &&
                    modifiers.contains(.control) == settings.requiresControl
                switch sourcePort.name {
                case "Pressed":
                    return matches ? 1.0 : 0.0
                default:
                    return nil
                }
            case .scroll:
                switch sourcePort.name {
                case "X":
                    return currentScrollPosition.x
                case "Y":
                    return currentScrollPosition.y
                case "Active":
                    return isScrollActive ? 1.0 : 0.0
                default:
                    return nil
                }
            case .pinch:
                guard let fingerInput = sourceNode.inputPorts.first(where: { $0.name == "Finger" }),
                      let thumbInput = sourceNode.inputPorts.first(where: { $0.name == "Thumb" }),
                      let finger = resolvedPointValue(forInputPortID: fingerInput.id),
                      let thumb = resolvedPointValue(forInputPortID: thumbInput.id) else {
                    return sourcePort.name == "Pinched" ? 0.0 : nil
                }
                let threshold = settings(forPinchNodeID: sourceNode.id).threshold
                let dx = Double(finger.x - thumb.x)
                let dy = Double(finger.y - thumb.y)
                let distance = sqrt((dx * dx) + (dy * dy))
                switch sourcePort.name {
                case "Distance":
                    return distance
                case "Strength":
                    guard threshold > 0.0001 else { return 0.0 }
                    return max(0.0, min(1.0, 1.0 - (distance / threshold)))
                case "Pinched":
                    return distance <= threshold ? 1.0 : 0.0
                default:
                    return nil
                }
            case .pointSplit:
                guard
                    let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point" }),
                    let point = resolvedPointValue(forInputPortID: pointInput.id)
                else {
                    return nil
                }
                switch sourcePort.name {
                case "X":
                    return point.x
                case "Y":
                    return point.y
                default:
                    return nil
                }
            case .point3Split:
                guard
                    let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point3" }),
                    let point = resolvedPoint3Value(forInputPortID: pointInput.id)
                else {
                    return nil
                }
                switch sourcePort.name {
                case "X":
                    return point.x
                case "Y":
                    return point.y
                case "Z":
                    return point.z
                default:
                    return nil
                }
            case .point4Split:
                guard
                    let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point4" }),
                    let point = resolvedPoint4Value(forInputPortID: pointInput.id)
                else {
                    return nil
                }
                switch sourcePort.name {
                case "X":
                    return point.x
                case "Y":
                    return point.y
                case "Z":
                    return point.z
                case "W":
                    return point.w
                default:
                    return nil
                }
            case .scrollGesture:
                let settings = settings(forScrollGestureNodeID: sourceNode.id)
                let pointAInput = sourceNode.inputPorts.first(where: { $0.name == "Point A" })
                let pointBInput = sourceNode.inputPorts.first(where: { $0.name == "Point B" })
                let engageInput = sourceNode.inputPorts.first(where: { $0.name == "Engage" })
                let pointA = pointAInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
                let pointB = pointBInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
                let gate = engageInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) } ?? 0.0
                let hasGateConnection = engageInput.map { gatePort in
                    document.connections.contains(where: { $0.toPortID == gatePort.id })
                } ?? false
                var runtime = scrollGestureNodeRuntimeStates[sourceNode.id] ?? ScrollGestureNodeRuntimeState()
                let center = pointB.map { midpoint(pointA, Optional($0)) } ?? pointA
                let engaged = center != nil && (!hasGateConnection || gate >= settings.threshold)
                if engaged, let center {
                    if let previous = runtime.lastCenter {
                        let deltaY = Double(center.y - previous.y) * settings.sensitivity * (settings.invertY ? -1.0 : 1.0)
                        runtime.accumulatedY += deltaY
                    }
                    runtime.lastCenter = center
                } else {
                    runtime.lastCenter = nil
                }
                runtime.isEngaged = engaged
                scrollGestureNodeRuntimeStates[sourceNode.id] = runtime
                return sourcePort.name == "Y" ? runtime.accumulatedY : nil
            case .zoomGesture:
                let settings = settings(forZoomGestureNodeID: sourceNode.id)
                let pointAInput = sourceNode.inputPorts.first(where: { $0.name == "Point A" })
                let pointBInput = sourceNode.inputPorts.first(where: { $0.name == "Point B" })
                let engageInput = sourceNode.inputPorts.first(where: { $0.name == "Engage" })
                let pointA = pointAInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
                let pointB = pointBInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
                let gate = engageInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) } ?? 0.0
                let hasGateConnection = engageInput.map { gatePort in
                    document.connections.contains(where: { $0.toPortID == gatePort.id })
                } ?? false
                var runtime = zoomGestureNodeRuntimeStates[sourceNode.id] ?? ZoomGestureNodeRuntimeState(zoom: settings.initialZoom)
                let distance = pointA.flatMap { a in pointB.map { b in
                    let dx = Double(a.x - b.x)
                    let dy = Double(a.y - b.y)
                    return sqrt((dx * dx) + (dy * dy))
                }}
                let engaged = distance != nil && (!hasGateConnection || gate >= settings.threshold)
                if engaged, let distance {
                    if let previous = runtime.lastDistance {
                        let delta = (distance - previous) * settings.sensitivity
                        runtime.zoom = min(max(runtime.zoom + delta, settings.minZoom), settings.maxZoom)
                    } else {
                        runtime.zoom = min(max(runtime.zoom, settings.minZoom), settings.maxZoom)
                    }
                    runtime.lastDistance = distance
                } else {
                    runtime.lastDistance = nil
                }
                runtime.isEngaged = engaged
                zoomGestureNodeRuntimeStates[sourceNode.id] = runtime
                return sourcePort.name == "Zoom" ? runtime.zoom : nil
            case .trackball:
                let settings = settings(forTrackballNodeID: sourceNode.id)
                var runtime = trackballNodeRuntimeStates[sourceNode.id] ?? TrackballNodeRuntimeState(
                    orbit: settings.initialOrbit,
                    pitch: settings.initialPitch,
                    rotationX: settings.initialPitch,
                    rotationY: settings.initialOrbit,
                    panX: settings.initialPanX,
                    panY: settings.initialPanY,
                    distance: settings.initialDistance
                )
                let modifiers = currentKeyboardModifierFlags
                let panDragging = currentMouseLeftButtonDown && currentMousePosition != nil && modifiers.contains(.option) && modifiers.contains(.shift)
                let orbitDragging = currentMouseLeftButtonDown && currentMousePosition != nil && panDragging == false
                let dragging = orbitDragging || panDragging
                if dragging, let mousePosition = currentMousePosition {
                    if let previous = runtime.lastMousePosition {
                        let deltaX = Double(mousePosition.x - previous.x)
                        let deltaY = Double(mousePosition.y - previous.y)
                        let verticalScale = (settings.invertY ? 1.0 : -1.0)
                        if panDragging {
                            // Keep pan in stable scene units. Scaling by camera distance made
                            // large 3D/splat scenes jump by tens of units per drag.
                            let panScale = settings.panSensitivity * 2.0
                            runtime.panX -= deltaX * panScale
                            runtime.panY += deltaY * panScale * verticalScale
                        } else {
                            runtime.orbit += deltaX * 360.0 * settings.sensitivity
                            runtime.pitch += deltaY * 180.0 * settings.sensitivity * verticalScale
                            runtime.pitch = min(max(runtime.pitch, -89.0), 89.0)
                            runtime.rotationY += deltaX * 360.0 * settings.sensitivity
                            runtime.rotationX += deltaY * 180.0 * settings.sensitivity * verticalScale
                        }
                    }
                    runtime.lastMousePosition = mousePosition
                } else {
                    runtime.lastMousePosition = nil
                }
                let scrollDeltaY = currentScrollPosition.y - runtime.lastScrollPosition.y
                if abs(scrollDeltaY) > 0.0001 {
                    runtime.distance -= scrollDeltaY * settings.zoomSensitivity
                    runtime.distance = min(max(runtime.distance, settings.minDistance), settings.maxDistance)
                    runtime.lastDistanceScrollTime = CACurrentMediaTime()
                    runtime.lastScrollPosition = currentScrollPosition
                } else {
                    runtime.lastScrollPosition = currentScrollPosition
                }
                runtime.isDragging = dragging
                trackballNodeRuntimeStates[sourceNode.id] = runtime
                switch sourcePort.name {
                case "Orbit":
                    return runtime.orbit
                case "Pitch":
                    return runtime.pitch
                case "Pan X":
                    return runtime.panX
                case "Pan Y":
                    return runtime.panY
                case "Distance":
                    return runtime.distance
                case "Rotation X":
                    return runtime.rotationX
                case "Rotation Y":
                    return runtime.rotationY
                case "Dragging":
                    return runtime.isDragging ? 1.0 : 0.0
                case "Scroll Active":
                    if let lastDistanceScrollTime = runtime.lastDistanceScrollTime,
                       CACurrentMediaTime() - lastDistanceScrollTime < 0.35 {
                        return 1.0
                    }
                    return 0.0
                default:
                    return nil
                }
            case .depthEstimate:
                return depthEstimateOutput(from: sourceNode, outputName: sourcePort.name, visitedNodeIDs: visitedNodeIDs)
            case .math:
                let settings = settings(forMathNodeID: sourceNode.id)
                let a = sourceNode.inputPorts.first(where: { $0.name == "A" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.a
                let b = sourceNode.inputPorts.first(where: { $0.name == "B" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.b
                let result: Double
                switch settings.operation {
                case .add:
                    result = a + b
                case .subtract:
                    result = a - b
                case .multiply:
                    result = a * b
                case .divide:
                    result = abs(b) > .ulpOfOne ? (a / b) : 0.0
                case .minimum:
                    result = min(a, b)
                case .maximum:
                    result = max(a, b)
                case .power:
                    result = Foundation.pow(a, b)
                case .sine:
                    result = Foundation.sin(a)
                case .cosine:
                    result = Foundation.cos(a)
                case .round:
                    result = a.rounded()
                case .floor:
                    result = Foundation.floor(a)
                case .ceil:
                    result = Foundation.ceil(a)
                }
                return sourcePort.name == "Result" ? result : nil
            case .expression:
                guard sourcePort.name == "Result" else { return nil }
                let settings = settings(forExpressionNodeID: sourceNode.id)
                return evaluateExpressionNode(sourceNode, settings: settings, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
            case .scalarSwitch:
                let settings = settings(forSelectNodeID: sourceNode.id)
                let selectValue = sourceNode.inputPorts.first(where: { $0.name == "Select" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.selectValue
                let selectedName = selectValue >= settings.threshold ? "B" : "A"
                return sourceNode.inputPorts.first(where: { $0.name == selectedName }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                }
            case .clamp:
                let settings = settings(forClampNodeID: sourceNode.id)
                let value = sourceNode.inputPorts.first(where: { $0.name == "Value" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? 0.0
                let minimum = sourceNode.inputPorts.first(where: { $0.name == "Min" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.minimum
                let maximum = sourceNode.inputPorts.first(where: { $0.name == "Max" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.maximum
                let lower = min(minimum, maximum)
                let upper = max(minimum, maximum)
                return sourcePort.name == "Result" ? min(max(value, lower), upper) : nil
            case .mapRange:
                let settings = settings(forMapRangeNodeID: sourceNode.id)
                let value = sourceNode.inputPorts.first(where: { $0.name == "Value" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? 0.0
                let inputMinimum = sourceNode.inputPorts.first(where: { $0.name == "In Min" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.inputMinimum
                let inputMaximum = sourceNode.inputPorts.first(where: { $0.name == "In Max" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.inputMaximum
                let outputMinimum = sourceNode.inputPorts.first(where: { $0.name == "Out Min" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.outputMinimum
                let outputMaximum = sourceNode.inputPorts.first(where: { $0.name == "Out Max" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.outputMaximum
                let denominator = inputMaximum - inputMinimum
                let result: Double
                if abs(denominator) > .ulpOfOne {
                    result = outputMinimum + ((value - inputMinimum) * (outputMaximum - outputMinimum) / denominator)
                } else {
                    result = outputMinimum
                }
                return sourcePort.name == "Result" ? result : nil
            case .logic:
                let settings = settings(forLogicNodeID: sourceNode.id)
                let a = sourceNode.inputPorts.first(where: { $0.name == "A" }).flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) } ?? 0.0
                let b = sourceNode.inputPorts.first(where: { $0.name == "B" }).flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) } ?? 0.0
                let aBool = a >= settings.threshold
                let bBool = b >= settings.threshold
                let result: Bool
                switch settings.operation {
                case .and:
                    result = aBool && bBool
                case .or:
                    result = aBool || bBool
                case .xor:
                    result = aBool != bBool
                case .not:
                    result = !aBool
                }
                return sourcePort.name == "Value" ? (result ? 1.0 : 0.0) : nil
            case .compare:
                let settings = settings(forCompareNodeID: sourceNode.id)
                let value = sourceNode.inputPorts.first(where: { $0.name == "Value" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? 0.0
                let referenceValue = sourceNode.inputPorts.first(where: { $0.name == "Number" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.referenceValue
                let threshold = sourceNode.inputPorts.first(where: { $0.name == "Threshold" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.epsilon
                let result: Bool
                switch settings.operation {
                case .lessThan:
                    result = value < referenceValue
                case .lessThanOrEqual:
                    result = value <= referenceValue
                case .greaterThan:
                    result = value > referenceValue
                case .greaterThanOrEqual:
                    result = value >= referenceValue
                case .equal:
                    result = abs(value - referenceValue) <= threshold
                case .notEqual:
                    result = abs(value - referenceValue) > threshold
                }
                return sourcePort.name == "Result" ? (result ? 1.0 : 0.0) : nil
            case .beatDetect:
                return beatDetectValue(for: sourceNode.id, outputName: sourcePort.name)
            case .random:
                return sourcePort.name == "Value" ? resolvedRandomOutput(for: sourceNode, visitedNodeIDs: visitedNodeIDs) : nil
            case .pulse:
                let settings = settings(forPulseNodeID: sourceNode.id)
                let gateValue = sourceNode.inputPorts.first(where: { $0.name == "Gate" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.gate
                let isGateHigh = gateValue >= settings.threshold
                let frameID = evaluationFrameID
                var runtime = pulseNodeRuntimeStates[sourceNode.id] ?? PulseNodeRuntimeState()
                if isGateHigh && runtime.lastGateHigh == false {
                    runtime.lastRiseFrame = frameID
                } else if isGateHigh == false, runtime.lastRiseFrame != frameID {
                    runtime.lastRiseFrame = nil
                }
                runtime.lastGateHigh = isGateHigh
                pulseNodeRuntimeStates[sourceNode.id] = runtime
                return sourcePort.name == "Value" ? ((runtime.lastRiseFrame == frameID) ? 1.0 : 0.0) : nil
            case .fireOnLoad:
                let frameID = evaluationFrameID
                var runtime = fireOnLoadNodeRuntimeStates[sourceNode.id] ?? FireOnLoadNodeRuntimeState()
                if runtime.lastActivationID != graphActivationID {
                    runtime.lastActivationID = graphActivationID
                    runtime.lastFireFrame = frameID
                }
                fireOnLoadNodeRuntimeStates[sourceNode.id] = runtime
                return sourcePort.name == "Value" ? ((runtime.lastFireFrame == frameID) ? 1.0 : 0.0) : nil
            case .counter:
                let settings = settings(forCounterNodeID: sourceNode.id)
                let trigger = sourceNode.inputPorts.first(where: { $0.name == "Trigger" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.trigger
                let reset = sourceNode.inputPorts.first(where: { $0.name == "Reset" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.reset
                let step = sourceNode.inputPorts.first(where: { $0.name == "Step" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.step
                let minimum = sourceNode.inputPorts.first(where: { $0.name == "Min" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.minimum
                let maximum = sourceNode.inputPorts.first(where: { $0.name == "Max" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.maximum
                let isTriggerHigh = trigger >= settings.threshold
                let isResetHigh = reset >= settings.threshold
                var runtime = counterNodeRuntimeStates[sourceNode.id] ?? CounterNodeRuntimeState(value: settings.initialValue)
                if isResetHigh && runtime.lastResetHigh == false {
                    runtime.value = min(max(settings.initialValue, minimum), maximum)
                } else if isTriggerHigh && runtime.lastTriggerHigh == false {
                    let nextValue = runtime.value + step
                    if settings.wrap {
                        if nextValue > maximum {
                            runtime.value = minimum
                        } else if nextValue < minimum {
                            runtime.value = maximum
                        } else {
