                        }
                    } else {
                        runtime.value = min(max(nextValue, minimum), maximum)
                    }
                }
                runtime.lastTriggerHigh = isTriggerHigh
                runtime.lastResetHigh = isResetHigh
                counterNodeRuntimeStates[sourceNode.id] = runtime
                return sourcePort.name == "Value" ? runtime.value : nil
            case .toggle:
                let settings = settings(forToggleNodeID: sourceNode.id)
                let trigger = sourceNode.inputPorts.first(where: { $0.name == "Trigger" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.trigger
                let reset = sourceNode.inputPorts.first(where: { $0.name == "Reset" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.reset
                let isTriggerHigh = trigger >= settings.threshold
                let isResetHigh = reset >= settings.threshold
                var runtime = toggleNodeRuntimeStates[sourceNode.id] ?? ToggleNodeRuntimeState(isOn: settings.initialOn)
                if isResetHigh && runtime.lastResetHigh == false {
                    runtime.isOn = settings.initialOn
                } else if isTriggerHigh && runtime.lastTriggerHigh == false {
                    runtime.isOn.toggle()
                }
                runtime.lastTriggerHigh = isTriggerHigh
                runtime.lastResetHigh = isResetHigh
                toggleNodeRuntimeStates[sourceNode.id] = runtime
                return sourcePort.name == "Value" ? (runtime.isOn ? 1.0 : 0.0) : nil
            case .delay:
                let settings = settings(forDelayNodeID: sourceNode.id)
                let trigger = sourceNode.inputPorts.first(where: { $0.name == "Trigger" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.trigger
                let duration = sourceNode.inputPorts.first(where: { $0.name == "Duration" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.duration
                let isTriggerHigh = trigger >= settings.threshold
                let now = CACurrentMediaTime()
                let frameID = evaluationFrameID
                var runtime = delayNodeRuntimeStates[sourceNode.id] ?? DelayNodeRuntimeState()
                if isTriggerHigh && runtime.lastTriggerHigh == false {
                    runtime.armedAt = now
                    runtime.firedForArm = false
                    runtime.outputFrame = nil
                }
                if let armedAt = runtime.armedAt,
                   runtime.firedForArm == false,
                   now - armedAt >= max(0.0, duration) {
                    runtime.firedForArm = true
                    runtime.outputFrame = frameID
                }
                runtime.lastTriggerHigh = isTriggerHigh
                delayNodeRuntimeStates[sourceNode.id] = runtime
                return sourcePort.name == "Value" ? ((runtime.outputFrame == frameID) ? 1.0 : 0.0) : nil
            case .timer:
                let settings = settings(forTimerNodeID: sourceNode.id)
                if isGraphRunning == false {
                    var runtime = timerNodeRuntimeStates[sourceNode.id] ?? TimerNodeRuntimeState()
                    runtime.outputFrame = nil
                    timerNodeRuntimeStates[sourceNode.id] = runtime
                    return sourcePort.name == "Value" ? 0.0 : nil
                }
                let enabled = sourceNode.inputPorts.first(where: { $0.name == "Enabled" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.enabled
                let interval = sourceNode.inputPorts.first(where: { $0.name == "Interval" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.interval
                let isEnabledHigh = enabled >= settings.threshold
                let safeInterval = max(0.01, interval)
                let frameID = evaluationFrameID
                var runtime = timerNodeRuntimeStates[sourceNode.id] ?? TimerNodeRuntimeState()
                if isEnabledHigh {
                    let bucket = Int(floor(graphClockTime / safeInterval))
                    if runtime.lastEnabledHigh == false {
                        runtime.lastBucket = bucket
                        runtime.outputFrame = nil
                    } else if runtime.lastBucket != bucket {
                        runtime.lastBucket = bucket
                        runtime.outputFrame = frameID
                    }
                } else {
                    runtime.lastBucket = nil
                    runtime.outputFrame = nil
                }
                runtime.lastEnabledHigh = isEnabledHigh
                timerNodeRuntimeStates[sourceNode.id] = runtime
                return sourcePort.name == "Value" ? ((runtime.outputFrame == frameID) ? 1.0 : 0.0) : nil
            case .stringCompare:
                let settings = settings(forStringCompareNodeID: sourceNode.id)
                let left = sourceNode.inputPorts.first(where: { $0.name == "A" }).flatMap {
                    stringValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.left
                let right = sourceNode.inputPorts.first(where: { $0.name == "B" }).flatMap {
                    stringValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.right
                let lhs = settings.caseSensitive ? left : left.lowercased()
                let rhs = settings.caseSensitive ? right : right.lowercased()
                let result: Bool
                switch settings.operation {
                case .equal:
                    result = lhs == rhs
                case .notEqual:
                    result = lhs != rhs
                case .contains:
                    result = lhs.contains(rhs)
                case .startsWith:
                    result = lhs.hasPrefix(rhs)
                case .endsWith:
                    result = lhs.hasSuffix(rhs)
                }
                return sourcePort.name == "Result" ? (result ? 1.0 : 0.0) : nil
            case .button:
                switch sourcePort.name {
                case "Pressed":
                    return buttonPressedValue(for: sourceNode.id)
                case "Hover":
                    return buttonHoverValue(for: sourceNode.id)
                default:
                    return nil
                }
            case .handTracker:
                switch sourcePort.name {
                case "Finger 1 Tracked":
                    return handTrackedValue(isLeftHand: true)
                case "Finger 2 Tracked":
                    return handTrackedValue(isLeftHand: false)
                default:
                    return nil
                }
            case .sliderStyle:
                return nil
            case .buttonStyle:
                return nil
            case .slider:
                return sourcePort.name == "Value" ? sliderValue(for: sourceNode.id) : nil
            case .hold:
                let settings = settings(forHoldNodeID: sourceNode.id)
                let gateInput = sourceNode.inputPorts.first(where: { $0.name == "Gate" })
                let valueInput = sourceNode.inputPorts.first(where: { $0.name == "Value" })
                let hasGateConnection = gateInput.map { gatePort in
                    document.connections.contains(where: { $0.toPortID == gatePort.id })
                } ?? false
                let gate = gateInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) } ?? 0.0
                let incomingValue = valueInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) }
                let currentHeld = holdNodeRuntimeStates[sourceNode.id]?.heldValue ?? settings.initialValue
                if !hasGateConnection, let incomingValue {
                    holdNodeRuntimeStates[sourceNode.id] = HoldNodeRuntimeState(heldValue: incomingValue)
                    return incomingValue
                }
                if gate >= settings.threshold, let incomingValue {
                    holdNodeRuntimeStates[sourceNode.id] = HoldNodeRuntimeState(heldValue: incomingValue)
                    return incomingValue
                }
                holdNodeRuntimeStates[sourceNode.id] = HoldNodeRuntimeState(heldValue: currentHeld)
                return currentHeld
            case .scalarSmooth:
                return scalarSmoothValue(for: sourceNode, visitedNodeIDs: visitedNodeIDs)
            case .scalarArrayIndex:
                let settings = settings(forScalarArrayIndexNodeID: sourceNode.id)
                guard
                    let arrayInput = sourceNode.inputPorts.first(where: { $0.name == "Array" }),
                    let values = scalarArrayValue(forInputPortID: arrayInput.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])),
                    values.isEmpty == false
                else {
                    return nil
                }
                let index = sourceNode.inputPorts.first(where: { $0.name == "Index" }).flatMap {
                    scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? settings.index
                let resolvedIndex = min(max(Int(index.rounded()), 0), values.count - 1)
                return values[resolvedIndex]
            case .arrayCount:
                guard let arrayInput = sourceNode.inputPorts.first(where: { $0.name == "Array" }) else {
                    return 0
                }
                if let connection = effectiveIncomingConnection(for: arrayInput.id),
                   let sourcePort = resolvedSourcePort(for: connection.fromPortID),
                   case .imageArraySignal = sourcePort.kind,
                   let arrayNode = document.nodes.first(where: { $0.id == sourcePort.nodeID }) {
                    return Double(settings(forImageArrayNodeID: arrayNode.id).count)
                }
                if let values = scalarArrayValue(forInputPortID: arrayInput.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) {
                    return Double(values.count)
                }
                if let values = stringArrayValue(forInputPortID: arrayInput.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) {
                    return Double(values.count)
                }
                if let values = colorArrayValue(forInputPortID: arrayInput.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) {
                    return Double(values.count)
                }
                if let connection = effectiveIncomingConnection(for: arrayInput.id),
                   let sourcePort = resolvedSourcePort(for: connection.fromPortID),
                   case .imageArraySignal = sourcePort.kind {
                    return 0
                }
                return 0
            case .scale:
                guard
                    let valueInput = sourceNode.inputPorts.first(where: { $0.name == "Value" }),
                    let incomingValue = scalarValue(forInputPortID: valueInput.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                else {
                    return nil
                }
                let settings = settings(forScaleNodeID: sourceNode.id)
                let minInput = sourceNode.inputPorts.first(where: { $0.name == "Min" })
                let maxInput = sourceNode.inputPorts.first(where: { $0.name == "Max" })
                let scaledMinInput = sourceNode.inputPorts.first(where: { $0.name == "Scaled Min" })
                let scaledMaxInput = sourceNode.inputPorts.first(where: { $0.name == "Scaled Max" })
                let minValue = minInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) } ?? settings.min
                let maxValue = maxInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) } ?? settings.max
                let scaledMinValue = scaledMinInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) } ?? settings.scaledMin
                let scaledMaxValue = scaledMaxInput.flatMap { scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id])) } ?? settings.scaledMax
                let denominator = maxValue - minValue
                guard abs(denominator) > .ulpOfOne else {
                    return scaledMinValue
                }
                return scaledMinValue + ((incomingValue - minValue) * (scaledMaxValue - scaledMinValue) / denominator)
            case .interpolator:
                let settings = settings(forInterpolatorNodeID: sourceNode.id)
                let duration = max(settings.duration, 0.0001)
                let elapsed = max(0.0, graphClockTime + settings.phase)
                let normalizedTime = elapsed / duration
                let cyclePosition: Double
                if settings.autoreverses {
                    let wrapped = normalizedTime.truncatingRemainder(dividingBy: 2.0)
                    cyclePosition = wrapped <= 1.0 ? wrapped : (2.0 - wrapped)
                } else {
                    cyclePosition = normalizedTime.truncatingRemainder(dividingBy: 1.0)
                }

                let easedProgress: Double
                switch settings.easing {
                case .linear:
                    easedProgress = cyclePosition
                case .easeIn:
                    easedProgress = cyclePosition * cyclePosition
                case .easeOut:
                    let inverse = 1.0 - cyclePosition
                    easedProgress = 1.0 - (inverse * inverse)
                case .easeInOut:
                    if cyclePosition < 0.5 {
                        easedProgress = 2.0 * cyclePosition * cyclePosition
                    } else {
                        let inverse = -2.0 * cyclePosition + 2.0
                        easedProgress = 1.0 - ((inverse * inverse) / 2.0)
                    }
                }

                return settings.start + ((settings.end - settings.start) * easedProgress)
            case .polar:
                guard let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point" }),
                      let point = resolvedPointValue(forInputPortID: pointInput.id) else {
                    return nil
                }
                let settings = settings(forPolarNodeID: sourceNode.id)
                let centerInput = sourceNode.inputPorts.first(where: { $0.name == "Center" })
                let center = centerInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
                    ?? CGPoint(x: settings.centerX, y: settings.centerY)
                let dx = Double(point.x - center.x)
                let dy = Double(point.y - center.y)
                let rawAngle = atan2(dy, dx)
                var degrees = rawAngle * 180.0 / .pi
                if settings.clockwise {
                    degrees = -degrees
                }
                degrees += settings.angleOffsetDegrees
                degrees.formTruncatingRemainder(dividingBy: 360.0)
                if degrees < 0 {
                    degrees += 360.0
                }
                let normalized = degrees / 360.0
                let radians = normalized * (.pi * 2.0)

                switch sourcePort.name {
                case "Angle":
                    return radians
                case "Degrees":
                    return degrees
                case "Normalized":
                    return normalized
                case "Radius":
                    return sqrt((dx * dx) + (dy * dy))
                default:
                    return nil
                }
            case .hitZone:
                guard let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point" }) else {
                    return nil
                }
                guard let point = resolvedPointValue(forInputPortID: pointInput.id) else {
                    return sourcePort.name == "Inside" ? 0.0 : nil
                }
                let settings = settings(forHitZoneNodeID: sourceNode.id)
                let centerInput = sourceNode.inputPorts.first(where: { $0.name == "Center" })
                let center = centerInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
                    ?? CGPoint(x: settings.centerX, y: settings.centerY)
                let dx = Double(point.x - center.x)
                let dy = Double(point.y - center.y)
                let distance = sqrt((dx * dx) + (dy * dy))

                switch sourcePort.name {
                case "Inside":
                    return (distance >= settings.innerRadius && distance <= settings.outerRadius) ? 1.0 : 0.0
                case "Distance":
                    return distance
                default:
                    return nil
                }
            case .rectHit:
                return scalarValueForOutputPort(sourcePort)
            case .screenSize:
                return scalarValueForOutputPort(sourcePort)
            case .screenBounds:
                return scalarValueForOutputPort(sourcePort)
            case .renderBounds:
                return scalarValueForOutputPort(sourcePort)
            case .gridLayout:
                return scalarValueForOutputPort(sourcePort)
            default:
                return nil
            }
        case .pointSignal, .fragmentShader, .time, .sliderStyle, .buttonStyle:
            return nil
        }
    }

    private func stringValue(forInputPortID portID: GraphPort.ID, visitedNodeIDs: Set<GraphNode.ID>) -> String? {
        guard
            let connection = effectiveIncomingConnection(for: portID),
            let sourcePort = resolvedSourcePort(for: connection.fromPortID)
        else {
            return nil
        }

        if case .audio(let signal) = sourcePort.kind {
            return stringFromScalar(audioValue(for: signal))
        }

        if case .scalarSignal = sourcePort.kind {
            return scalarValueForOutputPort(sourcePort).map(stringFromScalar(_:))
        }

        if case .uniform(let uniformID) = sourcePort.kind,
           let uniform = currentUniform(matching: uniformID),
           case .float(let value) = uniform.defaultValue {
            return stringFromScalar(value)
        }

        guard case .stringSignal = sourcePort.kind else { return nil }
        guard let sourceNode = document.nodes.first(where: { $0.id == sourcePort.nodeID }) else { return nil }
        guard !visitedNodeIDs.contains(sourceNode.id) else { return nil }

        switch sourceNode.kind {
        case .stringVariable:
            return settings(forStringVariableNodeID: sourceNode.id).value
        case .string:
            return settings(forStringNodeID: sourceNode.id).value
        case .stringFormat:
            let settings = settings(forStringFormatNodeID: sourceNode.id)
            var result = settings.template
            for index in 0...3 {
                let inputName = "Text \(index + 1)"
                let replacement = sourceNode.inputPorts.first(where: { $0.name == inputName }).flatMap {
                    stringValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
                } ?? stringFormatFallbackText(for: index, settings: settings)
                result = result.replacingOccurrences(of: "{\(index)}", with: replacement)
            }
            return result
        case .stringSplit:
            let settings = settings(forStringSplitNodeID: sourceNode.id)
            let text = sourceNode.inputPorts.first(where: { $0.name == "Text" }).flatMap {
                stringValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
            } ?? settings.text
            let index = sourceNode.inputPorts.first(where: { $0.name == "Index" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
            } ?? settings.index
            let parts = settings.separator.isEmpty
                ? Array(text).map(String.init)
                : text.components(separatedBy: settings.separator).map {
                    $0.trimmingCharacters(in: .whitespacesAndNewlines)
                }
            let resolvedIndex = min(max(Int(index.rounded()), 0), max(parts.count - 1, 0))
            return parts.isEmpty ? "" : parts[resolvedIndex]
        case .stringArrayIndex:
            return stringValueForOutputPort(sourcePort)
        case .oscInput:
            return oscInputStringValue(for: sourceNode.id, outputName: sourcePort.name)
        case .oscReceive:
            return oscReceiveStringValue(for: sourceNode.id, outputName: sourcePort.name)
        case .oscGet4:
            return stringValueForOutputPort(sourcePort)
        case .oscGetArray:
            return stringValueForOutputPort(sourcePort)
        case .scene3DGaussianSplat:
            return stringValueForOutputPort(sourcePort)
        case .stringSwitch:
            let settings = settings(forSelectNodeID: sourceNode.id)
            let selectValue = sourceNode.inputPorts.first(where: { $0.name == "Select" }).flatMap {
                scalarValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
            } ?? settings.selectValue
            let selectedName = selectValue >= settings.threshold ? "B" : "A"
            let fallbackValue = selectedName == "B" ? settings.stringB : settings.stringA
            return sourceNode.inputPorts.first(where: { $0.name == selectedName }).flatMap {
                stringValue(forInputPortID: $0.id, visitedNodeIDs: visitedNodeIDs.union([sourceNode.id]))
            } ?? fallbackValue
        default:
            return nil
        }
    }

    private func linePreviewInstance(for sourceNode: GraphNode) -> PreviewLineInstance {
        let settings = settings(forLineNodeID: sourceNode.id)
        let x1 = sourceNode.inputPorts.first(where: { $0.name == "X1" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.x1
        let y1 = sourceNode.inputPorts.first(where: { $0.name == "Y1" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.y1
        let x2 = sourceNode.inputPorts.first(where: { $0.name == "X2" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.x2
        let y2 = sourceNode.inputPorts.first(where: { $0.name == "Y2" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.y2
        let z = sourceNode.inputPorts.first(where: { $0.name == "Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.z
        let thickness = sourceNode.inputPorts.first(where: { $0.name == "Thickness" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.thickness
        let opacity = sourceNode.inputPorts.first(where: { $0.name == "Opacity" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.opacity
        let tint = sourceNode.inputPorts.first(where: { $0.name == "Color" }).flatMap { resolvedColorValue(forInputPortID: $0.id) }
            ?? SIMD4<Float>(Float(settings.red), Float(settings.green), Float(settings.blue), Float(settings.alpha))

        let dx = x2 - x1
        let dy = y2 - y1
        let length = max(0.001, sqrt((dx * dx) + (dy * dy)))
        let centerX = (x1 + x2) * 0.5
        let centerY = (y1 + y2) * 0.5
        // Preview rendering flips normalized Y into clip-space Y, so line rotation
        // needs the same sign correction or diagonal spokes lean sideways.
        let rotationZ = atan2(-dy, dx)

        return PreviewLineInstance(
            position: SIMD3<Float>(
                Float(max(-1.0, min(2.0, centerX))),
                Float(max(-1.0, min(2.0, centerY))),
                Float(z)
            ),
            scale: SIMD2<Float>(
                Float(length),
                Float(max(0.001, thickness))
            ),
            rotationRadiansZ: Float(rotationZ),
            color: SIMD4<Float>(
                tint.x,
                tint.y,
                tint.z,
                tint.w * Float(max(0.0, min(1.0, opacity)))
            )
        )
    }

    private func previewConfigurationForSourceNode(_ sourceNode: GraphNode) -> PreviewRenderConfiguration? {
        let childVisitedNodeIDs: Set<GraphNode.ID> = [sourceNode.id]
        let childFeedbackNodeID: GraphNode.ID?
        if case .feedback = sourceNode.kind {
            childFeedbackNodeID = sourceNode.id
        } else {
            childFeedbackNodeID = nil
        }

        switch sourceNode.kind {
        case .metalFragment:
            let uniforms = effectiveUniforms(forFragmentNodeID: sourceNode.id)
            return .single(PreviewShaderPass(
                metalSource: runtimePreviewShaderSource(for: metalSource(for: sourceNode.id), uniforms: uniforms),
                uniforms: uniforms,
                imageUniformSources: imageUniformSources(
                    forFragmentNodeID: sourceNode.id,
                    visitedNodeIDs: childVisitedNodeIDs,
                    activeFeedbackNodeID: childFeedbackNodeID
                )
            ))
        case .pointInterpolate, .point3Interpolate, .point4Interpolate, .pointScale, .point3Scale, .point4Scale, .scalarSmooth:
            return nil
        case .trackball:
            return nil
        case .trail:
            let settings = settings(forTrailNodeID: sourceNode.id)
            let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point" })
            let radiusInput = sourceNode.inputPorts.first(where: { $0.name == "Radius" })
            let durationInput = sourceNode.inputPorts.first(where: { $0.name == "Duration" })
            let resolvedPoint = pointInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
            let resolvedRadius = radiusInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.radius
            let resolvedDuration = durationInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.duration
            return .trail(PreviewTrailPass(
                point: resolvedPoint,
                radius: Float(max(0.001, resolvedRadius)),
                duration: Float(max(0.05, resolvedDuration))
            ))
        case .clear:
            let settings = settings(forClearNodeID: sourceNode.id)
            return .clear(PreviewClearPass(
                color: SIMD4(
                    Float(max(0, min(1, settings.red))),
                    Float(max(0, min(1, settings.green))),
                    Float(max(0, min(1, settings.blue))),
                    Float(max(0, min(1, settings.alpha)))
                )
            ))
        case .color, .hslColor, .colorVariable, .colorSplit, .scalarArray, .scalarArrayVariable, .stringArray, .stringArrayVariable, .colorArray, .colorArrayVariable, .imageArray, .imageArrayVariable, .scalarArrayIndex, .stringArrayIndex, .colorArrayIndex, .arrayCount, .iteratorVariables, .random, .pulse, .fireOnLoad, .counter, .toggle, .delay, .timer, .keyboard, .screenSize, .screenBounds, .renderBounds, .renderWindow, .gridLayout, .scalarMultiplexor, .stringMultiplexor, .colorMultiplexor, .expression, .beatDetect, .midiCCInput, .midiNoteInput, .oscInput, .oscOutput, .oscReceive, .oscSend, .oscGet4, .oscGetArray, .oscMake4, .oscMakeArray, .oscBundle:
            return nil
        case .imageArrayIndex:
            return imageArraySelectedSource(for: sourceNode).map(renderConfiguration(from:))
        case .imageMultiplexor:
            return imageMultiplexorSelectedSource(for: sourceNode).map(renderConfiguration(from:))
        case .iterator:
            return iteratorSource(for: sourceNode).map(renderConfiguration(from:))
        case .image:
            guard let settings = settings(forImageNodeID: sourceNode.id) else {
                return nil
            }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: settings.imageData))
        case .webView:
            let settings = settings(forWebViewNodeID: sourceNode.id)
            guard !settings.snapshotData.isEmpty else { return nil }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: settings.snapshotData))
        case .aiImage:
            let settings = settings(forAIImageNodeID: sourceNode.id)
            guard !settings.imageData.isEmpty else { return nil }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: settings.imageData))
        case .videoPlayer:
            return .videoPlayer(PreviewVideoPlayerPass(nodeID: sourceNode.id))
        case .video:
            return .video
        case .coreImage, .blur, .bloom, .hueRotate, .posterize, .levels, .glow:
            guard
                let effect = resolvedCoreImageEffect(for: sourceNode),
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Source" }),
                let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
            else {
                return nil
            }

            let settings = settings(forCoreImageNodeID: sourceNode.id)
            let primaryInput = sourceNode.inputPorts.first(where: { $0.name == coreImagePrimaryLabel(for: effect) })
            let secondaryInput = coreImageSecondaryLabel(for: effect).flatMap { label in
                sourceNode.inputPorts.first(where: { $0.name == label })
            }
            return .coreImage(PreviewCoreImagePass(
                nodeID: sourceNode.id,
                source: source,
                effect: effect,
                primary: Float(primaryInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.primary),
                secondary: Float(secondaryInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.secondary)
            ))
        case .underwater:
            guard
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Source" }),
                let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
            else {
                return nil
            }

            let settings = settings(forUnderwaterNodeID: sourceNode.id)
            return .underwater(PreviewUnderwaterPass(
                nodeID: sourceNode.id,
                source: source,
                scale: Float(settings.scale),
                distortion: Float(settings.distortion),
                octaves: settings.octaves,
                lacunarity: Float(settings.lacunarity),
                gain: Float(settings.gain),
                amplitude: Float(settings.amplitude),
                textureScale: Float(settings.textureScale),
                uvClampMargin: Float(settings.uvClampMargin)
            ))
        case .feedback:
            guard
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Source" }),
                let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
            else {
                return nil
            }

            let settings = settings(forFeedbackNodeID: sourceNode.id)
            let levelInput = sourceNode.inputPorts.first(where: { $0.name == "Level" })
            let resolvedLevel = levelInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.level
            return .feedback(PreviewFeedbackPass(
                nodeID: sourceNode.id,
                source: source,
                level: Float(max(0.0, min(0.999, resolvedLevel))),
                blendMode: settings.blendMode
            ))
        case .reactionDiffusion:
            let settings = settings(forReactionDiffusionNodeID: sourceNode.id)
            let source = sourceNode.inputPorts.first(where: { $0.name == "Texture" }).flatMap {
                previewPassSource(forInputPortID: $0.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
            }
            func scalar(_ name: String, _ fallback: Double) -> Float {
                Float(max(0.0, min(1.0, sourceNode.inputPorts.first(where: { $0.name == name }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? fallback)))
            }
            let tint = SIMD4<Float>(
                Float(max(0.0, min(1.0, settings.red))),
                Float(max(0.0, min(1.0, settings.green))),
                Float(max(0.0, min(1.0, settings.blue))),
                Float(max(0.0, min(1.0, settings.alpha)))
            )
            return .reactionDiffusion(PreviewReactionDiffusionPass(
                nodeID: sourceNode.id,
                source: source,
                settings: settings,
                feed: scalar("Feed", settings.feed),
                kill: scalar("Kill", settings.kill),
                diffusionA: scalar("Diffusion A", settings.diffusionA),
                diffusionB: scalar("Diffusion B", settings.diffusionB),
                speed: scalar("Speed", settings.speed),
                seed: scalar("Seed", settings.seed),
                inputDrive: scalar("Input Drive", settings.inputDrive),
                displayBoost: scalar("Display Boost", settings.displayBoost),
                hueShift: scalar("Hue Shift", settings.hueShift),
                saturation: scalar("Saturation", settings.saturation),
                sourceColor: scalar("Source Color", settings.sourceColor),
                reset: scalar("Reset", settings.reset),
                tint: tint
            ))
        case .transition:
            guard
                let sourceAInput = sourceNode.inputPorts.first(where: { $0.name == "Source A" }),
                let sourceBInput = sourceNode.inputPorts.first(where: { $0.name == "Source B" }),
                let primarySource = previewPassSource(forInputPortID: sourceAInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID),
                let secondarySource = previewPassSource(forInputPortID: sourceBInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
            else {
                return nil
            }

            let settings = settings(forTransitionNodeID: sourceNode.id)
            let progressInput = sourceNode.inputPorts.first(where: { $0.name == "Progress" })
            let softnessInput = sourceNode.inputPorts.first(where: { $0.name == "Softness" })
            let progress = Float(max(0.0, min(1.0, progressInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.progress)))
            let softness = Float(max(0.0, min(1.0, softnessInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.softness)))
            return .transition(PreviewTransitionPass(
                nodeID: sourceNode.id,
                primary: primarySource,
                secondary: secondarySource,
                style: settings.style,
                progress: progress,
                softness: softness
            ))
        case .circle:
            let settings = settings(forCircleNodeID: sourceNode.id)
            let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point" })
            let radiusInput = sourceNode.inputPorts.first(where: { $0.name == "Radius" })
            let softnessInput = sourceNode.inputPorts.first(where: { $0.name == "Softness" })
            let alphaInput = sourceNode.inputPorts.first(where: { $0.name == "Alpha" })
            let resolvedPoint = pointInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
            let resolvedRadius = radiusInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.radius
            let resolvedSoftness = softnessInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.softness
            let resolvedAlpha = alphaInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.alpha
            return .circle(PreviewCirclePass(
                point: resolvedPoint,
                radius: Float(max(0.001, resolvedRadius)),
                softness: Float(max(0.0, min(1.0, resolvedSoftness))),
                color: SIMD4(
                    Float(max(0.0, min(1.0, settings.red))),
                    Float(max(0.0, min(1.0, settings.green))),
                    Float(max(0.0, min(1.0, settings.blue))),
                    Float(max(0.0, min(1.0, resolvedAlpha)))
                )
            ))
        case .note:
            guard let imageData = renderedNoteImageData(for: sourceNode.id) else {
                return nil
            }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: imageData))
        case .textImage:
            guard let imageData = renderedTextImageData(for: sourceNode.id) else {
                return nil
            }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: imageData))
        case .sliderStyle:
            return nil
        case .slider:
            guard let imageData = renderedSliderImageData(for: sourceNode.id) else {
                return nil
            }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: imageData))
        case .button:
            guard let imageData = renderedButtonImageData(for: sourceNode.id) else {
                return nil
            }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: imageData))
        case .select:
            let settings = settings(forSelectNodeID: sourceNode.id)
            guard
                let sourceAInput = sourceNode.inputPorts.first(where: { $0.name == "Source A" }),
                let sourceBInput = sourceNode.inputPorts.first(where: { $0.name == "Source B" }),
                let primarySource = previewPassSource(forInputPortID: sourceAInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID),
                let secondarySource = previewPassSource(forInputPortID: sourceBInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID),
                let selectInput = sourceNode.inputPorts.first(where: { $0.name == "Select" })
            else {
                return nil
            }
            let selectValue = resolvedScalarValue(forInputPortID: selectInput.id) ?? settings.selectValue
            return renderConfiguration(from: selectValue >= settings.threshold ? secondarySource : primarySource)
        case .scalarSwitch, .stringSwitch, .colorSwitch:
            return nil
        case .transform:
            guard
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Source" }),
                let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
            else {
                return nil
            }
            let settings = settings(forTransformNodeID: sourceNode.id)
            let x = sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.x
            let y = sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.y
            let z = sourceNode.inputPorts.first(where: { $0.name == "Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.z
            let scaleX = sourceNode.inputPorts.first(where: { $0.name == "Scale X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scaleX
            let scaleY = sourceNode.inputPorts.first(where: { $0.name == "Scale Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scaleY
            let rotationX = sourceNode.inputPorts.first(where: { $0.name == "Rotation X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationX
            let rotationY = sourceNode.inputPorts.first(where: { $0.name == "Rotation Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationY
            let rotationZ = sourceNode.inputPorts.first(where: { $0.name == "Rotation Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationZ
            let opacity = sourceNode.inputPorts.first(where: { $0.name == "Opacity" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.opacity
            return .transform(PreviewTransformPass(
                nodeID: sourceNode.id,
                source: source,
                x: Float(max(-1.0, min(2.0, x))),
                y: Float(max(-1.0, min(2.0, y))),
                z: Float(z),
                scaleX: Float(max(0.001, scaleX)),
                scaleY: Float(max(0.001, scaleY)),
                rotationDegreesX: Float(rotationX),
                rotationDegreesY: Float(rotationY),
                rotationDegreesZ: Float(rotationZ),
                opacity: Float(max(0.0, min(1.0, opacity))),
                tint: SIMD4<Float>(1, 1, 1, 1)
            ))
        case .billboard:
            guard
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Source" })
            else {
                return nil
            }
            let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID) ?? .clear(PreviewClearPass(
                color: SIMD4<Float>(1, 1, 1, 1)
            ))
            let settings = settings(forBillboardNodeID: sourceNode.id)
            let x = sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.x
            let y = sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.y
            let z = sourceNode.inputPorts.first(where: { $0.name == "Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.z
            let width = sourceNode.inputPorts.first(where: { $0.name == "Width" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.width
            let height = sourceNode.inputPorts.first(where: { $0.name == "Height" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.height
            let rotationX = sourceNode.inputPorts.first(where: { $0.name == "Rotation X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationX
            let rotationY = sourceNode.inputPorts.first(where: { $0.name == "Rotation Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationY
            let rotationZ = sourceNode.inputPorts.first(where: { $0.name == "Rotation Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationZ
            let opacity = sourceNode.inputPorts.first(where: { $0.name == "Opacity" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.opacity
            let tint = sourceNode.inputPorts.first(where: { $0.name == "Color" }).flatMap { resolvedColorValue(forInputPortID: $0.id) } ?? colorFromSettings(settings)
            return .transform(PreviewTransformPass(
                nodeID: sourceNode.id,
                source: source,
                x: Float(max(-1.0, min(2.0, x))),
                y: Float(max(-1.0, min(2.0, y))),
                z: Float(z),
                scaleX: Float(max(0.001, width)),
                scaleY: Float(max(0.001, height)),
                rotationDegreesX: Float(rotationX),
                rotationDegreesY: Float(rotationY),
                rotationDegreesZ: Float(rotationZ),
                opacity: Float(max(0.0, min(1.0, opacity))),
                tint: tint
            ))
        case .line:
            return .lineBatch(PreviewLineBatchPass(nodeID: sourceNode.id, instances: [linePreviewInstance(for: sourceNode)]))
        case .scene3DTransform, .scene3DTile:
            return nil
        case .scene3DLight:
            return nil
        case .scene3DMaterial:
            return nil
        case .scene3DPrimitive:
            let settings = resolvedScene3DPrimitiveSettings(forNodeID: sourceNode.id)
            let material = resolvedConnectedScene3DMaterial(for: sourceNode)
                ?? Scene3DMaterialNodeSettings(
                    red: settings.materialRed,
                    green: settings.materialGreen,
                    blue: settings.materialBlue,
                    alpha: settings.materialAlpha,
                    metallic: 0.35,
                    roughness: 0.28,
                    emission: 0.0,
                    doubleSided: false
                )
            return .scene3DPrimitive(PreviewScene3DPrimitivePass(
                nodeID: sourceNode.id,
                settings: settings,
                light: resolvedConnectedScene3DLight(for: sourceNode),
                material: material,
                materialMaps: resolvedConnectedScene3DMaterialMaps(for: sourceNode)
            ))
        case .scene3DText:
            let settings = resolvedScene3DTextSettings(forNodeID: sourceNode.id)
            let material = resolvedConnectedScene3DMaterial(for: sourceNode)
                ?? Scene3DMaterialNodeSettings(
                    red: settings.materialRed,
                    green: settings.materialGreen,
                    blue: settings.materialBlue,
                    alpha: settings.materialAlpha,
                    metallic: 0.35,
                    roughness: 0.28,
                    emission: 0.0,
                    doubleSided: false
                )
            return .scene3DText(PreviewScene3DTextPass(
                nodeID: sourceNode.id,
                settings: settings,
                light: resolvedConnectedScene3DLight(for: sourceNode),
                material: material,
                materialMaps: resolvedConnectedScene3DMaterialMaps(for: sourceNode)
            ))
        case .scene3DModel:
            let settings = resolvedScene3DModelSettings(forNodeID: sourceNode.id)
            return .scene3DModel(PreviewScene3DModelPass(
                nodeID: sourceNode.id,
                settings: settings,
                light: resolvedConnectedScene3DLight(for: sourceNode),
                material: resolvedConnectedScene3DMaterial(for: sourceNode),
                materialMaps: resolvedConnectedScene3DMaterialMaps(for: sourceNode)
            ))
        case .scene3DGaussianSplat:
            return .scene3DGaussianSplat(PreviewScene3DGaussianSplatPass(
                nodeID: sourceNode.id,
                settings: resolvedScene3DGaussianSplatSettings(forNodeID: sourceNode.id)
            ))
        case .scene3DParticle:
            return .scene3DParticle(PreviewScene3DParticlePass(
                nodeID: sourceNode.id,
                settings: resolvedScene3DParticleSettings(forNodeID: sourceNode.id),
                spriteSource: sourceNode.inputPorts.first(where: { $0.name == "Sprite" }).flatMap {
                    previewPassSource(forInputPortID: $0.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
                }
            ))
        case .scene3DRender:
            let settings = settings(forScene3DRenderNodeID: sourceNode.id)
            let sources = sourceNode.inputPorts
                .filter { $0.name.hasPrefix("Scene ") }
                .compactMap { previewPassSource(forInputPortID: $0.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID).flatMap(extractScene3DSource) }
            guard sources.isEmpty == false else { return nil }
            let cameraDistance = sourceNode.inputPorts.first(where: { $0.name == "Camera Distance" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.cameraDistance
            let orbit = sourceNode.inputPorts.first(where: { $0.name == "Orbit" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.cameraOrbit
            let pitch = sourceNode.inputPorts.first(where: { $0.name == "Pitch" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.cameraPitch
            let panX = sourceNode.inputPorts.first(where: { $0.name == "Pan X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.cameraPanX
            let panY = sourceNode.inputPorts.first(where: { $0.name == "Pan Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.cameraPanY
            return .scene3DRender(PreviewScene3DRenderPass(
                nodeID: sourceNode.id,
                sources: sources,
                cameraDistance: Float(cameraDistance),
                cameraOrbit: Float(orbit),
                cameraPitch: Float(pitch),
                cameraPanX: Float(panX),
                cameraPanY: Float(panY),
                backgroundAlpha: Float(settings.backgroundAlpha),
                defaultLightIntensity: Float(settings.defaultLightIntensity),
                waterDistortion: Float(settings.waterDistortion),
                waterScale: Float(settings.waterScale),
                waterSpeed: Float(settings.waterSpeed)
            ))
        case .mix:
            guard
                let shaderAInput = sourceNode.inputPorts.first(where: { $0.name == "Shader A" }),
                let shaderBInput = sourceNode.inputPorts.first(where: { $0.name == "Shader B" }),
                let primarySource = previewPassSource(forInputPortID: shaderAInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID),
                let secondarySource = previewPassSource(forInputPortID: shaderBInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID),
                let mixInput = sourceNode.inputPorts.first(where: { $0.name == "Mix" })
            else {
                return nil
            }

            let mixAmount = max(0.0, min(1.0, resolvedScalarValue(forInputPortID: mixInput.id) ?? 0.5))
            return .mix(primary: primarySource, secondary: secondarySource, amount: Float(mixAmount))
        case .layers:
            guard let opacityInput = sourceNode.inputPorts.first(where: { $0.name == "Opacity" }) else {
                return nil
            }

            let settings = settings(forLayerNodeID: sourceNode.id)
                let connectedLayers: [PreviewLayerPass] = (1...settings.layerCount).compactMap { index in
                    guard
                        let layerInput = sourceNode.inputPorts.first(where: { $0.name == "Layer \(index)" }),
                        let source = previewPassSource(forInputPortID: layerInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
                    else {
                        return nil
                    }

                let opacityInput = sourceNode.inputPorts.first(where: { $0.name == "Opacity \(index)" })
                let defaultOpacity = settings.layerOpacities[index - 1]
                let resolvedOpacity = opacityInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? defaultOpacity
                    let zIndex: Float
                    switch source {
                    case .transform(let pass):
                        zIndex = pass.z
                    default:
                        zIndex = Float(index - 1)
                    }
                    return PreviewLayerPass(
                        source: source,
                        opacity: Float(max(0.0, min(1.0, resolvedOpacity))),
                        zIndex: zIndex
                    )
                }

                guard connectedLayers.isEmpty == false else {
                    return nil
                }

                let opacity = Float(max(0.0, min(1.0, resolvedScalarValue(forInputPortID: opacityInput.id) ?? settings.opacity)))
                return .layers(layers: connectedLayers.sorted { lhs, rhs in
                    if lhs.zIndex == rhs.zIndex {
                        return lhs.opacity <= rhs.opacity
                    }
                    return lhs.zIndex < rhs.zIndex
                }, opacity: opacity)
        case .uniform, .time, .mouse, .pointSplit, .pointCombine, .point3Split, .point3Combine, .point4Split, .point4Combine, .scroll, .handTracker, .pinch, .scrollGesture, .zoomGesture, .depthEstimate, .math, .clamp, .mapRange, .logic, .compare, .scalarVariable, .stringVariable, .string, .stringFormat, .stringCompare, .stringSplit, .audio, .polar, .hitZone, .rectHit, .macro, .midiOut, .midiCC, .scale, .interpolator, .hold, .monitor, .renderOutput, .buttonStyle:
            return nil
        }
    }

    private func previewConfigurationForOutputNode(renderNodeID: GraphNode.ID) -> PreviewRenderConfiguration? {
        guard let sourceNode = connectedSourceNode(forOutputNodeID: renderNodeID) else {
            return nil
        }
        return previewConfigurationForSourceNode(sourceNode)
    }

    private func renderConfiguration(from source: PreviewPassSource) -> PreviewRenderConfiguration {
        switch source {
        case .shader(let pass):
            return .single(pass)
        case .trail(let pass):
            return .trail(pass)
        case .circle(let pass):
            return .circle(pass)
        case .clear(let pass):
            return .clear(pass)
        case .image(let pass):
            return .image(pass)
        case .videoPlayer(let pass):
            return .videoPlayer(pass)
        case .video:
            return .video
        case .coreImage(let pass):
            return .coreImage(pass)
        case .underwater(let pass):
            return .underwater(pass)
        case .transform(let pass):
            return .transform(pass)
        case .lineBatch(let pass):
            return .lineBatch(pass)
        case .scene3DPrimitive(let pass):
            return .scene3DPrimitive(pass)
        case .scene3DText(let pass):
            return .scene3DText(pass)
        case .scene3DModel(let pass):
            return .scene3DModel(pass)
        case .scene3DGaussianSplat(let pass):
            return .scene3DGaussianSplat(pass)
        case .scene3DParticle(let pass):
            return .scene3DParticle(pass)
        case .scene3DSource(let sceneSource):
            let nodeID: UUID
            switch sceneSource {
            case .primitive(let pass):
                nodeID = pass.nodeID
            case .text(let pass):
                nodeID = pass.nodeID
            case .model(let pass):
                nodeID = pass.nodeID
            case .gaussianSplat(let pass):
                nodeID = pass.nodeID
            case .particle(let pass):
                nodeID = pass.nodeID
            case .light:
                nodeID = UUID()
            case .transform(let transformNodeID, _, _, _, _, _, _, _, _, _, _):
                nodeID = transformNodeID
            case .tile(let tileNodeID, _, _, _, _, _, _, _, _, _, _):
                nodeID = tileNodeID
            }
            return .scene3DRender(PreviewScene3DRenderPass(
                nodeID: nodeID,
                sources: [sceneSource],
                cameraDistance: 6.0,
                cameraOrbit: 0.0,
                cameraPitch: 12.0,
                cameraPanX: 0.0,
                cameraPanY: 0.0,
                backgroundAlpha: 0.0,
                defaultLightIntensity: 100.0,
                waterDistortion: 0.0,
                waterScale: 3.2,
                waterSpeed: 1.0
            ))
        case .scene3DRender(let pass):
            return .scene3DRender(pass)
        case .transition(let pass):
            return .transition(pass)
        case .mix(let primary, let secondary, let amount):
            return .mix(primary: primary, secondary: secondary, amount: amount)
        case .layers(let layers, let opacity):
            return .layers(layers: layers, opacity: opacity)
        case .feedback(let pass):
            return .feedback(pass)
        case .reactionDiffusion(let pass):
            return .reactionDiffusion(pass)
        case .feedbackHistory:
            return .clear(PreviewClearPass(color: SIMD4<Float>(0, 0, 0, 0)))
        }
    }

    private func previewPassSource(from configuration: PreviewRenderConfiguration) -> PreviewPassSource? {
        switch configuration {
        case .empty:
            return nil
        case .single(let pass):
            return .shader(pass)
        case .trail(let pass):
            return .trail(pass)
        case .circle(let pass):
            return .circle(pass)
        case .clear(let pass):
            return .clear(pass)
        case .image(let pass):
            return .image(pass)
        case .videoPlayer(let pass):
            return .videoPlayer(pass)
        case .video:
            return .video
        case .coreImage(let pass):
            return .coreImage(pass)
        case .underwater(let pass):
            return .underwater(pass)
        case .transform(let pass):
            return .transform(pass)
        case .lineBatch(let pass):
            return .lineBatch(pass)
        case .scene3DPrimitive(let pass):
            return .scene3DPrimitive(pass)
        case .scene3DText(let pass):
            return .scene3DText(pass)
        case .scene3DModel(let pass):
            return .scene3DModel(pass)
        case .scene3DGaussianSplat(let pass):
            return .scene3DGaussianSplat(pass)
        case .scene3DParticle(let pass):
            return .scene3DParticle(pass)
        case .scene3DRender(let pass):
            return .scene3DRender(pass)
        case .feedback(let pass):
            return .feedback(pass)
        case .reactionDiffusion(let pass):
            return .reactionDiffusion(pass)
        case .transition(let pass):
            return .transition(pass)
        case .mix(let primary, let secondary, let amount):
            return .mix(primary: primary, secondary: secondary, amount: amount)
        case .layers(let layers, let opacity):
            return .layers(layers: layers, opacity: opacity)
        }
    }

    private func iteratorSource(for iteratorNode: GraphNode) -> PreviewPassSource? {
        guard case .iterator = iteratorNode.kind else { return nil }
        let settings = settings(forIteratorNodeID: iteratorNode.id)
        guard let publishedOutput = settings.publishedOutputs.first(where: {
            $0.isPublished && graphPortKind(for: $0.kind) == .fragmentShader
        }) else {
            return nil
        }

        let iterationsInput = iteratorNode.inputPorts.first(where: { $0.name == "Iterations" })
        let rawIterations = iterationsInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.iterations
        let iterations = max(1, min(512, Int(rawIterations.rounded())))
        let iteratorVariableNodeIDs = settings.childNodeIDs.compactMap { childNodeID -> GraphNode.ID? in
            guard let childNode = document.nodes.first(where: { $0.id == childNodeID }) else { return nil }
            if case .iteratorVariables = childNode.kind {
                return childNode.id
            }
            return nil
        }
        guard let internalPort = port(withID: publishedOutput.internalPortID),
              let sourceNode = document.nodes.first(where: { $0.id == internalPort.nodeID }) else {
            return nil
        }

        if case .line = sourceNode.kind {
            var instances: [PreviewLineInstance] = []
            instances.reserveCapacity(iterations)
            for index in 0..<iterations {
                let context = IteratorEvaluationContext(iteratorNodeID: iteratorNode.id, index: index, iterations: iterations)
                iteratorEvaluationStack.append(context)
                for iteratorVariableNodeID in iteratorVariableNodeIDs {
                    iteratorVariableRuntimeContexts[iteratorVariableNodeID] = context
                }
                let instance = linePreviewInstance(for: sourceNode)
                _ = iteratorEvaluationStack.popLast()
                instances.append(instance)
            }
            return .lineBatch(PreviewLineBatchPass(nodeID: iteratorNode.id, instances: instances))
        }

        var layers: [PreviewLayerPass] = []
        for index in 0..<iterations {
            let context = IteratorEvaluationContext(iteratorNodeID: iteratorNode.id, index: index, iterations: iterations)
            iteratorEvaluationStack.append(context)
            for iteratorVariableNodeID in iteratorVariableNodeIDs {
                iteratorVariableRuntimeContexts[iteratorVariableNodeID] = context
            }
            defer { _ = iteratorEvaluationStack.popLast() }

            guard
                let configuration = previewConfigurationForSourceNode(sourceNode),
                let source = previewPassSource(from: configuration)
            else {
                continue
            }

            let zIndex: Float
            switch source {
            case .transform(let pass):
                zIndex = pass.z
            default:
                zIndex = Float(index)
            }
            layers.append(PreviewLayerPass(source: source, opacity: 1.0, zIndex: zIndex))
        }

        guard layers.isEmpty == false else { return nil }
        return .layers(layers: layers, opacity: 1.0)
    }

    private func imageArraySelectedSource(for node: GraphNode) -> PreviewPassSource? {
        guard case .imageArrayIndex = node.kind else { return nil }
        let settings = settings(forImageArrayIndexNodeID: node.id)
        guard
            let arrayInput = node.inputPorts.first(where: { $0.name == "Array" }),
            let sources = imageArraySourcesWithHoles(forInputPortID: arrayInput.id, visitedNodeIDs: [node.id])
        else {
            return nil
        }
        guard sources.isEmpty == false else { return nil }
        let index = node.inputPorts.first(where: { $0.name == "Index" }).flatMap {
            resolvedScalarValue(forInputPortID: $0.id)
        } ?? settings.index
        let resolvedIndex = min(max(Int(index.rounded()), 0), sources.count - 1)
        return sources[resolvedIndex]
    }

    private func imageMultiplexorSelectedSource(for node: GraphNode) -> PreviewPassSource? {
        guard case .imageMultiplexor = node.kind else { return nil }
        let arraySettings = settings(forImageArrayNodeID: node.id)
        let indexSettings = settings(forScalarArrayIndexNodeID: node.id)
        let itemPorts = sortedArrayItemPorts(node.inputPorts.filter { $0.name.hasPrefix("Item ") })
        let availableCount = min(max(arraySettings.count, 0), itemPorts.count)
        guard availableCount > 0 else { return nil }
        let index = node.inputPorts.first(where: { $0.name == "Index" }).flatMap {
            resolvedScalarValue(forInputPortID: $0.id)
        } ?? indexSettings.index
        let resolvedIndex = min(max(Int(index.rounded()), 0), availableCount - 1)
        return previewPassSourceForVisualInputPortID(itemPorts[resolvedIndex].id)
    }

    private func previewPassSourceForVisualInputPortID(
        _ inputPortID: GraphPort.ID,
        visitedNodeIDs: Set<GraphNode.ID> = [],
        activeFeedbackNodeID: GraphNode.ID? = nil
    ) -> PreviewPassSource? {
        guard
            let connection = effectiveIncomingConnection(for: inputPortID),
            let sourcePort = resolvedSourcePort(for: connection.fromPortID)
        else {
            return nil
        }

        switch sourcePort.kind {
        case .fragmentShader:
            return previewPassSource(
                forInputPortID: inputPortID,
                visitedNodeIDs: visitedNodeIDs,
                activeFeedbackNodeID: activeFeedbackNodeID
            )
        case .imageArraySignal:
            guard
                let sourceNode = document.nodes.first(where: { $0.id == sourcePort.nodeID }),
                case .imageArrayIndex = sourceNode.kind
            else {
                return nil
            }
            return imageArraySelectedSource(for: sourceNode)
        default:
            return previewPassSource(
                forInputPortID: inputPortID,
                visitedNodeIDs: visitedNodeIDs,
                activeFeedbackNodeID: activeFeedbackNodeID
            )
        }
    }

    private func extractScene3DSource(from source: PreviewPassSource) -> PreviewScene3DSource? {
        guard case .scene3DSource(let sceneSource) = source else {
            return nil
        }
        return sceneSource
    }

    private func previewPassSource(forInputPortID inputPortID: GraphPort.ID) -> PreviewPassSource? {
        previewPassSource(forInputPortID: inputPortID, visitedNodeIDs: [], activeFeedbackNodeID: nil)
    }

    private func feedbackCycleFallback(activeFeedbackNodeID: GraphNode.ID?) -> PreviewPassSource {
        if let activeFeedbackNodeID {
            return .feedbackHistory(nodeID: activeFeedbackNodeID)
        }
        return .clear(PreviewClearPass(color: SIMD4<Float>(0, 0, 0, 0)))
    }

    private func previewPassSource(
        forInputPortID inputPortID: GraphPort.ID,
        visitedNodeIDs: Set<GraphNode.ID>,
        activeFeedbackNodeID: GraphNode.ID?
    ) -> PreviewPassSource? {
        guard
            let connection = effectiveIncomingConnection(for: inputPortID),
            let sourcePort = resolvedSourcePort(for: connection.fromPortID),
            let sourceNode = document.nodes.first(where: { $0.id == sourcePort.nodeID })
        else {
            return nil
        }

        if visitedNodeIDs.contains(sourceNode.id) {
            return feedbackCycleFallback(activeFeedbackNodeID: activeFeedbackNodeID)
        }

        let childVisitedNodeIDs = visitedNodeIDs.union([sourceNode.id])
        let childFeedbackNodeID: GraphNode.ID?
        if case .feedback = sourceNode.kind {
            childFeedbackNodeID = sourceNode.id
        } else {
            childFeedbackNodeID = activeFeedbackNodeID
        }

        switch sourceNode.kind {
        case .metalFragment:
            let uniforms = effectiveUniforms(forFragmentNodeID: sourceNode.id)
            return .shader(PreviewShaderPass(
                metalSource: runtimePreviewShaderSource(for: metalSource(for: sourceNode.id), uniforms: uniforms),
                uniforms: uniforms,
                imageUniformSources: imageUniformSources(
                    forFragmentNodeID: sourceNode.id,
                    visitedNodeIDs: childVisitedNodeIDs,
                    activeFeedbackNodeID: childFeedbackNodeID
                )
            ))
        case .iterator:
            return iteratorSource(for: sourceNode)
        case .trail:
            let settings = settings(forTrailNodeID: sourceNode.id)
            let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point" })
            let radiusInput = sourceNode.inputPorts.first(where: { $0.name == "Radius" })
            let durationInput = sourceNode.inputPorts.first(where: { $0.name == "Duration" })
            let resolvedPoint = pointInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
            let resolvedRadius = radiusInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.radius
            let resolvedDuration = durationInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.duration
            return .trail(PreviewTrailPass(
                point: resolvedPoint,
                radius: Float(max(0.001, resolvedRadius)),
                duration: Float(max(0.05, resolvedDuration))
            ))
        case .clear:
            let settings = settings(forClearNodeID: sourceNode.id)
            return .clear(PreviewClearPass(
                color: SIMD4(
                    Float(max(0, min(1, settings.red))),
                    Float(max(0, min(1, settings.green))),
                    Float(max(0, min(1, settings.blue))),
                    Float(max(0, min(1, settings.alpha)))
                )
            ))
        case .imageArrayIndex:
            return imageArraySelectedSource(for: sourceNode)
        case .imageMultiplexor:
            return imageMultiplexorSelectedSource(for: sourceNode)
        case .circle:
            let settings = settings(forCircleNodeID: sourceNode.id)
            let pointInput = sourceNode.inputPorts.first(where: { $0.name == "Point" })
            let radiusInput = sourceNode.inputPorts.first(where: { $0.name == "Radius" })
            let softnessInput = sourceNode.inputPorts.first(where: { $0.name == "Softness" })
            let alphaInput = sourceNode.inputPorts.first(where: { $0.name == "Alpha" })
            let resolvedPoint = pointInput.flatMap { resolvedPointValue(forInputPortID: $0.id) }
            let resolvedRadius = radiusInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.radius
            let resolvedSoftness = softnessInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.softness
            let resolvedAlpha = alphaInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.alpha
            return .circle(PreviewCirclePass(
                point: resolvedPoint,
                radius: Float(max(0.001, resolvedRadius)),
                softness: Float(max(0.0, min(1.0, resolvedSoftness))),
                color: SIMD4(
                    Float(max(0.0, min(1.0, settings.red))),
                    Float(max(0.0, min(1.0, settings.green))),
                    Float(max(0.0, min(1.0, settings.blue))),
                    Float(max(0.0, min(1.0, resolvedAlpha)))
                )
            ))
        case .note:
            guard let imageData = renderedNoteImageData(for: sourceNode.id) else {
                return nil
            }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: imageData))
        case .textImage:
            guard let imageData = renderedTextImageData(for: sourceNode.id) else {
                return nil
            }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: imageData))
        case .slider:
            guard let imageData = renderedSliderImageData(for: sourceNode.id) else {
                return nil
            }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: imageData))
        case .button:
            guard let imageData = renderedButtonImageData(for: sourceNode.id) else {
                return nil
            }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: imageData))
        case .select:
            let settings = settings(forSelectNodeID: sourceNode.id)
            guard
                let sourceAInput = sourceNode.inputPorts.first(where: { $0.name == "Source A" }),
                let sourceBInput = sourceNode.inputPorts.first(where: { $0.name == "Source B" }),
                let primarySource = previewPassSource(forInputPortID: sourceAInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID),
                let secondarySource = previewPassSource(forInputPortID: sourceBInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID),
                let selectInput = sourceNode.inputPorts.first(where: { $0.name == "Select" })
            else {
                return nil
            }
            let selectValue = resolvedScalarValue(forInputPortID: selectInput.id) ?? settings.selectValue
            return selectValue >= settings.threshold ? secondarySource : primarySource
        case .scalarSwitch, .stringSwitch, .colorSwitch, .screenBounds, .renderBounds, .renderWindow, .scalarMultiplexor, .stringMultiplexor, .colorMultiplexor:
            return nil
        case .transform:
            guard
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Source" }),
                let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
            else {
                return nil
            }
            let settings = settings(forTransformNodeID: sourceNode.id)
            let x = sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.x
            let y = sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.y
            let z = sourceNode.inputPorts.first(where: { $0.name == "Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.z
            let scaleX = sourceNode.inputPorts.first(where: { $0.name == "Scale X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scaleX
            let scaleY = sourceNode.inputPorts.first(where: { $0.name == "Scale Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scaleY
            let rotationX = sourceNode.inputPorts.first(where: { $0.name == "Rotation X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationX
            let rotationY = sourceNode.inputPorts.first(where: { $0.name == "Rotation Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationY
            let rotationZ = sourceNode.inputPorts.first(where: { $0.name == "Rotation Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationZ
            let opacity = sourceNode.inputPorts.first(where: { $0.name == "Opacity" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.opacity
            return .transform(PreviewTransformPass(
                nodeID: sourceNode.id,
                source: source,
                x: Float(max(-1.0, min(2.0, x))),
                y: Float(max(-1.0, min(2.0, y))),
                z: Float(z),
                scaleX: Float(max(0.001, scaleX)),
                scaleY: Float(max(0.001, scaleY)),
                rotationDegreesX: Float(rotationX),
                rotationDegreesY: Float(rotationY),
                rotationDegreesZ: Float(rotationZ),
                opacity: Float(max(0.0, min(1.0, opacity))),
                tint: SIMD4<Float>(1, 1, 1, 1)
            ))
        case .billboard:
            guard
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Source" })
            else {
                return nil
            }
            let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID) ?? .clear(PreviewClearPass(
                color: SIMD4<Float>(1, 1, 1, 1)
            ))
            let settings = settings(forBillboardNodeID: sourceNode.id)
            let x = sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.x
            let y = sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.y
            let z = sourceNode.inputPorts.first(where: { $0.name == "Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.z
            let width = sourceNode.inputPorts.first(where: { $0.name == "Width" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.width
            let height = sourceNode.inputPorts.first(where: { $0.name == "Height" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.height
            let rotationX = sourceNode.inputPorts.first(where: { $0.name == "Rotation X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationX
            let rotationY = sourceNode.inputPorts.first(where: { $0.name == "Rotation Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationY
            let rotationZ = sourceNode.inputPorts.first(where: { $0.name == "Rotation Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationZ
            let opacity = sourceNode.inputPorts.first(where: { $0.name == "Opacity" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.opacity
            let tint = sourceNode.inputPorts.first(where: { $0.name == "Color" }).flatMap { resolvedColorValue(forInputPortID: $0.id) } ?? colorFromSettings(settings)
            return .transform(PreviewTransformPass(
                nodeID: sourceNode.id,
                source: source,
                x: Float(max(-1.0, min(2.0, x))),
                y: Float(max(-1.0, min(2.0, y))),
                z: Float(z),
                scaleX: Float(max(0.001, width)),
                scaleY: Float(max(0.001, height)),
                rotationDegreesX: Float(rotationX),
                rotationDegreesY: Float(rotationY),
                rotationDegreesZ: Float(rotationZ),
                opacity: Float(max(0.0, min(1.0, opacity))),
                tint: tint
            ))
        case .line:
            return .lineBatch(PreviewLineBatchPass(nodeID: sourceNode.id, instances: [linePreviewInstance(for: sourceNode)]))
        case .scene3DTransform:
            guard
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Scene" }),
                let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID).flatMap(extractScene3DSource)
            else {
                return nil
            }
            let settings = settings(forScene3DTransformNodeID: sourceNode.id)
            let x = sourceNode.inputPorts.first(where: { $0.name == "X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.x
            let y = sourceNode.inputPorts.first(where: { $0.name == "Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.y
            let z = sourceNode.inputPorts.first(where: { $0.name == "Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.z
            let scaleX = sourceNode.inputPorts.first(where: { $0.name == "Scale X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scaleX
            let scaleY = sourceNode.inputPorts.first(where: { $0.name == "Scale Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scaleY
            let scaleZ = sourceNode.inputPorts.first(where: { $0.name == "Scale Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.scaleZ
            let rotationX = sourceNode.inputPorts.first(where: { $0.name == "Rotation X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationX
            let rotationY = sourceNode.inputPorts.first(where: { $0.name == "Rotation Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationY
            let rotationZ = sourceNode.inputPorts.first(where: { $0.name == "Rotation Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.rotationZ
            return .scene3DSource(.transform(
                nodeID: sourceNode.id,
                source: source,
                x: Float(x),
                y: Float(y),
                z: Float(z),
                scaleX: Float(max(0.001, scaleX)),
                scaleY: Float(max(0.001, scaleY)),
                scaleZ: Float(max(0.001, scaleZ)),
                rotationDegreesX: Float(rotationX),
                rotationDegreesY: Float(rotationY),
                rotationDegreesZ: Float(rotationZ)
            ))
        case .scene3DTile:
            guard
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Scene" }),
                let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID).flatMap(extractScene3DSource)
            else {
                return nil
            }
            let settings = settings(forScene3DTileNodeID: sourceNode.id)
            let centerX = sourceNode.inputPorts.first(where: { $0.name == "Center X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.centerX
            let centerY = sourceNode.inputPorts.first(where: { $0.name == "Center Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.centerY
            let centerZ = sourceNode.inputPorts.first(where: { $0.name == "Center Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.centerZ
            let spacingX = sourceNode.inputPorts.first(where: { $0.name == "Spacing X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.spacingX
            let spacingY = sourceNode.inputPorts.first(where: { $0.name == "Spacing Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.spacingY
            let spacingZ = sourceNode.inputPorts.first(where: { $0.name == "Spacing Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.spacingZ
            let fieldX = sourceNode.inputPorts.first(where: { $0.name == "Field X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.fieldX
            let fieldY = sourceNode.inputPorts.first(where: { $0.name == "Field Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.fieldY
            let fieldZ = sourceNode.inputPorts.first(where: { $0.name == "Field Z" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.fieldZ
            return .scene3DSource(.tile(
                nodeID: sourceNode.id,
                source: source,
                centerX: Float(centerX),
                centerY: Float(centerY),
                centerZ: Float(centerZ),
                spacingX: Float(max(0.0, spacingX)),
                spacingY: Float(max(0.0, spacingY)),
                spacingZ: Float(max(0.0, spacingZ)),
                fieldX: Float(max(0.0, fieldX)),
                fieldY: Float(max(0.0, fieldY)),
                fieldZ: Float(max(0.0, fieldZ))
            ))
        case .scene3DMaterial:
            return nil
        case .scene3DPrimitive:
            let settings = resolvedScene3DPrimitiveSettings(forNodeID: sourceNode.id)
            let material = resolvedConnectedScene3DMaterial(for: sourceNode)
                ?? Scene3DMaterialNodeSettings(
                    red: settings.materialRed,
                    green: settings.materialGreen,
                    blue: settings.materialBlue,
                    alpha: settings.materialAlpha,
                    metallic: 0.35,
                    roughness: 0.28,
                    emission: 0.0,
                    doubleSided: false
                )
            let pass = PreviewScene3DPrimitivePass(
                nodeID: sourceNode.id,
                settings: settings,
                light: resolvedConnectedScene3DLight(for: sourceNode),
                material: material,
                materialMaps: resolvedConnectedScene3DMaterialMaps(for: sourceNode)
            )
            if case .scene3DSignal = sourcePort.kind {
                return .scene3DSource(.primitive(pass))
            }
            return .scene3DPrimitive(pass)
        case .scene3DText:
            let settings = resolvedScene3DTextSettings(forNodeID: sourceNode.id)
            let material = resolvedConnectedScene3DMaterial(for: sourceNode)
                ?? Scene3DMaterialNodeSettings(
                    red: settings.materialRed,
                    green: settings.materialGreen,
                    blue: settings.materialBlue,
                    alpha: settings.materialAlpha,
                    metallic: 0.35,
                    roughness: 0.28,
                    emission: 0.0,
                    doubleSided: false
                )
            let pass = PreviewScene3DTextPass(
                nodeID: sourceNode.id,
                settings: settings,
                light: resolvedConnectedScene3DLight(for: sourceNode),
                material: material,
                materialMaps: resolvedConnectedScene3DMaterialMaps(for: sourceNode)
            )
            if case .scene3DSignal = sourcePort.kind {
                return .scene3DSource(.text(pass))
            }
            return .scene3DText(pass)
        case .scene3DModel:
            let settings = resolvedScene3DModelSettings(forNodeID: sourceNode.id)
            let pass = PreviewScene3DModelPass(
                nodeID: sourceNode.id,
                settings: settings,
                light: resolvedConnectedScene3DLight(for: sourceNode),
                material: resolvedConnectedScene3DMaterial(for: sourceNode),
                materialMaps: resolvedConnectedScene3DMaterialMaps(for: sourceNode)
            )
            if case .scene3DSignal = sourcePort.kind {
                return .scene3DSource(.model(pass))
            }
            return .scene3DModel(pass)
        case .scene3DGaussianSplat:
            let pass = PreviewScene3DGaussianSplatPass(
                nodeID: sourceNode.id,
                settings: resolvedScene3DGaussianSplatSettings(forNodeID: sourceNode.id)
            )
            if case .scene3DSignal = sourcePort.kind {
                return .scene3DSource(.gaussianSplat(pass))
            }
            return .scene3DGaussianSplat(pass)
        case .scene3DParticle:
            let pass = PreviewScene3DParticlePass(
                nodeID: sourceNode.id,
                settings: resolvedScene3DParticleSettings(forNodeID: sourceNode.id),
                spriteSource: sourceNode.inputPorts.first(where: { $0.name == "Sprite" }).flatMap {
                    previewPassSource(forInputPortID: $0.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
                }
            )
            if case .scene3DSignal = sourcePort.kind {
                return .scene3DSource(.particle(pass))
            }
            return .scene3DParticle(pass)
        case .scene3DLight:
            if case .scene3DSignal = sourcePort.kind {
                return .scene3DSource(.light(PreviewScene3DLight(settings: resolvedScene3DLightSettings(forNodeID: sourceNode.id))))
            }
            return nil
        case .scene3DRender:
            let settings = settings(forScene3DRenderNodeID: sourceNode.id)
            let sources = sourceNode.inputPorts
                .filter { $0.name.hasPrefix("Scene ") }
                .compactMap { previewPassSource(forInputPortID: $0.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID).flatMap(extractScene3DSource) }
            guard sources.isEmpty == false else { return nil }
            let cameraDistance = sourceNode.inputPorts.first(where: { $0.name == "Camera Distance" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.cameraDistance
            let orbit = sourceNode.inputPorts.first(where: { $0.name == "Orbit" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.cameraOrbit
            let pitch = sourceNode.inputPorts.first(where: { $0.name == "Pitch" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.cameraPitch
            let panX = sourceNode.inputPorts.first(where: { $0.name == "Pan X" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.cameraPanX
            let panY = sourceNode.inputPorts.first(where: { $0.name == "Pan Y" }).flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.cameraPanY
            return .scene3DRender(PreviewScene3DRenderPass(
                nodeID: sourceNode.id,
                sources: sources,
                cameraDistance: Float(cameraDistance),
                cameraOrbit: Float(orbit),
                cameraPitch: Float(pitch),
                cameraPanX: Float(panX),
                cameraPanY: Float(panY),
                backgroundAlpha: Float(settings.backgroundAlpha),
                defaultLightIntensity: Float(settings.defaultLightIntensity),
                waterDistortion: Float(settings.waterDistortion),
                waterScale: Float(settings.waterScale),
                waterSpeed: Float(settings.waterSpeed)
            ))
        case .image:
            guard let settings = settings(forImageNodeID: sourceNode.id) else {
                return nil
            }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: settings.imageData))
        case .webView:
            let settings = settings(forWebViewNodeID: sourceNode.id)
            guard !settings.snapshotData.isEmpty else { return nil }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: settings.snapshotData))
        case .aiImage:
            let settings = settings(forAIImageNodeID: sourceNode.id)
            guard !settings.imageData.isEmpty else { return nil }
            return .image(PreviewImagePass(nodeID: sourceNode.id, imageData: settings.imageData))
        case .videoPlayer:
            return .videoPlayer(PreviewVideoPlayerPass(nodeID: sourceNode.id))
        case .video:
            return .video
        case .coreImage, .blur, .bloom, .hueRotate, .posterize, .levels, .glow:
            guard
                let effect = resolvedCoreImageEffect(for: sourceNode),
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Source" }),
                let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
            else {
                return nil
            }

            let settings = settings(forCoreImageNodeID: sourceNode.id)
            let primaryInput = sourceNode.inputPorts.first(where: { $0.name == coreImagePrimaryLabel(for: effect) })
            let secondaryInput = coreImageSecondaryLabel(for: effect).flatMap { label in
                sourceNode.inputPorts.first(where: { $0.name == label })
            }
            return .coreImage(PreviewCoreImagePass(
                nodeID: sourceNode.id,
                source: source,
                effect: effect,
                primary: Float(primaryInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.primary),
                secondary: Float(secondaryInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.secondary)
            ))
        case .underwater:
            guard
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Source" }),
                let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
            else {
                return nil
            }

            let settings = settings(forUnderwaterNodeID: sourceNode.id)
            return .underwater(PreviewUnderwaterPass(
                nodeID: sourceNode.id,
                source: source,
                scale: Float(settings.scale),
                distortion: Float(settings.distortion),
                octaves: settings.octaves,
                lacunarity: Float(settings.lacunarity),
                gain: Float(settings.gain),
                amplitude: Float(settings.amplitude),
                textureScale: Float(settings.textureScale),
                uvClampMargin: Float(settings.uvClampMargin)
            ))
        case .feedback:
            guard
                let sourceInput = sourceNode.inputPorts.first(where: { $0.name == "Source" }),
                let source = previewPassSource(forInputPortID: sourceInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
            else {
                return nil
            }

            let settings = settings(forFeedbackNodeID: sourceNode.id)
            let levelInput = sourceNode.inputPorts.first(where: { $0.name == "Level" })
            let resolvedLevel = levelInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.level
            return .feedback(PreviewFeedbackPass(
                nodeID: sourceNode.id,
                source: source,
                level: Float(max(0.0, min(0.999, resolvedLevel))),
                blendMode: settings.blendMode
            ))
        case .transition:
            guard
                let sourceAInput = sourceNode.inputPorts.first(where: { $0.name == "Source A" }),
                let sourceBInput = sourceNode.inputPorts.first(where: { $0.name == "Source B" }),
                let primarySource = previewPassSource(forInputPortID: sourceAInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID),
                let secondarySource = previewPassSource(forInputPortID: sourceBInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
            else {
                return nil
            }

            let settings = settings(forTransitionNodeID: sourceNode.id)
            let progressInput = sourceNode.inputPorts.first(where: { $0.name == "Progress" })
            let softnessInput = sourceNode.inputPorts.first(where: { $0.name == "Softness" })
            let progress = Float(max(0.0, min(1.0, progressInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.progress)))
            let softness = Float(max(0.0, min(1.0, softnessInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? settings.softness)))
            return .transition(PreviewTransitionPass(
                nodeID: sourceNode.id,
                primary: primarySource,
                secondary: secondarySource,
                style: settings.style,
                progress: progress,
                softness: softness
            ))
        case .mix:
            guard
                let shaderAInput = sourceNode.inputPorts.first(where: { $0.name == "Shader A" }),
                let shaderBInput = sourceNode.inputPorts.first(where: { $0.name == "Shader B" }),
                let primarySource = previewPassSource(forInputPortID: shaderAInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID),
                let secondarySource = previewPassSource(forInputPortID: shaderBInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID),
                let mixInput = sourceNode.inputPorts.first(where: { $0.name == "Mix" })
            else {
                return nil
            }

            let mixAmount = max(0.0, min(1.0, resolvedScalarValue(forInputPortID: mixInput.id) ?? 0.5))
            return .mix(primary: primarySource, secondary: secondarySource, amount: Float(mixAmount))
        case .layers:
            guard let opacityInput = sourceNode.inputPorts.first(where: { $0.name == "Opacity" }) else {
                return nil
            }

            let settings = settings(forLayerNodeID: sourceNode.id)
            let connectedLayers: [PreviewLayerPass] = (1...settings.layerCount).compactMap { index in
                guard
                    let layerInput = sourceNode.inputPorts.first(where: { $0.name == "Layer \(index)" }),
                    let source = previewPassSource(forInputPortID: layerInput.id, visitedNodeIDs: childVisitedNodeIDs, activeFeedbackNodeID: childFeedbackNodeID)
                else {
                    return nil
                }

                let opacityInput = sourceNode.inputPorts.first(where: { $0.name == "Opacity \(index)" })
                let defaultOpacity = settings.layerOpacities[index - 1]
                let resolvedOpacity = opacityInput.flatMap { resolvedScalarValue(forInputPortID: $0.id) } ?? defaultOpacity
                let zIndex: Float
                switch source {
                case .transform(let pass):
                    zIndex = pass.z
                default:
                    zIndex = Float(index - 1)
                }
                return PreviewLayerPass(
                    source: source,
                    opacity: Float(max(0.0, min(1.0, resolvedOpacity))),
                    zIndex: zIndex
                )
            }

            guard connectedLayers.isEmpty == false else {
                return nil
            }

            let opacity = Float(max(0.0, min(1.0, resolvedScalarValue(forInputPortID: opacityInput.id) ?? settings.opacity)))
            return .layers(layers: connectedLayers.sorted { lhs, rhs in
                if lhs.zIndex == rhs.zIndex {
                    return lhs.opacity <= rhs.opacity
                }
                return lhs.zIndex < rhs.zIndex
            }, opacity: opacity)
        case .macro:
            return nil
        case .iteratorVariables:
            return nil
        case .buttonStyle:
            return nil
        default:
            return nil
        }
    }

    private func syncEditableMetalSourceWithSelection() {
        if let codeEditorFragmentNodeID,
           document.nodes.contains(where: { $0.id == codeEditorFragmentNodeID }) {
            setEditableMetalSourceProgrammatically(metalSource(for: codeEditorFragmentNodeID))
            return
        }
        guard let fragmentNodeID = selectedFragmentNode?.id ?? primaryFragmentNode?.id else { return }
        setEditableMetalSourceProgrammatically(metalSource(for: fragmentNodeID))
    }

    private func restoreGraphSnapshot(from text: String) throws {
        suppressDirtyTracking = true
        defer { suppressDirtyTracking = false }
        closeAllPreviewWindows()
        let snapshot = try JSONDecoder().decode(GraphSnapshot.self, from: Data(text.utf8))
        graphActivationID += 1
        preferredCanvasViewportCenter = snapshot.canvasViewportCenter
        currentCanvasViewportCenter = snapshot.canvasViewportCenter
        parameterInspectorWidth = snapshot.parameterInspectorWidth ?? parameterInspectorWidth
        nodeLibraryWidth = snapshot.nodeLibraryWidth ?? nodeLibraryWidth
        let parsed = ISFParser.parse(shaderSource: snapshot.source)
        let restoredUniforms = try snapshot.uniforms.map { try $0.uniformDescriptor() }
        var uniformByName: [String: UniformDescriptor] = [:]
        for uniform in restoredUniforms {
            let key = uniform.name.lowercased()
            if uniformByName[key] == nil {
                uniformByName[key] = uniform
            }
        }
        var fallbackUniforms: [String: UniformDescriptor] = [:]
        for uniform in parsed.uniforms {
            let key = uniform.name.lowercased()
            if fallbackUniforms[key] == nil {
                fallbackUniforms[key] = uniform
            }
        }

        let restoredNodes = try snapshot.nodes.compactMap { savedNode -> GraphNode? in
            let nodeID = try savedNode.nodeID()
            let position = CGPoint(x: savedNode.positionX, y: savedNode.positionY)

            switch savedNode.kind {
            case "uniform":
                guard let uniform = uniformByName[savedNode.title.lowercased()] ?? fallbackUniforms[savedNode.title.lowercased()] else {
                    return nil
                }
                let outputPort = GraphPort(
                    id: "uniform:\(uniform.name)",
                    nodeID: nodeID,
                    name: uniform.name,
                    direction: .output,
                    kind: .uniform(uniform.id)
                )
                return GraphNode(
                    id: nodeID,
                    title: savedNode.title,
                    kind: .uniform(uniform),
                    position: position,
                    inputPorts: [],
                    outputPorts: [outputPort]
                )
            case "time":
                return GraphNode(
                    id: nodeID,
                    title: savedNode.title,
                    kind: .time,
                    position: position,
                    inputPorts: [],
                    outputPorts: [
                        GraphPort(
                            id: "time:output",
                            nodeID: nodeID,
                            name: "TIME",
                            direction: .output,
                            kind: .time
                        )
                    ]
                )
            case "mouse":
                return GraphNode(
                    id: nodeID,
                    title: savedNode.title,
                    kind: .mouse,
                    position: position,
                    inputPorts: [],
                    outputPorts: [
                        GraphPort(
                            id: "mouse:\(nodeID.uuidString):output",
                            nodeID: nodeID,
                            name: "Position",
                            direction: .output,
                            kind: .pointSignal("mouse")
                        ),
                        GraphPort(
                            id: "mouse:\(nodeID.uuidString):leftClick",
                            nodeID: nodeID,
                            name: "Left Click",
                            direction: .output,
                            kind: .scalarSignal("mouseLeftClick")
                        ),
                        GraphPort(
                            id: "mouse:\(nodeID.uuidString):rightClick",
                            nodeID: nodeID,
