                    var updatedDocument = document
                    updatedDocument.nodes[index] = GraphNode(
                        id: updatedDocument.nodes[index].id,
                        title: updatedDocument.nodes[index].title,
                        kind: updatedDocument.nodes[index].kind,
                        position: updatedDocument.nodes[index].position,
                        inputPorts: makeScene3DGaussianSplatInputPorts(nodeID: node.id),
                        outputPorts: makeScene3DGaussianSplatOutputPorts(nodeID: node.id)
                    )
                    document = updatedDocument
                }
            }
            if case .transition = node.kind, transitionNodeSettings[node.id] == nil {
                transitionNodeSettings[node.id] = TransitionNodeSettings()
                transitionNodeRuntimeStates[node.id] = TransitionNodeRuntimeState()
            }
            if case .circle = node.kind, circleNodeSettings[node.id] == nil {
                circleNodeSettings[node.id] = CircleNodeSettings()
            }
            if case .clear = node.kind, clearNodeSettings[node.id] == nil {
                clearNodeSettings[node.id] = ClearNodeSettings()
            }
            if case .image = node.kind, imageNodeSettings[node.id] == nil {
                imageNodeSettings[node.id] = ImageNodeSettings(filename: "Image", imageData: Data())
            }
        if case .webView = node.kind, webViewNodeSettings[node.id] == nil {
            webViewNodeSettings[node.id] = WebViewNodeSettings()
        }
            if case .aiImage = node.kind, aiImageNodeSettings[node.id] == nil {
                aiImageNodeSettings[node.id] = AIImageNodeSettings()
            }
            if case .videoPlayer = node.kind, videoPlayerNodeSettings[node.id] == nil {
                videoPlayerNodeSettings[node.id] = VideoPlayerNodeSettings()
                videoPlayerNodeStatus[node.id] = "Choose a movie file."
            }
            if case .feedback = node.kind, feedbackNodeSettings[node.id] == nil {
                feedbackNodeSettings[node.id] = FeedbackNodeSettings()
            }
            if case .reactionDiffusion = node.kind, reactionDiffusionNodeSettings[node.id] == nil {
                reactionDiffusionNodeSettings[node.id] = ReactionDiffusionNodeSettings()
            }
            if let effect = resolvedCoreImageEffect(for: node), coreImageNodeSettings[node.id] == nil {
                coreImageNodeSettings[node.id] = defaultCoreImageSettings(for: effect)
            }
            if case .underwater = node.kind, underwaterNodeSettings[node.id] == nil {
                underwaterNodeSettings[node.id] = UnderwaterNodeSettings()
            }
            if case .layers = node.kind, layerNodeSettings[node.id] == nil {
                layerNodeSettings[node.id] = LayerNodeSettings()
            }
        }
        restoredDocument = syncFragmentNodePorts(in: restoredDocument)
        restoredDocument = syncSliderStyleNodePorts(in: restoredDocument)
        restoredDocument = syncButtonStyleNodePorts(in: restoredDocument)
        restoredDocument = syncCoreImageNodePorts(in: restoredDocument)
        restoredDocument = syncCompareNodePorts(in: restoredDocument)
        restoredDocument = syncStringFormatNodePorts(in: restoredDocument)
        restoredDocument = syncExpressionNodePorts(in: restoredDocument)
        restoredDocument = syncArrayNodePorts(in: restoredDocument)
        restoredDocument = syncTextImageNodePorts(in: restoredDocument)
        restoredDocument = syncHSLColorNodePorts(in: restoredDocument)
        restoredDocument = syncVideoPlayerNodePorts(in: restoredDocument)
        restoredDocument = syncLayerNodePorts(in: restoredDocument)
        restoredDocument = syncOSCBundleNodePorts(in: restoredDocument)

        let validPortIDs = Set(restoredDocument.nodes.flatMap { $0.allPorts }.map { $0.id })
        restoredDocument.connections = snapshot.connections.compactMap { savedConnection -> GraphConnection? in
            guard validPortIDs.contains(savedConnection.fromPortID),
                  validPortIDs.contains(savedConnection.toPortID) else {
                return nil
            }
            return GraphConnection(fromPortID: savedConnection.fromPortID, toPortID: savedConnection.toPortID)
        }

        document = restoredDocument
        baselineUniformValues = Dictionary(uniqueKeysWithValues: restoredDocument.uniforms.map { ($0.id, $0.defaultValue) })
        setEditableSourceProgrammatically(restoredDocument.source)
        synchronizeWebViewControllers()
        synchronizeVideoPlayerControllers()
        reconnectTimeNodesIfNeeded()
        reconnectRenderNodesIfNeeded()
        selectedNodeID = restoredDocument.nodes.first(where: { $0.isPrimaryFragment })?.id ?? restoredDocument.nodes.first?.id
        syncEditableMetalSourceWithSelection()
        updateAudioMonitorState()
        updateVideoMonitorState()
        updateInspectorFocus()
        validateMetalSource()
        updateMIDINodes()
        if isApplyingHistory {
            lastHistoryGraphText = text
        } else {
            resetHistoryTracking(currentGraphText: text)
        }
        objectWillChange.send()
    }

    private func shouldUpdateBaseline(for uniformID: UniformDescriptor.ID) -> Bool {
        guard
            let sourceNode = document.nodes.first(where: { node in
                guard case .uniform(let uniform) = node.kind else { return false }
                return uniform.id == uniformID
            }),
            let outputPort = sourceNode.outputPorts.first
        else {
            return true
        }

        guard
            let connection = document.connections.first(where: { $0.fromPortID == outputPort.id }),
            let inputPort = port(withID: connection.toPortID),
            case .uniform(let targetUniformID) = inputPort.kind
        else {
            return true
        }

        return targetUniformID == uniformID
    }

    private func preferredAutoConnectInputPort(for uniformID: UniformDescriptor.ID) -> GraphPort? {
        if let selectedNode,
           case .metalFragment = selectedNode.kind,
           let port = selectedNode.inputPorts.first(where: { $0.kind == .uniform(uniformID) }) {
            return port
        }

        if let selectedNode,
           case .renderOutput = selectedNode.kind,
           let fragmentID = connectedFragmentNodeID(forRenderNodeID: selectedNode.id),
           let fragmentNode = document.nodes.first(where: { $0.id == fragmentID }),
           let port = fragmentNode.inputPorts.first(where: { $0.kind == .uniform(uniformID) }) {
            return port
        }

        return document.nodes
            .first(where: { node in
                if case .metalFragment = node.kind {
                    return node.inputPorts.contains(where: { $0.kind == .uniform(uniformID) })
                }
                return false
            })?
            .inputPorts
            .first(where: { $0.kind == .uniform(uniformID) })
    }

    private func preferredAutoConnectMouseInputPort() -> GraphPort? {
        if let selectedNode,
           case .metalFragment = selectedNode.kind,
           let port = selectedNode.inputPorts.first(where: { inputPort in
               guard case .uniform(let uniformID) = inputPort.kind,
                     let uniform = currentUniform(matching: uniformID) else { return false }
               return uniform.kind == .point2D
           }) {
            return port
        }

        if let selectedNode,
           case .renderOutput = selectedNode.kind,
           let fragmentID = connectedFragmentNodeID(forRenderNodeID: selectedNode.id),
           let fragmentNode = document.nodes.first(where: { $0.id == fragmentID }),
           let port = fragmentNode.inputPorts.first(where: { inputPort in
               guard case .uniform(let uniformID) = inputPort.kind,
                     let uniform = currentUniform(matching: uniformID) else { return false }
               return uniform.kind == .point2D
           }) {
            return port
        }

        return document.nodes
            .first(where: { node in
                if case .metalFragment = node.kind {
                    return node.inputPorts.contains(where: { inputPort in
                        guard case .uniform(let uniformID) = inputPort.kind,
                              let uniform = currentUniform(matching: uniformID) else { return false }
                        return uniform.kind == .point2D
                    })
                }
                return false
            })?
            .inputPorts
            .first(where: { inputPort in
                guard case .uniform(let uniformID) = inputPort.kind,
                      let uniform = currentUniform(matching: uniformID) else { return false }
                return uniform.kind == .point2D
            })
    }

