    private func makeLayerInputPorts(nodeID: GraphNode.ID, layerCount: Int) -> [GraphPort] {
        let normalizedCount = max(2, layerCount)
        var ports: [GraphPort] = []

        for index in 1...normalizedCount {
            let suffix: String
            switch index {
            case 1:
                suffix = "background"
            case 2:
                suffix = "foreground"
            default:
                suffix = "layer\(index)"
            }

            ports.append(GraphPort(
                id: "layers:\(nodeID.uuidString):\(suffix)",
                nodeID: nodeID,
                name: "Layer \(index)",
                direction: .input,
                kind: .fragmentShader
            ))

            ports.append(GraphPort(
                id: "layers:\(nodeID.uuidString):opacity\(index)",
                nodeID: nodeID,
                name: "Opacity \(index)",
                direction: .input,
                kind: .scalarSignal("layerOpacity:\(index)")
            ))
        }

        ports.append(
            GraphPort(
                id: "layers:\(nodeID.uuidString):opacity",
                nodeID: nodeID,
                name: "Opacity",
                direction: .input,
                kind: .scalarSignal("opacity")
            )
        )

        return ports
    }

    private func makeOSCBundleInputPorts(nodeID: GraphNode.ID, packetCount: Int) -> [GraphPort] {
        let normalizedCount = max(1, packetCount)
        return (1...normalizedCount).map { index in
            GraphPort(
                id: "oscbundle:\(nodeID.uuidString):packet\(index)",
                nodeID: nodeID,
                name: "Packet \(index)",
                direction: .input,
                kind: .oscPacketSignal("packet\(index)")
            )
        }
    }

