    private func stringFormatPlaceholderIndices(in template: String) -> [Int] {
        let pattern = #"\{([0-3])\}"#
        guard let regex = try? NSRegularExpression(pattern: pattern) else {
            return [0]
        }

        let range = NSRange(template.startIndex..., in: template)
        let matches = regex.matches(in: template, range: range)
        let indices = matches.compactMap { match -> Int? in
            guard
                match.numberOfRanges > 1,
                let captureRange = Range(match.range(at: 1), in: template)
            else {
                return nil
            }
            return Int(template[captureRange])
        }

        let uniqueSorted = Array(Set(indices)).sorted()
        return uniqueSorted.isEmpty ? [0] : uniqueSorted
    }

    private func stringFormatFallbackText(for index: Int, settings: StringFormatNodeSettings) -> String {
        switch index {
        case 0: return settings.text1
        case 1: return settings.text2
        case 2: return settings.text3
        case 3: return settings.text4
        default: return ""
        }
    }

    private func updateStringFormatFallbackText(_ index: Int, value: String, settings: inout StringFormatNodeSettings) {
        switch index {
        case 0: settings.text1 = value
        case 1: settings.text2 = value
        case 2: settings.text3 = value
        case 3: settings.text4 = value
        default: break
        }
    }

    private func stringFromScalar(_ value: Double) -> String {
        if value.rounded() == value {
            return String(Int(value))
        }

        var text = String(format: "%.4f", value)
        while text.contains(".") && (text.hasSuffix("0") || text.hasSuffix(".")) {
            text.removeLast()
        }
        return text
    }

    private func evaluateExpressionNode(
        _ node: GraphNode,
        settings: ExpressionNodeSettings,
        visitedNodeIDs: Set<GraphNode.ID>
    ) -> Double? {
        var values = settings.variables
        for inputPort in node.inputPorts {
            let fallback = values[inputPort.name] ?? 0.0
            values[inputPort.name] = scalarValue(forInputPortID: inputPort.id, visitedNodeIDs: visitedNodeIDs) ?? fallback
        }
        return ExpressionEngine.evaluate(settings.expression, variables: values)
    }

    private func makeStringFormatInputPorts(nodeID: GraphNode.ID, template: String) -> [GraphPort] {
        let indices = stringFormatPlaceholderIndices(in: template)
        return indices.map { index in
            GraphPort(
                id: "stringformat:\(nodeID.uuidString):text\(index + 1)",
                nodeID: nodeID,
                name: "Text \(index + 1)",
                direction: .input,
                kind: .stringSignal("text\(index + 1)")
            )
        }
    }

    private static func expressionVariableNames(in expression: String) -> [String] {
        ExpressionEngine.variableNames(in: expression)
    }

    private func makeExpressionInputPorts(nodeID: GraphNode.ID, expression: String) -> [GraphPort] {
        Self.expressionVariableNames(in: expression).map { name in
            GraphPort(
                id: "expression:\(nodeID.uuidString):\(name)",
                nodeID: nodeID,
                name: name,
                direction: .input,
                kind: .scalarSignal(name)
            )
        }
    }

