    private func syncCompareNodePorts(in document: ShaderDocument) -> ShaderDocument {
        var updatedDocument = document
        updatedDocument.nodes = updatedDocument.nodes.map { node in
            guard case .compare = node.kind else { return node }
            return GraphNode(
                id: node.id,
                title: node.title,
                kind: node.kind,
                position: node.position,
