    private func syncArrayNodePorts(in document: ShaderDocument) -> ShaderDocument {
        var updatedDocument = document
        var removedPortIDs = Set<GraphPort.ID>()

        updatedDocument.nodes = updatedDocument.nodes.map { node in
            let inputPorts: [GraphPort]
            switch node.kind {
            case .scalarArray:
                inputPorts = makeScalarArrayInputPorts(nodeID: node.id, count: settings(forScalarArrayNodeID: node.id).count)
            case .stringArray:
                inputPorts = makeStringArrayInputPorts(nodeID: node.id, count: settings(forStringArrayNodeID: node.id).count)
            case .colorArray:
                inputPorts = makeColorArrayInputPorts(nodeID: node.id, count: settings(forColorArrayNodeID: node.id).count)
            case .imageArray:
                inputPorts = makeImageArrayInputPorts(nodeID: node.id, count: settings(forImageArrayNodeID: node.id).count)
            case .scalarMultiplexor:
                inputPorts = makeScalarMultiplexorInputPorts(nodeID: node.id, count: settings(forScalarArrayNodeID: node.id).count)
            case .stringMultiplexor:
                inputPorts = makeStringMultiplexorInputPorts(nodeID: node.id, count: settings(forStringArrayNodeID: node.id).count)
            case .colorMultiplexor:
                inputPorts = makeColorMultiplexorInputPorts(nodeID: node.id, count: settings(forColorArrayNodeID: node.id).count)
            case .imageMultiplexor:
                inputPorts = makeImageMultiplexorInputPorts(nodeID: node.id, count: settings(forImageArrayNodeID: node.id).count)
            default:
                return node
            }

            let preservedPortIDs = Set(inputPorts.map(\.id))
            let previousPortIDs = Set(node.inputPorts.map(\.id))
            removedPortIDs.formUnion(previousPortIDs.subtracting(preservedPortIDs))

            return GraphNode(
                id: node.id,
                title: node.title,
                kind: node.kind,
                position: node.position,
                inputPorts: inputPorts,
                outputPorts: node.outputPorts
            )
        }

        if removedPortIDs.isEmpty == false {
            updatedDocument.connections.removeAll { connection in
                removedPortIDs.contains(connection.fromPortID) || removedPortIDs.contains(connection.toPortID)
            }
        }

        return updatedDocument
    }

