    private func normalizedLayerSettings(_ settings: LayerNodeSettings) -> LayerNodeSettings {
        var normalized = settings
        normalized.layerCount = max(2, normalized.layerCount)
        if normalized.layerOpacities.count < normalized.layerCount {
            normalized.layerOpacities.append(contentsOf: repeatElement(1.0, count: normalized.layerCount - normalized.layerOpacities.count))
        } else if normalized.layerOpacities.count > normalized.layerCount {
            normalized.layerOpacities = Array(normalized.layerOpacities.prefix(normalized.layerCount))
        }
        return normalized
    }

    private func normalizedOSCBundleSettings(_ settings: OSCBundleNodeSettings) -> OSCBundleNodeSettings {
        var normalized = settings
        normalized.packetCount = max(1, normalized.packetCount)
        return normalized
    }

    private func normalizedScalarArraySettings(_ settings: ScalarArrayNodeSettings) -> ScalarArrayNodeSettings {
        var normalized = settings
        normalized.count = max(1, normalized.count)
        if normalized.values.count < normalized.count {
            normalized.values.append(contentsOf: repeatElement(0.0, count: normalized.count - normalized.values.count))
        } else if normalized.values.count > normalized.count {
            normalized.values = Array(normalized.values.prefix(normalized.count))
        }
        return normalized
    }

    private func normalizedStringArraySettings(_ settings: StringArrayNodeSettings) -> StringArrayNodeSettings {
        var normalized = settings
        normalized.count = max(1, normalized.count)
        if normalized.values.count < normalized.count {
            normalized.values.append(contentsOf: repeatElement("", count: normalized.count - normalized.values.count))
        } else if normalized.values.count > normalized.count {
            normalized.values = Array(normalized.values.prefix(normalized.count))
        }
        return normalized
    }

    private func normalizedColorArraySettings(_ settings: ColorArrayNodeSettings) -> ColorArrayNodeSettings {
        var normalized = settings
        normalized.count = max(1, normalized.count)
        if normalized.values.count < normalized.count {
            normalized.values.append(contentsOf: repeatElement(ArrayColorValue(), count: normalized.count - normalized.values.count))
        } else if normalized.values.count > normalized.count {
            normalized.values = Array(normalized.values.prefix(normalized.count))
        }
        return normalized
    }

    private func arrayItemIndex(from name: String) -> Int? {
        if name.hasPrefix("Item ") {
            return Int(name.dropFirst(5))
        }
        if name.hasPrefix("Value "), let value = Int(name.dropFirst(6)) {
            return max(0, value - 1)
        }
        if name.hasPrefix("Text "), let value = Int(name.dropFirst(5)) {
            return max(0, value - 1)
        }
        if name.hasPrefix("Color "), let value = Int(name.dropFirst(6)) {
            return max(0, value - 1)
        }
        return nil
    }

    private func coreImageEffectKind(for nodeKind: GraphNodeKind) -> CoreImageEffectKind? {
        switch nodeKind {
        case .coreImage:
            return nil
        case .blur:
            return .blur
        case .bloom:
            return .bloom
        case .hueRotate:
            return .hueRotate
        case .posterize:
            return .posterize
        case .levels:
            return .levels
        case .glow:
            return .glow
        default:
            return nil
        }
    }

    private func resolvedCoreImageEffect(for node: GraphNode) -> CoreImageEffectKind? {
        if case .coreImage = node.kind {
            return settings(forCoreImageNodeID: node.id).effect
        }
        return coreImageEffectKind(for: node.kind)
    }

    private func graphNodeKind(for effect: CoreImageEffectKind) -> GraphNodeKind {
        switch effect {
        case .blur:
            return .blur
        case .bloom:
            return .bloom
        case .hueRotate:
            return .hueRotate
        case .posterize:
            return .posterize
        case .levels:
            return .levels
        case .glow:
            return .glow
        case .edges, .pixellate, .twirl, .kaleidoscope:
            return .coreImage
        }
    }

    private func defaultCoreImageSettings(for effect: CoreImageEffectKind) -> CoreImageNodeSettings {
        switch effect {
        case .blur:
            return CoreImageNodeSettings(effect: .blur, primary: 12.0, secondary: 0.0)
        case .bloom:
            return CoreImageNodeSettings(effect: .bloom, primary: 10.0, secondary: 0.75)
        case .hueRotate:
            return CoreImageNodeSettings(effect: .hueRotate, primary: 0.5, secondary: 0.0)
        case .posterize:
            return CoreImageNodeSettings(effect: .posterize, primary: 4.0, secondary: 0.0)
        case .levels:
            return CoreImageNodeSettings(effect: .levels, primary: 0.0, secondary: 1.0)
        case .glow:
            return CoreImageNodeSettings(effect: .glow, primary: 10.0, secondary: 0.9)
        case .edges:
            return CoreImageNodeSettings(effect: .edges, primary: 1.5, secondary: 0.0)
        case .pixellate:
            return CoreImageNodeSettings(effect: .pixellate, primary: 24.0, secondary: 0.0)
        case .twirl:
            return CoreImageNodeSettings(effect: .twirl, primary: 0.35, secondary: 0.5)
        case .kaleidoscope:
            return CoreImageNodeSettings(effect: .kaleidoscope, primary: 6.0, secondary: 0.0)
        }
    }

