    private func completeFragmentMetalSources() -> [GraphNode.ID: String] {
        Dictionary(
            uniqueKeysWithValues: document.nodes.compactMap { node in
                guard case .metalFragment = node.kind else { return nil }
                return (node.id, metalSource(for: node.id))
            }
        )
    }

    private func flushSessionSnapshot() {
        commitPendingEditorState()
        persistSessionSnapshot()
        autosaveCurrentGraphFileIfNeeded()
    }

    private func autosaveCurrentGraphFileIfNeeded() {
        guard let currentGraphFileURL else { return }
        do {
            let text = try currentGraphSnapshotText()
            try writeGraphText(text, to: currentGraphFileURL)
        } catch {
            statusMessage = "Autosave failed: \(error.localizedDescription)"
        }
    }

    private func refreshCurrentGraphDisplayName() {
        if let currentGraphFileURL {
            currentGraphDisplayName = currentGraphFileURL.deletingPathExtension().lastPathComponent
        } else if document.name.isEmpty == false {
            currentGraphDisplayName = document.name
        } else {
            currentGraphDisplayName = "Untitled Graph"
        }
    }

    private func markCurrentGraphDirty() {
        refreshCurrentGraphDisplayName()
        guard !suppressDirtyTracking else { return }
        guard let currentText = try? currentGraphSnapshotText() else {
            isCurrentGraphDirty = true
            return
        }
        if let lastSavedGraphText,
           currentText != lastSavedGraphText,
           isWithinViewportDirtyGraceWindow,
           snapshotsDifferOnlyByViewport(currentText: currentText, savedText: lastSavedGraphText) {
            self.lastSavedGraphText = currentText
            isCurrentGraphDirty = false
            return
        }

        isCurrentGraphDirty = currentText != lastSavedGraphText
        if isCurrentGraphDirty {
            logDirtyMismatch(currentText: currentText)
        }
    }

    private func markCurrentGraphSaved(savedGraphText: String? = nil) {
        refreshCurrentGraphDisplayName()
        let resolvedSavedText = savedGraphText ?? (try? currentGraphSnapshotText())
        lastSavedGraphText = resolvedSavedText
        isCurrentGraphDirty = false
    }

    private func logDirtyMismatch(currentText: String) {
        guard let lastSavedGraphText else {
            return
        }
        if currentText == lastSavedGraphText { return }
    }

    private var isWithinViewportDirtyGraceWindow: Bool {
        guard let viewportDirtyGraceDeadline else { return false }
        return CACurrentMediaTime() <= viewportDirtyGraceDeadline
    }

    private func beginViewportDirtyGraceWindow() {
        viewportDirtyGraceDeadline = CACurrentMediaTime() + 0.75
    }

    private func snapshotsDifferOnlyByViewport(currentText: String, savedText: String) -> Bool {
        sanitizedSnapshotForDirtyComparison(currentText) == sanitizedSnapshotForDirtyComparison(savedText)
    }

    private func sanitizedSnapshotForDirtyComparison(_ text: String) -> String {
        var sanitized = text
        let patterns = [
            #""canvasViewportCenterX":[^,}]*,?"#,
            #""canvasViewportCenterY":[^,}]*,?"#
        ]
        for pattern in patterns {
            sanitized = sanitized.replacingOccurrences(
                of: pattern,
                with: "",
                options: .regularExpression
            )
        }
        sanitized = sanitized.replacingOccurrences(of: ",}", with: "}")
        sanitized = sanitized.replacingOccurrences(of: ",,", with: ",")
        return sanitized
    }

    private func restoreSessionSnapshotIfPossible() -> Bool {
        guard let url = try? Self.sessionSnapshotURL(),
              FileManager.default.fileExists(atPath: url.path),
              let data = try? Data(contentsOf: url),
              let sessionSnapshot = try? JSONDecoder().decode(SessionSnapshot.self, from: data)
        else {
            return false
        }

        guard sessionSnapshotLooksRestorable(sessionSnapshot) else {
            return false
        }

        do {
            let graphData = try JSONEncoder().encode(sessionSnapshot.graph)
            guard let graphText = String(data: graphData, encoding: .utf8) else {
                return false
            }
            try restoreGraphSnapshot(from: graphText)
            currentGraphFileURL = sessionSnapshot.currentGraphFilePath.map(URL.init(fileURLWithPath:))
            if preferredCanvasViewportCenter == nil, let currentGraphFileURL {
                preferredCanvasViewportCenter = loadCanvasViewport(for: currentGraphFileURL)
            } else if currentGraphFileURL == nil {
                preferredCanvasViewportCenter = nil
            }
            canvasViewportRestoreRequestID = UUID()
            refreshCurrentGraphDisplayName()
            markCurrentGraphSaved()
            restartOSCInputRouting()
            return true
        } catch {
            statusMessage = "Could not restore last session: \(error.localizedDescription)"
            return false
        }
    }

    private func sessionSnapshotLooksRestorable(_ snapshot: SessionSnapshot) -> Bool {
        if snapshot.currentGraphFilePath != nil {
            return true
        }

        return snapshot.graph.nodes.isEmpty == false
    }

    private func canvasViewportDefaultsKey(for url: URL) -> String {
        "graphCanvasViewport:\(url.path)"
    }

    private func persistCanvasViewport(_ center: CGPoint, for url: URL) {
        let defaults = UserDefaults.standard
        let key = canvasViewportDefaultsKey(for: url)
        defaults.set(center.x, forKey: key + ":x")
        defaults.set(center.y, forKey: key + ":y")
    }

    private func loadCanvasViewport(for url: URL) -> CGPoint? {
        let defaults = UserDefaults.standard
        let key = canvasViewportDefaultsKey(for: url)
        guard defaults.object(forKey: key + ":x") != nil,
              defaults.object(forKey: key + ":y") != nil else {
            return nil
        }
        return CGPoint(
            x: defaults.double(forKey: key + ":x"),
            y: defaults.double(forKey: key + ":y")
        )
    }

    private static func sessionSnapshotURL() throws -> URL {
        let appSupport = try FileManager.default.url(
            for: .applicationSupportDirectory,
            in: .userDomainMask,
            appropriateFor: nil,
            create: true
        )
        return appSupport
            .appendingPathComponent("MetalNode", isDirectory: true)
            .appendingPathComponent(sessionSnapshotFilename)
    }

    private func sanitizedFilename(_ value: String) -> String {
        let invalidCharacters = CharacterSet(charactersIn: "/:\\?%*|\"<>")
        let cleaned = value.components(separatedBy: invalidCharacters).joined(separator: "-")
        let trimmed = cleaned.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? "MetalNode" : trimmed.replacingOccurrences(of: " ", with: "")
    }

