            clearNodeSettings = try container.decodeIfPresent([String: ClearNodeSettings].self, forKey: .clearNodeSettings) ?? [:]
            imageNodeSettings = try container.decodeIfPresent([String: ImageNodeSettings].self, forKey: .imageNodeSettings) ?? [:]
            webViewNodeSettings = try container.decodeIfPresent([String: WebViewNodeSettings].self, forKey: .webViewNodeSettings) ?? [:]
            aiImageNodeSettings = try container.decodeIfPresent([String: AIImageNodeSettings].self, forKey: .aiImageNodeSettings) ?? [:]
            videoPlayerNodeSettings = try container.decodeIfPresent([String: VideoPlayerNodeSettings].self, forKey: .videoPlayerNodeSettings) ?? [:]
            feedbackNodeSettings = try container.decodeIfPresent([String: FeedbackNodeSettings].self, forKey: .feedbackNodeSettings) ?? [:]
            reactionDiffusionNodeSettings = try container.decodeIfPresent([String: ReactionDiffusionNodeSettings].self, forKey: .reactionDiffusionNodeSettings) ?? [:]
            coreImageNodeSettings = try container.decodeIfPresent([String: CoreImageNodeSettings].self, forKey: .coreImageNodeSettings) ?? [:]
            underwaterNodeSettings = try container.decodeIfPresent([String: UnderwaterNodeSettings].self, forKey: .underwaterNodeSettings) ?? [:]
            layerNodeSettings = try container.decodeIfPresent([String: LayerNodeSettings].self, forKey: .layerNodeSettings) ?? [:]
            uniforms = try container.decode([SavedUniform].self, forKey: .uniforms)
            nodes = try container.decode([SavedNode].self, forKey: .nodes)
            connections = try container.decode([SavedConnection].self, forKey: .connections)
        }
    }

    private struct SavedUniform: Codable {
        let id: String?
        let name: String
        let kind: String
        let defaultPayload: String
        let minValue: Double?
        let maxValue: Double?
        let label: String?

        init(_ uniform: UniformDescriptor) {
            id = uniform.id.uuidString
            name = uniform.name
            kind = uniform.kind.rawValue
            minValue = uniform.minValue
            maxValue = uniform.maxValue
            label = uniform.label
            switch uniform.defaultValue {
            case .float(let value):
                defaultPayload = "\(value)"
            case .color(let value):
                defaultPayload = "\(value.x),\(value.y),\(value.z),\(value.w)"
            case .point(let value):
                defaultPayload = "\(value.x),\(value.y)"
            case .point3(let value):
                defaultPayload = "\(value.x),\(value.y),\(value.z)"
            case .point4(let value):
                defaultPayload = "\(value.x),\(value.y),\(value.z),\(value.w)"
            case .bool(let value):
                defaultPayload = value ? "true" : "false"
            case .image(let value):
                defaultPayload = value
            }
        }

        func uniformDescriptor() throws -> UniformDescriptor {
            guard let uniformKind = UniformKind(rawValue: kind) else {
                throw GraphSnapshotError.invalidUniformKind(kind)
            }

            let defaultValue: UniformValue
            switch uniformKind {
            case .float:
                defaultValue = .float(Double(defaultPayload) ?? 0.0)
            case .color:
                let values = defaultPayload.split(separator: ",").compactMap { Float($0) }
                defaultValue = .color(SIMD4<Float>(
                    GraphStore.value(at: 0, in: values) ?? 1,
                    GraphStore.value(at: 1, in: values) ?? 1,
                    GraphStore.value(at: 2, in: values) ?? 1,
                    GraphStore.value(at: 3, in: values) ?? 1
                ))
            case .point2D:
                let values = defaultPayload.split(separator: ",").compactMap { Double($0) }
                defaultValue = .point(CGPoint(x: GraphStore.value(at: 0, in: values) ?? 0.5, y: GraphStore.value(at: 1, in: values) ?? 0.5))
            case .float3:
                let values = defaultPayload.split(separator: ",").compactMap { Double($0) }
                defaultValue = .point3(Point3Value(
                    x: GraphStore.value(at: 0, in: values) ?? 0.0,
                    y: GraphStore.value(at: 1, in: values) ?? 0.0,
                    z: GraphStore.value(at: 2, in: values) ?? 0.0
                ))
            case .float4:
                let values = defaultPayload.split(separator: ",").compactMap { Double($0) }
                defaultValue = .point4(Point4Value(
                    x: GraphStore.value(at: 0, in: values) ?? 0.0,
                    y: GraphStore.value(at: 1, in: values) ?? 0.0,
                    z: GraphStore.value(at: 2, in: values) ?? 0.0,
                    w: GraphStore.value(at: 3, in: values) ?? 0.0
                ))
            case .bool:
                defaultValue = .bool(defaultPayload.lowercased() == "true")
            case .image:
                defaultValue = .image(defaultPayload)
            }

            return UniformDescriptor(
                id: UUID(uuidString: id ?? "") ?? UUID(),
                name: name,
                kind: uniformKind,
                defaultValue: defaultValue,
                minValue: minValue,
                maxValue: maxValue,
                label: label
            )
        }
    }

