    private enum GraphSnapshotError: LocalizedError {
        case invalidUniformKind(String)
        case invalidNodeID(String)

        var errorDescription: String? {
            switch self {
            case .invalidUniformKind(let kind):
                return "Unsupported uniform kind: \(kind)"
            case .invalidNodeID(let id):
                return "Invalid saved node id: \(id)"
            }
        }
    }

    private static func value<T>(at index: Int, in values: [T]) -> T? {
        guard values.indices.contains(index) else { return nil }
        return values[index]
    }

    private static let sampleISF = """
    /*
    {
      "DESCRIPTION": "Metal fracture bloom",
      "CATEGORIES": [ "Generator", "Stylize" ],
      "INPUTS": [
        { "NAME": "intensity", "TYPE": "float", "DEFAULT": 0.72, "MIN": 0.0, "MAX": 1.0, "LABEL": "Intensity" },
        { "NAME": "tint", "TYPE": "color", "DEFAULT": [0.96, 0.44, 0.18, 1.0], "LABEL": "Tint" },
        { "NAME": "origin", "TYPE": "point2D", "DEFAULT": [0.5, 0.5], "LABEL": "Origin" },
        { "NAME": "useBands", "TYPE": "bool", "DEFAULT": true, "LABEL": "Bands" }
      ]
    }
    */

    void main() {
      // Original ISF shader body goes here.
}
"""

    private static let blankDocument = ShaderDocument(
        name: "Untitled Graph",
        description: "Blank composition",
        source: "",
        shaderPrelude: "",
        shaderBody: "",
        uniforms: [],
        nodes: [],
        connections: []
    )

    private static let defaultEditableMetalSource = """
/*
{
  "DESCRIPTION": "Custom Metal fragment",
  "INPUTS": [
    { "NAME": "Speed", "TYPE": "float", "DEFAULT": 0.5, "MIN": 0.0, "MAX": 1.0 },
    { "NAME": "Mix", "TYPE": "float", "DEFAULT": 0.65, "MIN": 0.0, "MAX": 1.0 },
    { "NAME": "Tint", "TYPE": "color", "DEFAULT": [1.0, 0.5, 0.2, 1.0] },
    { "NAME": "Center", "TYPE": "point2D", "DEFAULT": [0.5, 0.5] },
    { "NAME": "Axis3", "TYPE": "float3", "DEFAULT": [0.0, 0.0, 1.0] },
    { "NAME": "Quat4", "TYPE": "float4", "DEFAULT": [0.0, 0.0, 0.0, 1.0] },
    { "NAME": "UseBands", "TYPE": "bool", "DEFAULT": true },
    { "NAME": "texture", "TYPE": "image", "DEFAULT": "Texture" }
  ]
}
*/

// The metadata block above defines the fragment node's ports.
// Access float/color/point/bool inputs through the packed uniform buffers below:
//   float Speed = floatUniforms[0];
//   float Mix = floatUniforms[1];
//   float4 Tint = colorUniforms[0];
//   float2 Center = pointUniforms[0];
//   float3 Axis3 = point3Uniforms[0];
//   float4 Quat4 = point4Uniforms[0];
//   bool UseBands = boolUniforms[0] != 0;
//
// Image uniforms declared in the metadata header become texture inputs with the same
// name and a matching sampler named <InputName>Sampler. Example:
//   { "NAME": "texture", "TYPE": "image", "DEFAULT": "Texture" }
// can be sampled with:
//   float4 texel = texture.sample(textureSampler, in.uv);

fragment float4 generatedFragment(RasterizerData in [[stage_in]],
                                  constant PreviewUniforms& uniforms [[buffer(0)]],
                                  constant float* floatUniforms [[buffer(1)]],
                                  constant float4* colorUniforms [[buffer(2)]],
                                  constant float2* pointUniforms [[buffer(3)]],
                                  constant uint* boolUniforms [[buffer(4)]],
                                  constant float3* point3Uniforms [[buffer(5)]],
                                  constant float4* point4Uniforms [[buffer(6)]]) {
    float Speed = floatUniforms[0];
    float Mix = floatUniforms[1];
    float4 Tint = colorUniforms[0];
    float2 Center = pointUniforms[0];
    float3 Axis3 = point3Uniforms[0];
    float4 Quat4 = point4Uniforms[0];
    bool UseBands = boolUniforms[0] != 0;

    float2 uv = in.uv;
    float2 delta = uv - Center;
    float wave = sin((delta.x * 5.0) + uniforms.time * Speed * 4.5);
    float pulse = 0.5 + 0.5 * sin((delta.x + delta.y + uniforms.time * Speed * 0.9) * 6.28318);
    float mask = UseBands ? pulse : 1.0;
    float3 base = float3(uv.x, uv.y, 1.0 - uv.y);
    float3 animated = float3(
        0.5 + 0.5 * sin((uv.x + uniforms.time * Speed * 0.35) * 6.28318),
        0.5 + 0.5 * sin((uv.y + uniforms.time * Speed * 0.22 + 0.33) * 6.28318),
        0.5 + 0.5 * sin(((uv.x + uv.y) + uniforms.time * Speed * 0.41 + 0.67) * 6.28318)
    );
    float3 gradient = mix(base, animated, 0.65);
    gradient = mix(gradient, Tint.rgb, 0.30 + 0.45 * mask + 0.15 * wave);
    float4 texel = texture.sample(textureSampler, uv);
    float imageMix = clamp(Mix, 0.0, 1.0) * texel.a;
    float axisInfluence = clamp((Axis3.x + Axis3.y + Axis3.z) / 3.0, -1.0, 1.0);
    float quatInfluence = clamp((Quat4.x + Quat4.y + Quat4.z + Quat4.w) * 0.25, -1.0, 1.0);
    float3 vectorTint = 0.5 + 0.5 * float3(Axis3.x, Axis3.y, Axis3.z);
    float3 color = mix(gradient * mix(float3(1.0), vectorTint, 0.35), texel.rgb * Tint.rgb, imageMix);
    color *= 0.9 + 0.1 * axisInfluence;
    color += quatInfluence * 0.05;
    return float4(color, 1.0);
}
"""
}

@MainActor
private final class PreviewWindowController: NSObject, NSWindowDelegate {
    private weak var store: GraphStore?
    private let renderNodeID: GraphNode.ID
    private var window: NSWindow?

    var isVisible: Bool {
        window?.isVisible == true
    }

    init(store: GraphStore, renderNodeID: GraphNode.ID) {
        self.store = store
        self.renderNodeID = renderNodeID
    }

    func show(
        title: String,
        preferredContentSize: CGSize?,
        preferredOrigin: CGPoint?,
        preferredLevelMode: RenderWindowLevelMode?,
        preferredFullScreen: Bool?
    ) {
        if let window {
            applyTitle(title, to: window)
            if let preferredContentSize {
                applyContentSize(preferredContentSize, to: window)
            }
            if let preferredOrigin {
                applyOrigin(preferredOrigin, to: window)
            }
            if let preferredLevelMode {
                applyLevelMode(preferredLevelMode, to: window)
            }
            if let preferredFullScreen {
                setFullScreen(preferredFullScreen)
            }
            window.makeKeyAndOrderFront(nil)
            NSApp.activate(ignoringOtherApps: true)
            store?.previewDidOpen(renderNodeID: renderNodeID)
            reportContentSize(for: window)
            return
        }

        guard let store else { return }
        let content = PreviewWindowView(renderNodeID: renderNodeID)
            .environmentObject(store)

        let hostingController = NSHostingController(rootView: content)
        let window = NSWindow(contentViewController: hostingController)
        applyTitle(title, to: window)
        window.setContentSize(preferredContentSize.map { NSSize(width: $0.width, height: $0.height) } ?? NSSize(width: 960, height: 640))
        window.styleMask = NSWindow.StyleMask([
            .titled,
            .closable,
            .miniaturizable,
            .resizable,
            .fullSizeContentView
        ])
        window.titlebarAppearsTransparent = true
        window.isMovableByWindowBackground = true
        window.collectionBehavior = [.managed, .fullScreenPrimary]
        window.standardWindowButton(.zoomButton)?.isEnabled = true
        window.isReleasedWhenClosed = false
        window.delegate = self
        if let preferredLevelMode {
            applyLevelMode(preferredLevelMode, to: window)
        }
        if let preferredOrigin {
            window.setFrameOrigin(preferredOrigin)
        } else {
            window.center()
        }
        self.window = window
        window.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
        store.previewDidOpen(renderNodeID: renderNodeID)
        reportContentSize(for: window)
        if let preferredFullScreen {
            setFullScreen(preferredFullScreen)
        }
    }

    func updateTitle(_ title: String) {
        guard let window else { return }
        applyTitle(title, to: window)
    }

    func setContentSize(_ size: CGSize) {
        guard let window else { return }
        applyContentSize(size, to: window)
    }

    func setOrigin(_ origin: CGPoint) {
        guard let window else { return }
        applyOrigin(origin, to: window)
    }

    func setLevelMode(_ levelMode: RenderWindowLevelMode) {
        guard let window else { return }
        applyLevelMode(levelMode, to: window)
    }

    func setFullScreen(_ fullScreen: Bool) {
        guard let window else { return }
        let isCurrentlyFullScreen = window.styleMask.contains(.fullScreen)
        guard isCurrentlyFullScreen != fullScreen else { return }
        NSApp.activate(ignoringOtherApps: true)
        window.makeKeyAndOrderFront(nil)
        window.toggleFullScreen(nil)
    }

    func close() {
        window?.performClose(nil)
    }

    @discardableResult
    func toggleFullScreen() -> Bool {
        guard let window else { return false }
        NSApp.activate(ignoringOtherApps: true)
        window.makeKeyAndOrderFront(nil)
        window.toggleFullScreen(nil)
        return true
    }

    func windowWillClose(_ notification: Notification) {
        store?.previewDidClose(renderNodeID: renderNodeID)
    }

    func windowDidResize(_ notification: Notification) {
        guard let window else { return }
        reportContentSize(for: window)
    }

    func windowDidMove(_ notification: Notification) {
        guard let window else { return }
        store?.previewWindowDidMove(renderNodeID: renderNodeID, origin: window.frame.origin)
    }

    func windowDidEnterFullScreen(_ notification: Notification) {
        store?.previewWindowDidChangeFullScreen(renderNodeID: renderNodeID, isFullScreen: true)
    }

    func windowDidExitFullScreen(_ notification: Notification) {
        store?.previewWindowDidChangeFullScreen(renderNodeID: renderNodeID, isFullScreen: false)
    }

    private func reportContentSize(for window: NSWindow) {
        let contentSize = window.contentLayoutRect.size
        store?.previewWindowDidResize(renderNodeID: renderNodeID, contentSize: contentSize)
    }

    private func applyContentSize(_ size: CGSize, to window: NSWindow) {
        let width = max(1.0, size.width)
        let height = max(1.0, size.height)
        let current = window.contentLayoutRect.size
        guard abs(current.width - width) > 0.5 || abs(current.height - height) > 0.5 else { return }
        window.setContentSize(NSSize(width: width, height: height))
        reportContentSize(for: window)
    }

    private func applyOrigin(_ origin: CGPoint, to window: NSWindow) {
        let current = window.frame.origin
        guard abs(current.x - origin.x) > 0.5 || abs(current.y - origin.y) > 0.5 else { return }
        window.setFrameOrigin(origin)
        store?.previewWindowDidMove(renderNodeID: renderNodeID, origin: origin)
    }

    private func applyTitle(_ title: String, to window: NSWindow) {
        let resolvedTitle = title.trimmingCharacters(in: .whitespacesAndNewlines)
        window.title = resolvedTitle.isEmpty ? "Render" : resolvedTitle
        window.titleVisibility = resolvedTitle.isEmpty ? .hidden : .visible
    }

    private func applyLevelMode(_ levelMode: RenderWindowLevelMode, to window: NSWindow) {
        let level: NSWindow.Level
        switch levelMode {
        case .normal:
            level = .normal
        case .floating:
            level = .floating
        case .desktop:
            level = NSWindow.Level(rawValue: Int(CGWindowLevelForKey(.desktopIconWindow)) - 1)
        case .screenSaver:
            level = .screenSaver
        }
        guard window.level != level else { return }
        window.level = level
    }
}

@MainActor
private final class CodeEditorWindowController: NSObject, NSWindowDelegate {
    private weak var store: GraphStore?
    private var window: NSWindow?

    init(store: GraphStore) {
        self.store = store
    }

    func show() {
        if let window {
            window.makeKeyAndOrderFront(nil)
            NSApp.activate(ignoringOtherApps: true)
            store?.codeEditorDidOpen()
            return
        }

        guard let store else { return }
        let content = CodeEditorWindowView()
            .environmentObject(store)

        let hostingController = NSHostingController(rootView: content)
        let window = NSWindow(contentViewController: hostingController)
        window.title = "Metal Fragment Editor"
        window.setContentSize(NSSize(width: 940, height: 720))
        window.styleMask = NSWindow.StyleMask([
            .titled,
            .closable,
            .miniaturizable,
            .resizable
        ])
        window.isReleasedWhenClosed = false
        window.delegate = self
        self.window = window
        window.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
        store.codeEditorDidOpen()
    }

    func close() {
        window?.performClose(nil)
    }

    func windowWillClose(_ notification: Notification) {
        store?.codeEditorDidClose()
    }
}

@MainActor
private final class WebViewWindowController: NSObject, NSWindowDelegate, WKNavigationDelegate, NSTextFieldDelegate {
    private weak var store: GraphStore?
    private let nodeID: GraphNode.ID
    private var window: NSWindow?
    private weak var webView: WKWebView?
    private weak var urlField: NSTextField?
    private var snapshotTimer: Timer?
    private var inputTimer: Timer?
    private var pendingSnapshotWorkItem: DispatchWorkItem?
    private var lastLoadedURLString = ""
    private var lastClickValue = 0.0
    private var lastScrollX = 0.0
    private var lastScrollY = 0.0
    private var scrollVelocityX = 0.0
    private var scrollVelocityY = 0.0
    private var lastZoomValue = 1.0
    private var smoothedPointer: CGPoint?
    private var latchedClickPoint: CGPoint?
    private var isDisposing = false
    private var isCapturingSnapshot = false
    private var lastSnapshotTime = CACurrentMediaTime()
    private var needsSnapshot = false
    private var acceleratedSnapshotDeadline = CACurrentMediaTime()

    init(store: GraphStore, nodeID: GraphNode.ID) {
        self.store = store
        self.nodeID = nodeID
    }

    var isVisible: Bool {
        window?.isVisible == true
    }

    deinit {
        snapshotTimer?.invalidate()
        inputTimer?.invalidate()
    }

    func ensureRunning() {
        prepareWindowIfNeeded(showWindow: false)
    }

    func show() {
        prepareWindowIfNeeded(showWindow: true)
    }

    private func prepareWindowIfNeeded(showWindow: Bool) {
        if let window {
            syncFromStore()
            if showWindow {
                window.makeKeyAndOrderFront(nil)
                NSApp.activate(ignoringOtherApps: true)
            }
            return
        }

        let container = NSView(frame: NSRect(x: 0, y: 0, width: 1024, height: 760))
        container.wantsLayer = true
        container.layer?.backgroundColor = NSColor.windowBackgroundColor.cgColor

        let toolbar = NSView(frame: NSRect(x: 0, y: 712, width: 1024, height: 48))
        toolbar.wantsLayer = true
        toolbar.layer?.backgroundColor = NSColor.controlBackgroundColor.cgColor

        let urlField = NSTextField(frame: NSRect(x: 16, y: 10, width: 760, height: 28))
        urlField.font = .systemFont(ofSize: 13)
        urlField.delegate = self
        toolbar.addSubview(urlField)
        self.urlField = urlField

        let goButton = NSButton(frame: NSRect(x: 786, y: 8, width: 72, height: 32))
        goButton.title = "Go"
        goButton.target = self
        goButton.action = #selector(goPressed)
        toolbar.addSubview(goButton)

        let refreshButton = NSButton(frame: NSRect(x: 866, y: 8, width: 92, height: 32))
        refreshButton.title = "Refresh"
        refreshButton.target = self
        refreshButton.action = #selector(refreshPressed)
        toolbar.addSubview(refreshButton)

        let configuration = WKWebViewConfiguration()
        let webView = WKWebView(frame: NSRect(x: 0, y: 0, width: 1024, height: 712), configuration: configuration)
        webView.navigationDelegate = self
        webView.autoresizingMask = [.width, .height]
        if #available(macOS 13.0, *) {
            webView.underPageBackgroundColor = .white
        }
        container.addSubview(webView)
        container.addSubview(toolbar)
        self.webView = webView

        let controller = NSViewController()
        controller.view = container

        let window = NSWindow(contentViewController: controller)
        window.title = store?.node(withID: nodeID)?.title ?? "WebView"
        window.setContentSize(NSSize(width: 1024, height: 760))
        window.styleMask = [.titled, .closable, .miniaturizable, .resizable]
        window.isReleasedWhenClosed = false
        window.delegate = self
        self.window = window

        syncFromStore()

        snapshotTimer?.invalidate()
        snapshotTimer = Timer.scheduledTimer(timeInterval: 1.0 / 30.0, target: self, selector: #selector(snapshotTick), userInfo: nil, repeats: true)
        inputTimer?.invalidate()
        inputTimer = Timer.scheduledTimer(timeInterval: 1.0 / 30.0, target: self, selector: #selector(inputTick), userInfo: nil, repeats: true)

        if showWindow {
            window.makeKeyAndOrderFront(nil)
            NSApp.activate(ignoringOtherApps: true)
        } else {
            window.orderOut(nil)
        }
    }

    func close() {
        isDisposing = true
        window?.performClose(nil)
    }

    func reloadCurrentURL() {
        syncFromStore(forceReload: true)
    }

    func controlTextDidEndEditing(_ obj: Notification) {
        loadFromField(forceReload: false)
    }

    @objc private func goPressed() {
        loadFromField(forceReload: false)
    }

    @objc private func refreshPressed() {
        loadFromField(forceReload: true)
    }

    @objc private func snapshotTick() {
        let now = CACurrentMediaTime()
        let minimumInterval = now < acceleratedSnapshotDeadline ? (1.0 / 18.0) : 0.35
        guard needsSnapshot || now < acceleratedSnapshotDeadline else { return }
        guard now - lastSnapshotTime >= minimumInterval else { return }
        captureSnapshot()
    }

    @objc private func inputTick() {
        applyGraphInputs()
    }

    private func loadFromField(forceReload: Bool) {
        guard let store else { return }
        let raw = urlField?.stringValue ?? store.settings(forWebViewNodeID: nodeID).urlString
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.isEmpty == false else { return }
        let normalized = trimmed.contains("://") ? trimmed : "https://\(trimmed)"
        urlField?.stringValue = normalized
        store.updateWebViewNodeSettings(nodeID) {
            $0.urlString = normalized
            $0.statusText = "Loading \(normalized)…"
        }
        load(urlString: normalized, forceReload: forceReload)
    }

    private func syncFromStore(forceReload: Bool = false) {
        guard let store else { return }
        let settings = store.settings(forWebViewNodeID: nodeID)
        urlField?.stringValue = settings.urlString
        load(urlString: settings.urlString, forceReload: forceReload)
    }

    private func load(urlString: String, forceReload: Bool) {
        guard let webView else { return }
        let trimmed = urlString.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.isEmpty == false else { return }
        let normalized = trimmed.contains("://") ? trimmed : "https://\(trimmed)"
        guard forceReload || normalized != lastLoadedURLString else { return }
        guard let url = URL(string: normalized) else {
            store?.updateWebViewStatus(nodeID, "Invalid URL.")
            return
        }
        lastLoadedURLString = normalized
        store?.updateWebViewStatus(nodeID, "Loading \(normalized)…")
        let request = URLRequest(url: url, cachePolicy: .reloadIgnoringLocalCacheData, timeoutInterval: 30)
        webView.load(request)
    }

    func webView(_ webView: WKWebView, didStartProvisionalNavigation navigation: WKNavigation!) {
        store?.updateWebViewStatus(nodeID, "Loading \(webView.url?.absoluteString ?? lastLoadedURLString)…")
    }

    func webView(_ webView: WKWebView, didCommit navigation: WKNavigation!) {
        scheduleSnapshot()
    }

    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        store?.updateWebViewStatus(nodeID, "Loaded \(webView.url?.host ?? "page")")
        scheduleSnapshot()
    }

    func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) {
        store?.updateWebViewStatus(nodeID, "Web load failed: \(error.localizedDescription)")
    }

    func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) {
        store?.updateWebViewStatus(nodeID, "Web load failed: \(error.localizedDescription)")
    }

    private func scheduleSnapshot() {
        needsSnapshot = true
        acceleratedSnapshotDeadline = max(acceleratedSnapshotDeadline, CACurrentMediaTime() + 0.8)
    }

    private func captureSnapshot() {
        guard let webView else { return }
        guard isCapturingSnapshot == false else { return }
        let bounds = webView.bounds
        guard bounds.isEmpty == false else { return }
        isCapturingSnapshot = true
        lastSnapshotTime = CACurrentMediaTime()
        needsSnapshot = false

        let configuration = WKSnapshotConfiguration()
        configuration.rect = bounds

        webView.takeSnapshot(with: configuration) { [weak self] image, error in
            guard let self else { return }
            self.isCapturingSnapshot = false

            if let image, let data = image.pngData {
                let host = webView.url?.host ?? "WebView"
                self.store?.updateWebViewSnapshot(self.nodeID, imageData: data, filename: "\(host).png")
                return
            }

            if let data = webView.fallbackSnapshotPNGData {
                let host = webView.url?.host ?? "WebView"
                self.store?.updateWebViewSnapshot(self.nodeID, imageData: data, filename: "\(host).png")
                return
            }

            let message = error?.localizedDescription ?? "Could not capture web view."
            self.store?.updateWebViewStatus(self.nodeID, message)
        }
    }

    private func applyGraphInputs() {
        guard let store, let webView else { return }
        let state = store.webViewControlState(for: nodeID)

        if let pointer = state.pointer {
            let viewportWidth = webView.bounds.width
            let viewportHeight = webView.bounds.height
            guard viewportWidth > 1, viewportHeight > 1 else { return }

            let clampedPointer = CGPoint(
                x: min(max(pointer.x, 0.0), 1.0),
                y: min(max(pointer.y, 0.0), 1.0)
            )
            let nextPointer: CGPoint
            if let previous = smoothedPointer {
                let alpha: CGFloat = state.click >= 0.5 ? 0.12 : 0.3
                nextPointer = CGPoint(
                    x: previous.x + ((clampedPointer.x - previous.x) * alpha),
                    y: previous.y + ((clampedPointer.y - previous.y) * alpha)
                )
            } else {
                nextPointer = clampedPointer
            }
            smoothedPointer = nextPointer
            let livePoint = CGPoint(x: nextPointer.x * viewportWidth, y: nextPointer.y * viewportHeight)

            if state.click >= 0.5 && lastClickValue < 0.5 {
                latchedClickPoint = livePoint
                let clickPoint = latchedClickPoint ?? livePoint
                let script = """
                (() => {
                    const x = \(formatJSNumber(clickPoint.x));
                    const y = \(formatJSNumber(clickPoint.y));
                    const el = document.elementFromPoint(x, y);
                    if (!el) return false;
                    ["mouseover","mousedown","mouseup","click"].forEach(type => {
                        el.dispatchEvent(new MouseEvent(type, {
                            view: window,
                            bubbles: true,
                            cancelable: true,
                            clientX: x,
                            clientY: y,
                            button: 0,
                            buttons: 1
                        }));
                    });
                    if (typeof el.focus === "function") el.focus();
                    return true;
                })();
                """
                webView.evaluateJavaScript(script, completionHandler: nil)
                scheduleSnapshot()
            }
            if state.click < 0.5 {
                latchedClickPoint = nil
            }
        } else if state.click < 0.5 {
            latchedClickPoint = nil
        }

        let deltaX = state.scrollX - lastScrollX
        let deltaY = state.scrollY - lastScrollY
        if abs(deltaX) > 0.0001 || abs(deltaY) > 0.0001 {
            scrollVelocityX += deltaX * 1200.0
            scrollVelocityY += deltaY * 1200.0
        }

        if abs(scrollVelocityX) > 0.05 || abs(scrollVelocityY) > 0.05 {
            let script = """
            window.scrollBy(\(formatJSNumber(scrollVelocityX)), \(formatJSNumber(scrollVelocityY)));
            """
            webView.evaluateJavaScript(script, completionHandler: nil)
            scrollVelocityX *= 0.84
            scrollVelocityY *= 0.84
            if abs(scrollVelocityX) < 0.05 { scrollVelocityX = 0.0 }
            if abs(scrollVelocityY) < 0.05 { scrollVelocityY = 0.0 }
            scheduleSnapshot()
        }

        let clampedZoom = min(max(state.zoom, 0.05), 6.0)
        if abs(clampedZoom - lastZoomValue) > 0.0005 {
            let zoomString = formatJSNumber(clampedZoom)
            let script = """
            (() => {
                const zoom = "\(zoomString)";
                document.documentElement.style.zoom = zoom;
                if (document.body) document.body.style.zoom = zoom;
                return zoom;
            })();
            """
            webView.evaluateJavaScript(script, completionHandler: nil)
            lastZoomValue = clampedZoom
            scheduleSnapshot()
        }

        lastClickValue = state.click
        lastScrollX = state.scrollX
        lastScrollY = state.scrollY
    }

    private func formatJSNumber(_ value: Double) -> String {
        String(format: "%.4f", value)
    }

    func windowWillClose(_ notification: Notification) {
        snapshotTimer?.invalidate()
        inputTimer?.invalidate()
        if isDisposing {
            store?.webViewWindowDidClose(nodeID: nodeID)
        }
    }

    func windowShouldClose(_ sender: NSWindow) -> Bool {
        if isDisposing {
            return true
        }
        sender.orderOut(nil)
        store?.updateWebViewStatus(nodeID, "Browser hidden. WebView is still active.")
        return false
    }
}

private extension NSView {
    var fallbackSnapshotPNGData: Data? {
        guard bounds.isEmpty == false else { return nil }
        guard let bitmapRep = bitmapImageRepForCachingDisplay(in: bounds) else { return nil }
        cacheDisplay(in: bounds, to: bitmapRep)
        return bitmapRep.representation(using: .png, properties: [:])
    }
}

private struct VideoPlayerControlState {
    let play: Double
    let rate: Double
    let seek: Double?
    let volume: Double
}

@MainActor
private final class VideoPlayerController: NSObject {
    private weak var store: GraphStore?
    private let nodeID: GraphNode.ID
    private var player: AVPlayer?
    private var playerItem: AVPlayerItem?
    private var videoOutput: AVPlayerItemVideoOutput?
    private var timer: Timer?
    private var endObserver: Any?
    private let ciContext = CIContext(options: nil)
    private var lastLoadedBookmarkData = Data()
    private var lastAppliedSeek: Double?
    private var scopedURL: URL?
    private var isAccessingScopedResource = false
    private var imageGenerator: AVAssetImageGenerator?
    private var assetDurationSeconds: Double?

    init(store: GraphStore, nodeID: GraphNode.ID) {
        self.store = store
        self.nodeID = nodeID
    }

    func ensureRunning() {
        if timer == nil {
            timer = Timer.scheduledTimer(withTimeInterval: 1.0 / 30.0, repeats: true) { [weak self] _ in
                Task { @MainActor [weak self] in
                    self?.tick()
                }
            }
            if let timer {
                RunLoop.main.add(timer, forMode: .common)
            }
        }
        reloadFromStore()
    }

    func seek(toNormalizedTime normalizedTime: Double) {
        guard playerItem != nil else { return }
        guard let durationSeconds = assetDurationSeconds else { return }
        guard durationSeconds.isFinite, durationSeconds > 0 else { return }
        let clamped = max(0.0, min(1.0, normalizedTime))
        let time = CMTime(seconds: durationSeconds * clamped, preferredTimescale: 600)
        player?.seek(to: time, toleranceBefore: .zero, toleranceAfter: .zero)
        lastAppliedSeek = clamped
        store?.updateVideoPlayerStatus(nodeID, "Seek \(Int(clamped * 100))%")
    }

    func reloadFromStore() {
        guard let store else { return }
        let settings = store.settings(forVideoPlayerNodeID: nodeID)
        guard settings.bookmarkData.isEmpty == false else {
            tearDownPlayer()
            store.updateVideoPlayerStatus(nodeID, "Choose a movie file.")
            return
        }

        guard settings.bookmarkData != lastLoadedBookmarkData else {
            applyControlState()
            return
        }

        tearDownPlayer()

        var stale = false
        guard let url = try? URL(
            resolvingBookmarkData: settings.bookmarkData,
            options: [.withSecurityScope],
            relativeTo: nil,
            bookmarkDataIsStale: &stale
        ) else {
            store.updateVideoPlayerStatus(nodeID, "Could not open movie file.")
            return
        }

        if url.startAccessingSecurityScopedResource() {
            isAccessingScopedResource = true
            scopedURL = url
        }

        let asset = AVAsset(url: url)
        let item = AVPlayerItem(asset: asset)
        let output = AVPlayerItemVideoOutput(pixelBufferAttributes: [
            kCVPixelBufferPixelFormatTypeKey as String: Int(kCVPixelFormatType_32BGRA)
        ])
        item.add(output)

        let player = AVPlayer(playerItem: item)
        player.actionAtItemEnd = .pause

        let generator = AVAssetImageGenerator(asset: asset)
        generator.appliesPreferredTrackTransform = true
        generator.maximumSize = CGSize(width: 1280, height: 720)

        playerItem = item
        videoOutput = output
        self.player = player
        imageGenerator = generator
        assetDurationSeconds = nil
        lastLoadedBookmarkData = settings.bookmarkData
        lastAppliedSeek = nil

        endObserver = NotificationCenter.default.addObserver(
            forName: .AVPlayerItemDidPlayToEndTime,
            object: item,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor [weak self] in
                self?.handlePlaybackEnded()
            }
        }

        store.updateVideoPlayerStatus(nodeID, "Loaded \(settings.filename)")
        Task { @MainActor [weak self] in
            guard let self else { return }
            do {
                let duration = try await asset.load(.duration)
                self.assetDurationSeconds = duration.seconds
            } catch {
                self.assetDurationSeconds = nil
            }
        }
        applyControlState()
        captureFrame(force: true)
    }

    func close() {
        timer?.invalidate()
        timer = nil
        tearDownPlayer()
    }

    private func tick() {
        reloadFromStore()
        applyControlState()
        captureFrame(force: false)
    }

    private func applyControlState() {
        guard let store, let player else { return }
        let settings = store.settings(forVideoPlayerNodeID: nodeID)
        let control = store.videoPlayerControlState(for: nodeID)
        let hasConsumer = store.nodeHasRenderableConsumer(nodeID)
        player.volume = Float(control.volume)
        player.isMuted = control.volume <= 0.0001

        if let seek = control.seek, seek != lastAppliedSeek {
            self.seek(toNormalizedTime: seek)
        }

        let shouldPlay = hasConsumer && control.play >= 0.5
        if shouldPlay {
            player.rate = Float(max(0.0, min(4.0, control.rate)))
            if player.timeControlStatus != .playing && player.rate > 0 {
                player.play()
                player.rate = Float(max(0.0, min(4.0, control.rate)))
            }
            store.updateVideoPlayerStatus(nodeID, "Playing \(settings.filename)")
        } else {
            player.pause()
            if hasConsumer {
                store.updateVideoPlayerStatus(nodeID, "Paused \(settings.filename)")
            } else {
                store.updateVideoPlayerStatus(nodeID, "Disconnected \(settings.filename)")
            }
        }
    }

    private func handlePlaybackEnded() {
        guard let store else { return }
        let settings = store.settings(forVideoPlayerNodeID: nodeID)
        if settings.isLooping {
            player?.seek(to: .zero, toleranceBefore: .zero, toleranceAfter: .zero)
            lastAppliedSeek = 0.0
            if settings.isPlaying {
                player?.play()
                player?.rate = Float(settings.rate)
            }
            store.updateVideoPlayerStatus(nodeID, "Looping \(settings.filename)")
        } else {
            player?.pause()
            store.updateVideoPlayerNodeSettings(nodeID) { $0.isPlaying = false }
            store.updateVideoPlayerStatus(nodeID, "Finished \(settings.filename)")
        }
    }

    private func captureFrame(force: Bool) {
        guard let store else { return }
        if let output = videoOutput, let item = playerItem {
            let itemTime = item.currentTime()
            if force || output.hasNewPixelBuffer(forItemTime: itemTime) {
                var displayTime = CMTime.zero
                if let pixelBuffer = output.copyPixelBuffer(forItemTime: itemTime, itemTimeForDisplay: &displayTime) {
                    VideoPlayerFrameRegistry.shared.setPixelBuffer(pixelBuffer, for: nodeID)
                    return
                }
            }
        }

        guard force, let generator = imageGenerator, let player else { return }
        let time = player.currentTime()
        if let image = try? generator.copyCGImage(at: time, actualTime: nil),
           let data = pngData(from: image) {
            store.updateVideoPlayerFrame(nodeID, imageData: data)
        }
    }

    private func pngData(from pixelBuffer: CVPixelBuffer) -> Data? {
        let ciImage = CIImage(cvPixelBuffer: pixelBuffer)
        let rect = ciImage.extent.integral
        guard let cgImage = ciContext.createCGImage(ciImage, from: rect) else { return nil }
        return pngData(from: cgImage)
    }

    private func pngData(from cgImage: CGImage) -> Data? {
        let rep = NSBitmapImageRep(cgImage: cgImage)
        return rep.representation(using: .png, properties: [:])
    }

    private func tearDownPlayer() {
        if let endObserver {
            NotificationCenter.default.removeObserver(endObserver)
            self.endObserver = nil
        }
        player?.pause()
        player = nil
        playerItem = nil
        videoOutput = nil
        imageGenerator = nil
        assetDurationSeconds = nil
        VideoPlayerFrameRegistry.shared.removePixelBuffer(for: nodeID)
        lastLoadedBookmarkData = Data()
        lastAppliedSeek = nil
        if isAccessingScopedResource {
            scopedURL?.stopAccessingSecurityScopedResource()
            isAccessingScopedResource = false
        }
        scopedURL = nil
    }
}

private struct WebViewControlState {
    let pointer: CGPoint?
    let click: Double
    let scrollX: Double
    let scrollY: Double
    let zoom: Double
}

private extension NSImage {
    var pngData: Data? {
        guard
            let tiffRepresentation,
            let rep = NSBitmapImageRep(data: tiffRepresentation)
        else {
            return nil
        }
        return rep.representation(using: .png, properties: [:])
    }
}

private enum ExpressionEngine {
    private static let constants: [String: Double] = [
        "pi": Double.pi,
        "tau": Double.pi * 2.0,
        "e": M_E
    ]

    private static let functionNames: Set<String> = [
        "sin", "cos", "tan", "abs", "sqrt",
        "min", "max", "clamp", "floor", "ceil",
        "round", "pow"
    ]

    static func variableNames(in expression: String) -> [String] {
        let pattern = #"\b[A-Za-z_][A-Za-z0-9_]*\b"#
        guard let regex = try? NSRegularExpression(pattern: pattern) else { return ["a"] }
        let range = NSRange(expression.startIndex..<expression.endIndex, in: expression)
        let matches = regex.matches(in: expression, range: range)
        let names = matches.compactMap { match -> String? in
            guard let matchRange = Range(match.range, in: expression) else { return nil }
            let name = String(expression[matchRange])
            if functionNames.contains(name.lowercased()) { return nil }
            if constants[name.lowercased()] != nil { return nil }
            return name
        }

        let unique = Array(Set(names)).sorted()
        return unique.isEmpty ? ["a"] : unique
    }

    static func evaluate(_ expression: String, variables: [String: Double]) -> Double? {
        guard var parser = Parser(expression: expression, variables: variables, constants: constants) else {
            return nil
        }
        return parser.parse()
    }

    private enum Token: Equatable {
        case number(Double)
        case identifier(String)
        case plus
        case minus
        case star
        case slash
        case caret
        case comma
        case leftParen
        case rightParen
    }

    private struct Lexer {
        let characters: [Character]
        var index: Int = 0

        init(expression: String) {
            self.characters = Array(expression)
        }

        mutating func tokenize() -> [Token]? {
            var tokens: [Token] = []

            while index < characters.count {
                let character = characters[index]

                if character.isWhitespace {
                    index += 1
                    continue
                }

                if character.isNumber || character == "." {
                    guard let token = numberToken() else { return nil }
                    tokens.append(token)
                    continue
                }

                if character.isLetter || character == "_" {
                    tokens.append(identifierToken())
                    continue
                }

                switch character {
                case "+": tokens.append(.plus)
                case "-": tokens.append(.minus)
                case "*": tokens.append(.star)
                case "/": tokens.append(.slash)
                case "^": tokens.append(.caret)
                case ",": tokens.append(.comma)
                case "(": tokens.append(.leftParen)
                case ")": tokens.append(.rightParen)
                default: return nil
                }
                index += 1
            }

            return tokens
        }

        private mutating func numberToken() -> Token? {
            let start = index
            var hasDot = false

            while index < characters.count {
                let character = characters[index]
                if character == "." {
                    if hasDot { break }
                    hasDot = true
                    index += 1
                    continue
                }
                guard character.isNumber else { break }
                index += 1
            }

            let text = String(characters[start..<index])
            guard let value = Double(text) else { return nil }
            return .number(value)
        }

        private mutating func identifierToken() -> Token {
            let start = index
            index += 1
            while index < characters.count, characters[index].isLetter || characters[index].isNumber || characters[index] == "_" {
                index += 1
            }
            return .identifier(String(characters[start..<index]))
        }
    }

    private struct Parser {
        let tokens: [Token]
        let variables: [String: Double]
        let constants: [String: Double]
        var index: Int = 0

        init?(expression: String, variables: [String: Double], constants: [String: Double]) {
            var lexer = Lexer(expression: expression)
            guard let tokens = lexer.tokenize() else { return nil }
            self.tokens = tokens
            self.variables = variables
            self.constants = constants
        }

        mutating func parse() -> Double? {
            guard let value = parseExpression(), index == tokens.count else { return nil }
            return value
        }

        private mutating func parseExpression() -> Double? {
            guard var value = parseTerm() else { return nil }
            while true {
                if match(.plus) {
                    guard let rhs = parseTerm() else { return nil }
                    value += rhs
                } else if match(.minus) {
                    guard let rhs = parseTerm() else { return nil }
                    value -= rhs
                } else {
                    return value
                }
            }
        }

        private mutating func parseTerm() -> Double? {
            guard var value = parsePower() else { return nil }
            while true {
                if match(.star) {
                    guard let rhs = parsePower() else { return nil }
                    value *= rhs
                } else if match(.slash) {
                    guard let rhs = parsePower(), rhs != 0 else { return nil }
                    value /= rhs
                } else {
                    return value
                }
            }
        }

        private mutating func parsePower() -> Double? {
            guard var value = parseUnary() else { return nil }
            while match(.caret) {
                guard let rhs = parseUnary() else { return nil }
                value = Foundation.pow(value, rhs)
            }
            return value
        }

        private mutating func parseUnary() -> Double? {
            if match(.minus) {
                guard let value = parseUnary() else { return nil }
                return -value
            }
            if match(.plus) {
                return parseUnary()
            }
            return parsePrimary()
        }

        private mutating func parsePrimary() -> Double? {
            guard let token = peek() else { return nil }

            switch token {
            case .number(let value):
                index += 1
                return value
            case .identifier(let name):
                index += 1
                if match(.leftParen) {
                    var arguments: [Double] = []
                    if match(.rightParen) == false {
                        repeat {
                            guard let value = parseExpression() else { return nil }
                            arguments.append(value)
                        } while match(.comma)

                        guard match(.rightParen) else { return nil }
                    }
                    return applyFunction(name: name, arguments: arguments)
                }
                let lowered = name.lowercased()
                if let value = variables[name] { return value }
                if let value = variables[lowered] { return value }
                return constants[lowered] ?? 0.0
            case .leftParen:
                index += 1
                guard let value = parseExpression(), match(.rightParen) else { return nil }
                return value
            default:
                return nil
            }
        }

        private mutating func applyFunction(name: String, arguments: [Double]) -> Double? {
            switch name.lowercased() {
            case "sin":
                guard arguments.count == 1 else { return nil }
                return Foundation.sin(arguments[0])
            case "cos":
                guard arguments.count == 1 else { return nil }
                return Foundation.cos(arguments[0])
            case "tan":
                guard arguments.count == 1 else { return nil }
                return Foundation.tan(arguments[0])
            case "abs":
                guard arguments.count == 1 else { return nil }
                return Swift.abs(arguments[0])
            case "sqrt":
                guard arguments.count == 1, arguments[0] >= 0 else { return nil }
                return Foundation.sqrt(arguments[0])
            case "floor":
                guard arguments.count == 1 else { return nil }
                return Foundation.floor(arguments[0])
            case "ceil":
                guard arguments.count == 1 else { return nil }
                return Foundation.ceil(arguments[0])
            case "round":
                guard arguments.count == 1 else { return nil }
                return arguments[0].rounded()
            case "min":
                guard arguments.count == 2 else { return nil }
                return Swift.min(arguments[0], arguments[1])
            case "max":
                guard arguments.count == 2 else { return nil }
                return Swift.max(arguments[0], arguments[1])
            case "pow":
                guard arguments.count == 2 else { return nil }
                return Foundation.pow(arguments[0], arguments[1])
            case "clamp":
                guard arguments.count == 3 else { return nil }
                return Swift.max(arguments[1], Swift.min(arguments[0], arguments[2]))
            default:
                return nil
            }
        }

        private func peek() -> Token? {
            guard index < tokens.count else { return nil }
            return tokens[index]
        }

        private mutating func match(_ token: Token) -> Bool {
            guard peek() == token else { return false }
            index += 1
            return true
        }
    }
}
